// @system @ref LLP 0362#crash-capsule-and-flight-recorder — fixed-capacity,
// value-free production interaction categories at normalized host ingress.

export type ProductionActionCategory =
  | 'navigation'
  | 'press'
  | 'change'
  | 'submit'
  | 'focus'
  | 'blur'
  | 'scroll'
  | 'invariant'
  | 'protocol-error'
  | 'unknown';

const CATEGORY_CODES: Record<ProductionActionCategory, number> = {
  navigation: 1,
  press: 2,
  change: 3,
  submit: 4,
  focus: 5,
  blur: 6,
  scroll: 7,
  invariant: 8,
  'protocol-error': 9,
  unknown: 10,
};
const CODE_CATEGORIES = Object.freeze(
  Object.fromEntries(Object.entries(CATEGORY_CODES).map(([category, code]) => [code, category])),
) as Readonly<Record<number, ProductionActionCategory>>;
const OPAQUE_SEMANTIC_ID = /^(?:react|contract|rust-native|route|clause):[a-f0-9]{24}$/;

export interface ProductionActionCategoryRecord {
  seq: number;
  category: ProductionActionCategory;
  timeBucketMs: number;
  manifestId?: string;
}

export class ProductionActionCategoryRing {
  readonly #categories: Uint8Array;
  readonly #timeBuckets: Float64Array;
  readonly #sequences: Uint32Array;
  readonly #manifestIds: Array<string | undefined>;
  readonly #nowMs: () => number;
  #nextSequence = 0;
  #size = 0;
  #evicted = 0;

  constructor(
    capacity = 128,
    nowMs: () => number = () => typeof performance === 'undefined' ? Date.now() : performance.now(),
  ) {
    if (!Number.isInteger(capacity) || capacity < 1 || capacity > 4096) {
      throw new RangeError('category-ring capacity must be an integer in [1, 4096]');
    }
    this.#categories = new Uint8Array(capacity);
    this.#timeBuckets = new Float64Array(capacity);
    this.#sequences = new Uint32Array(capacity);
    this.#manifestIds = new Array(capacity);
    this.#nowMs = nowMs;
  }

  record(
    category: ProductionActionCategory,
    manifestId?: string,
    options: { secureInput?: boolean } = {},
  ): void {
    const code = CATEGORY_CODES[category];
    if (code === undefined) throw new TypeError('unknown production action category');
    if (category === 'change' && options.secureInput === true) {
      return;
    }
    if (manifestId !== undefined && !OPAQUE_SEMANTIC_ID.test(manifestId)) {
      throw new TypeError('manifestId must be a release-scoped opaque manifest identity');
    }
    const timeBucketMs = Math.max(0, Math.floor(this.#nowMs() / 100) * 100);
    if (this.#size > 0) {
      const previousSequence = this.#nextSequence - 1;
      const previousIndex = previousSequence % this.#categories.length;
      if (
        this.#sequences[previousIndex] === (previousSequence >>> 0)
        && this.#categories[previousIndex] === code
        && this.#timeBuckets[previousIndex] === timeBucketMs
        && this.#manifestIds[previousIndex] === manifestId
      ) {
        return;
      }
    }
    const sequence = this.#nextSequence++;
    const index = sequence % this.#categories.length;
    if (this.#size === this.#categories.length) this.#evicted += 1;
    else this.#size += 1;
    this.#categories[index] = code;
    this.#timeBuckets[index] = timeBucketMs;
    this.#sequences[index] = sequence >>> 0;
    this.#manifestIds[index] = manifestId;
  }

  snapshot(): ProductionActionCategoryRecord[] {
    const first = Math.max(0, this.#nextSequence - this.#size);
    const records: ProductionActionCategoryRecord[] = [];
    for (let sequence = first; sequence < this.#nextSequence; sequence += 1) {
      const index = sequence % this.#categories.length;
      if (this.#sequences[index] !== (sequence >>> 0)) continue;
      const manifestId = this.#manifestIds[index];
      records.push({
        seq: sequence,
        category: CODE_CATEGORIES[this.#categories[index]!] ?? 'unknown',
        timeBucketMs: this.#timeBuckets[index]!,
        ...(manifestId === undefined ? {} : { manifestId }),
      });
    }
    return records;
  }

  get coverage(): { retained: number; evicted: number } {
    return { retained: this.#size, evicted: this.#evicted };
  }
}

interface CategoryRingGlobal {
  __exactProductionActionCategoryRing?: ProductionActionCategoryRing;
}

export function productionActionCategoryRing(): ProductionActionCategoryRing {
  const runtime = globalThis as typeof globalThis & CategoryRingGlobal;
  return runtime.__exactProductionActionCategoryRing ??= new ProductionActionCategoryRing();
}

export function recordProductionActionCategory(
  category: ProductionActionCategory,
  manifestId?: string,
  options?: { secureInput?: boolean },
): void {
  productionActionCategoryRing().record(category, manifestId, options);
}

export function resetProductionActionCategoryRingForTests(): void {
  delete (globalThis as typeof globalThis & CategoryRingGlobal).__exactProductionActionCategoryRing;
}
