// @system @ref LLP 0099#gesture-recognizers
// @system @ref LLP 0099#gesture-composition
// @system @ref LLP 0099#typed-worklet-abi
//
// Runtime-side lowering for the native Motion commit sidecar. This module is
// intentionally structural: host-ops must not pull the web recognizer into
// native startup merely to validate a descriptor produced by Contract/React.

import {
  MotionDescriptorKind,
  type MotionDescriptorRecord,
} from '@exact/core/protocol/motion-snapshot';
import type {
  MotionGestureCompositionDescriptor,
  MotionGestureDescriptor,
  MotionGestureLeafDescriptor,
  MotionGestureOptions,
} from './motion-gesture-recognizer.js';
import {
  MOTION_GESTURE_COMPOSITION_SLOT,
  MOTION_GESTURE_LEAF_SLOT,
  MOTION_GESTURE_NATIVE_SCHEMA,
  MOTION_GESTURE_NATIVE_SCHEMA_DIGEST_HIGH,
  MOTION_GESTURE_NATIVE_SCHEMA_DIGEST_LOW,
} from './motion-gesture-sidecar-schema.generated.js';
import { motionCommandIdentityDigests } from './motion-command.js';
import {
  MOTION_WORKLET_INSTALL_PLANE_SCHEMA_VERSION,
  type MotionWorkletInstallArtifactV2,
  type MotionWorkletInstallCallbackV2,
  type MotionWorkletInstallCaptureV2,
  type MotionWorkletInstallPhaseV2,
} from './motion-worklet-install-plane.generated.js';

const MOTION_GESTURE_KIND = Symbol.for('exact.motion.gesture');
const U32_MAX = 0xffff_ffff;

type GesturePhase = (typeof MOTION_GESTURE_NATIVE_SCHEMA.callbackPhases)[number];
export type MotionWorkletInstallPhase = MotionWorkletInstallPhaseV2;
type GestureOptionKey = keyof MotionGestureOptions;

interface MotionWorkletCallback extends Function {
  /** Stable compiler/bundle-registry key for a callback whose source is elsewhere. */
  readonly __exactMotionWorkletId?: unknown;
  /** Build-time UTF-8 function-expression extraction (LLP 0297 / LLP 0099 M6). */
  readonly __workletSource?: unknown;
  /** Compiler-owned typed install artifact, completed with live captures at mount. */
  readonly __exactMotionWorkletArtifact?: unknown;
}

export interface MotionWorkletSharedValueCaptureSource {
  readonly id: string;
  readonly generation: number;
  current(): number;
  /** Renderer-owned descriptor capture (for a DerivedValue graph edge). */
  readonly __exactMotionDescriptorId?: string;
}

export type MotionWorkletInstallCapture = MotionWorkletInstallCaptureV2;
export type MotionWorkletInstallCallback = MotionWorkletInstallCallbackV2;

/**
 * JSON-safe record consumed by the native, main-owned worklet installer.
 * The enclosing host-ops plane supplies the root transaction fence; records
 * deliberately contain no JS object/function references.
 */
export type MotionWorkletInstallArtifact = MotionWorkletInstallArtifactV2;

export interface MotionWorkletCallbackRegistration extends MotionWorkletInstallCallback {
  /** Exact installed artifact fence copied onto every app-runtime callback. */
  readonly sourceIdentity: string;
  readonly generation: number;
  readonly callback: (...args: unknown[]) => unknown;
}

type UnfencedMotionWorkletCallbackRegistration = MotionWorkletInstallCallback & {
  readonly callback: (...args: unknown[]) => unknown;
};

export interface LoweredMotionGestureSidecarRecords {
  readonly descriptors: MotionDescriptorRecord[];
  readonly artifacts: MotionWorkletInstallArtifact[];
  readonly sharedValueCaptures: ReadonlyMap<string, MotionWorkletSharedValueCaptureSource>;
  readonly callbackRegistrations: MotionWorkletCallbackRegistration[];
}

interface RuntimeMotionWorkletArtifact {
  readonly schemaVersion: unknown;
  readonly installFormat: unknown;
  readonly compilerId: unknown;
  readonly source: unknown;
  readonly captureNames: unknown;
  readonly captureKinds: unknown;
  readonly captures: unknown;
  readonly inputSlots: unknown;
  readonly outputSlots: unknown;
  readonly callbacks?: unknown;
}

interface RuntimeMotionWorkletCallback {
  readonly identity: unknown;
  readonly action: unknown;
  readonly payloadKeys: unknown;
  readonly callback: unknown;
}

interface WorkletCollector {
  readonly artifacts: MotionWorkletInstallArtifact[];
  readonly sharedValueCaptures: Map<string, MotionWorkletSharedValueCaptureSource>;
  readonly callbackRegistrations: MotionWorkletCallbackRegistration[];
}

interface MotionCommandShape {
  readonly commandInstanceId: string;
  readonly action: string;
  readonly ownerInstance: string;
  readonly bindingGeneration: number;
}

const KNOWN_OPTION_KEYS = new Set<GestureOptionKey>([
  'axis',
  'claim',
  'minDistance',
  'minDurationMs',
  'maxDurationMs',
  'maxDistance',
  'maxInterTapMs',
  'tapCount',
  'pointerCount',
  'minVelocity',
  'minScaleDelta',
  'minRotationRadians',
  'axisLockRatio',
  'failCrossAxis',
  'direction',
  'update',
  'start',
  'end',
  'cancel',
  'activeOffsetX',
  'activeOffsetY',
  'command',
  'prospective', 'prospectiveTarget',
]);

const NUMERIC_OPTION_SLOTS = [
  ['minDistance', MOTION_GESTURE_LEAF_SLOT.minDistance],
  ['minDurationMs', MOTION_GESTURE_LEAF_SLOT.minDurationMs],
  ['maxDurationMs', MOTION_GESTURE_LEAF_SLOT.maxDurationMs],
  ['maxDistance', MOTION_GESTURE_LEAF_SLOT.maxDistance],
  ['maxInterTapMs', MOTION_GESTURE_LEAF_SLOT.maxInterTapMs],
  ['tapCount', MOTION_GESTURE_LEAF_SLOT.tapCount],
  ['pointerCount', MOTION_GESTURE_LEAF_SLOT.pointerCount],
  ['minVelocity', MOTION_GESTURE_LEAF_SLOT.minVelocity],
  ['minScaleDelta', MOTION_GESTURE_LEAF_SLOT.minScaleDelta],
  ['minRotationRadians', MOTION_GESTURE_LEAF_SLOT.minRotationRadians],
  ['axisLockRatio', MOTION_GESTURE_LEAF_SLOT.axisLockRatio],
] as const;

const CALLBACK_SLOTS: Record<GesturePhase, {
  identityLow: number;
  identityHigh: number;
  sourceKind: number;
  sourceIdentityLow: number;
  sourceIdentityHigh: number;
  sourceByteLength: number;
}> = {
  start: {
    identityLow: MOTION_GESTURE_LEAF_SLOT.startCallbackIdentityLow,
    identityHigh: MOTION_GESTURE_LEAF_SLOT.startCallbackIdentityHigh,
    sourceKind: MOTION_GESTURE_LEAF_SLOT.startSourceKind,
    sourceIdentityLow: MOTION_GESTURE_LEAF_SLOT.startSourceIdentityLow,
    sourceIdentityHigh: MOTION_GESTURE_LEAF_SLOT.startSourceIdentityHigh,
    sourceByteLength: MOTION_GESTURE_LEAF_SLOT.startSourceByteLength,
  },
  update: {
    identityLow: MOTION_GESTURE_LEAF_SLOT.updateCallbackIdentityLow,
    identityHigh: MOTION_GESTURE_LEAF_SLOT.updateCallbackIdentityHigh,
    sourceKind: MOTION_GESTURE_LEAF_SLOT.updateSourceKind,
    sourceIdentityLow: MOTION_GESTURE_LEAF_SLOT.updateSourceIdentityLow,
    sourceIdentityHigh: MOTION_GESTURE_LEAF_SLOT.updateSourceIdentityHigh,
    sourceByteLength: MOTION_GESTURE_LEAF_SLOT.updateSourceByteLength,
  },
  end: {
    identityLow: MOTION_GESTURE_LEAF_SLOT.endCallbackIdentityLow,
    identityHigh: MOTION_GESTURE_LEAF_SLOT.endCallbackIdentityHigh,
    sourceKind: MOTION_GESTURE_LEAF_SLOT.endSourceKind,
    sourceIdentityLow: MOTION_GESTURE_LEAF_SLOT.endSourceIdentityLow,
    sourceIdentityHigh: MOTION_GESTURE_LEAF_SLOT.endSourceIdentityHigh,
    sourceByteLength: MOTION_GESTURE_LEAF_SLOT.endSourceByteLength,
  },
  cancel: {
    identityLow: MOTION_GESTURE_LEAF_SLOT.cancelCallbackIdentityLow,
    identityHigh: MOTION_GESTURE_LEAF_SLOT.cancelCallbackIdentityHigh,
    sourceKind: MOTION_GESTURE_LEAF_SLOT.cancelSourceKind,
    sourceIdentityLow: MOTION_GESTURE_LEAF_SLOT.cancelSourceIdentityLow,
    sourceIdentityHigh: MOTION_GESTURE_LEAF_SLOT.cancelSourceIdentityHigh,
    sourceByteLength: MOTION_GESTURE_LEAF_SLOT.cancelSourceByteLength,
  },
};

function fnv1a64(value: string): bigint {
  let digest = 0xcbf29ce484222325n;
  for (const byte of new TextEncoder().encode(value)) {
    digest = BigInt.asUintN(64, (digest ^ BigInt(byte)) * 0x100000001b3n);
  }
  return digest === 0n ? 1n : digest;
}

function splitU64(value: bigint): readonly [number, number] {
  return [Number(value & 0xffff_ffffn), Number(value >> 32n)];
}

function writeU64(
  parameters: number[],
  lowSlot: number,
  highSlot: number,
  value: bigint,
): void {
  const [low, high] = splitU64(value);
  parameters[lowSlot] = low;
  parameters[highSlot] = high;
}

function u32(value: unknown, label: string): number {
  if (!Number.isInteger(value) || (value as number) < 0 || (value as number) > U32_MAX) {
    throw new RangeError(`[motion] ${label} must be a u32`);
  }
  return value as number;
}

function nonzeroU32(value: unknown, label: string): number {
  const cooked = u32(value, label);
  if (cooked === 0) throw new RangeError(`[motion] ${label} must be nonzero`);
  return cooked;
}

function nonzeroU64(value: unknown, label: string): bigint {
  let cooked: bigint;
  if (typeof value === 'bigint') {
    cooked = value;
  } else if (typeof value === 'string' && /^(?:0|[1-9][0-9]*)$/.test(value)) {
    cooked = BigInt(value);
  } else {
    throw new TypeError(`[motion] ${label} must be a canonical decimal u64`);
  }
  if (cooked <= 0n || cooked > 0xffff_ffff_ffff_ffffn) {
    throw new RangeError(`[motion] ${label} must be a nonzero u64`);
  }
  return cooked;
}

function finite(value: unknown, label: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`[motion] ${label} must be finite`);
  }
  return value;
}

function nonnegative(value: unknown, label: string): number {
  const cooked = finite(value, label);
  if (cooked < 0) throw new RangeError(`[motion] ${label} must not be negative`);
  return cooked;
}

function finiteF32(value: unknown, label: string): number {
  const cooked = Math.fround(finite(value, label));
  if (!Number.isFinite(cooked)) {
    throw new RangeError(`[motion] ${label} is outside the finite f32 range`);
  }
  return cooked;
}

function nonemptyString(value: unknown, label: string): string {
  if (typeof value !== 'string' || value.length === 0) {
    throw new TypeError(`[motion] ${label} must be a non-empty string`);
  }
  return value;
}

function stringArray(value: unknown, label: string, maximum = 16): string[] {
  if (!Array.isArray(value) || value.length > maximum) {
    throw new TypeError(`[motion] ${label} must be an array of at most ${maximum} strings`);
  }
  const strings = value.map((item, index) => nonemptyString(item, `${label}[${index}]`));
  if (new Set(strings).size !== strings.length) {
    throw new TypeError(`[motion] ${label} must not contain duplicate entries`);
  }
  return strings;
}

function runtimeArtifact(
  value: unknown,
  label: string,
): RuntimeMotionWorkletArtifact | undefined {
  if (value === undefined) return undefined;
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`[motion] ${label} must be a typed worklet artifact`);
  }
  return value as RuntimeMotionWorkletArtifact;
}

function sharedValueCapture(
  value: unknown,
  label: string,
): MotionWorkletSharedValueCaptureSource {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new TypeError(`[motion] ${label} must be a SharedValue`);
  }
  const candidate = value as Partial<MotionWorkletSharedValueCaptureSource>;
  const id = nonemptyString(candidate.id, `${label} id`);
  const generation = nonzeroU32(candidate.generation, `${label} generation`);
  if (typeof candidate.current !== 'function') {
    throw new TypeError(`[motion] ${label} must expose current()`);
  }
  const current = candidate.current.call(value);
  finiteF32(current, `${label} current value`);
  void id;
  void generation;
  return value as MotionWorkletSharedValueCaptureSource;
}

function callbackRecords(
  value: unknown,
  label: string,
  identityFor: (authoredIdentity: number) => number = (identity) => identity,
): {
  records: MotionWorkletInstallCallback[];
  registrations: UnfencedMotionWorkletCallbackRegistration[];
} {
  if (value === undefined) return { records: [], registrations: [] };
  if (!Array.isArray(value) || value.length > 16) {
    throw new TypeError(`[motion] ${label} must be an array of at most 16 callbacks`);
  }
  const records: MotionWorkletInstallCallback[] = [];
  const registrations: UnfencedMotionWorkletCallbackRegistration[] = [];
  const authoredIdentities = new Set<number>();
  const runtimeIdentities = new Set<number>();
  for (let index = 0; index < value.length; index += 1) {
    const candidate = value[index];
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
      throw new TypeError(`[motion] ${label}[${index}] must be a callback record`);
    }
    const callback = candidate as RuntimeMotionWorkletCallback;
    const authoredIdentity = nonzeroU32(callback.identity, `${label}[${index}] identity`);
    if (authoredIdentities.has(authoredIdentity)) {
      throw new TypeError(
        `[motion] ${label} contains duplicate callback identity ${authoredIdentity}`,
      );
    }
    authoredIdentities.add(authoredIdentity);
    const identity = nonzeroU32(
      identityFor(authoredIdentity),
      `${label}[${index}] runtime identity`,
    );
    if (runtimeIdentities.has(identity)) {
      throw new TypeError(`[motion] ${label} runtime callback identity ${identity} collides`);
    }
    runtimeIdentities.add(identity);
    const action = nonemptyString(callback.action, `${label}[${index}] action`);
    const payloadKeys = stringArray(callback.payloadKeys, `${label}[${index}] payloadKeys`);
    if (typeof callback.callback !== 'function') {
      throw new TypeError(`[motion] ${label}[${index}] callback must be a function`);
    }
    const record = Object.freeze({ identity, action, payloadKeys: Object.freeze(payloadKeys) });
    records.push(record);
    registrations.push(Object.freeze({
      ...record,
      callback: callback.callback as (...args: unknown[]) => unknown,
    }));
  }
  return { records, registrations };
}

function runtimeRunOnJSIdentity(
  descriptorId: bigint,
  phase: MotionWorkletInstallPhase,
  compilerId: string,
  authoredIdentity: number,
): number {
  const digest = fnv1a64(
    `motion-run-on-js:${descriptorId.toString()}:${phase}:${compilerId}:${authoredIdentity}`,
  );
  const identity = Number(digest & 0xffff_ffffn) >>> 0;
  return identity === 0 ? 1 : identity;
}

function rewriteRunOnJSIdentities(
  source: string,
  identities: ReadonlyMap<number, number>,
  label: string,
): string {
  return source.replace(/worklet\.runOnJS\((\d+)(?=,|\))/g, (match, rawIdentity: string) => {
    const authoredIdentity = Number(rawIdentity);
    const runtimeIdentity = identities.get(authoredIdentity);
    if (runtimeIdentity === undefined) {
      throw new TypeError(
        `[motion] ${label} source references unregistered runOnJS callback ${rawIdentity}`,
      );
    }
    return match.replace(rawIdentity, String(runtimeIdentity));
  });
}

function captureIdentityPart(capture: MotionWorkletInstallCapture): string {
  switch (capture.kind) {
    case 'f32': return `f32:${capture.name}:${Object.is(capture.value, -0) ? '-0' : capture.value}`;
    case 'bool': return `bool:${capture.name}:${capture.value ? 1 : 0}`;
    case 'sharedValue':
      return `shared:${capture.name}:${capture.descriptorId}:${capture.generation}`;
  }
}

function present(
  parameters: number[],
  key: keyof typeof MOTION_GESTURE_NATIVE_SCHEMA.optionPresenceBits,
): void {
  parameters[MOTION_GESTURE_LEAF_SLOT.optionPresenceMask] +=
    2 ** MOTION_GESTURE_NATIVE_SCHEMA.optionPresenceBits[key];
}

function commandShape(value: unknown, label: string): MotionCommandShape {
  if (!value || typeof value !== 'object') {
    throw new TypeError(`[motion] ${label} must be a command identity`);
  }
  const command = value as Partial<MotionCommandShape>;
  if (
    typeof command.commandInstanceId !== 'string' || command.commandInstanceId.length === 0 ||
    typeof command.action !== 'string' || command.action.length === 0 ||
    typeof command.ownerInstance !== 'string' || command.ownerInstance.length === 0
  ) {
    throw new TypeError(`[motion] ${label} has an invalid command identity`);
  }
  return {
    commandInstanceId: command.commandInstanceId,
    action: command.action,
    ownerInstance: command.ownerInstance,
    bindingGeneration: nonzeroU32(command.bindingGeneration, `${label} bindingGeneration`),
  };
}

function sameCommand(left: MotionCommandShape, right: MotionCommandShape): boolean {
  return left.commandInstanceId === right.commandInstanceId &&
    left.action === right.action &&
    left.ownerInstance === right.ownerInstance &&
    left.bindingGeneration === right.bindingGeneration;
}

function writeCommand(
  parameters: number[],
  command: MotionCommandShape,
  slots: {
    instanceLow: number;
    instanceHigh: number;
    actionLow: number;
    actionHigh: number;
    ownerLow: number;
    ownerHigh: number;
    generation: number;
  },
): void {
  const digests = motionCommandIdentityDigests(command);
  writeU64(
    parameters,
    slots.instanceLow,
    slots.instanceHigh,
    digests.commandInstanceHash,
  );
  writeU64(
    parameters,
    slots.actionLow,
    slots.actionHigh,
    digests.actionHash,
  );
  writeU64(
    parameters,
    slots.ownerLow,
    slots.ownerHigh,
    digests.ownerHash,
  );
  parameters[slots.generation] = command.bindingGeneration;
}

function offsetBounds(
  value: unknown,
  label: string,
): readonly [number, number] {
  if (typeof value === 'number') {
    const magnitude = Math.abs(finite(value, label));
    return [-magnitude, magnitude];
  }
  if (!Array.isArray(value) || value.length !== 2) {
    throw new TypeError(`[motion] ${label} must be a number or [min, max] tuple`);
  }
  const minimum = finite(value[0], `${label} minimum`);
  const maximum = finite(value[1], `${label} maximum`);
  if (minimum > maximum) {
    throw new RangeError(`[motion] ${label} minimum must not exceed maximum`);
  }
  return [minimum, maximum];
}

function writeWorklet(
  parameters: number[],
  descriptor: {
    authoredId: string;
    nativeId: bigint;
    nodeId: number;
    generation: number;
  },
  phase: MotionWorkletInstallPhase,
  callback: unknown,
  collector: WorkletCollector,
): void {
  if (typeof callback !== 'function') {
    throw new TypeError(`[motion] ${descriptor.authoredId} ${phase} callback must be a function`);
  }
  const metadata = callback as MotionWorkletCallback;
  if (
    metadata.__exactMotionWorkletId !== undefined &&
    (typeof metadata.__exactMotionWorkletId !== 'string' ||
      metadata.__exactMotionWorkletId.length === 0)
  ) {
    throw new TypeError(`[motion] ${descriptor.authoredId} ${phase} has an invalid worklet id`);
  }
  if (
    metadata.__workletSource !== undefined &&
    (typeof metadata.__workletSource !== 'string' || metadata.__workletSource.length === 0)
  ) {
    throw new TypeError(`[motion] ${descriptor.authoredId} ${phase} has invalid extracted source`);
  }

  const explicitId = metadata.__exactMotionWorkletId as string | undefined;
  let source = metadata.__workletSource as string | undefined;
  const artifact = runtimeArtifact(
    metadata.__exactMotionWorkletArtifact,
    `${descriptor.authoredId} ${phase} worklet artifact`,
  );
  let installArtifact: MotionWorkletInstallArtifact | undefined;
  let artifactCallbackIdentity: bigint | undefined;
  if (artifact) {
    if (artifact.schemaVersion !== 1 || artifact.installFormat !== 'source-utf8') {
      throw new TypeError(
        `[motion] ${descriptor.authoredId} ${phase} has an unsupported worklet artifact schema`,
      );
    }
    const compilerId = nonemptyString(
      artifact.compilerId,
      `${descriptor.authoredId} ${phase} compilerId`,
    );
    if (explicitId !== undefined && explicitId !== compilerId) {
      throw new TypeError(`[motion] ${descriptor.authoredId} ${phase} worklet id disagrees with artifact`);
    }
    const declaredArtifactSource = nonemptyString(
      artifact.source,
      `${descriptor.authoredId} ${phase} source`,
    );
    if (source !== undefined && source !== declaredArtifactSource) {
      throw new TypeError(`[motion] ${descriptor.authoredId} ${phase} source disagrees with artifact`);
    }
    const captureNames = stringArray(
      artifact.captureNames,
      `${descriptor.authoredId} ${phase} captureNames`,
      64,
    );
    if (!Array.isArray(artifact.captureKinds) || !Array.isArray(artifact.captures)) {
      throw new TypeError(`[motion] ${descriptor.authoredId} ${phase} captures must be arrays`);
    }
    if (
      artifact.captureKinds.length !== captureNames.length ||
      artifact.captures.length !== captureNames.length
    ) {
      throw new TypeError(`[motion] ${descriptor.authoredId} ${phase} capture vectors disagree`);
    }
    const captures: MotionWorkletInstallCapture[] = [];
    for (let index = 0; index < captureNames.length; index += 1) {
      const name = captureNames[index]!;
      const kind = artifact.captureKinds[index];
      const value = artifact.captures[index];
      if (kind === 'scalar') {
        if (typeof value === 'boolean') {
          captures.push(Object.freeze({ kind: 'bool', name, value }));
        } else {
          captures.push(Object.freeze({
            kind: 'f32',
            name,
            value: finiteF32(value, `${descriptor.authoredId} ${phase} capture ${name}`),
          }));
        }
        continue;
      }
      if (kind !== 'sharedValue') {
        throw new TypeError(
          `[motion] ${descriptor.authoredId} ${phase} capture ${name} has unsupported kind`,
        );
      }
      const shared = sharedValueCapture(
        value,
        `${descriptor.authoredId} ${phase} capture ${name}`,
      );
      let descriptorId: string;
      if (shared.__exactMotionDescriptorId !== undefined) {
        descriptorId = nonzeroU64(
          shared.__exactMotionDescriptorId,
          `${descriptor.authoredId} ${phase} capture ${name} descriptorId`,
        ).toString();
      } else {
        const existing = collector.sharedValueCaptures.get(shared.id);
        if (existing && existing !== shared) {
          throw new Error(`[motion] SharedValue identity collision at ${shared.id}`);
        }
        collector.sharedValueCaptures.set(shared.id, shared);
        descriptorId = fnv1a64(`shared:${shared.id}`).toString();
      }
      captures.push(Object.freeze({
        kind: 'sharedValue',
        name,
        descriptorId,
        generation: shared.generation,
      }));
    }
    const inputSlots = stringArray(
      artifact.inputSlots,
      `${descriptor.authoredId} ${phase} inputSlots`,
    );
    const outputSlots = stringArray(
      artifact.outputSlots,
      `${descriptor.authoredId} ${phase} outputSlots`,
    );
    const callbackIdentityMap = new Map<number, number>();
    const callbacks = callbackRecords(
      artifact.callbacks,
      `${descriptor.authoredId} ${phase} callbacks`,
      (authoredIdentity) => {
        const runtimeIdentity = runtimeRunOnJSIdentity(
          descriptor.nativeId,
          phase,
          compilerId,
          authoredIdentity,
        );
        callbackIdentityMap.set(authoredIdentity, runtimeIdentity);
        return runtimeIdentity;
      },
    );
    const artifactSource = rewriteRunOnJSIdentities(
      declaredArtifactSource,
      callbackIdentityMap,
      `${descriptor.authoredId} ${phase}`,
    );
    source = artifactSource;
    const logicalIdentity = fnv1a64(
      `motion-worklet-typed:${artifactSource}\0${captures.map(captureIdentityPart).join('\0')}`,
    );
    // Derive descriptors do not carry a callback identity in the binary
    // graph (native invokes them by (rootId, descriptorId, phase)), so their
    // install identity may — and must — include the descriptor: two sinks
    // with byte-identical expressions over the same shared value (every
    // tile binding its radius to one live SharedValue) otherwise mint the
    // same callbackIdentity under different descriptors and the plane fails
    // the generated uniqueness contract. Gesture-phase identities stay
    // descriptor-free because the binary gesture record embeds them.
    artifactCallbackIdentity = fnv1a64(
      phase === 'derive'
        ? `motion-callback:${phase}:${compilerId}:${descriptor.nativeId.toString()}:${logicalIdentity.toString(16)}`
        : `motion-callback:${phase}:${compilerId}:${logicalIdentity.toString(16)}`,
    );
    const frozenArtifact = Object.freeze({
      schemaVersion: MOTION_WORKLET_INSTALL_PLANE_SCHEMA_VERSION,
      descriptorId: descriptor.nativeId.toString(),
      nodeId: descriptor.nodeId,
      phase,
      generation: descriptor.generation,
      compilerId,
      installFormat: 'source-utf8',
      source: artifactSource,
      sourceIdentity: logicalIdentity.toString(),
      callbackIdentity: artifactCallbackIdentity.toString(),
      captures: Object.freeze(captures),
      inputSlots: Object.freeze(inputSlots),
      outputSlots: Object.freeze(outputSlots),
      callbacks: Object.freeze(callbacks.records),
    });
    installArtifact = frozenArtifact;
    // One derive node can be referenced by several sinks in the same commit
    // (e.g. every tile binding its radius to one shared live SharedValue);
    // each reference lowers the same descriptor. The plane's uniqueness
    // contract is (descriptorId, phase) + callbackIdentity, so an IDENTICAL
    // artifact collapses to one entry — only a conflicting duplicate (same
    // identity, different content) may reach the native validator's
    // fail-closed rejection.
    const existingArtifact = collector.artifacts.find((candidate) =>
      candidate.descriptorId === frozenArtifact.descriptorId &&
      candidate.phase === frozenArtifact.phase);
    const identicalDuplicate = existingArtifact !== undefined &&
      existingArtifact.callbackIdentity === frozenArtifact.callbackIdentity &&
      existingArtifact.sourceIdentity === frozenArtifact.sourceIdentity &&
      existingArtifact.generation === frozenArtifact.generation;
    if (!identicalDuplicate) {
      // A conflicting duplicate (same identity, different content) is still
      // pushed so the native validator rejects it loudly.
      collector.artifacts.push(frozenArtifact);
    }
    collector.callbackRegistrations.push(...callbacks.registrations.map((registration) =>
      Object.freeze({
        ...registration,
        sourceIdentity: frozenArtifact.sourceIdentity,
        generation: frozenArtifact.generation,
      })));
  }
  const sourceIdentity = installArtifact !== undefined
    ? BigInt(installArtifact.sourceIdentity)
    : source === undefined
    ? explicitId === undefined
      ? 0n
      : fnv1a64(`motion-worklet-bundle:${explicitId}`)
    : fnv1a64(`motion-worklet-source:${source}`);
  const callbackIdentity = artifactCallbackIdentity ?? fnv1a64(
    `motion-callback:${phase}:${explicitId ?? (
      sourceIdentity === 0n ? descriptor.authoredId : sourceIdentity.toString(16)
    )}`,
  );
  if (phase === 'derive') return;
  const slots = CALLBACK_SLOTS[phase];
  writeU64(parameters, slots.identityLow, slots.identityHigh, callbackIdentity);
  parameters[slots.sourceKind] = source !== undefined
    ? MOTION_GESTURE_NATIVE_SCHEMA.workletSourceCodes.compiledSourceRegistry
    : explicitId !== undefined
      ? MOTION_GESTURE_NATIVE_SCHEMA.workletSourceCodes.bundleRegistry
      : MOTION_GESTURE_NATIVE_SCHEMA.workletSourceCodes.unresolvedFunction;
  writeU64(parameters, slots.sourceIdentityLow, slots.sourceIdentityHigh, sourceIdentity);
  parameters[slots.sourceByteLength] = source === undefined
    ? 0
    : new TextEncoder().encode(source).byteLength;
}

function validateLeafOptions(descriptor: MotionGestureLeafDescriptor): void {
  const { options, kind, id } = descriptor;
  if (!options || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError(`[motion] gesture ${id} options must be an object`);
  }
  for (const key of Object.keys(options)) {
    if (!KNOWN_OPTION_KEYS.has(key as GestureOptionKey)) {
      throw new TypeError(`[motion] ${kind} has no option "${key}"`);
    }
  }
  if (options.axis !== undefined && !(options.axis in MOTION_GESTURE_NATIVE_SCHEMA.axisCodes)) {
    throw new TypeError(`[motion] ${kind} axis is not supported`);
  }
  if (
    options.direction !== undefined &&
    !(options.direction in MOTION_GESTURE_NATIVE_SCHEMA.directionCodes)
  ) {
    throw new TypeError(`[motion] ${kind} direction is not supported`);
  }
  if (options.claim !== undefined && (typeof options.claim !== 'string' || options.claim.length === 0)) {
    throw new TypeError(`[motion] ${kind} claim must be a non-empty testId`);
  }
  for (const key of [
    'minDistance',
    'minDurationMs',
    'maxDurationMs',
    'maxDistance',
    'maxInterTapMs',
    'minVelocity',
    'minScaleDelta',
    'minRotationRadians',
  ] as const) {
    if (options[key] !== undefined) nonnegative(options[key], `${kind} ${key}`);
  }
  for (const key of ['tapCount', 'pointerCount'] as const) {
    if (options[key] !== undefined) nonzeroU32(options[key], `${kind} ${key}`);
  }
  if (options.axisLockRatio !== undefined && finite(options.axisLockRatio, `${kind} axisLockRatio`) < 1) {
    throw new RangeError(`[motion] ${kind} axisLockRatio must be at least one`);
  }
  if (options.failCrossAxis !== undefined && typeof options.failCrossAxis !== 'boolean') {
    throw new TypeError(`[motion] ${kind} failCrossAxis must be a boolean`);
  }
  if (
    (kind === 'pinch' || kind === 'rotation') &&
    options.pointerCount !== undefined &&
    options.pointerCount !== 2
  ) {
    throw new RangeError(`[motion] ${kind} pointerCount must be exactly two`);
  }
  if (
    options.minDurationMs !== undefined &&
    options.maxDurationMs !== undefined &&
    options.minDurationMs > options.maxDurationMs
  ) {
    throw new RangeError(`[motion] ${kind} minDurationMs must not exceed maxDurationMs`);
  }
  if (options.activeOffsetX !== undefined) offsetBounds(options.activeOffsetX, `${kind} activeOffsetX`);
  if (options.activeOffsetY !== undefined) offsetBounds(options.activeOffsetY, `${kind} activeOffsetY`);
  for (const phase of MOTION_GESTURE_NATIVE_SCHEMA.callbackPhases) {
    const callback = options[phase];
    if (callback !== undefined && typeof callback !== 'function') {
      throw new TypeError(`[motion] ${kind} ${phase} callback must be a function`);
    }
  }
  if (options.command !== undefined) commandShape(options.command, `${kind} command`);
  if ((options.prospective !== undefined || options.prospectiveTarget !== undefined) && options.command === undefined) {
    throw new TypeError(`[motion] ${kind} prospective values require a command binding`);
  }
  if (options.prospectiveTarget !== undefined && options.prospective === undefined) {
    throw new TypeError(`[motion] ${kind} prospectiveTarget requires prospective`);
  }
  if (
    options.prospective !== undefined &&
    options.prospectiveTarget !== undefined &&
    (
      options.prospective === options.prospectiveTarget ||
      (
        options.prospective.id === options.prospectiveTarget.id &&
        options.prospective.generation === options.prospectiveTarget.generation
      )
    )
  ) {
    throw new TypeError(
      `[motion] ${kind} prospective and prospectiveTarget must reference distinct SharedValues`,
    );
  }
  if (options.prospective !== undefined) {
    sharedValueCapture(options.prospective, `${kind} prospective`);
  }
  if (options.prospectiveTarget !== undefined) {
    sharedValueCapture(options.prospectiveTarget, `${kind} prospectiveTarget`);
  }
}

function prospectiveDescriptorIds(
  descriptor: MotionGestureLeafDescriptor,
  collector: WorkletCollector,
): bigint[] {
  const ids = [
    ['prospective', descriptor.options.prospective],
    ['prospectiveTarget', descriptor.options.prospectiveTarget],
  ].flatMap(([label, candidate]) => {
    if (candidate === undefined) return [];
    const shared = sharedValueCapture(candidate, `${descriptor.kind} ${label}`);
    if (shared.__exactMotionDescriptorId !== undefined) {
      return [nonzeroU64(
        shared.__exactMotionDescriptorId,
        `${descriptor.kind} ${label} descriptorId`,
      )];
    }
    const existing = collector.sharedValueCaptures.get(shared.id);
    if (existing && existing !== shared) {
      throw new Error(`[motion] SharedValue identity collision at ${shared.id}`);
    }
    collector.sharedValueCaptures.set(shared.id, shared);
    return [fnv1a64(`shared:${shared.id}`)];
  });
  if (ids.length === 2 && ids[0] === ids[1]) {
    throw new TypeError(
      `[motion] ${descriptor.kind} prospective and prospectiveTarget must reference distinct SharedValues`,
    );
  }
  return ids;
}

function leafParameters(
  descriptor: MotionGestureLeafDescriptor,
  nativeId: bigint,
  nodeId: number,
  generation: number,
  collector: WorkletCollector,
): number[] {
  validateLeafOptions(descriptor);
  const { options } = descriptor;
  const parameters = new Array<number>(
    MOTION_GESTURE_NATIVE_SCHEMA.leafParameterSlots.length,
  ).fill(0);
  parameters[MOTION_GESTURE_LEAF_SLOT.layoutVersion] =
    MOTION_GESTURE_NATIVE_SCHEMA.descriptorLayoutVersion;
  parameters[MOTION_GESTURE_LEAF_SLOT.schemaDigestLow] =
    MOTION_GESTURE_NATIVE_SCHEMA_DIGEST_LOW;
  parameters[MOTION_GESTURE_LEAF_SLOT.schemaDigestHigh] =
    MOTION_GESTURE_NATIVE_SCHEMA_DIGEST_HIGH;

  if (options.axis !== undefined) {
    present(parameters, 'axis');
    parameters[MOTION_GESTURE_LEAF_SLOT.axisCode] =
      MOTION_GESTURE_NATIVE_SCHEMA.axisCodes[options.axis];
  }
  if (options.direction !== undefined) {
    present(parameters, 'direction');
    parameters[MOTION_GESTURE_LEAF_SLOT.directionCode] =
      MOTION_GESTURE_NATIVE_SCHEMA.directionCodes[options.direction];
  }
  for (const [key, slot] of NUMERIC_OPTION_SLOTS) {
    const value = options[key];
    if (value !== undefined) {
      present(parameters, key);
      parameters[slot] = value;
    }
  }
  if (options.failCrossAxis !== undefined) {
    present(parameters, 'failCrossAxis');
    parameters[MOTION_GESTURE_LEAF_SLOT.failCrossAxis] = options.failCrossAxis ? 1 : 0;
  }
  for (const [key, minimumSlot, maximumSlot] of [
    [
      'activeOffsetX',
      MOTION_GESTURE_LEAF_SLOT.activeOffsetXMin,
      MOTION_GESTURE_LEAF_SLOT.activeOffsetXMax,
    ],
    [
      'activeOffsetY',
      MOTION_GESTURE_LEAF_SLOT.activeOffsetYMin,
      MOTION_GESTURE_LEAF_SLOT.activeOffsetYMax,
    ],
  ] as const) {
    const value = options[key];
    if (value !== undefined) {
      present(parameters, key);
      const [minimum, maximum] = offsetBounds(value, `${descriptor.kind} ${key}`);
      parameters[minimumSlot] = minimum;
      parameters[maximumSlot] = maximum;
    }
  }
  if (options.claim !== undefined) {
    present(parameters, 'claim');
    writeU64(
      parameters,
      MOTION_GESTURE_LEAF_SLOT.claimHashLow,
      MOTION_GESTURE_LEAF_SLOT.claimHashHigh,
      fnv1a64(`motion-gesture-claim:${options.claim}`),
    );
  }
  if (options.command !== undefined) {
    present(parameters, 'command');
    writeCommand(parameters, commandShape(options.command, `${descriptor.kind} command`), {
      instanceLow: MOTION_GESTURE_LEAF_SLOT.commandInstanceHashLow,
      instanceHigh: MOTION_GESTURE_LEAF_SLOT.commandInstanceHashHigh,
      actionLow: MOTION_GESTURE_LEAF_SLOT.commandActionHashLow,
      actionHigh: MOTION_GESTURE_LEAF_SLOT.commandActionHashHigh,
      ownerLow: MOTION_GESTURE_LEAF_SLOT.commandOwnerHashLow,
      ownerHigh: MOTION_GESTURE_LEAF_SLOT.commandOwnerHashHigh,
      generation: MOTION_GESTURE_LEAF_SLOT.commandBindingGeneration,
    });
  }
  for (const phase of MOTION_GESTURE_NATIVE_SCHEMA.callbackPhases) {
    const callback = options[phase];
    if (callback !== undefined) {
      present(parameters, phase);
      writeWorklet(parameters, {
        authoredId: descriptor.id,
        nativeId,
        nodeId,
        generation,
      }, phase, callback, collector);
    }
  }
  return parameters;
}

function compositionParameters(
  descriptor: MotionGestureCompositionDescriptor,
  claim: string | undefined,
  command: MotionCommandShape | undefined,
): number[] {
  const parameters = new Array<number>(
    MOTION_GESTURE_NATIVE_SCHEMA.compositionParameterSlots.length,
  ).fill(0);
  parameters[MOTION_GESTURE_COMPOSITION_SLOT.layoutVersion] =
    MOTION_GESTURE_NATIVE_SCHEMA.descriptorLayoutVersion;
  parameters[MOTION_GESTURE_COMPOSITION_SLOT.schemaDigestLow] =
    MOTION_GESTURE_NATIVE_SCHEMA_DIGEST_LOW;
  parameters[MOTION_GESTURE_COMPOSITION_SLOT.schemaDigestHigh] =
    MOTION_GESTURE_NATIVE_SCHEMA_DIGEST_HIGH;
  parameters[MOTION_GESTURE_COMPOSITION_SLOT.compositionCode] =
    MOTION_GESTURE_NATIVE_SCHEMA.compositionCodes[descriptor.composition];
  parameters[MOTION_GESTURE_COMPOSITION_SLOT.childCount] = descriptor.gestures.length;
  if (claim !== undefined) {
    writeU64(
      parameters,
      MOTION_GESTURE_COMPOSITION_SLOT.claimHashLow,
      MOTION_GESTURE_COMPOSITION_SLOT.claimHashHigh,
      fnv1a64(`motion-gesture-claim:${claim}`),
    );
  }
  if (command !== undefined) {
    writeCommand(parameters, command, {
      instanceLow: MOTION_GESTURE_COMPOSITION_SLOT.commandInstanceHashLow,
      instanceHigh: MOTION_GESTURE_COMPOSITION_SLOT.commandInstanceHashHigh,
      actionLow: MOTION_GESTURE_COMPOSITION_SLOT.commandActionHashLow,
      actionHigh: MOTION_GESTURE_COMPOSITION_SLOT.commandActionHashHigh,
      ownerLow: MOTION_GESTURE_COMPOSITION_SLOT.commandOwnerHashLow,
      ownerHigh: MOTION_GESTURE_COMPOSITION_SLOT.commandOwnerHashHigh,
      generation: MOTION_GESTURE_COMPOSITION_SLOT.commandBindingGeneration,
    });
  }
  return parameters;
}

function descriptorIdentity(rootId: number, nodeId: number, authoredId: string): bigint {
  return fnv1a64(`motion-gesture:${rootId}:${nodeId}:${authoredId}`);
}

/**
 * Lowers one React/Contract `__exactMotionGesture` host prop into records for
 * the authoritative whole-root Motion snapshot. Composition dependencies are
 * deliberately kept in authored child order; the snapshot's record list may
 * still be globally identity-sorted by host-ops.
 */
export function lowerMotionGestureSidecarRecords(
  rootId: number,
  nodeId: number,
  value: unknown,
  ownerTestId?: string,
): LoweredMotionGestureSidecarRecords {
  u32(rootId, 'gesture rootId');
  nonzeroU32(nodeId, 'gesture nodeId');
  const records: MotionDescriptorRecord[] = [];
  const collector: WorkletCollector = {
    artifacts: [],
    sharedValueCaptures: new Map(),
    callbackRegistrations: [],
  };
  const authoredIds = new Set<string>();
  const objects = new Set<object>();
  const nativeIds = new Set<bigint>();

  const visit = (
    candidate: unknown,
    depth: number,
  ): { id: bigint; claims: Set<string>; commands: MotionCommandShape[] } => {
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
      throw new TypeError('[motion] __exactMotionGesture must be a gesture descriptor');
    }
    if (depth > 64 || objects.has(candidate)) {
      throw new TypeError('[motion] gesture descriptor graph is cyclic or too deep');
    }
    objects.add(candidate);
    const descriptor = candidate as Partial<MotionGestureDescriptor>;
    if (
      (descriptor as { __exactMotionKind?: unknown }).__exactMotionKind !== MOTION_GESTURE_KIND ||
      typeof descriptor.id !== 'string' || descriptor.id.length === 0 ||
      authoredIds.has(descriptor.id)
    ) {
      throw new TypeError('[motion] gesture descriptor has an invalid or duplicate identity');
    }
    authoredIds.add(descriptor.id);
    const generation = nonzeroU32(descriptor.generation, `gesture ${descriptor.id} generation`);
    const id = descriptorIdentity(rootId, nodeId, descriptor.id);
    if (nativeIds.has(id)) {
      throw new TypeError(`[motion] gesture descriptor identity collision at ${id}`);
    }
    nativeIds.add(id);

    if (descriptor.descriptorType === 'gesture') {
      if (
        descriptor.kind === undefined ||
        !(descriptor.kind in MOTION_GESTURE_NATIVE_SCHEMA.gestureKindCodes)
      ) {
        throw new TypeError(`[motion] gesture ${descriptor.id} has an unsupported kind`);
      }
      const leaf = descriptor as MotionGestureLeafDescriptor;
      const parameters = leafParameters(leaf, id, nodeId, generation, collector);
      const prospective = prospectiveDescriptorIds(leaf, collector);
      records.push({
        id,
        generation,
        nodeId,
        kind: MOTION_GESTURE_NATIVE_SCHEMA.gestureKindCodes[leaf.kind] as MotionDescriptorKind,
        dependencies: prospective,
        parameters,
      });
      const claims = new Set<string>();
      if (leaf.options.claim !== undefined) claims.add(leaf.options.claim);
      const commands = leaf.options.command === undefined
        ? []
        : [commandShape(leaf.options.command, `${leaf.kind} command`)];
      return { id, claims, commands };
    }

    if (
      descriptor.descriptorType !== 'composition' ||
      descriptor.kind !== 'composition' ||
      descriptor.composition === undefined ||
      !(descriptor.composition in MOTION_GESTURE_NATIVE_SCHEMA.compositionCodes) ||
      !Array.isArray(descriptor.gestures) ||
      descriptor.gestures.length < 2
    ) {
      throw new TypeError(`[motion] gesture ${descriptor.id} has an invalid composition`);
    }
    const composition = descriptor as MotionGestureCompositionDescriptor;
    const children = composition.gestures.map((gesture) => visit(gesture, depth + 1));
    const claims = new Set(children.flatMap((child) => [...child.claims]));
    const commands = children.flatMap((child) => child.commands);
    if (composition.claim !== undefined) {
      if (typeof composition.claim !== 'string' || composition.claim.length === 0) {
        throw new TypeError(`[motion] composition ${composition.id} has an invalid claim`);
      }
      claims.add(composition.claim);
    }
    if (claims.size > 1) {
      throw new TypeError(`[motion] composition ${composition.id} spans multiple claims`);
    }
    if (composition.command !== undefined) {
      commands.push(commandShape(composition.command, `composition ${composition.id} command`));
    }
    const command = commands[0];
    if (command && commands.some((candidateCommand) => !sameCommand(command, candidateCommand))) {
      throw new TypeError(`[motion] composition ${composition.id} spans multiple commands`);
    }
    const claim = [...claims][0];
    records.push({
      id,
      generation,
      nodeId,
      kind: MotionDescriptorKind.Composition,
      dependencies: children.map((child) => child.id),
      parameters: compositionParameters(composition, claim, command),
    });
    return { id, claims, commands: command ? [command] : [] };
  };

  const root = visit(value, 0);
  if (root.claims.size > 0) {
    if (ownerTestId === undefined) {
      throw new TypeError('[motion] a claimed gesture requires testId on its host node');
    }
    if (!root.claims.has(ownerTestId)) {
      throw new TypeError(
        `[motion] gesture claim "${[...root.claims][0]}" does not match host testId "${ownerTestId}"`,
      );
    }
  }
  collector.artifacts.sort((left, right) => {
    const descriptorDifference = BigInt(left.descriptorId) < BigInt(right.descriptorId)
      ? -1
      : BigInt(left.descriptorId) > BigInt(right.descriptorId) ? 1 : 0;
    return descriptorDifference ||
      MOTION_GESTURE_NATIVE_SCHEMA.callbackPhases.indexOf(left.phase as GesturePhase) -
        MOTION_GESTURE_NATIVE_SCHEMA.callbackPhases.indexOf(right.phase as GesturePhase);
  });
  // One derive node referenced by several sinks (every tile binding radius to
  // one shared live SharedValue) lowers once per reference; the plane's
  // uniqueness contract is (descriptorId, phase) + callbackIdentity, so
  // IDENTICAL artifacts collapse to one entry. A conflicting duplicate (same
  // key, different content) is kept for the native validator's fail-closed
  // rejection.
  const dedupedArtifacts = collector.artifacts.filter((artifact, index) => {
    if (index === 0) return true;
    const previous = collector.artifacts[index - 1]!;
    const identical = previous.descriptorId === artifact.descriptorId &&
      previous.phase === artifact.phase &&
      previous.callbackIdentity === artifact.callbackIdentity &&
      previous.sourceIdentity === artifact.sourceIdentity &&
      previous.generation === artifact.generation;
    return !identical;
  });
  return {
    descriptors: records,
    artifacts: dedupedArtifacts,
    sharedValueCaptures: collector.sharedValueCaptures,
    callbackRegistrations: collector.callbackRegistrations,
  };
}

export interface LoweredMotionDerivedWorkletArtifact {
  readonly artifact: MotionWorkletInstallArtifact;
  readonly sharedValueCaptures: ReadonlyMap<string, MotionWorkletSharedValueCaptureSource>;
  readonly callbackRegistrations: readonly MotionWorkletCallbackRegistration[];
}

/**
 * Project one DerivedValue graph node onto the same typed installer used by
 * gesture callbacks. Graph callers own descriptor topology; this helper owns
 * the closed source/capture/output validation and JSON-safe artifact record.
 */
export function lowerMotionDerivedWorkletArtifact(input: {
  readonly authoredId: string;
  readonly descriptorId: bigint;
  readonly nodeId: number;
  readonly generation: number;
  readonly artifact: unknown;
}): LoweredMotionDerivedWorkletArtifact {
  const artifact = runtimeArtifact(input.artifact, `${input.authoredId} derive worklet artifact`);
  if (!artifact) throw new TypeError(`[motion] ${input.authoredId} has no derive worklet artifact`);
  const callback = Object.assign(
    () => undefined,
    {
      __exactMotionWorkletId: artifact.compilerId,
      __workletSource: artifact.source,
      __exactMotionWorkletArtifact: artifact,
    },
  );
  const collector: WorkletCollector = {
    artifacts: [],
    sharedValueCaptures: new Map(),
    callbackRegistrations: [],
  };
  writeWorklet(
    [],
    {
      authoredId: nonemptyString(input.authoredId, 'derive authoredId'),
      nativeId: nonzeroU64(input.descriptorId, 'derive descriptorId'),
      nodeId: u32(input.nodeId, 'derive nodeId'),
      generation: nonzeroU32(input.generation, 'derive generation'),
    },
    'derive',
    callback,
    collector,
  );
  const lowered = collector.artifacts[0];
  if (!lowered || collector.artifacts.length !== 1) {
    throw new Error(`[motion] ${input.authoredId} did not produce exactly one derive artifact`);
  }
  return {
    artifact: lowered,
    sharedValueCaptures: collector.sharedValueCaptures,
    callbackRegistrations: collector.callbackRegistrations,
  };
}

/** Compatibility projection for callers that only consume graph records. */
export function lowerMotionGestureDescriptorRecords(
  rootId: number,
  nodeId: number,
  value: unknown,
  ownerTestId?: string,
): MotionDescriptorRecord[] {
  return lowerMotionGestureSidecarRecords(rootId, nodeId, value, ownerTestId).descriptors;
}

export function motionGestureDescriptorNativeId(
  rootId: number,
  nodeId: number,
  authoredId: string,
): bigint {
  return descriptorIdentity(rootId, nodeId, authoredId);
}
