import { isAssetRef } from '@exact/core/assets-fonts-state';

import {
  resolveImagePlaceholderForNative,
  resolveImageSourceForNative,
  warnIfImageMissingAlt,
} from '../image-source.js';
import {
  resolveSvgSourceForFetch,
  resolveSvgSourceForNative,
} from '../svg-source.js';
import type {
  CanonicalProps,
  ColorSchemeImageSource,
  ImagePlaceholder,
  ImageSource,
  ResizeMode,
  SvgSource,
} from '../types.js';
import { canonicalImageColorMatrixProp } from './image-color-matrix.js';
import { extractResizeMode, normalizeImageDynamicRange } from './normalize.js';
import type { ImagePropsRuntime } from './image-runtime.js';

export function extractWebImageSource(props: Record<string, unknown>): string | undefined {
  const themed = imageSourceFromThemeProps(props);
  if (themed) {
    return resolveImageSourceForNative(themed, undefined, imageCacheAliases(props));
  }

  const src = props.src;
  if (typeof src === 'string' && src.length > 0) {
    return resolveImageSourceForNative(src, undefined, imageCacheAliases(props));
  }
  if (typeof src === 'object' && src !== null) {
    return resolveImageSourceForNative(src as ImageSource, undefined, imageCacheAliases(props));
  }
  return undefined;
}

export function extractRNImageSource(props: Record<string, unknown>): string | undefined {
  const themed = imageSourceFromThemeProps(props);
  if (themed) {
    return resolveImageSourceForNative(themed, undefined, imageCacheAliases(props));
  }

  const source = props.source as ImageSource | undefined;
  if (!source) {
    return undefined;
  }

  return resolveImageSourceForNative(source, undefined, imageCacheAliases(props));
}

function imageCacheAliases(props: Record<string, unknown>): {
  cacheKey?: string;
  cachePolicy?: 'auto' | 'disk' | 'memory' | 'none';
} {
  const cacheKey = typeof props.cacheKey === 'string' && props.cacheKey.length > 0
    ? props.cacheKey
    : undefined;
  const cachePolicy =
    props.cachePolicy === 'auto' ||
    props.cachePolicy === 'disk' ||
    props.cachePolicy === 'memory' ||
    props.cachePolicy === 'none'
      ? props.cachePolicy
      : undefined;
  return { ...(cacheKey ? { cacheKey } : {}), ...(cachePolicy ? { cachePolicy } : {}) };
}

function imageSourceFromThemeProps(props: Record<string, unknown>): ColorSchemeImageSource | undefined {
  const light = typeof props.lightSrc === 'string' && props.lightSrc.length > 0
    ? props.lightSrc
    : undefined;
  const dark = typeof props.darkSrc === 'string' && props.darkSrc.length > 0
    ? props.darkSrc
    : undefined;
  if (!light && !dark) {
    return undefined;
  }

  return {
    ...(light ? { light } : {}),
    ...(dark ? { dark } : {}),
    ...(typeof props.src === 'string' && props.src.length > 0 ? { fallback: props.src } : {}),
  };
}

function extractSvgSource(props: Record<string, unknown>): string | undefined {
  const source = props.source as SvgSource | undefined;
  if (!source) {
    return undefined;
  }

  if (typeof source === 'string' && source.length > 0) {
    return source;
  }

  if (isAssetRef(source)) {
    return source.url;
  }

  if (typeof source === 'object' && source !== null && typeof source.uri === 'string' && source.uri.length > 0) {
    return source.uri;
  }

  return undefined;
}

function normalizeImage(
  props: Record<string, unknown>,
  isRNStyle: boolean,
  canonical: CanonicalProps,
): void {
  warnIfImageMissingAlt({
    alt: typeof props.alt === 'string' ? props.alt : undefined,
    decorative: props.decorative === true,
    source: (imageSourceFromThemeProps(props) ?? (isRNStyle ? props.source : props.src)) as ImageSource | undefined,
    testID: typeof props.testID === 'string' ? props.testID : undefined,
  });

  const source = isRNStyle
    ? extractRNImageSource(props)
    : extractWebImageSource(props);
  if (source) {
    canonical.imageSource = source;
  }

  // Inline-SVG glyphs carry their artwork as markup rather than a `src`.
  // URL/asset sources stay on the image pipeline because the kernel
  // rasterizer does not fetch resources. A raster source wins.
  if (canonical.imageSource === undefined && props.svgSource !== undefined) {
    const svgSource = props.svgSource as SvgSource;
    const svgRequest = resolveSvgSourceForFetch(svgSource);
    if (svgRequest?.markup !== undefined) {
      canonical.svgSource = svgRequest.markup;
    } else {
      const svgImageSource = resolveSvgSourceForNative(svgSource);
      if (svgImageSource !== undefined) {
        canonical.imageSource = svgImageSource;
      }
    }
  }
  // Tint applies to any image source, not only inline-SVG glyphs: native
  // hosts render `system-symbol:` (and other template) sources through the
  // platform image catalog and tint via UIImageView.tintColor /
  // NSImageView.contentTintColor. Forwarding this only from the svgSource
  // branch dropped the prop for `src=`-authored images, so SF Symbols
  // always rendered in the platform default tint (system blue on iOS).
  if (
    typeof props.tintColor === 'string' &&
    (canonical.imageSource !== undefined || canonical.svgSource !== undefined)
  ) {
    canonical.tintColor = props.tintColor;
  }
  if (typeof props.svgImageSourceOutcome === 'string') {
    canonical.svgImageSourceOutcome = props.svgImageSourceOutcome;
  }

  const resizeMode = extractResizeMode(props, isRNStyle);
  if (resizeMode) {
    canonical.resizeMode = resizeMode;
  }

  canonical.imageDynamicRange = normalizeImageDynamicRange(props.dynamicRange, props.hdr);
  canonical.imageColorMatrix = canonicalImageColorMatrixProp(props.colorMatrix);
  if (props.loading === 'auto' || props.loading === 'eager' || props.loading === 'lazy') {
    canonical.imageLoading = props.loading;
  }
  if (
    props.priority === 'auto' ||
    props.priority === 'high' ||
    props.priority === 'normal' ||
    props.priority === 'low'
  ) {
    canonical.imageFetchPriority = props.priority;
  }

  const placeholder = resolveImagePlaceholderForNative(
    props.placeholder as ImagePlaceholder | undefined,
  );
  if (placeholder) {
    canonical.placeholder = placeholder;
  }
}

function normalizeSvg(props: Record<string, unknown>, canonical: CanonicalProps): void {
  warnIfImageMissingAlt({
    alt: typeof props.alt === 'string' ? props.alt : undefined,
    decorative: props.decorative === true,
    source: props.source as ImageSource | undefined,
    testID: typeof props.testID === 'string' ? props.testID : undefined,
  });

  const source = extractSvgSource(props);
  if (source) {
    canonical.svgSource = source;
  }

  const resizeMode: ResizeMode | undefined = extractResizeMode(props, true);
  if (resizeMode) {
    canonical.resizeMode = resizeMode;
  }

  if (typeof props.tintColor === 'string') {
    canonical.tintColor = props.tintColor;
  }

  if (typeof props.objectPosition === 'string' && props.objectPosition.trim().length > 0) {
    canonical.svgObjectPosition = props.objectPosition.trim();
  }

  if (typeof props.pixelDensity === 'number' && isFinite(props.pixelDensity) && props.pixelDensity > 0) {
    canonical.svgPixelDensity = String(props.pixelDensity);
  }

  if (typeof props.colors === 'object' && props.colors !== null) {
    const colorEntries = Object.entries(props.colors as Record<string, unknown>)
      .filter(([key, value]) => key.startsWith('--') && typeof value === 'string');
    if (colorEntries.length > 0) {
      canonical.svgColors = JSON.stringify(Object.fromEntries(colorEntries));
    }
  }
}

export const imagePropsRuntime: ImagePropsRuntime = {
  normalize(tagType, props, isRNStyle, canonical) {
    if (tagType === 'image') {
      normalizeImage(props, isRNStyle, canonical);
    } else {
      normalizeSvg(props, canonical);
    }
  },
};
