import { isAssetRef } from '@exact/core/assets-fonts-state';
import { MAX_STRING_PROP_BYTES } from '@exact/core/protocol/buffer-writer';

import type { ImageCandidate, ImageSource, SvgSource } from './types.js';
import { redactedImageSourceId } from './image-source-redaction.js';

export interface ResolvedSvgRequest {
  readonly headers?: Record<string, string>;
  readonly markup?: string;
  readonly uri?: string;
}

// Remote markup crosses SetProp(SvgSource), so the protocol's u16 payload is
// the effective limit. The kernel's 2 MiB parse guard remains defense in depth
// and is cataloged as shadowed by this limit (LLP 0343 / ENG-24939).
export const MAX_REMOTE_SVG_BYTES = MAX_STRING_PROP_BYTES;
const MAX_SVG_SIGNATURE_BYTES = 1024;

export type SvgFetchErrorCode =
  | 'body-too-large'
  | 'content-type'
  | 'http-status'
  | 'invalid-signature'
  | 'invalid-utf8'
  | 'stream-unavailable';

export class SvgFetchError extends Error {
  readonly code: SvgFetchErrorCode;
  readonly retryable: boolean;

  constructor(code: SvgFetchErrorCode, message: string, retryable = false) {
    super(message);
    this.name = 'SvgFetchError';
    this.code = code;
    this.retryable = retryable;
  }
}

export type SvgImageSourceState = 'pending' | 'admitted' | 'failed';

export interface SvgImageSourceOutcome {
  readonly v: 1;
  readonly generation: number;
  readonly state: SvgImageSourceState;
  readonly sourceId: string;
  readonly encodedSource: 'network' | 'bundle' | 'local' | 'data' | 'unknown';
  readonly errorCode?:
    | 'invalid-source'
    | 'transport'
    | 'http-status'
    | 'content-type'
    | 'invalid-signature'
    | 'encoded-size-limit';
  readonly message?: string;
  readonly retryable?: boolean;
}

export type SvgFetch = (input: RequestInfo | URL, init?: RequestInit) => Promise<Response>;

export interface FetchSvgMarkupOptions {
  readonly fetchImpl?: SvgFetch;
  readonly maxBytes?: number;
  readonly signal?: AbortSignal;
  readonly signatureBytes?: number;
}

/**
 * Fetch and admit remote SVG markup without ever materializing an unbounded
 * response body. This stays JS-owned for v1 (ENG-24925); the kernel only sees
 * the surviving immutable UTF-8 string.
 */
export async function fetchSvgMarkup(
  request: ResolvedSvgRequest,
  options: FetchSvgMarkupOptions = {},
): Promise<string> {
  if (!request.uri) {
    throw new SvgFetchError('invalid-signature', 'SVG request has no remote URI.');
  }

  const fetchImpl: SvgFetch = options.fetchImpl ?? ((input, init) => globalThis.fetch(input, init));
  const response = await fetchImpl(request.uri, {
    headers: request.headers,
    signal: options.signal,
  });

  if (!response.ok) {
    await cancelResponseBody(response);
    throw new SvgFetchError(
      'http-status',
      `SVG request failed with ${response.status}.`,
      response.status === 408 || response.status === 429 || response.status >= 500,
    );
  }

  const mimeType = normalizeMimeType(response.headers.get('content-type') ?? undefined);
  if (mimeType !== '' && !isSvgOrGenericMimeType(mimeType)) {
    await cancelResponseBody(response);
    throw new SvgFetchError('content-type', `SVG request returned ${mimeType}.`);
  }

  const maxBytes = normalizePositiveLimit(options.maxBytes, MAX_REMOTE_SVG_BYTES);
  const declaredLength = parseContentLength(response.headers.get('content-length'));
  if (declaredLength !== undefined && declaredLength > maxBytes) {
    await cancelResponseBody(response);
    throw new SvgFetchError(
      'body-too-large',
      `SVG response exceeds the ${maxBytes}-byte limit.`,
    );
  }

  const bytes = await readBoundedResponseBody(response, maxBytes);
  const signatureBytes = normalizePositiveLimit(options.signatureBytes, MAX_SVG_SIGNATURE_BYTES);
  if (!hasSvgSignature(bytes.subarray(0, Math.min(bytes.byteLength, signatureBytes)))) {
    throw new SvgFetchError('invalid-signature', 'SVG response has no admitted <svg> root signature.');
  }

  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    throw new SvgFetchError('invalid-utf8', 'SVG response is not valid UTF-8.');
  }
}

async function readBoundedResponseBody(response: Response, maxBytes: number): Promise<Uint8Array> {
  const body = response.body;
  if (body == null || typeof body.getReader !== 'function') {
    throw new SvgFetchError(
      'stream-unavailable',
      'SVG response body is not available as a bounded byte stream.',
      true,
    );
  }

  const reader = body.getReader();
  const chunks: Uint8Array[] = [];
  let totalBytes = 0;

  try {
    while (true) {
      const result = await reader.read();
      if (result.done) {
        break;
      }
      const chunk = result.value;
      totalBytes += chunk.byteLength;
      if (totalBytes > maxBytes) {
        try {
          await reader.cancel();
        } catch {
          // Preserve the deterministic admission error if transport
          // cancellation itself fails.
        }
        throw new SvgFetchError(
          'body-too-large',
          `SVG response exceeds the ${maxBytes}-byte limit.`,
        );
      }
      chunks.push(chunk);
    }
  } finally {
    reader.releaseLock();
  }

  const bytes = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return bytes;
}

async function cancelResponseBody(response: Response): Promise<void> {
  try {
    await response.body?.cancel();
  } catch {
    // Admission has already failed; transport cancellation is best effort.
  }
}

function normalizePositiveLimit(value: number | undefined, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0
    ? Math.floor(value)
    : fallback;
}

function parseContentLength(value: string | null): number | undefined {
  if (value == null || !/^\d+$/.test(value.trim())) {
    return undefined;
  }
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) ? parsed : undefined;
}

function isSvgOrGenericMimeType(mimeType: string): boolean {
  return mimeType === 'image/svg+xml' ||
    mimeType === 'application/xml' ||
    mimeType === 'text/xml' ||
    mimeType === 'application/octet-stream' ||
    mimeType === 'binary/octet-stream' ||
    mimeType === 'text/plain';
}

function hasSvgSignature(prefix: Uint8Array): boolean {
  // Non-fatal decode is intentional for the bounded prefix: its final byte
  // may split a valid multi-byte code point after the already-visible root.
  // The full body is decoded with `fatal: true` after admission.
  const text = new TextDecoder('utf-8').decode(prefix);

  // The prefix is capped, so this deliberately bounded expression can admit
  // XML declarations/comments/DOCTYPE before the root without scanning an
  // attacker-controlled full document.
  return /^(?:\uFEFF|\s|<\?xml[\s\S]*?\?>|<!--[\s\S]*?-->|<!doctype[\s\S]*?>)*<svg(?:\s|\/?>)/i.test(text);
}

export function isInlineSvgSource(source: SvgSource | undefined): boolean {
  return typeof source === 'string' &&
    (source.trimStart().startsWith('<') || source.trimStart().startsWith('<?xml'));
}

export function resolveSvgSourceForDOM(source: SvgSource | undefined): string | undefined {
  if (source == null) {
    return undefined;
  }

  if (typeof source === 'string' && source.length > 0) {
    return source;
  }

  if (isAssetRef(source)) {
    return source.url;
  }

  if (typeof source === 'object' && source !== null && typeof source.uri === 'string' && source.uri.length > 0) {
    return source.uri;
  }

  return undefined;
}

/**
 * Resolve an SVG source to a string for legacy native image-pipeline callers.
 *
 * Native renderers (the AppKit/UIKit presenters' `applyNativeImage`) load a
 * glyph from a named asset, a file/remote URL, or a `data:` URI; they cannot
 * consume raw inline `<svg>` markup the way the DOM mirror can. Inline markup
 * is therefore wrapped as a percent-encoded `data:image/svg+xml` URI:
 * `encodeURIComponent` keeps the transform dependency-free on Hermes and the
 * payload inspectable. UIKit cannot decode SVG image data, so default native
 * image glyphs should preserve `svgSource` and let the kernel rasterize.
 */
export function resolveSvgSourceForNative(source: SvgSource | undefined): string | undefined {
  const resolved = resolveSvgSourceForDOM(source);
  if (resolved == null || resolved.length === 0) {
    return undefined;
  }

  if (isInlineSvgSource(resolved)) {
    return `data:image/svg+xml,${encodeURIComponent(resolved)}`;
  }

  return resolved;
}

export function resolveSvgSourceForFetch(source: SvgSource | undefined): ResolvedSvgRequest | undefined {
  if (source == null) {
    return undefined;
  }

  if (typeof source === 'string' && isInlineSvgSource(source)) {
    return { markup: source };
  }

  if (typeof source === 'string') {
    const decodedMarkup = decodeSvgDataUrl(source);
    if (decodedMarkup !== undefined) {
      return { markup: decodedMarkup };
    }
    return source !== '' ? { uri: source } : undefined;
  }

  if (isAssetRef(source)) {
    return { uri: source.url };
  }

  if (typeof source === 'object' && source !== null && typeof source.uri === 'string' && source.uri.length > 0) {
    const decodedMarkup = decodeSvgDataUrl(source.uri);
    if (decodedMarkup !== undefined) {
      return { markup: decodedMarkup };
    }
    return { uri: source.uri, headers: source.headers };
  }

  return undefined;
}

function canonicalHeaders(headers: Record<string, string> | undefined): string {
  if (!headers) return '';
  return Object.entries(headers)
    .map(([name, value]) => [name.trim().toLowerCase(), value.trim()] as const)
    .sort(([leftName, leftValue], [rightName, rightValue]) =>
      leftName.localeCompare(rightName) || leftValue.localeCompare(rightValue))
    .map(([name, value]) => `${name}:${value}`)
    .join('\n');
}

/**
 * Stable, redacted identity for an SVG logical source. Header values and
 * markup participate in the digest but never appear in the returned value.
 */
export function svgImageSourceId(source: SvgSource): string {
  const request = resolveSvgSourceForFetch(source);
  const identity = request?.markup !== undefined
    ? `markup\n${request.markup}`
    : `uri\n${request?.uri ?? ''}\nheaders\n${canonicalHeaders(request?.headers)}`;
  return redactedImageSourceId(`opaque:svg-image:${identity}`);
}

export function svgImageEncodedSource(
  source: SvgSource,
): SvgImageSourceOutcome['encodedSource'] {
  if (typeof source === 'string') {
    if (isInlineSvgSource(source) || source.startsWith('data:')) return 'data';
    try {
      const url = new URL(source, 'https://exact.invalid');
      if (url.origin === 'https://exact.invalid') return 'bundle';
      if (url.protocol === 'http:' || url.protocol === 'https:') return 'network';
      if (url.protocol === 'file:' || url.protocol === 'app:') return 'local';
    } catch {
      return 'unknown';
    }
    return 'unknown';
  }
  if (isAssetRef(source)) return 'bundle';
  if (typeof source === 'object' && source !== null && typeof source.uri === 'string') {
    return svgImageEncodedSource(source.uri);
  }
  return 'unknown';
}

export function svgImageFailureOutcome(
  error: unknown,
  generation: number,
  sourceId: string,
  encodedSource: SvgImageSourceOutcome['encodedSource'],
): SvgImageSourceOutcome {
  if (error instanceof SvgFetchError) {
    const mapping: Record<SvgFetchErrorCode, {
      code: NonNullable<SvgImageSourceOutcome['errorCode']>;
      message: string;
    }> = {
      'body-too-large': {
        code: 'encoded-size-limit',
        message: 'SVG source exceeds the encoded-size limit.',
      },
      'content-type': {
        code: 'content-type',
        message: 'SVG source has an unsupported content type.',
      },
      'http-status': {
        code: 'http-status',
        message: 'SVG request failed.',
      },
      'invalid-signature': {
        code: 'invalid-signature',
        message: 'SVG source has an invalid signature.',
      },
      'invalid-utf8': {
        code: 'invalid-signature',
        message: 'SVG source is not valid UTF-8.',
      },
      'stream-unavailable': {
        code: 'transport',
        message: 'SVG response could not be read safely.',
      },
    };
    const mapped = mapping[error.code];
    return {
      v: 1,
      generation,
      state: 'failed',
      sourceId,
      encodedSource,
      errorCode: mapped.code,
      message: mapped.message,
      retryable: error.retryable,
    };
  }
  return {
    v: 1,
    generation,
    state: 'failed',
    sourceId,
    encodedSource,
    errorCode: 'transport',
    message: 'SVG request failed.',
    retryable: true,
  };
}

export function coerceImageSourceToSvgSource(source: ImageSource | undefined): SvgSource | undefined {
  if (source == null || typeof source === 'number') {
    return undefined;
  }

  if (typeof source === 'string') {
    return isInlineSvgSource(source) || isSvgLikeUri(source) ? source : undefined;
  }

  if (isAssetRef(source)) {
    return isSvgLikeUri(source.url) ? source : undefined;
  }

  if (isImageCandidateArraySource(source)) {
    const candidate = source.find((entry) => isSvgImageCandidate(entry));
    if (!candidate) {
      return undefined;
    }
    return {
      uri: candidate.uri,
      headers: candidate.headers,
      cacheKey: candidate.cacheKey,
    };
  }

  if (typeof source === 'object' && source !== null && 'thumbhash' in source) {
    return undefined;
  }

  if (isSvgUriSourceLike(source)) {
    return isSvgLikeUri(source.uri) ? source : undefined;
  }

  return undefined;
}

export function filterSvgColors(
  colors: Record<string, string> | undefined,
): Record<string, string> | undefined {
  if (colors == null) {
    return undefined;
  }

  const filtered = Object.fromEntries(
    Object.entries(colors).filter(([key, value]) => key.startsWith('--') && value.length > 0),
  );

  return Object.keys(filtered).length > 0 ? filtered : undefined;
}

export function getDefaultSvgPixelDensity(): number {
  const devicePixelRatio = (
    globalThis as typeof globalThis & { devicePixelRatio?: unknown }
  ).devicePixelRatio;
  if (typeof devicePixelRatio === 'number' && isFinite(devicePixelRatio) && devicePixelRatio > 0) {
    return devicePixelRatio;
  }

  const exact = (globalThis as { exact?: { screenScale?: unknown } }).exact;
  if (typeof exact?.screenScale === 'number' && isFinite(exact.screenScale) && exact.screenScale > 0) {
    return exact.screenScale;
  }

  return 1;
}

function decodeSvgDataUrl(input: string): string | undefined {
  if (!input.startsWith('data:image/svg+xml')) {
    return undefined;
  }

  const commaIndex = input.indexOf(',');
  if (commaIndex === -1) {
    return undefined;
  }

  const metadata = input.slice(0, commaIndex).toLowerCase();
  const payload = input.slice(commaIndex + 1);

  try {
    if (metadata.includes(';base64')) {
      if (typeof Buffer !== 'undefined') {
        return Buffer.from(payload, 'base64').toString('utf8');
      }
      if (typeof Uint8Array !== 'undefined' && typeof TextDecoder !== 'undefined') {
        const binary = atob(payload);
        const bytes = Uint8Array.from(binary, (char) => char.charCodeAt(0));
        return new TextDecoder().decode(bytes);
      }
      return atob(payload);
    }

    return decodeURIComponent(payload);
  } catch {
    return undefined;
  }
}

function isSvgLikeUri(uri: string): boolean {
  const normalized = uri.trim();
  if (normalized.length === 0) {
    return false;
  }

  if (normalized.startsWith('data:image/svg+xml')) {
    return true;
  }

  const withoutHash = normalized.split('#', 1)[0] ?? normalized;
  const withoutQuery = withoutHash.split('?', 1)[0] ?? withoutHash;
  return /\.svgz?$/i.test(withoutQuery);
}

function isSvgImageCandidate(candidate: ImageCandidate): boolean {
  return isSvgLikeUri(candidate.uri) || normalizeMimeType(candidate.type) === 'image/svg+xml';
}

function isImageCandidateArraySource(source: ImageSource): source is readonly ImageCandidate[] {
  return Array.isArray(source);
}

function isSvgUriSourceLike(
  source: Exclude<ImageSource, string | number | readonly ImageCandidate[]>,
): source is { uri: string; headers?: Record<string, string>; cacheKey?: string } {
  return typeof source === 'object' && source !== null && 'uri' in source && typeof source.uri === 'string';
}

function normalizeMimeType(type: string | undefined): string {
  return type?.split(';', 1)[0]?.trim().toLowerCase() ?? '';
}
