// @system @ref LLP 0099#agent-api — correlated gesture trace facts
// (ENG-25119). This ring is deliberately supplemental: the correlated trace
// is assembled by joining the existing LLP 0099 M8 rings (arbitration
// receipts, gesture/animation states, command dispatch receipts) with the
// facts those rings do not record — delivery batches from input sessions
// (ENG-25120), runOnJS scheduling/drops, and semantic acks. It reuses the M8
// identity spine (rootId, streamId, gestureId, generations) rather than
// minting a parallel identity model.
import type {
  GestureTraceEvent,
  GestureTraceEventStatus,
  GestureTracePhaseId,
} from "./types.js";

export const GESTURE_TRACE_LIMITS = Object.freeze({
  eventsPerRoot: 256,
});

const PHASES = new Set<GestureTracePhaseId>([
  "delivered",
  "hit-test",
  "arbitration",
  "callback",
  "worklet-presented",
  "terminal-scheduling",
  "semantic-commit",
]);
const STATUSES = new Set<GestureTraceEventStatus>([
  "ok",
  "denied",
  "failed",
  "dropped",
  "info",
]);

interface RootGestureTraceState {
  events: GestureTraceEvent[];
  nextSequence: number;
  evictions: number;
}

interface GestureTraceStore {
  roots: Map<number, RootGestureTraceState>;
}

type GestureTraceGlobal = typeof globalThis & {
  __exactGestureTrace?: GestureTraceStore;
};

function store(): GestureTraceStore {
  const scope = globalThis as GestureTraceGlobal;
  return (scope.__exactGestureTrace ??= { roots: new Map() });
}

function rootState(rootId: number): RootGestureTraceState {
  const current = store();
  let root = current.roots.get(rootId);
  if (!root) {
    root = { events: [], nextSequence: 0, evictions: 0 };
    current.roots.set(rootId, root);
  }
  return root;
}

function cloneEvent(event: GestureTraceEvent): GestureTraceEvent {
  return {
    ...event,
    ...(event.detail ? { detail: { ...event.detail } } : {}),
    ...(event.generations ? { generations: { ...event.generations } } : {}),
  };
}

export type GestureTraceEventPublish = Omit<
  GestureTraceEvent,
  "schemaVersion" | "sequence" | "timestampMs"
> & { timestampMs?: number };

/** Append one trace fact. Never throws into input/motion paths. */
export function recordGestureTraceEvent(input: GestureTraceEventPublish): boolean {
  if (
    !Number.isSafeInteger(input.rootId) ||
    input.rootId < 0 ||
    !PHASES.has(input.phase) ||
    !STATUSES.has(input.status)
  ) {
    return false;
  }
  if (input.status !== "ok" && input.status !== "info" && !input.reason) {
    return false;
  }
  const root = rootState(input.rootId);
  const event: GestureTraceEvent = cloneEvent({
    ...input,
    schemaVersion: 1,
    sequence: (root.nextSequence += 1),
    timestampMs:
      typeof input.timestampMs === "number" && Number.isFinite(input.timestampMs)
        ? input.timestampMs
        : Date.now(),
  });
  root.events.push(event);
  while (root.events.length > GESTURE_TRACE_LIMITS.eventsPerRoot) {
    root.events.shift();
    root.evictions += 1;
  }
  return true;
}

export function getGestureTraceEvents(options: {
  rootId: number;
  sessionId?: string;
  streamId?: number | string;
  gestureId?: string;
  sinceSequence?: number;
  sinceTimestampMs?: number;
}): GestureTraceEvent[] {
  const root = store().roots.get(options.rootId);
  if (!root) return [];
  return root.events
    .filter(
      (event) =>
        (options.sessionId === undefined || event.sessionId === options.sessionId) &&
        (options.streamId === undefined || event.streamId === options.streamId) &&
        (options.gestureId === undefined || event.gestureId === options.gestureId) &&
        (options.sinceSequence === undefined || event.sequence > options.sinceSequence) &&
        (options.sinceTimestampMs === undefined ||
          event.timestampMs >= options.sinceTimestampMs),
    )
    .map(cloneEvent);
}

export function getGestureTraceEvictions(rootId: number): number {
  return store().roots.get(rootId)?.evictions ?? 0;
}

export function resetGestureTraceState(): void {
  const scope = globalThis as GestureTraceGlobal;
  delete scope.__exactGestureTrace;
}

// ============================================================================
// Ambient gesture callback context — set by recognizers around author
// callback invocation so downstream terminal edges (runOnJS scheduling,
// command dispatch) can attach the gesture identity to their trace facts
// without a parallel correlation channel. Mirrors the shape of the LLP 0336
// interaction dispatch context.
// ============================================================================

export interface GestureCallbackContext {
  gestureId: string;
  streamId?: number | string;
  compositionInstanceId?: number | string;
  sessionId?: string;
  rootId?: number;
}

type GestureCallbackContextGlobal = typeof globalThis & {
  __exactGestureCallbackContext?: GestureCallbackContext | null;
};

export function currentGestureCallbackContext(): GestureCallbackContext | null {
  return (globalThis as GestureCallbackContextGlobal).__exactGestureCallbackContext ?? null;
}

export function runWithGestureCallbackContext<T>(
  context: GestureCallbackContext,
  fn: () => T,
): T {
  const scope = globalThis as GestureCallbackContextGlobal;
  const previous = scope.__exactGestureCallbackContext ?? null;
  scope.__exactGestureCallbackContext = context;
  try {
    return fn();
  } finally {
    scope.__exactGestureCallbackContext = previous;
  }
}
