// @system @ref LLP 0099#protocol-and-transport
// @system @ref LLP 0099#animation-drivers

import {
  MOTION_SCHEMA_DIGEST,
  MOTION_SCHEMA_VERSION,
  type MotionTransactionId,
} from './motion-snapshot.js';
import { MOTION_VALUE_COMMAND_SCHEMA } from './motion-command-schema.generated.js';

export { MOTION_VALUE_COMMAND_SCHEMA };

export const MOTION_COMMAND_MAGIC = 0x4d43_4f4d; // "MOCM" little-endian
export const MOTION_COMMAND_HEADER_SIZE = MOTION_VALUE_COMMAND_SCHEMA.envelope.headerBytes;
export const MOTION_COMMAND_LAYOUT_VERSION = MOTION_VALUE_COMMAND_SCHEMA.layoutVersion;
export const MOTION_COMMAND_QUEUE_CAPACITY =
  MOTION_VALUE_COMMAND_SCHEMA.bounds.pendingCommandsPerRoot;
export const MOTION_MAX_DRIVER_DEPTH = MOTION_VALUE_COMMAND_SCHEMA.bounds.maximumDriverDepth;
export const MOTION_MAX_DRIVER_NODES = MOTION_VALUE_COMMAND_SCHEMA.bounds.maximumDriverNodes;
export const MOTION_MAX_SEQUENCE_CHILDREN =
  MOTION_VALUE_COMMAND_SCHEMA.bounds.maximumSequenceChildren;
export const MOTION_MAX_COMMAND_BYTES = MOTION_VALUE_COMMAND_SCHEMA.bounds.maximumCommandBytes;

export type MotionCommandKind = 'writeValue' | 'startDriver' | 'cancelDriver';
export type MotionCommandTimingEasing = 'linear' | 'easeIn' | 'easeOut' | 'easeInOut';
export type MotionCommandInteractionClass =
  | 'none'
  | 'directManipulation'
  | 'navigationSettle'
  | 'pagerSettle'
  | 'localSettle'
  | 'decorativeAutonomous'
  | 'noninteractiveNavigation'
  | 'tier1Transition';
export type MotionCommandReducedAction =
  | 'unchanged'
  | 'suppress'
  | 'immediate'
  | 'crossFade150'
  | 'trackWithoutDecoration';

export interface MotionCommandTarget {
  /** Stable `SharedValue` descriptor identity. Main resolves its physical slot. */
  readonly descriptorId: bigint;
  readonly generation: number;
  /** Must equal the enclosing transaction epoch; encoded once in the envelope. */
  readonly epoch: number;
}

export interface MotionCommandReducedMotionRewrite {
  readonly profileVersion: number;
  readonly interactionClass: MotionCommandInteractionClass;
  readonly applied: boolean;
  readonly action: MotionCommandReducedAction;
  readonly durationMs: number | null;
}

interface MotionCommandDriverBase {
  readonly __exactMotionDriver?: true;
}

export interface MotionCommandSpringDriver extends MotionCommandDriverBase {
  readonly kind: 'spring';
  readonly target: number;
  readonly inheritVelocity: boolean;
  readonly options: Readonly<{
    damping: number;
    stiffness: number;
    mass: number;
    velocity: number;
    restSpeedThreshold: number;
    restDisplacementThreshold: number;
  }>;
}

export interface MotionCommandTimingDriver extends MotionCommandDriverBase {
  readonly kind: 'timing';
  readonly target: number;
  readonly options: Readonly<{
    duration: number;
    easing?: MotionCommandTimingEasing | ((progress: number) => number);
  }>;
}

export interface MotionCommandDecayDriver extends MotionCommandDriverBase {
  readonly kind: 'decay';
  readonly options: Readonly<{
    velocity: number;
    deceleration: number;
    clamp?: readonly [number, number];
    rubberBandEffect?: boolean;
    rubberBandFactor?: number;
    restSpeedThreshold?: number;
  }>;
}

export interface MotionCommandSequenceDriver extends MotionCommandDriverBase {
  readonly kind: 'sequence';
  readonly drivers: readonly MotionCommandDriver[];
}

export interface MotionCommandRepeatDriver extends MotionCommandDriverBase {
  readonly kind: 'repeat';
  readonly driver: MotionCommandDriver;
  readonly count: number;
  readonly reverse: boolean;
}

export type MotionCommandDriver =
  | MotionCommandSpringDriver
  | MotionCommandTimingDriver
  | MotionCommandDecayDriver
  | MotionCommandSequenceDriver
  | MotionCommandRepeatDriver;

interface MotionValueCommandBase {
  readonly transaction: MotionTransactionId;
  readonly commandId: bigint;
  readonly target: MotionCommandTarget;
  readonly reducedMotion: MotionCommandReducedMotionRewrite;
}

export interface MotionWriteValueCommand extends MotionValueCommandBase {
  readonly kind: 'writeValue';
  readonly value: number;
}

export interface MotionStartDriverCommand extends MotionValueCommandBase {
  readonly kind: 'startDriver';
  readonly driver: MotionCommandDriver;
}

export interface MotionCancelDriverCommand extends MotionValueCommandBase {
  readonly kind: 'cancelDriver';
}

export type MotionValueCommand =
  | MotionWriteValueCommand
  | MotionStartDriverCommand
  | MotionCancelDriverCommand;

export const MOTION_NO_REDUCED_MOTION: MotionCommandReducedMotionRewrite = Object.freeze({
  profileVersion: MOTION_VALUE_COMMAND_SCHEMA.reducedMotion.profileVersion,
  interactionClass: 'none',
  applied: false,
  action: 'unchanged',
  durationMs: null,
});

const commandKindCode = MOTION_VALUE_COMMAND_SCHEMA.commandKindCodes;
const driverKindCode = MOTION_VALUE_COMMAND_SCHEMA.driverKindCodes;
const timingEasingCode = MOTION_VALUE_COMMAND_SCHEMA.timingEasingCodes;
const interactionClassCode = MOTION_VALUE_COMMAND_SCHEMA.reducedMotion.interactionClassCodes;
const reducedActionCode = MOTION_VALUE_COMMAND_SCHEMA.reducedMotion.actionCodes;
const unchangedDuration = MOTION_VALUE_COMMAND_SCHEMA.reducedMotion.unchangedDurationSentinel;

function invertCodes<T extends string>(codes: Readonly<Record<T, number>>): Map<number, T> {
  const inverted = new Map<number, T>();
  for (const [name, code] of Object.entries(codes) as Array<[T, number]>) {
    inverted.set(code, name);
  }
  return inverted;
}

const commandKindByCode = invertCodes(commandKindCode);
const driverKindByCode = invertCodes(driverKindCode);
const timingEasingByCode = invertCodes(timingEasingCode);
const interactionClassByCode = invertCodes(interactionClassCode);
const reducedActionByCode = invertCodes(reducedActionCode);
const reducedActionByInteractionClass: Readonly<
  Record<Exclude<MotionCommandInteractionClass, 'none'>, MotionCommandReducedAction>
> = Object.freeze({
  directManipulation: 'trackWithoutDecoration',
  navigationSettle: 'crossFade150',
  pagerSettle: 'immediate',
  localSettle: 'crossFade150',
  decorativeAutonomous: 'suppress',
  noninteractiveNavigation: 'crossFade150',
  tier1Transition: 'suppress',
});

function hasOwnCode<T extends string>(
  codes: Readonly<Record<T, number>>,
  value: unknown,
): value is T {
  return typeof value === 'string' && Object.prototype.hasOwnProperty.call(codes, value);
}

function u32(value: number, label: string): number {
  if (!Number.isInteger(value) || value < 0 || value > 0xffff_ffff) {
    throw new RangeError(`[motion-command] ${label} must be a u32`);
  }
  return value;
}

function nonzeroU32(value: number, label: string): number {
  const cooked = u32(value, label);
  if (cooked === 0) throw new RangeError(`[motion-command] ${label} must be nonzero`);
  return cooked;
}

function nonzeroU64(value: bigint, label: string): bigint {
  if (typeof value !== 'bigint' || value <= 0n || value > 0xffff_ffff_ffff_ffffn) {
    throw new RangeError(`[motion-command] ${label} must be a nonzero u64`);
  }
  return value;
}

function finite(value: number, label: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError(`[motion-command] ${label} must be finite`);
  }
  return value;
}

function positive(value: number, label: string): number {
  finite(value, label);
  if (value <= 0) throw new RangeError(`[motion-command] ${label} must be positive`);
  return value;
}

function nonnegative(value: number, label: string): number {
  finite(value, label);
  if (value < 0) throw new RangeError(`[motion-command] ${label} must be nonnegative`);
  return value;
}

function validateReducedMotion(
  rewrite: MotionCommandReducedMotionRewrite,
  kind: MotionCommandKind,
): void {
  if (!rewrite || typeof rewrite !== 'object') {
    throw new TypeError('[motion-command] reduced-motion metadata is required');
  }
  if (rewrite.profileVersion !== MOTION_VALUE_COMMAND_SCHEMA.reducedMotion.profileVersion) {
    throw new RangeError('[motion-command] reduced-motion profile version mismatch');
  }
  if (!hasOwnCode(interactionClassCode, rewrite.interactionClass)) {
    throw new TypeError('[motion-command] unknown reduced-motion interaction class');
  }
  if (!hasOwnCode(reducedActionCode, rewrite.action)) {
    throw new TypeError('[motion-command] unknown reduced-motion action');
  }
  if (rewrite.applied !== (rewrite.action !== 'unchanged')) {
    throw new TypeError('[motion-command] reduced-motion applied/action mismatch');
  }
  if (rewrite.action === 'unchanged') {
    if (rewrite.durationMs !== null) {
      throw new TypeError('[motion-command] unchanged reduced motion has no duration');
    }
  } else {
    const duration = u32(rewrite.durationMs ?? -1, 'reduced-motion duration');
    if (duration > 0xfffe) {
      throw new RangeError('[motion-command] reduced-motion duration exceeds u16');
    }
    const expected = rewrite.action === 'crossFade150' ? 150 : 0;
    if (duration !== expected) {
      throw new RangeError(`[motion-command] ${rewrite.action} duration must be ${expected}ms`);
    }
  }
  if (kind === 'startDriver' && rewrite.interactionClass === 'none') {
    throw new TypeError('[motion-command] driver start requires an interaction class');
  }
  if (
    rewrite.applied && rewrite.interactionClass !== 'none' &&
    rewrite.action !== reducedActionByInteractionClass[rewrite.interactionClass]
  ) {
    throw new TypeError('[motion-command] reduced-motion class/action mismatch');
  }
  if (kind !== 'startDriver' && (
    rewrite.interactionClass !== 'none' || rewrite.action !== 'unchanged'
  )) {
    throw new TypeError('[motion-command] write/cancel records cannot carry a driver rewrite');
  }
}

interface DriverBudget {
  nodes: number;
}

function validateDriver(
  driver: MotionCommandDriver,
  depth = 1,
  budget: DriverBudget = { nodes: 0 },
): void {
  if (!driver || typeof driver !== 'object') {
    throw new TypeError('[motion-command] driver must be an object');
  }
  if (depth > MOTION_MAX_DRIVER_DEPTH) {
    throw new RangeError(`[motion-command] driver depth exceeds ${MOTION_MAX_DRIVER_DEPTH}`);
  }
  budget.nodes += 1;
  if (budget.nodes > MOTION_MAX_DRIVER_NODES) {
    throw new RangeError(`[motion-command] driver node count exceeds ${MOTION_MAX_DRIVER_NODES}`);
  }
  switch (driver.kind) {
    case 'spring':
      finite(driver.target, 'spring target');
      if (typeof driver.inheritVelocity !== 'boolean') {
        throw new TypeError('[motion-command] spring inheritVelocity must be boolean');
      }
      nonnegative(driver.options.damping, 'spring damping');
      positive(driver.options.stiffness, 'spring stiffness');
      positive(driver.options.mass, 'spring mass');
      finite(driver.options.velocity, 'spring velocity');
      positive(driver.options.restSpeedThreshold, 'spring restSpeedThreshold');
      positive(driver.options.restDisplacementThreshold, 'spring restDisplacementThreshold');
      return;
    case 'timing': {
      finite(driver.target, 'timing target');
      nonnegative(driver.options.duration, 'timing duration');
      const easing = driver.options.easing ?? 'linear';
      if (typeof easing === 'function') {
        throw new TypeError('[motion-command] native timing commands require a named easing');
      }
      if (!hasOwnCode(timingEasingCode, easing)) {
        throw new TypeError('[motion-command] unknown timing easing');
      }
      return;
    }
    case 'decay': {
      finite(driver.options.velocity, 'decay velocity');
      const deceleration = finite(driver.options.deceleration, 'decay deceleration');
      if (deceleration <= 0 || deceleration >= 1) {
        throw new RangeError('[motion-command] decay deceleration must be between zero and one');
      }
      if (driver.options.clamp !== undefined) {
        if (!Array.isArray(driver.options.clamp) || driver.options.clamp.length !== 2) {
          throw new TypeError('[motion-command] decay clamp must be a pair');
        }
        const minimum = finite(driver.options.clamp[0], 'decay clamp minimum');
        const maximum = finite(driver.options.clamp[1], 'decay clamp maximum');
        if (minimum > maximum) {
          throw new RangeError('[motion-command] decay clamp minimum exceeds maximum');
        }
      }
      const factor = positive(driver.options.rubberBandFactor ?? 0.55, 'decay rubberBandFactor');
      if (factor > 1) {
        throw new RangeError('[motion-command] decay rubberBandFactor must not exceed one');
      }
      positive(driver.options.restSpeedThreshold ?? 0.01, 'decay restSpeedThreshold');
      if (
        driver.options.rubberBandEffect !== undefined &&
        typeof driver.options.rubberBandEffect !== 'boolean'
      ) {
        throw new TypeError('[motion-command] decay rubberBandEffect must be boolean');
      }
      return;
    }
    case 'sequence':
      if (
        !Array.isArray(driver.drivers) || driver.drivers.length === 0 ||
        driver.drivers.length > MOTION_MAX_SEQUENCE_CHILDREN
      ) {
        throw new RangeError(
          `[motion-command] sequence requires 1..${MOTION_MAX_SEQUENCE_CHILDREN} children`,
        );
      }
      driver.drivers.forEach((child) => validateDriver(child, depth + 1, budget));
      return;
    case 'repeat':
      if (
        !Number.isInteger(driver.count) || driver.count < -1 || driver.count === 0 ||
        driver.count > 0x7fff_ffff
      ) {
        throw new RangeError('[motion-command] repeat count must be -1 or a positive i32');
      }
      if (typeof driver.reverse !== 'boolean') {
        throw new TypeError('[motion-command] repeat reverse must be boolean');
      }
      validateDriver(driver.driver, depth + 1, budget);
      return;
    default:
      throw new TypeError(`[motion-command] unknown driver kind ${(driver as { kind?: unknown }).kind}`);
  }
}

export function validateMotionValueCommand(command: MotionValueCommand): void {
  if (!command || typeof command !== 'object') {
    throw new TypeError('[motion-command] command must be an object');
  }
  nonzeroU32(command.transaction.epoch, 'epoch');
  nonzeroU64(command.transaction.motionSeq, 'motionSeq');
  nonzeroU32(command.transaction.rootInstance, 'rootInstance');
  nonzeroU64(command.commandId, 'commandId');
  nonzeroU64(command.target.descriptorId, 'target descriptor id');
  nonzeroU32(command.target.generation, 'target generation');
  if (nonzeroU32(command.target.epoch, 'target epoch') !== command.transaction.epoch) {
    throw new TypeError('[motion-command] target epoch differs from command epoch');
  }
  if (!hasOwnCode(commandKindCode, command.kind)) {
    throw new TypeError('[motion-command] unknown command kind');
  }
  validateReducedMotion(command.reducedMotion, command.kind);
  switch (command.kind) {
    case 'writeValue':
      finite(command.value, 'write value');
      return;
    case 'startDriver':
      validateDriver(command.driver);
      return;
    case 'cancelDriver':
      return;
  }
}

function driverEncodedSize(driver: MotionCommandDriver): number {
  switch (driver.kind) {
    case 'spring': return 8 + 7 * 8;
    case 'timing': return 8 + 2 * 8;
    case 'decay': return 8 + 6 * 8;
    case 'sequence':
      return 8 + driver.drivers.reduce((total, child) => total + driverEncodedSize(child), 0);
    case 'repeat': return 8 + 8 + driverEncodedSize(driver.driver);
  }
}

class Writer {
  readonly bytes: Uint8Array;
  private readonly view: DataView;
  offset = 0;
  constructor(size: number) {
    this.bytes = new Uint8Array(size);
    this.view = new DataView(this.bytes.buffer);
  }
  u8(value: number): void { this.view.setUint8(this.offset++, value); }
  u16(value: number): void { this.view.setUint16(this.offset, value, true); this.offset += 2; }
  u32(value: number): void { this.view.setUint32(this.offset, value, true); this.offset += 4; }
  u64(value: bigint): void { this.view.setBigUint64(this.offset, value, true); this.offset += 8; }
  f64(value: number): void { this.view.setFloat64(this.offset, value, true); this.offset += 8; }
}

class Reader {
  private readonly view: DataView;
  offset = 0;
  constructor(readonly bytes: Uint8Array) {
    this.view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  }
  get remaining(): number { return this.bytes.length - this.offset; }
  private require(count: number): void {
    if (count < 0 || count > this.remaining) {
      throw new RangeError('[motion-command] unexpected end of payload');
    }
  }
  u8(): number { this.require(1); return this.view.getUint8(this.offset++); }
  u16(): number { this.require(2); const value = this.view.getUint16(this.offset, true); this.offset += 2; return value; }
  u32(): number { this.require(4); const value = this.view.getUint32(this.offset, true); this.offset += 4; return value; }
  u64(): bigint { this.require(8); const value = this.view.getBigUint64(this.offset, true); this.offset += 8; return value; }
  f64(): number { this.require(8); const value = this.view.getFloat64(this.offset, true); this.offset += 8; return value; }
}

function encodeDriver(writer: Writer, driver: MotionCommandDriver): void {
  let flags = 0;
  let children: readonly MotionCommandDriver[] = [];
  let parameters: readonly number[];
  switch (driver.kind) {
    case 'spring':
      flags = driver.inheritVelocity ? 1 : 0;
      parameters = [
        driver.target,
        driver.options.damping,
        driver.options.stiffness,
        driver.options.mass,
        driver.options.velocity,
        driver.options.restSpeedThreshold,
        driver.options.restDisplacementThreshold,
      ];
      break;
    case 'timing': {
      const easing = driver.options.easing ?? 'linear';
      if (typeof easing === 'function') {
        throw new TypeError('[motion-command] native timing commands require a named easing');
      }
      flags = timingEasingCode[easing];
      parameters = [driver.target, driver.options.duration];
      break;
    }
    case 'decay': {
      const clamp = driver.options.clamp;
      flags = (clamp ? 1 : 0) | (driver.options.rubberBandEffect ? 2 : 0);
      parameters = [
        driver.options.velocity,
        driver.options.deceleration,
        clamp?.[0] ?? 0,
        clamp?.[1] ?? 0,
        driver.options.rubberBandFactor ?? 0.55,
        driver.options.restSpeedThreshold ?? 0.01,
      ];
      break;
    }
    case 'sequence':
      children = driver.drivers;
      parameters = [];
      break;
    case 'repeat':
      flags = driver.reverse ? 1 : 0;
      children = [driver.driver];
      parameters = [driver.count];
      break;
  }
  writer.u8(driverKindCode[driver.kind]);
  writer.u8(flags);
  writer.u16(children.length);
  writer.u16(parameters.length);
  writer.u16(0);
  parameters.forEach((parameter) => writer.f64(parameter));
  children.forEach((child) => encodeDriver(writer, child));
}

export function encodeMotionValueCommand(command: MotionValueCommand): Uint8Array {
  validateMotionValueCommand(command);
  const bodySize = command.kind === 'writeValue'
    ? 8
    : command.kind === 'startDriver' ? driverEncodedSize(command.driver) : 0;
  const size = MOTION_COMMAND_HEADER_SIZE + bodySize;
  if (size > MOTION_MAX_COMMAND_BYTES) {
    throw new RangeError(`[motion-command] command is ${size} bytes; maximum is ${MOTION_MAX_COMMAND_BYTES}`);
  }
  const writer = new Writer(size);
  writer.u32(MOTION_COMMAND_MAGIC);
  writer.u16(MOTION_SCHEMA_VERSION);
  writer.u16(MOTION_COMMAND_LAYOUT_VERSION);
  writer.u64(MOTION_SCHEMA_DIGEST);
  writer.u32(command.transaction.epoch);
  writer.u64(command.transaction.motionSeq);
  writer.u32(command.transaction.rootInstance);
  writer.u64(command.commandId);
  writer.u64(command.target.descriptorId);
  writer.u32(command.target.generation);
  writer.u8(commandKindCode[command.kind]);
  writer.u8(interactionClassCode[command.reducedMotion.interactionClass]);
  writer.u8(reducedActionCode[command.reducedMotion.action]);
  writer.u8(command.reducedMotion.applied ? 1 : 0);
  writer.u16(command.reducedMotion.profileVersion);
  writer.u16(command.reducedMotion.durationMs ?? unchangedDuration);
  if (command.kind === 'writeValue') writer.f64(command.value);
  if (command.kind === 'startDriver') encodeDriver(writer, command.driver);
  return writer.bytes;
}

function decodeDriver(reader: Reader, depth: number, budget: DriverBudget): MotionCommandDriver {
  if (depth > MOTION_MAX_DRIVER_DEPTH) {
    throw new RangeError(`[motion-command] driver depth exceeds ${MOTION_MAX_DRIVER_DEPTH}`);
  }
  budget.nodes += 1;
  if (budget.nodes > MOTION_MAX_DRIVER_NODES) {
    throw new RangeError(`[motion-command] driver node count exceeds ${MOTION_MAX_DRIVER_NODES}`);
  }
  const kindCode = reader.u8();
  const kind = driverKindByCode.get(kindCode);
  if (!kind) throw new TypeError(`[motion-command] unknown driver kind ${kindCode}`);
  const flags = reader.u8();
  const childCount = reader.u16();
  const parameterCount = reader.u16();
  if (reader.u16() !== 0) throw new TypeError('[motion-command] nonzero driver reserved field');
  const parameters = Array.from({ length: parameterCount }, () => reader.f64());
  if (parameters.some((parameter) => !Number.isFinite(parameter))) {
    throw new TypeError('[motion-command] driver contains a non-finite parameter');
  }
  const children = Array.from(
    { length: childCount },
    () => decodeDriver(reader, depth + 1, budget),
  );
  switch (kind) {
    case 'spring': {
      if (flags > 1 || childCount !== 0 || parameterCount !== 7) {
        throw new TypeError('[motion-command] invalid spring node shape');
      }
      const [target, damping, stiffness, mass, velocity, restSpeedThreshold, restDisplacementThreshold] = parameters as [number, number, number, number, number, number, number];
      return {
        __exactMotionDriver: true,
        kind,
        target,
        inheritVelocity: flags === 1,
        options: { damping, stiffness, mass, velocity, restSpeedThreshold, restDisplacementThreshold },
      };
    }
    case 'timing': {
      const easing = timingEasingByCode.get(flags);
      if (!easing || childCount !== 0 || parameterCount !== 2) {
        throw new TypeError('[motion-command] invalid timing node shape');
      }
      return {
        __exactMotionDriver: true,
        kind,
        target: parameters[0]!,
        options: { duration: parameters[1]!, easing },
      };
    }
    case 'decay': {
      if ((flags & ~3) !== 0 || childCount !== 0 || parameterCount !== 6) {
        throw new TypeError('[motion-command] invalid decay node shape');
      }
      const [velocity, deceleration, minimum, maximum, rubberBandFactor, restSpeedThreshold] = parameters as [number, number, number, number, number, number];
      return {
        __exactMotionDriver: true,
        kind,
        options: {
          velocity,
          deceleration,
          ...((flags & 1) !== 0 ? { clamp: [minimum, maximum] as const } : {}),
          rubberBandEffect: (flags & 2) !== 0,
          rubberBandFactor,
          restSpeedThreshold,
        },
      };
    }
    case 'sequence':
      if (flags !== 0 || parameterCount !== 0) {
        throw new TypeError('[motion-command] invalid sequence node shape');
      }
      return { __exactMotionDriver: true, kind, drivers: children };
    case 'repeat':
      if (flags > 1 || childCount !== 1 || parameterCount !== 1) {
        throw new TypeError('[motion-command] invalid repeat node shape');
      }
      return {
        __exactMotionDriver: true,
        kind,
        driver: children[0]!,
        count: parameters[0]!,
        reverse: flags === 1,
      };
  }
}

export function decodeMotionValueCommand(bytes: Uint8Array): MotionValueCommand {
  if (
    !(bytes instanceof Uint8Array) || bytes.length < MOTION_COMMAND_HEADER_SIZE ||
    bytes.length > MOTION_MAX_COMMAND_BYTES
  ) {
    throw new RangeError('[motion-command] invalid command byte length');
  }
  const reader = new Reader(bytes);
  if (reader.u32() !== MOTION_COMMAND_MAGIC) throw new TypeError('[motion-command] invalid magic');
  if (reader.u16() !== MOTION_SCHEMA_VERSION) {
    throw new TypeError('[motion-command] schema version mismatch');
  }
  if (reader.u16() !== MOTION_COMMAND_LAYOUT_VERSION) {
    throw new TypeError('[motion-command] layout version mismatch');
  }
  if (reader.u64() !== MOTION_SCHEMA_DIGEST) {
    throw new TypeError('[motion-command] record schema digest mismatch');
  }
  const transaction: MotionTransactionId = {
    epoch: reader.u32(),
    motionSeq: reader.u64(),
    rootInstance: reader.u32(),
  };
  const commandId = reader.u64();
  const descriptorId = reader.u64();
  const generation = reader.u32();
  const kindRaw = reader.u8();
  const kind = commandKindByCode.get(kindRaw);
  if (!kind) throw new TypeError(`[motion-command] unknown command kind ${kindRaw}`);
  const interactionClassRaw = reader.u8();
  const interactionClass = interactionClassByCode.get(interactionClassRaw);
  if (!interactionClass) {
    throw new TypeError(`[motion-command] unknown reduced-motion class ${interactionClassRaw}`);
  }
  const actionRaw = reader.u8();
  const action = reducedActionByCode.get(actionRaw);
  if (!action) throw new TypeError(`[motion-command] unknown reduced-motion action ${actionRaw}`);
  const flags = reader.u8();
  if ((flags & ~1) !== 0) throw new TypeError('[motion-command] nonzero command reserved flags');
  const profileVersion = reader.u16();
  const durationRaw = reader.u16();
  const reducedMotion: MotionCommandReducedMotionRewrite = {
    profileVersion,
    interactionClass,
    applied: (flags & 1) !== 0,
    action,
    durationMs: durationRaw === unchangedDuration ? null : durationRaw,
  };
  const base = {
    transaction,
    commandId,
    target: { descriptorId, generation, epoch: transaction.epoch },
    reducedMotion,
  };
  let command: MotionValueCommand;
  switch (kind) {
    case 'writeValue':
      command = { ...base, kind, value: reader.f64() };
      break;
    case 'startDriver':
      command = { ...base, kind, driver: decodeDriver(reader, 1, { nodes: 0 }) };
      break;
    case 'cancelDriver':
      command = { ...base, kind };
      break;
  }
  if (reader.remaining !== 0) {
    throw new TypeError(`[motion-command] trailing bytes: ${reader.remaining}`);
  }
  validateMotionValueCommand(command);
  return command;
}

/** Stable descriptor identity shared with the whole-root Motion snapshot. */
export function motionDescriptorIdFromStableIdentity(identity: string): bigint {
  if (typeof identity !== 'string' || identity.length === 0) {
    throw new TypeError('[motion-command] stable descriptor identity must be non-empty');
  }
  let digest = 0xcbf29ce484222325n;
  for (const byte of new TextEncoder().encode(identity)) {
    digest = BigInt.asUintN(64, (digest ^ BigInt(byte)) * 0x100000001b3n);
  }
  return digest === 0n ? 1n : digest;
}

/**
 * Per-root producer queue. Admission is bounded and lossless: a full queue
 * throws before accepting the new command, and accepted commands never
 * coalesce (including equal scalar writes).
 */
export class MotionCommandPendingQueue {
  private readonly records: MotionValueCommand[] = [];
  constructor(readonly capacity = MOTION_COMMAND_QUEUE_CAPACITY) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new RangeError('[motion-command] queue capacity must be positive');
    }
  }
  get length(): number { return this.records.length; }
  enqueue(command: MotionValueCommand): void {
    validateMotionValueCommand(command);
    if (this.records.length >= this.capacity) {
      throw new RangeError(`[motion-command] pending queue is full at ${this.capacity} records`);
    }
    this.records.push(command);
  }
  drain(): readonly MotionValueCommand[] {
    return this.records.splice(0);
  }
  clear(): void { this.records.length = 0; }
  snapshot(): readonly MotionValueCommand[] { return [...this.records]; }
}
