// @system @ref LLP 0019 — Agentic platform focus and perf state snapshots
import type {
  FocusSnapshotData,
  KeyboardSnapshotData,
  PerfSnapshotData,
  PerfStartupReportData,
  ResolvedTarget,
} from "./types.js";
import {
  getKeyboardStateForRoot,
  getWindowIdForRoot,
  getWindowViewportForRoot,
} from "../window-state.js";

const MAX_COMMIT_TIMESTAMPS = 120;
const TARGET_FRAME_MS = 1000 / 60;
const DEFAULT_KEYBOARD_HEIGHT = 216;

const commitTimestamps: number[] = [];

let focusedRootId = 0;
let focusKeyboardOverride: {
  visible?: boolean;
  height?: number;
} = {};
let focusSnapshot: FocusSnapshotData = {
  keyboardVisible: false,
  keyboardHeight: 0,
  keyboard: {
    rootId: 0,
    windowId: getWindowIdForRoot(0),
    ...getKeyboardStateForRoot(0),
  },
};

function currentTimestamp(): number {
  return Date.now();
}

function getResolvedKeyboardSnapshot(): KeyboardSnapshotData {
  const keyboard = getKeyboardStateForRoot(focusedRootId);
  const viewport = getWindowViewportForRoot(focusedRootId);
  const visible =
    typeof focusKeyboardOverride.visible === "boolean"
      ? focusKeyboardOverride.visible
      : keyboard.visible;
  const syntheticHeight =
    typeof focusKeyboardOverride.height === "number"
      ? focusKeyboardOverride.height
      : visible && keyboard.occlusion.height <= 0
        ? DEFAULT_KEYBOARD_HEIGHT
        : keyboard.occlusion.height;

  return {
    rootId: focusedRootId,
    windowId: getWindowIdForRoot(focusedRootId),
    ...keyboard,
    visible,
    occlusion:
      visible && keyboard.occlusion.height <= 0
        ? {
            x: 0,
            y: Math.max(0, viewport.height - syntheticHeight),
            width: viewport.width,
            height: syntheticHeight,
          }
        : { ...keyboard.occlusion },
  };
}

export function setFocusedTarget(
  target?: ResolvedTarget,
  options: {
    rootId?: number;
    keyboardVisible?: boolean;
    keyboardHeight?: number;
  } = {},
): void {
  focusedRootId = typeof options.rootId === "number" ? options.rootId : focusedRootId;
  focusKeyboardOverride = {
    visible: options.keyboardVisible,
    height: options.keyboardHeight,
  };
  const keyboard = getResolvedKeyboardSnapshot();
  focusSnapshot = {
    target: target ? { ...target } : undefined,
    keyboardVisible: keyboard.visible,
    keyboardHeight: keyboard.occlusion.height,
    keyboard,
  };
}

export function clearFocusedTarget(rootId?: number): void {
  focusedRootId = typeof rootId === "number" ? rootId : focusedRootId;
  focusKeyboardOverride = {};
  const keyboard = getResolvedKeyboardSnapshot();
  focusSnapshot = {
    keyboardVisible: keyboard.visible,
    keyboardHeight: keyboard.occlusion.height,
    keyboard,
  };
}

export function getFocusTrackingState(): FocusSnapshotData {
  const keyboard = getResolvedKeyboardSnapshot();
  return {
    target: focusSnapshot.target ? { ...focusSnapshot.target } : undefined,
    keyboardVisible: keyboard.visible,
    keyboardHeight: keyboard.occlusion.height,
    keyboard,
  };
}

export function recordCommitTimestamp(timestamp = currentTimestamp()): void {
  commitTimestamps.push(timestamp);
  while (commitTimestamps.length > MAX_COMMIT_TIMESTAMPS) {
    commitTimestamps.shift();
  }
}

/**
 * Read the runtime startup report the native bootstrap publishes after a
 * successful entry evaluation (LLP 0413 §13;
 * docs/startup-report-host-surfacing.md). Guarded: absent globals (web tabs,
 * pre-LLP-0413 artifacts) yield nulls, never a throw. `report: null` can
 * NEVER be read as parse-free — a parse-free claim requires the report
 * present with both runtime counters zero (not null).
 */
function readStartupReportSection(): PerfStartupReportData {
  const globals = globalThis as {
    __exactStartupReport?: unknown;
    __exactLoadTimings?: unknown;
    __exactStartupArtifactCacheKey?: unknown;
  };
  const rawReport = globals.__exactStartupReport;
  const report =
    rawReport !== null && typeof rawReport === "object"
      ? { ...(rawReport as Record<string, unknown>) }
      : null;
  let startupReportReadyMs: number | null = null;
  const timings = globals.__exactLoadTimings;
  if (timings !== null && typeof timings === "object") {
    const t0 = Number((timings as Record<string, unknown>).t0);
    const ready = Number(
      (timings as Record<string, unknown>).startupReportReady,
    );
    if (Number.isFinite(t0) && Number.isFinite(ready)) {
      startupReportReadyMs = Math.round(ready - t0);
    }
  }
  const cacheKey =
    typeof globals.__exactStartupArtifactCacheKey === "string" &&
    globals.__exactStartupArtifactCacheKey.length > 0
      ? globals.__exactStartupArtifactCacheKey
      : null;
  return { report, startupReportReadyMs, cacheKey };
}

export function getPerfTrackingState(frameCount: number): PerfSnapshotData {
  const recentCommitIntervals: number[] = [];
  let droppedFrameEstimate = 0;

  for (let index = 1; index < commitTimestamps.length; index += 1) {
    const interval = Math.max(0, commitTimestamps[index]! - commitTimestamps[index - 1]!);
    recentCommitIntervals.push(interval);
    droppedFrameEstimate += Math.max(0, Math.round(interval / TARGET_FRAME_MS) - 1);
  }

  const averageFrameTime =
    recentCommitIntervals.length > 0
      ? recentCommitIntervals.reduce((sum, value) => sum + value, 0) /
        recentCommitIntervals.length
      : null;

  return {
    frameCount,
    recentCommitIntervals,
    averageFrameTime,
    droppedFrameEstimate,
    jsThreadUtilization: null,
    startupReport: readStartupReportSection(),
  };
}

export function resetAgentInteractionStateTracking(): void {
  commitTimestamps.length = 0;
  focusedRootId = 0;
  focusKeyboardOverride = {};
  const keyboard = getResolvedKeyboardSnapshot();
  focusSnapshot = {
    keyboardVisible: keyboard.visible,
    keyboardHeight: keyboard.occlusion.height,
    keyboard,
  };
}
