// @system @ref LLP 0074#reduced-motion-interaction-class-profile
import { MOTION_REDUCED_MOTION_PROFILE } from "./reduced-motion-profile.generated.js";

export { MOTION_REDUCED_MOTION_PROFILE };

export type MotionInteractionClass =
  (typeof MOTION_REDUCED_MOTION_PROFILE.classes)[number]["id"];
export type MotionReducedMotionAction =
  (typeof MOTION_REDUCED_MOTION_PROFILE.actions)[number];
export type MotionReducedMotionSpatialPolicy =
  (typeof MOTION_REDUCED_MOTION_PROFILE.classes)[number]["spatialMotion"];
export type MotionReducedMotionDecorationPolicy =
  (typeof MOTION_REDUCED_MOTION_PROFILE.classes)[number]["decoration"];

export interface MotionReducedMotionResolution {
  interactionClass: MotionInteractionClass;
  applied: boolean;
  action: MotionReducedMotionAction | "unchanged";
  durationMs: number | null;
  spatialMotion: MotionReducedMotionSpatialPolicy | "unchanged";
  decoration: MotionReducedMotionDecorationPolicy | "unchanged";
}

const policyByClass = new Map(
  MOTION_REDUCED_MOTION_PROFILE.classes.map((entry) => [entry.id, entry]),
);

/**
 * Shared resolver for Motion, presenters, and the permanent web runtime.
 * A `null`/`unchanged` result is never a guess: the preference is disabled,
 * or this is an opt-in Tier-1 entry whose `respectsReducedMotion` is false.
 */
export function resolveMotionReducedMotion(
  interactionClass: MotionInteractionClass,
  options: {
    reducedMotion: boolean;
    respectsReducedMotion?: boolean;
  },
): MotionReducedMotionResolution {
  const policy = policyByClass.get(interactionClass);
  if (!policy) {
    throw new TypeError(
      `[motion] unknown reduced-motion interaction class ${interactionClass}`,
    );
  }
  const applies =
    options.reducedMotion &&
    (policy.applicability === "always" ||
      options.respectsReducedMotion !== false);
  return applies
    ? {
        interactionClass,
        applied: true,
        action: policy.action,
        durationMs: policy.durationMs,
        spatialMotion: policy.spatialMotion,
        decoration: policy.decoration,
      }
    : {
        interactionClass,
        applied: false,
        action: "unchanged",
        durationMs: null,
        spatialMotion: "unchanged",
        decoration: "unchanged",
      };
}

