// ---------------------------------------------------------------------------
// Lottie source/config derivation (LLP 0394 §6, ENG-25251).
//
// One derivation shared by the native canonical-prop path (below) and the
// web DOM description (dom-element-description.ts) so both hosts see
// identical values. Lives inline here rather than in its own module because
// normalize.ts is on the caltrain-native startup graph and the LLP 0128
// module-count ratchet only moves down — a separate lottie module would be
// one more eager startup module for a leaf most startups never mount.
//
// v1 source policy: plain string sources (URLs, absolute/relative paths,
// data:) pass through verbatim — hosts resolve them exactly like plain
// image sources (base-URL join + media-load policy gate). `asset()` refs
// resolve to their url/relativePath. The versioned `exact:lottie:` JSON
// envelope (headers/cacheKey/cachePolicy) is reserved by LLP 0394 §6.1 for
// structured requests; nothing emits it yet, but hosts already sniff the
// prefix, so introducing it later is additive.

export const EXACT_LOTTIE_ENVELOPE_PREFIX = 'exact:lottie:';

function normalizedHitSlopEdge(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : 0;
}

/** Defensive host-boundary normalization for the public hitSlop prop. */
export function normalizeHitSlop(value: unknown): string | undefined {
  if (typeof value === 'number') {
    const edge = normalizedHitSlopEdge(value);
    return `${edge},${edge},${edge},${edge}`;
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return undefined;
  }
  const edges = value as Record<string, unknown>;
  return [edges.top, edges.right, edges.bottom, edges.left]
    .map(normalizedHitSlopEdge)
    .join(',');
}

export interface LottiePlaybackConfig {
  autoplay: boolean;
  loop: boolean;
  speed: number;
  fit: 'contain' | 'cover' | 'fill' | 'none';
}

// Mirrors the Swift ExactLottieFit vocabulary; the four values also map
// 1:1 onto dotlottie-web's layout fit values on web.
const LOTTIE_FIT_VALUES: ReadonlySet<string> = new Set(['contain', 'cover', 'fill', 'none']);

function normalizeLottieFit(value: unknown): LottiePlaybackConfig['fit'] {
  return typeof value === 'string' && LOTTIE_FIT_VALUES.has(value)
    ? (value as LottiePlaybackConfig['fit'])
    : LOTTIE_CONFIG_DEFAULTS.fit;
}

export const LOTTIE_CONFIG_DEFAULTS: LottiePlaybackConfig = {
  autoplay: true,
  loop: true,
  speed: 1,
  fit: 'contain',
};

export function resolveLottieSource(props: Record<string, unknown>): string | undefined {
  const direct = props.lottieSource;
  if (typeof direct === 'string' && direct.length > 0) return direct;

  const src = props.src;
  if (typeof src === 'string' && src.length > 0) return src;
  if (isAssetRef(src)) {
    return src.url ?? src.relativePath;
  }
  return undefined;
}

/**
 * Deterministic JSON config string (stable key order) so unchanged playback
 * settings never produce a spurious prop diff.
 */
export function buildLottieConfig(props: Record<string, unknown>): string | undefined {
  const direct = props.lottieConfig;
  if (typeof direct === 'string' && direct.length > 0) return direct;

  const autoplay = typeof props.autoplay === 'boolean'
    ? props.autoplay
    : LOTTIE_CONFIG_DEFAULTS.autoplay;
  const loop = typeof props.loop === 'boolean' ? props.loop : LOTTIE_CONFIG_DEFAULTS.loop;
  const speed = typeof props.speed === 'number' && Number.isFinite(props.speed) && props.speed > 0
    ? props.speed
    : LOTTIE_CONFIG_DEFAULTS.speed;
  const fit = normalizeLottieFit(props.fit);

  return `{"autoplay":${autoplay},"fit":"${fit}","loop":${loop},"speed":${speed}}`;
}

export function parseLottieConfig(config: string | undefined): LottiePlaybackConfig {
  if (!config) return { ...LOTTIE_CONFIG_DEFAULTS };
  try {
    const parsed = JSON.parse(config) as Partial<LottiePlaybackConfig>;
    return {
      autoplay: typeof parsed.autoplay === 'boolean'
        ? parsed.autoplay
        : LOTTIE_CONFIG_DEFAULTS.autoplay,
      loop: typeof parsed.loop === 'boolean' ? parsed.loop : LOTTIE_CONFIG_DEFAULTS.loop,
      speed: typeof parsed.speed === 'number' && Number.isFinite(parsed.speed) && parsed.speed > 0
        ? parsed.speed
        : LOTTIE_CONFIG_DEFAULTS.speed,
      fit: normalizeLottieFit(parsed.fit),
    };
  } catch {
    return { ...LOTTIE_CONFIG_DEFAULTS };
  }
}

export function resolveLottiePlayerId(props: Record<string, unknown>): string | undefined {
  const id = props.lottiePlayerId;
  return typeof id === 'string' && id.length > 0 ? id : undefined;
}

// ---------------------------------------------------------------------------
// Rive source/config/binding derivation (LLP 0395, ENG-25252).

export const EXACT_RIVE_ENVELOPE_PREFIX = 'exact:rive:';

export type RiveFit =
  | 'contain'
  | 'cover'
  | 'fill'
  | 'fitWidth'
  | 'fitHeight'
  | 'none'
  | 'scaleDown'
  | 'layout';

export type RiveAlignment =
  | 'center'
  | 'topLeft'
  | 'topCenter'
  | 'topRight'
  | 'centerLeft'
  | 'centerRight'
  | 'bottomLeft'
  | 'bottomCenter'
  | 'bottomRight';

export interface RivePlaybackConfig {
  alignment: RiveAlignment;
  animation?: string;
  artboard?: string;
  autoBind: boolean;
  autoplay: boolean;
  fit: RiveFit;
  layoutScaleFactor: number;
  pointerMode: 'none' | 'opaque';
  stateMachine?: string;
}

export type RiveBindingValue = boolean | number | string;
export type RiveBindingSnapshot = Record<string, RiveBindingValue>;

// Owner note (LLP 0150): the fit/alignment vocabulary below is intentionally
// duplicated in the Contract analyzer (exact-contract compiler/analyze.ts)
// and the Apple bridge, following the image/video attr-vocabulary precedent.
// Keep the three sites in sync when the vocabulary changes.
const RIVE_FIT_VALUES: ReadonlySet<string> = new Set([
  'contain',
  'cover',
  'fill',
  'fitWidth',
  'fitHeight',
  'none',
  'scaleDown',
  'layout',
]);

const RIVE_ALIGNMENT_VALUES: ReadonlySet<string> = new Set([
  'center',
  'topLeft',
  'topCenter',
  'topRight',
  'centerLeft',
  'centerRight',
  'bottomLeft',
  'bottomCenter',
  'bottomRight',
]);

export const RIVE_CONFIG_DEFAULTS: RivePlaybackConfig = {
  alignment: 'center',
  autoBind: true,
  autoplay: true,
  fit: 'contain',
  layoutScaleFactor: 1,
  pointerMode: 'none',
};

function nonEmptyString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

function normalizeRiveFit(value: unknown): RiveFit {
  return typeof value === 'string' && RIVE_FIT_VALUES.has(value)
    ? (value as RiveFit)
    : RIVE_CONFIG_DEFAULTS.fit;
}

function normalizeRiveAlignment(value: unknown): RiveAlignment {
  return typeof value === 'string' && RIVE_ALIGNMENT_VALUES.has(value)
    ? (value as RiveAlignment)
    : RIVE_CONFIG_DEFAULTS.alignment;
}

function normalizeRiveLayoutScaleFactor(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0
    ? value
    : RIVE_CONFIG_DEFAULTS.layoutScaleFactor;
}

export function resolveRiveSource(props: Record<string, unknown>): string | undefined {
  const direct = nonEmptyString(props.riveSource);
  if (direct) return direct;

  const src = props.src;
  if (typeof src === 'string' && src.length > 0) return src;
  if (isAssetRef(src)) return src.url ?? src.relativePath;
  return undefined;
}

/** Stable-key JSON so semantically unchanged config never causes a reload. */
export function buildRiveConfig(props: Record<string, unknown>): string | undefined {
  const direct = nonEmptyString(props.riveConfig);
  if (direct) return direct;

  const config: RivePlaybackConfig = {
    alignment: normalizeRiveAlignment(props.alignment),
    ...(nonEmptyString(props.animation) ? { animation: nonEmptyString(props.animation) } : {}),
    ...(nonEmptyString(props.artboard) ? { artboard: nonEmptyString(props.artboard) } : {}),
    autoBind: typeof props.autoBind === 'boolean'
      ? props.autoBind
      : RIVE_CONFIG_DEFAULTS.autoBind,
    autoplay: typeof props.autoplay === 'boolean'
      ? props.autoplay
      : RIVE_CONFIG_DEFAULTS.autoplay,
    fit: normalizeRiveFit(props.fit),
    layoutScaleFactor: normalizeRiveLayoutScaleFactor(props.layoutScaleFactor),
    pointerMode: props.pointerMode === 'opaque' ? 'opaque' : 'none',
    ...(nonEmptyString(props.stateMachine)
      ? { stateMachine: nonEmptyString(props.stateMachine) }
      : {}),
  };
  return JSON.stringify(config);
}

export function parseRiveConfig(config: string | undefined): RivePlaybackConfig {
  if (!config) return { ...RIVE_CONFIG_DEFAULTS };
  try {
    const parsed = JSON.parse(config) as Partial<RivePlaybackConfig>;
    return {
      alignment: normalizeRiveAlignment(parsed.alignment),
      ...(nonEmptyString(parsed.animation) ? { animation: parsed.animation } : {}),
      ...(nonEmptyString(parsed.artboard) ? { artboard: parsed.artboard } : {}),
      autoBind: typeof parsed.autoBind === 'boolean'
        ? parsed.autoBind
        : RIVE_CONFIG_DEFAULTS.autoBind,
      autoplay: typeof parsed.autoplay === 'boolean'
        ? parsed.autoplay
        : RIVE_CONFIG_DEFAULTS.autoplay,
      fit: normalizeRiveFit(parsed.fit),
      layoutScaleFactor: normalizeRiveLayoutScaleFactor(parsed.layoutScaleFactor),
      pointerMode: parsed.pointerMode === 'opaque' ? 'opaque' : 'none',
      ...(nonEmptyString(parsed.stateMachine) ? { stateMachine: parsed.stateMachine } : {}),
    };
  } catch {
    return { ...RIVE_CONFIG_DEFAULTS };
  }
}

function isRiveBindingValue(value: unknown): value is RiveBindingValue {
  return (
    typeof value === 'boolean' ||
    typeof value === 'string' ||
    (typeof value === 'number' && Number.isFinite(value))
  );
}

const riveBindingWarnings = new Set<string>();

function warnDroppedRiveBinding(key: string): void {
  if (riveBindingWarnings.has(key)) return;
  riveBindingWarnings.add(key);
  console.warn(
    `[exact-renderer] rive bindings.${key} is not a boolean, finite number, or string; the key was dropped (nested view models and lists are deferred in v1).`,
  );
}

export function resetRiveBindingWarningsForTests(): void {
  riveBindingWarnings.clear();
}

function normalizeRiveBindings(value: unknown): RiveBindingSnapshot {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return {};
  const normalized: RiveBindingSnapshot = {};
  for (const key of Object.keys(value as Record<string, unknown>).sort()) {
    const candidate = (value as Record<string, unknown>)[key];
    if (isRiveBindingValue(candidate)) normalized[key] = candidate;
    else warnDroppedRiveBinding(key);
  }
  return normalized;
}

export function buildRiveBindings(props: Record<string, unknown>): string | undefined {
  const direct = nonEmptyString(props.riveBindings);
  if (direct) return direct;
  if (props.bindings === undefined) return undefined;
  return JSON.stringify(normalizeRiveBindings(props.bindings));
}

export function parseRiveBindings(bindings: string | undefined): RiveBindingSnapshot {
  if (!bindings) return {};
  try {
    return normalizeRiveBindings(JSON.parse(bindings));
  } catch {
    return {};
  }
}

export function resolveRiveControllerId(props: Record<string, unknown>): string | undefined {
  return nonEmptyString(props.riveControllerId);
}
