let sharedTextEncoder: TextEncoder | null = null;

// @system @ref LLP 0343#4-the-pressure-ledger
// Keep the u16 string-pressure ledger beside the enforcing writer. Importing
// it from the diagnostics-facing resource-pressure subpath would add that
// optional facade to every native first-frame graph (LLP 0128).
const MAX_PRESSURE_COUNT = (1n << 64n) - 1n;

export interface ProtocolStringPressureSnapshot {
  resetGeneration: number;
  stringProps: {
    attemptHighWater: number;
    enforcementCount: bigint;
    lastEvent?: { at: number; attemptedValue: number; effectiveValue: number };
  };
  svgSource: {
    attemptHighWater: number;
    enforcementCount: bigint;
    lastEvent?: { at: number; attemptedValue: number; effectiveValue: number };
  };
}

interface MutableProtocolStringPressure {
  attemptHighWater: number;
  enforcementCount: bigint;
  lastEvent?: { at: number; attemptedValue: number; effectiveValue: number };
}

const stringPropPressure: MutableProtocolStringPressure = {
  attemptHighWater: 0,
  enforcementCount: 0n,
};
const svgSourcePressure: MutableProtocolStringPressure = {
  attemptHighWater: 0,
  enforcementCount: 0n,
};
let protocolStringPressureResetGeneration = 0;

export function recordProtocolStringPressure(
  attemptedValue: number,
  effectiveValue: number,
  isSvgSource: boolean,
  at = Date.now(),
): void {
  recordProtocolStringPressureEntry(
    stringPropPressure,
    attemptedValue,
    effectiveValue,
    at,
  );
  if (isSvgSource) {
    recordProtocolStringPressureEntry(
      svgSourcePressure,
      attemptedValue,
      effectiveValue,
      at,
    );
  }
}

function recordProtocolStringPressureEntry(
  pressure: MutableProtocolStringPressure,
  attemptedValue: number,
  effectiveValue: number,
  at: number,
): void {
  pressure.attemptHighWater = Math.max(pressure.attemptHighWater, attemptedValue);
  if (attemptedValue <= effectiveValue) return;
  pressure.enforcementCount = pressure.enforcementCount < MAX_PRESSURE_COUNT
    ? pressure.enforcementCount + 1n
    : MAX_PRESSURE_COUNT;
  pressure.lastEvent = { at, attemptedValue, effectiveValue };
}

function cloneProtocolStringPressure(
  source: MutableProtocolStringPressure,
): MutableProtocolStringPressure {
  return {
    attemptHighWater: source.attemptHighWater,
    enforcementCount: source.enforcementCount,
    ...(source.lastEvent ? { lastEvent: { ...source.lastEvent } } : {}),
  };
}

export function getProtocolStringPressure(): ProtocolStringPressureSnapshot {
  return {
    resetGeneration: protocolStringPressureResetGeneration,
    stringProps: cloneProtocolStringPressure(stringPropPressure),
    svgSource: cloneProtocolStringPressure(svgSourcePressure),
  };
}

/** Test/runtime-reset hook; production callers do not reset individual counters. */
export function resetProtocolStringPressure(): void {
  for (const pressure of [stringPropPressure, svgSourcePressure]) {
    pressure.attemptHighWater = 0;
    pressure.enforcementCount = 0n;
    delete pressure.lastEvent;
  }
  protocolStringPressureResetGeneration += 1;
}

function getSharedTextEncoder(): TextEncoder {
  sharedTextEncoder ??= new TextEncoder();
  return sharedTextEncoder;
}

/**
 * Wire limit shared with the kernel decoder: op payload lengths are u16
 * (kernel/src/protocol/buffer.rs push_op asserts the same bound). Writing a
 * longer payload wraps the header length field and desynchronizes every
 * subsequent op, so the kernel rejects the whole frame (ENG-23149).
 */
export const MAX_OP_PAYLOAD_BYTES = 0xffff;
export const PAGER_BINDING_PAYLOAD_MAGIC = 0x4250;
export const PAGER_BINDING_LAYOUT_VERSION = 2;
export const PAGER_BINDING_PAYLOAD_HEADER_SIZE = 6;
export const PAGER_BINDING_ENTRY_SIZE = 22;

/** Max UTF-8 bytes for a string prop: payload = propId(2) + len(2) + text. */
export const MAX_STRING_PROP_BYTES = MAX_OP_PAYLOAD_BYTES - 4;

/** Max children per SetChildren op: payload = count(2) + 4 bytes per child. */
export const MAX_CHILDREN_PER_OP = Math.floor((MAX_OP_PAYLOAD_BYTES - 2) / 4);

/**
 * Degradation policy for oversized string payloads: clamp on a UTF-8 boundary
 * and report loudly. A truncated string renders (and keeps the rest of the
 * commit decodable); a wrapped length field silently drops the entire frame.
 */
function clampUtf8ToLimit(
  bytes: Uint8Array,
  limit: number,
  what: string,
): Uint8Array {
  if (bytes.length <= limit) {
    return bytes;
  }
  let end = limit;
  // Back off UTF-8 continuation bytes so the cut keeps valid UTF-8.
  while (end > 0 && ((bytes[end] ?? 0) & 0xc0) === 0x80) {
    end -= 1;
  }
  console.error(
    `[exact-protocol] ${what} is ${bytes.length} UTF-8 bytes; the u16 wire limit allows ${limit}. ` +
      `Truncating to ${end} bytes to keep the op stream decodable (ENG-23149). ` +
      'Split the content across nodes (or move large media out of inline data URIs) to avoid data loss.',
  );
  return bytes.subarray(0, end);
}

export interface Dimension {
  type: 'auto' | 'points' | 'percent';
  value?: number;
}

/** LLP 0336 pager binding snapshot entry (22 bytes on the wire). */
export interface PagerBindingDescriptor {
  pagerViewId: number;
  claimViewId: number;
  bindingGeneration: number;
  centerRevision: number;
  turnToken: number;
  axis: 'horizontal' | 'vertical';
  hasPrev: boolean;
  hasNext: boolean;
  /**
   * Opt-in presentation policy for a center change the host's own gesture
   * recognizer did not originate. `never` (the default) keeps a programmatic
   * center change a snap.
   */
  animateCenter?: 'never' | 'external' | 'always';
  /**
   * Direction the center moved to reach `centerRevision`. `none` means no
   * direction was recoverable, which always presents as a snap.
   */
  centerDirection?: 'none' | 'prev' | 'next';
}

const PAGER_ANIMATE_CENTER_CODE = { never: 0, external: 1, always: 2 } as const;
const PAGER_CENTER_DIRECTION_CODE = { none: 0, prev: 1, next: 2 } as const;

