/** Clamp a grid template track count to the kernel's u8 model (1..255). */
function clampGridTrackCount(value: number): number {
  if (!Number.isFinite(value)) return 1;
  return Math.min(255, Math.max(1, Math.trunc(value)));
}
const DIRECTION_VALUES = ['ltr', 'rtl'] as const;
const WRITING_MODE_VALUES = ['horizontal-tb', 'vertical-rl', 'vertical-lr'] as const;
