/**
 * Dev-only, bounded, once-per-(vocabulary,value) warning for enum fallback.
 *
 * An unrecognized enum string used to encode as the fallback index with no
 * trace — which let `position="fixed"` masquerade as `relative` for weeks
 * (issues/closed/20260728-native-fixed-position-resolves-to-safe-area.md,
 * issues/closed/20260730-write-masked-enum-silent-fallback.md). The gate
 * mirrors host-call-bridge's production check: only an explicit
 * NODE_ENV=production silences it (release HBC bundles set it).
 */
const warnedEnumFallbacks = new Set<string>();
const WARNED_ENUM_FALLBACK_CAPACITY = 64;

function warnEnumFallback(
  value: string,
  values: readonly string[],
  fallback: number,
): void {
  const nodeEnv = (
    globalThis as { process?: { env?: Record<string, string | undefined> } }
  ).process?.env?.NODE_ENV;
  if (nodeEnv === 'production') {
    return;
  }
  const key = `${values[0] ?? ''}|${values.length}::${value}`;
  if (warnedEnumFallbacks.has(key) || warnedEnumFallbacks.size >= WARNED_ENUM_FALLBACK_CAPACITY) {
    return;
  }
  warnedEnumFallbacks.add(key);
  // eslint-disable-next-line no-console
  console.warn(
    `[exact-protocol] enum value "${value}" is not in [${values.join(', ')}]; ` +
      `encoding the fallback "${values[fallback] ?? String(fallback)}" instead. ` +
      'The authored value is silently changing meaning on the wire — fix the ' +
      'author or teach the encoder the new value.',
  );
}

function writeEnumByte(
  view: DataView,
  offset: number,
  value: string,
  values: readonly string[],
  fallback = 0,
): number {
  const index = values.indexOf(value);
  if (index < 0) {
    warnEnumFallback(value, values, fallback);
  }
  view.setUint8(offset, index >= 0 ? index : fallback);
  return offset + 1;
}

/**
 * Buffer writer for constructing protocol messages
 */
export class BufferWriter {
  // Keep this as an explicit field assignment instead of a constructor parameter
  // property so Node can evaluate the package through strip-only TS loading when
  // config-time tools import `@exact/core`.
  private capacity: number;
  private buffer: ArrayBuffer;
  private view: DataView;
  private uint8: Uint8Array;
  private offset: number = BUFFER_HEADER_SIZE;
  private opCount: number = 0;
  private sequenceId: number;
  private readonly rootId: number;
  private readonly headerSize: number;
  private readonly protocolVersion: number;

  constructor(
    capacity: number = 1024 * 1024,
    sequenceId: number = 1,
    rootId: number = 0
  ) {
    this.capacity = capacity;
    this.buffer = new ArrayBuffer(capacity);
    this.view = new DataView(this.buffer);
    this.uint8 = new Uint8Array(this.buffer);
    this.sequenceId = sequenceId;
    this.rootId = rootId;
    // Use v3 12-byte header when rootId is non-zero, v2 8-byte header otherwise
    if (rootId !== 0) {
      this.headerSize = BUFFER_HEADER_V3_SIZE;
      this.protocolVersion = PROTOCOL_VERSION_3;
    } else {
      this.headerSize = BUFFER_HEADER_SIZE;
      this.protocolVersion = PROTOCOL_VERSION_2;
    }
    this.offset = this.headerSize;
  }

  /**
   * Reset the buffer for reuse
   */
  reset(sequenceId?: number): void {
    this.offset = this.headerSize;
    this.opCount = 0;
    if (sequenceId !== undefined) {
      this.sequenceId = sequenceId;
    } else {
      this.sequenceId++;
    }
  }

  /**
   * Get the current operation count
   */
  getOpCount(): number {
    return this.opCount;
  }

  /**
   * Get the current buffer size (bytes written)
   */
  getSize(): number {
    return this.offset;
  }

  /**
   * Write a CREATE_VIEW operation
   */
  createView(viewId: number, nodeType: NodeType = NodeType.View): this {
    this.writeOpHeader(OpCode.CreateView, viewId, 1);
    this.view.setUint8(this.offset++, nodeType);
    this.opCount++;
    return this;
  }

  /**
   * Write a DESTROY_VIEW operation
   */
  destroyView(viewId: number): this {
    this.writeOpHeader(OpCode.DestroyView, viewId, 0);
    this.opCount++;
    return this;
  }

  /**
   * Write a 64-bit mask as two 32-bit little-endian values
   */
  private writeMask64(offset: number, mask: Mask64): void {
    this.view.setUint32(offset, mask.low, true);
    this.view.setUint32(offset + 4, mask.high, true);
  }

  /**
   * Write a 128-bit mask as four 32-bit little-endian values (v2 protocol)
   * For v2 we always write 16 bytes: low u64 + high u64
   */
  private writeMask128(offset: number, maskLow: Mask64, maskHigh: Mask64 = { low: 0, high: 0 }): void {
    // Low 64 bits (bits 0-63)
    this.view.setUint32(offset, maskLow.low, true);
    this.view.setUint32(offset + 4, maskLow.high, true);
    // High 64 bits (bits 64-127)
    this.view.setUint32(offset + 8, maskHigh.low, true);
    this.view.setUint32(offset + 12, maskHigh.high, true);
  }

  /**
   * Write a SET_STYLE operation with size only (common case)
   */
  setStyleSize(viewId: number, width: number, height: number): this {
    this.ensureCapacity(OP_HEADER_SIZE + 1024);
    const payloadStart = this.offset + OP_HEADER_SIZE;
    let payloadOffset = payloadStart;

    // Write 128-bit mask (WIDTH | HEIGHT) - v2 protocol
    const mask = combineMasks(StyleMask.WIDTH, StyleMask.HEIGHT);
    this.writeMask128(payloadOffset, mask);
    payloadOffset += 16;

    // Write width (Points)
    this.view.setUint8(payloadOffset++, DimensionType.Points);
    this.view.setFloat32(payloadOffset, width, true);
    payloadOffset += 4;

    // Write height (Points)
    this.view.setUint8(payloadOffset++, DimensionType.Points);
    this.view.setFloat32(payloadOffset, height, true);
    payloadOffset += 4;

    const payloadLen = payloadOffset - payloadStart;
    this.writeOpHeader(OpCode.SetStyle, viewId, payloadLen);
    this.offset = payloadOffset;
    this.opCount++;
    return this;
  }

  /**
   * Write a SET_STYLE operation with size and background color
   */
  setStyleSizeAndColor(
    viewId: number,
    width: number,
    height: number,
    r: number,
    g: number,
    b: number,
    a: number = 255
  ): this {
    this.ensureCapacity(OP_HEADER_SIZE + 1024);
    const payloadStart = this.offset + OP_HEADER_SIZE;
    let payloadOffset = payloadStart;

    // Write 128-bit mask (WIDTH | HEIGHT | BACKGROUND_COLOR) - v2 protocol
    const mask = combineMasks(StyleMask.WIDTH, StyleMask.HEIGHT, StyleMask.BACKGROUND_COLOR);
    this.writeMask128(payloadOffset, mask);
    payloadOffset += 16;

    // Write width (Points)
    this.view.setUint8(payloadOffset++, DimensionType.Points);
    this.view.setFloat32(payloadOffset, width, true);
    payloadOffset += 4;

    // Write height (Points)
    this.view.setUint8(payloadOffset++, DimensionType.Points);
    this.view.setFloat32(payloadOffset, height, true);
    payloadOffset += 4;

    // Write background color (RGBA)
    this.view.setUint8(payloadOffset++, r);
    this.view.setUint8(payloadOffset++, g);
    this.view.setUint8(payloadOffset++, b);
    this.view.setUint8(payloadOffset++, a);

    const payloadLen = payloadOffset - payloadStart;
    this.writeOpHeader(OpCode.SetStyle, viewId, payloadLen);
    this.offset = payloadOffset;
    this.opCount++;
    return this;
  }

  /**
   * Write a transform patch operation that preserves existing layout style.
   */
  setTransform(
    viewId: number,
    x: number,
    y: number,
    scale: number = 1,
    rotate: number = 0,
  ): this {
    this.writeOpHeader(OpCode.SetTransform, viewId, 16);
    this.view.setFloat32(this.offset, x, true);
    this.offset += 4;
    this.view.setFloat32(this.offset, y, true);
    this.offset += 4;
    this.view.setFloat32(this.offset, scale, true);
    this.offset += 4;
    this.view.setFloat32(this.offset, rotate, true);
    this.offset += 4;
    this.opCount++;
    return this;
  }

  /**
   * Backward-compatible animation hot-path helper.
   */
  setStyleTransform(viewId: number, x: number, y: number): this {
    return this.setTransform(viewId, x, y);
  }

  /**
   * Write an opacity patch operation that preserves existing layout style.
   */
  setOpacity(viewId: number, opacity: number): this {
    this.writeOpHeader(OpCode.SetOpacity, viewId, 4);
    this.view.setFloat32(this.offset, opacity, true);
    this.offset += 4;
    this.opCount++;
    return this;
  }

  /**
   * Write a background-color patch operation that preserves existing layout style.
   */
  setBackgroundColor(
    viewId: number,
    color: { r: number; g: number; b: number; a: number },
  ): this {
    this.writeOpHeader(OpCode.SetBgColor, viewId, 4);
    this.view.setUint8(this.offset++, color.r);
    this.view.setUint8(this.offset++, color.g);
    this.view.setUint8(this.offset++, color.b);
    this.view.setUint8(this.offset++, color.a);
    this.opCount++;
    return this;
  }

  /** Replace the complete pager binding set for this protocol root. */
  setPagerBindings(viewId: number, bindings: readonly PagerBindingDescriptor[]): this {
    const maxBindings = Math.floor(
      (MAX_OP_PAYLOAD_BYTES - PAGER_BINDING_PAYLOAD_HEADER_SIZE) / PAGER_BINDING_ENTRY_SIZE,
    );
    if (bindings.length > maxBindings) {
      throw new RangeError(
        `[exact-protocol] pager binding count ${bindings.length} exceeds the wire limit ${maxBindings}`,
      );
    }
    for (const binding of bindings) {
      const identities = [
        ['pagerViewId', binding.pagerViewId, false],
        ['claimViewId', binding.claimViewId, false],
        ['bindingGeneration', binding.bindingGeneration, false],
        ['centerRevision', binding.centerRevision, false],
        ['turnToken', binding.turnToken, true],
      ] as const;
      for (const [name, value, allowZero] of identities) {
        if (!Number.isInteger(value) || value < (allowZero ? 0 : 1) || value > 0xffff_ffff) {
          throw new RangeError(`[exact-protocol] pager ${name} must be a ${allowZero ? '' : 'non-zero '}u32`);
        }
      }
    }
    const payloadLen = PAGER_BINDING_PAYLOAD_HEADER_SIZE +
      bindings.length * PAGER_BINDING_ENTRY_SIZE;
    this.writeOpHeader(OpCode.SetPagerBindings, viewId, payloadLen);
    this.view.setUint16(this.offset, PAGER_BINDING_PAYLOAD_MAGIC, true);
    this.offset += 2;
    this.view.setUint16(this.offset, PAGER_BINDING_LAYOUT_VERSION, true);
    this.offset += 2;
    this.view.setUint16(this.offset, bindings.length, true);
    this.offset += 2;
    for (const binding of bindings) {
      this.view.setUint32(this.offset, binding.pagerViewId, true);
      this.offset += 4;
      this.view.setUint32(this.offset, binding.claimViewId, true);
      this.offset += 4;
      this.view.setUint32(this.offset, binding.bindingGeneration, true);
      this.offset += 4;
      this.view.setUint32(this.offset, binding.centerRevision, true);
      this.offset += 4;
      this.view.setUint32(this.offset, binding.turnToken, true);
      this.offset += 4;
      this.view.setUint8(this.offset++, binding.axis === 'vertical' ? 1 : 0);
      // flags: bits 0..1 neighbor availability, bits 2..3 animateCenter,
      // bits 4..5 the center-change direction hint (LLP 0336 §4.1.1).
      this.view.setUint8(
        this.offset++,
        (binding.hasPrev ? 1 : 0) |
          (binding.hasNext ? 2 : 0) |
          (PAGER_ANIMATE_CENTER_CODE[binding.animateCenter ?? 'never'] << 2) |
          (PAGER_CENTER_DIRECTION_CODE[binding.centerDirection ?? 'none'] << 4),
      );
    }
    this.opCount++;
    return this;
  }

  /**
   * Carry one LLP 0099 M2 Motion snapshot chunk. The payload is produced by
   * the typed Motion codec; BufferWriter owns only the protocol envelope and
   * the u16 payload bound. A valid chunk always contains its fixed 36-byte
   * identity/digest header.
   */
  setMotionSnapshotChunk(viewId: number, payload: Uint8Array): this {
    if (!(payload instanceof Uint8Array) || payload.byteLength < 36) {
      throw new RangeError('[exact-protocol] Motion snapshot chunk must include its 36-byte header');
    }
    if (payload.byteLength > MAX_OP_PAYLOAD_BYTES) {
      throw new RangeError(
        `[exact-protocol] Motion snapshot chunk payload is ${payload.byteLength} bytes; ` +
          `the u16 wire limit is ${MAX_OP_PAYLOAD_BYTES}`,
      );
    }
    this.writeOpHeader(OpCode.SetMotionSnapshotChunk, viewId, payload.byteLength);
    this.uint8.set(payload, this.offset);
    this.offset += payload.byteLength;
    this.opCount++;
    return this;
  }

  /**
   * Carry one LLP 0099 M2/M3 value/driver command. The typed command codec
   * owns the 56-byte header and semantic validation; this method owns only
   * the protocol op envelope and its u16 bound.
   */
  setMotionCommand(viewId: number, payload: Uint8Array): this {
    if (!(payload instanceof Uint8Array) || payload.byteLength < 56) {
      throw new RangeError('[exact-protocol] Motion command must include its 56-byte header');
    }
    if (payload.byteLength > MAX_OP_PAYLOAD_BYTES) {
      throw new RangeError(
        `[exact-protocol] Motion command payload is ${payload.byteLength} bytes; ` +
          `the u16 wire limit is ${MAX_OP_PAYLOAD_BYTES}`,
      );
    }
    this.writeOpHeader(OpCode.SetMotionCommand, viewId, payload.byteLength);
    this.uint8.set(payload, this.offset);
    this.offset += payload.byteLength;
    this.opCount++;
    return this;
  }

  /** Carry one LLP 0139 Phase 2a native-list descriptor chunk. */
  setListModelChunk(viewId: number, payload: Uint8Array): this {
    if (!(payload instanceof Uint8Array) || payload.byteLength < 40) {
      throw new RangeError('[exact-protocol] List model chunk must include its 40-byte header');
    }
    if (payload.byteLength > MAX_OP_PAYLOAD_BYTES) {
      throw new RangeError(
        `[exact-protocol] List model chunk payload is ${payload.byteLength} bytes; ` +
          `the u16 wire limit is ${MAX_OP_PAYLOAD_BYTES}`,
      );
    }
    this.writeOpHeader(OpCode.SetListModelChunk, viewId, payload.byteLength);
    this.uint8.set(payload, this.offset);
    this.offset += payload.byteLength;
    this.opCount++;
    return this;
  }

  /**
   * Carry one LLP 0420 graphics scene publication chunk. The typed scene
   * codec owns the 56-byte header and its semantics; BufferWriter owns only
   * the protocol op envelope and the u16 payload bound. A chunk with no
   * trailing scene bytes is still exactly the header.
   */
  graphicsPublicationChunk(viewId: number, payload: Uint8Array): this {
    if (!(payload instanceof Uint8Array) || payload.byteLength < 56) {
      throw new RangeError(
        '[exact-protocol] Graphics publication chunk must include its 56-byte header',
      );
    }
    if (payload.byteLength > MAX_OP_PAYLOAD_BYTES) {
      throw new RangeError(
        `[exact-protocol] Graphics publication chunk payload is ${payload.byteLength} bytes; ` +
          `the u16 wire limit is ${MAX_OP_PAYLOAD_BYTES}`,
      );
    }
    this.writeOpHeader(OpCode.GraphicsPublicationChunk, viewId, payload.byteLength);
    this.uint8.set(payload, this.offset);
    this.offset += payload.byteLength;
    this.opCount++;
    return this;
  }

  /**
   * Carry one LLP 0420 graphics scene teardown. The payload is exactly the
   * fixed 12-byte record (surface_view_id: u32 LE, scene_epoch: u64 LE).
   */
  graphicsSceneTeardown(viewId: number, payload: Uint8Array): this {
    // The teardown record is fixed-width, and the kernel decoder rejects
    // trailing bytes outright, so the writer bound is an equality — a looser
    // lower bound would let an oversized payload through here and fail the
    // whole frame at the kernel edge instead.
    if (!(payload instanceof Uint8Array) || payload.byteLength !== 12) {
      throw new RangeError(
        '[exact-protocol] Graphics scene teardown payload must be exactly its 12-byte record',
      );
    }
    this.writeOpHeader(OpCode.GraphicsSceneTeardown, viewId, payload.byteLength);
    this.uint8.set(payload, this.offset);
    this.offset += payload.byteLength;
    this.opCount++;
    return this;
  }

  /**
   * Write a full SET_STYLE operation
   */
  setStyle(viewId: number, styles: StyleProps): this {
    this.ensureCapacity(OP_HEADER_SIZE + 4096);
    const payloadStart = this.offset + OP_HEADER_SIZE;
    let payloadOffset = payloadStart;
    let maskLow = { low: 0, high: 0 };
    let maskHigh = { low: 0, high: 0 };

    // Reserve space for 128-bit mask (16 bytes) - v2 protocol
    payloadOffset += 16;

    // Helper to write dimension
    const writeDimension = (dim: Dimension | number | undefined) => {
      if (dim === undefined) {
        return false;
      }

      if (typeof dim === 'number') {
        this.view.setUint8(payloadOffset++, DimensionType.Points);
        this.view.setFloat32(payloadOffset, dim, true);
        payloadOffset += 4;
        return true;
      }

      if (dim.type === 'auto') {
        this.view.setUint8(payloadOffset++, DimensionType.Auto);
        this.view.setFloat32(payloadOffset, 0, true);
      } else if (dim.type === 'points') {
        this.view.setUint8(payloadOffset++, DimensionType.Points);
        this.view.setFloat32(payloadOffset, dim.value ?? 0, true);
      } else {
        this.view.setUint8(payloadOffset++, DimensionType.Percent);
        this.view.setFloat32(payloadOffset, dim.value ?? 0, true);
      }

      payloadOffset += 4;
      return true;
    };

    // Helper to add mask
    const addMask = (m: Mask64) => {
      maskLow.low = (maskLow.low | m.low) >>> 0;
      maskLow.high = (maskLow.high | m.high) >>> 0;
    };

    const addMask128 = (m: Mask128) => {
      maskLow.low = (maskLow.low | m.loLow) >>> 0;
      maskLow.high = (maskLow.high | m.loHigh) >>> 0;
      maskHigh.low = (maskHigh.low | m.hiLow) >>> 0;
      maskHigh.high = (maskHigh.high | m.hiHigh) >>> 0;
    };

    const writeColor = (color: { r: number; g: number; b: number; a: number }) => {
      this.view.setUint8(payloadOffset++, color.r);
      this.view.setUint8(payloadOffset++, color.g);
      this.view.setUint8(payloadOffset++, color.b);
      this.view.setUint8(payloadOffset++, color.a);
    };

    const writeMaskedDimension = (mask: Mask64, dim: Dimension | number | undefined) => {
      if (writeDimension(dim)) {
        addMask(mask);
      }
    };

    const writeMaskedFloat = (mask: Mask64, value: number | undefined) => {
      if (value === undefined) {
        return;
      }
      addMask(mask);
      this.view.setFloat32(payloadOffset, value, true);
      payloadOffset += 4;
    };

    const writeMaskedEnum = (
      mask: Mask64,
      value: string | undefined,
      values: readonly string[],
      fallback = 0,
    ) => {
      if (value === undefined) {
        return;
      }
      addMask(mask);
      payloadOffset = writeEnumByte(this.view, payloadOffset, value, values, fallback);
    };

    const writeMaskedColor = (
      mask: Mask64,
      color: { r: number; g: number; b: number; a: number } | undefined,
    ) => {
      if (color === undefined) {
        return;
      }
      addMask(mask);
      writeColor(color);
    };

    const writeMaskedEnum128 = (
      mask: Mask128,
      value: string | undefined,
      values: readonly string[],
      fallback = 0,
    ) => {
      if (value === undefined) {
        return;
      }
      addMask128(mask);
      payloadOffset = writeEnumByte(this.view, payloadOffset, value, values, fallback);
    };

    // IMPORTANT: Write values in the EXACT order the kernel reads them!
    // The kernel reads sequentially based on which mask bits are set.

    // 1. Size dimensions (WIDTH, HEIGHT, MIN_WIDTH, MIN_HEIGHT, MAX_WIDTH, MAX_HEIGHT)
    writeMaskedDimension(StyleMask.WIDTH, styles.width);
    writeMaskedDimension(StyleMask.HEIGHT, styles.height);
    writeMaskedDimension(StyleMask.MIN_WIDTH, styles.minWidth);
    writeMaskedDimension(StyleMask.MIN_HEIGHT, styles.minHeight);
    writeMaskedDimension(StyleMask.MAX_WIDTH, styles.maxWidth);
    writeMaskedDimension(StyleMask.MAX_HEIGHT, styles.maxHeight);

    // 2. Padding (TOP, RIGHT, BOTTOM, LEFT)
    writeMaskedDimension(StyleMask.PADDING_TOP, styles.paddingTop);
    writeMaskedDimension(StyleMask.PADDING_RIGHT, styles.paddingRight);
    writeMaskedDimension(StyleMask.PADDING_BOTTOM, styles.paddingBottom);
    writeMaskedDimension(StyleMask.PADDING_LEFT, styles.paddingLeft);

    // 3. Margin (TOP, RIGHT, BOTTOM, LEFT)
    writeMaskedDimension(StyleMask.MARGIN_TOP, styles.marginTop);
    writeMaskedDimension(StyleMask.MARGIN_RIGHT, styles.marginRight);
    writeMaskedDimension(StyleMask.MARGIN_BOTTOM, styles.marginBottom);
    writeMaskedDimension(StyleMask.MARGIN_LEFT, styles.marginLeft);

    // 4. Flexbox (DIRECTION, WRAP, JUSTIFY, ALIGN_ITEMS, ALIGN_SELF, GROW, SHRINK, BASIS)
    writeMaskedEnum(StyleMask.FLEX_DIRECTION, styles.flexDirection, FLEX_DIRECTION_VALUES);
    writeMaskedEnum(StyleMask.FLEX_WRAP, styles.flexWrap, FLEX_WRAP_VALUES);
    writeMaskedEnum(StyleMask.JUSTIFY_CONTENT, styles.justifyContent, JUSTIFY_CONTENT_VALUES);
    writeMaskedEnum(StyleMask.ALIGN_ITEMS, styles.alignItems, ALIGN_ITEMS_VALUES, 4);
    writeMaskedEnum(StyleMask.ALIGN_SELF, styles.alignSelf, ALIGN_SELF_VALUES);
    writeMaskedFloat(StyleMask.FLEX_GROW, styles.flexGrow);
    writeMaskedFloat(StyleMask.FLEX_SHRINK, styles.flexShrink);
    writeMaskedDimension(StyleMask.FLEX_BASIS, styles.flexBasis);

    // 4b. Gap properties (ROW_GAP, COLUMN_GAP)
    writeMaskedFloat(StyleMask.ROW_GAP, styles.rowGap);
    writeMaskedFloat(StyleMask.COLUMN_GAP, styles.columnGap);

    // 5. Position (POSITION_TYPE, TOP, RIGHT, BOTTOM, LEFT)
    writeMaskedEnum(StyleMask.POSITION_TYPE, styles.positionType, POSITION_TYPE_VALUES);
    writeMaskedDimension(StyleMask.TOP, styles.top);
    writeMaskedDimension(StyleMask.RIGHT, styles.right);
    writeMaskedDimension(StyleMask.BOTTOM, styles.bottom);
    writeMaskedDimension(StyleMask.LEFT, styles.left);

    // 6. Transform (X, Y, SCALE, ROTATE)
    writeMaskedFloat(StyleMask.TRANSFORM_X, styles.transformX);
    writeMaskedFloat(StyleMask.TRANSFORM_Y, styles.transformY);
    writeMaskedFloat(StyleMask.TRANSFORM_SCALE, styles.transformScale);
    writeMaskedFloat(StyleMask.TRANSFORM_ROTATE, styles.transformRotate);

    // 7. Visual (BACKGROUND_COLOR, OPACITY, BORDER_RADIUS)
    writeMaskedColor(StyleMask.BACKGROUND_COLOR, styles.backgroundColor);
    writeMaskedFloat(StyleMask.OPACITY, styles.opacity);
    writeMaskedFloat(StyleMask.BORDER_RADIUS, styles.borderRadius);

    // 8. Border (WIDTH, COLOR)
    writeMaskedFloat(StyleMask.BORDER_WIDTH, styles.borderWidth);
    writeMaskedColor(StyleMask.BORDER_COLOR, styles.borderColor);

    // 8b. Shadow
    writeMaskedColor(StyleMask.SHADOW_COLOR, styles.shadowColor);

    if (
      styles.shadowOffsetX !== undefined &&
      styles.shadowOffsetY !== undefined
    ) {
      addMask(StyleMask.SHADOW_OFFSET);
      this.view.setFloat32(payloadOffset, styles.shadowOffsetX, true);
      payloadOffset += 4;
      this.view.setFloat32(payloadOffset, styles.shadowOffsetY, true);
      payloadOffset += 4;
    }

    writeMaskedFloat(StyleMask.SHADOW_RADIUS, styles.shadowRadius);
    writeMaskedFloat(StyleMask.SHADOW_OPACITY, styles.shadowOpacity);

    // 9. Overflow
    writeMaskedEnum(StyleMask.OVERFLOW, styles.overflow, OVERFLOW_VALUES);

    // 9b. Per-corner radii
    writeMaskedFloat(StyleMask.BORDER_RADIUS_TOP_LEFT, styles.borderTopLeftRadius);
    writeMaskedFloat(StyleMask.BORDER_RADIUS_TOP_RIGHT, styles.borderTopRightRadius);
    writeMaskedFloat(StyleMask.BORDER_RADIUS_BOTTOM_LEFT, styles.borderBottomLeftRadius);
    writeMaskedFloat(StyleMask.BORDER_RADIUS_BOTTOM_RIGHT, styles.borderBottomRightRadius);

    // 10. Typography
    if (styles.fontWeight !== undefined) {
      addMask(StyleMask.FONT_WEIGHT);
      this.view.setUint16(payloadOffset, styles.fontWeight, true);
      payloadOffset += 2;
    }

    writeMaskedEnum(StyleMask.TEXT_ALIGN, styles.textAlign, TEXT_ALIGN_VALUES);
    writeMaskedFloat(StyleMask.LINE_HEIGHT, styles.lineHeight);

    if (styles.numberOfLines !== undefined) {
      addMask(StyleMask.NUMBER_OF_LINES);
      this.view.setUint32(payloadOffset, styles.numberOfLines, true);
      payloadOffset += 4;
    }

    writeMaskedEnum(StyleMask.ELLIPSIZE_MODE, styles.ellipsizeMode, ELLIPSIZE_MODE_VALUES);
    writeMaskedEnum(StyleMask.DISPLAY, styles.display, DISPLAY_VALUES);

    // 11. Z-Index
    if (styles.zIndex !== undefined) {
      addMask(StyleMask.Z_INDEX);
      this.view.setInt32(payloadOffset, styles.zIndex, true);
      payloadOffset += 4;
    }

    // 12. Aspect Ratio
    writeMaskedFloat(StyleMask.ASPECT_RATIO, styles.aspectRatio);

    // 13. Font family and image properties
    if (styles.fontFamily !== undefined) {
      addMask(StyleMask.FONT_FAMILY);
      this.view.setUint16(payloadOffset, styles.fontFamily, true);
      payloadOffset += 2;
    }

    if (styles.resizeMode !== undefined) {
      addMask(StyleMask.RESIZE_MODE);
      this.view.setUint8(payloadOffset++, resizeModeToProtocolValue(styles.resizeMode));
    }

    writeMaskedFloat(StyleMask.BACKDROP_BLUR, styles.backdropBlur);
    writeMaskedFloat(StyleMask.FONT_SIZE, styles.fontSize);
    writeMaskedColor(StyleMask.TEXT_COLOR, styles.textColor);

    // 13b. Background gradient (LLP 0296 / ENG-22750). Order MUST match the
    // kernel decoder (`style_decoder.rs`): type (u8), angle (f32), then
    // start + end colors under one GRADIENT_COLORS bit.
    if (styles.gradientType !== undefined) {
      addMask(StyleMask.GRADIENT_TYPE);
      this.view.setUint8(payloadOffset++, styles.gradientType);
    }
    writeMaskedFloat(StyleMask.GRADIENT_ANGLE, styles.gradientAngle);
    if (styles.gradientColorStart !== undefined && styles.gradientColorEnd !== undefined) {
      addMask(StyleMask.GRADIENT_COLORS);
      writeColor(styles.gradientColorStart);
      writeColor(styles.gradientColorEnd);
    }

    // 14. CSS Grid container (high-word mask bits 64+). Payload order MUST
    // match the kernel decoder (`style_decoder.rs`): grid bits (64..71)
    // decode before DIRECTION (bit 72).
    writeMaskedEnum128(StyleMask128.GRID_AUTO_FLOW, styles.gridAutoFlow, GRID_AUTO_FLOW_VALUES);
    if (styles.gridTemplateColumns !== undefined) {
      addMask128(StyleMask128.GRID_TEMPLATE_COLUMNS);
      this.view.setUint8(payloadOffset++, clampGridTrackCount(styles.gridTemplateColumns));
    }
    if (styles.gridTemplateRows !== undefined) {
      addMask128(StyleMask128.GRID_TEMPLATE_ROWS);
      this.view.setUint8(payloadOffset++, clampGridTrackCount(styles.gridTemplateRows));
    }

    // 15. Extended typography (high-word mask bits 64+)
    writeMaskedEnum128(StyleMask128.DIRECTION, styles.direction, DIRECTION_VALUES);
    writeMaskedEnum128(StyleMask128.WRITING_MODE, styles.writingMode, WRITING_MODE_VALUES);
    writeMaskedEnum128(StyleMask128.FONT_STYLE, styles.fontStyle, FONT_STYLE_VALUES);
    writeMaskedEnum128(
      StyleMask128.TEXT_DECORATION_LINE,
      styles.textDecorationLine,
      TEXT_DECORATION_LINE_VALUES,
    );

    if (styles.fontVariantNumeric !== undefined) {
      addMask128(StyleMask128.FONT_VARIANT_NUMERIC);
      this.view.setUint8(payloadOffset++, styles.fontVariantNumeric & 0xff);
    }

    if (styles.letterSpacing !== undefined) {
      addMask128(StyleMask128.LETTER_SPACING);
      this.view.setFloat32(payloadOffset, styles.letterSpacing, true);
      payloadOffset += 4;
    }

    // Per-side borders (ENG-22085). Order MUST match the kernel decoder:
    // widths T/R/B/L, then colors T/R/B/L. High-word floats/colors use the
    // manual addMask128 pattern (writeMaskedFloat/Color are Mask64-only).
    if (styles.borderTopWidth !== undefined) {
      addMask128(StyleMask128.BORDER_WIDTH_TOP);
      this.view.setFloat32(payloadOffset, styles.borderTopWidth, true);
      payloadOffset += 4;
    }
    if (styles.borderRightWidth !== undefined) {
      addMask128(StyleMask128.BORDER_WIDTH_RIGHT);
      this.view.setFloat32(payloadOffset, styles.borderRightWidth, true);
      payloadOffset += 4;
    }
    if (styles.borderBottomWidth !== undefined) {
      addMask128(StyleMask128.BORDER_WIDTH_BOTTOM);
      this.view.setFloat32(payloadOffset, styles.borderBottomWidth, true);
      payloadOffset += 4;
    }
    if (styles.borderLeftWidth !== undefined) {
      addMask128(StyleMask128.BORDER_WIDTH_LEFT);
      this.view.setFloat32(payloadOffset, styles.borderLeftWidth, true);
      payloadOffset += 4;
    }
    if (styles.borderTopColor !== undefined) {
      addMask128(StyleMask128.BORDER_COLOR_TOP);
      writeColor(styles.borderTopColor);
    }
    if (styles.borderRightColor !== undefined) {
      addMask128(StyleMask128.BORDER_COLOR_RIGHT);
      writeColor(styles.borderRightColor);
    }
    if (styles.borderBottomColor !== undefined) {
      addMask128(StyleMask128.BORDER_COLOR_BOTTOM);
      writeColor(styles.borderBottomColor);
    }
    if (styles.borderLeftColor !== undefined) {
      addMask128(StyleMask128.BORDER_COLOR_LEFT);
      writeColor(styles.borderLeftColor);
    }
    if (styles.backdropMaterial !== undefined) {
      addMask128(StyleMask128.BACKDROP_MATERIAL);
      this.view.setUint8(payloadOffset, backdropMaterialProtocolValue(styles.backdropMaterial));
      payloadOffset += 1;
    }

    // Write 128-bit mask at the beginning of payload - v2 protocol
    this.writeMask128(payloadStart, maskLow, maskHigh);

    const payloadLen = payloadOffset - payloadStart;
    this.writeOpHeader(OpCode.SetStyle, viewId, payloadLen);
    this.offset = payloadOffset;
    this.opCount++;
    return this;
  }

  /**
   * Write a SET_TRANSITION operation.
   *
   * The payload is a whole-node replacement table:
   * [entry_count:u8]
   *   [property_id:u8][kind:u8][flags:u8][reserved:u8]
   *   [duration_ms:u16][delay_ms:u16][easing_type:u8][reserved:u8]
   *   [param1:f32][param2:f32][param3:f32][param4:f32]
  */
  setTransition(viewId: number, transitions: TransitionProps[]): this {
    if (transitions.length > 0xff) {
      throw new RangeError(
        `[exact-protocol] setTransition(${viewId}) got ${transitions.length} entries; ` +
          'the u8 wire count allows at most 255.',
      );
    }
    const payloadLen = 1 + transitions.length * 26;
    this.writeOpHeader(OpCode.SetTransition, viewId, payloadLen);

    this.view.setUint8(this.offset++, transitions.length);

    for (const transition of transitions) {
      this.view.setUint8(this.offset++, transition.propertyId);
      this.view.setUint8(this.offset++, transition.kind);
      this.view.setUint8(this.offset++, transition.respectsReducedMotion === false ? 0 : 1);
      this.view.setUint8(this.offset++, 0);
      this.view.setUint16(this.offset, transition.durationMs ?? 0, true);
      this.offset += 2;
      this.view.setUint16(this.offset, transition.delayMs ?? 0, true);
      this.offset += 2;
      this.view.setUint8(this.offset++, transition.easingType ?? TransitionEasingId.EaseInOut);
      this.view.setUint8(this.offset++, 0);

      const [param1, param2, param3, param4] = transition.params ?? [0, 0, 0, 0];
      this.view.setFloat32(this.offset, param1, true);
      this.offset += 4;
      this.view.setFloat32(this.offset, param2, true);
      this.offset += 4;
      this.view.setFloat32(this.offset, param3, true);
      this.offset += 4;
      this.view.setFloat32(this.offset, param4, true);
      this.offset += 4;
    }

    this.opCount++;
    return this;
  }

  /**
   * Write a SET_CHILDREN operation
   */
  setChildren(viewId: number, children: number[]): this {
    let encoded = children;
    if (children.length > MAX_CHILDREN_PER_OP) {
      console.error(
        `[exact-protocol] setChildren(${viewId}) got ${children.length} children; the u16 wire limit allows ${MAX_CHILDREN_PER_OP} per op. ` +
          'Dropping the overflow to keep the op stream decodable (ENG-23149). Virtualize the list to avoid this.',
      );
      encoded = children.slice(0, MAX_CHILDREN_PER_OP);
    }
    const payloadLen = 2 + encoded.length * 4;
    this.writeOpHeader(OpCode.SetChildren, viewId, payloadLen);

    // Write count
    this.view.setUint16(this.offset, encoded.length, true);
    this.offset += 2;

    // Write child IDs
    for (const childId of encoded) {
      this.view.setUint32(this.offset, childId, true);
      this.offset += 4;
    }

    this.opCount++;
    return this;
  }

  /**
   * Write a COMPUTE_LAYOUT operation
   */
  computeLayout(viewId: number, width: number, height: number): this {
    this.writeOpHeader(OpCode.ComputeLayout, viewId, 8);

    this.view.setFloat32(this.offset, width, true);
    this.offset += 4;
    this.view.setFloat32(this.offset, height, true);
    this.offset += 4;

    this.opCount++;
    return this;
  }

  /**
   * Write a MEASURE_TEXT operation
   *
   * @deprecated MeasureText is not accepted by the normal dispatch path. Use a
   * response-capable host text-measure channel instead.
   */
  measureText(viewId: number, text: string, fontSize: number): this {
    void viewId;
    void text;
    void fontSize;
    throw new Error(
      'BufferWriter.measureText is unsupported on the command-buffer dispatch path',
    );
  }

  private writeHeader(): void {
    this.view.setUint32(0, this.sequenceId, true);
    this.view.setUint16(4, this.opCount, true);
    this.view.setUint16(6, this.protocolVersion, true);
    if (this.protocolVersion >= PROTOCOL_VERSION_3) {
      this.view.setUint32(8, this.rootId, true);
    }
  }

  /**
   * Build the final buffer with header
   */
  build(): ArrayBuffer {
    this.writeHeader();
    // Return a copy of the used portion
    return this.buffer.slice(0, this.offset);
  }

  /**
   * Get the underlying buffer (for zero-copy scenarios)
   */
  getBuffer(): ArrayBuffer {
    this.writeHeader();
    return this.buffer;
  }

  /**
   * Get the underlying Uint8Array view
   */
  getUint8Array(): Uint8Array {
    this.writeHeader();
    return this.uint8.subarray(0, this.offset);
  }

  /**
   * Write a SET_PROP operation with a string value
   */
  setPropString(viewId: number, propId: PropId, value: string): this {
    const attemptedTextBytes = getSharedTextEncoder().encode(value);
    const textBytes = clampUtf8ToLimit(
      attemptedTextBytes,
      MAX_STRING_PROP_BYTES,
      `string prop ${propId} on view ${viewId}`,
    );
    recordProtocolStringPressure(
      attemptedTextBytes.length,
      textBytes.length,
      propId === PropId.SvgSource,
    );
    const payloadLen = 2 + 2 + textBytes.length; // propId (2) + length (2) + text

    this.writeOpHeader(OpCode.SetProp, viewId, payloadLen);

    // Write prop ID
    this.view.setUint16(this.offset, propId, true);
    this.offset += 2;

    // Write text length and text
    this.view.setUint16(this.offset, textBytes.length, true);
    this.offset += 2;
    this.uint8.set(textBytes, this.offset);
    this.offset += textBytes.length;

    this.opCount++;
    return this;
  }

  /**
   * Write a CLEAR_PROP operation (removes a prop from a view, ENG-23153)
   */
  clearProp(viewId: number, propId: PropId): this {
    this.writeOpHeader(OpCode.ClearProp, viewId, 2);
    this.view.setUint16(this.offset, propId, true);
    this.offset += 2;

    this.opCount++;
    return this;
  }

  /**
   * Write a BIND_EVENT operation
   */
  bindEvent(viewId: number, eventType: EventType, handlerId: number): this {
    const payloadLen = 1 + 4; // eventType (1) + handlerId (4)

    this.writeOpHeader(OpCode.BindEvent, viewId, payloadLen);

    this.view.setUint8(this.offset++, eventType);
    this.view.setUint32(this.offset, handlerId, true);
    this.offset += 4;

    this.opCount++;
    return this;
  }

  /**
   * Write an UNBIND_EVENT operation
   */
  unbindEvent(viewId: number, eventType: EventType): this {
    const payloadLen = 1; // eventType (1)

    this.writeOpHeader(OpCode.UnbindEvent, viewId, payloadLen);

    this.view.setUint8(this.offset++, eventType);

    this.opCount++;
    return this;
  }

  private ensureCapacity(needed: number): void {
    if (this.offset + needed <= this.capacity) {
      return;
    }
    let newCapacity = this.capacity;
    while (newCapacity < this.offset + needed) {
      newCapacity *= 2;
    }
    const newBuffer = new ArrayBuffer(newCapacity);
    new Uint8Array(newBuffer).set(this.uint8.subarray(0, this.offset));
    this.buffer = newBuffer;
    this.view = new DataView(this.buffer);
    this.uint8 = new Uint8Array(this.buffer);
    this.capacity = newCapacity;
  }

  private writeOpHeader(opType: OpCode, viewId: number, payloadLen: number): void {
    // Backstop mirroring the kernel builder's push_op assert: a wrapped u16
    // length desynchronizes the op stream for every subsequent op and the
    // kernel then rejects the whole frame (ENG-23149). String/children
    // writers clamp before reaching here; anything else oversized is a
    // programming error that must fail at encode time, not decode time.
    if (payloadLen > MAX_OP_PAYLOAD_BYTES) {
      throw new RangeError(
        `[exact-protocol] op ${opType} payload is ${payloadLen} bytes; the u16 wire limit is ${MAX_OP_PAYLOAD_BYTES}`,
      );
    }
    if (this.opCount >= 0xffff) {
      throw new RangeError(
        '[exact-protocol] frame op count exceeds the u16 wire limit (65535 ops)',
      );
    }
    this.ensureCapacity(OP_HEADER_SIZE + payloadLen);
    this.view.setUint8(this.offset, opType);
    this.view.setUint32(this.offset + 1, viewId, true);
    this.view.setUint16(this.offset + 5, payloadLen, true);
    this.offset += OP_HEADER_SIZE;
  }
}

function resizeModeToProtocolValue(
  resizeMode: NonNullable<StyleProps['resizeMode']>,
): number {
  switch (resizeMode) {
    case 'contain':
      return 1;
    case 'stretch':
      return 2;
    case 'center':
      return 3;
    case 'repeat':
      return 4;
    case 'cover':
    default:
      return 0;
  }
}
