export interface CollectionAgentMetadata {
  readonly logicalItemCount: number;
  readonly mountedItemCount: number;
  readonly virtualized: boolean;
  readonly nativeHost: boolean;
}

export const COLLECTION_AGENT_SEMANTICS_HINT =
  'logicalItems, mountedItems, virtualized, nativeHost';

/**
 * Add the reserved collection tuple after caller metadata so the collection
 * identity and counts cannot be clobbered by author hints.
 */
export function collectionAgentSemantics(
  metadata: CollectionAgentMetadata,
  caller?: Readonly<Record<string, unknown>>,
): AgentSemantics {
  return {
    ...(caller ?? {}),
    kind: 'list',
    value: [
      metadata.logicalItemCount,
      metadata.mountedItemCount,
      metadata.virtualized ? 1 : 0,
      metadata.nativeHost ? 1 : 0,
    ],
    hint: COLLECTION_AGENT_SEMANTICS_HINT,
  } as AgentSemantics;
}

