type CrashRuntimeModule = Awaited<ReturnType<typeof loadCrashRuntime>>;
type PrivacyRuntimeModule = Awaited<ReturnType<typeof loadPrivacyRuntime>>;
type CrashRuntimeLoader = () => Promise<CrashRuntimeModule>;
type PrivacyRuntimeLoader = () => Promise<PrivacyRuntimeModule>;
let crashRuntimeLoader: CrashRuntimeLoader = loadCrashRuntime;
let privacyRuntimeLoader: PrivacyRuntimeLoader = loadPrivacyRuntime;
let crashRuntimeLoadPromise: Promise<CrashRuntimeModule> | null = null;
let privacyRuntimeLoadPromise: Promise<PrivacyRuntimeModule> | null = null;
let crashCaptureInstallPromise: Promise<void> | null = null;
let crashStructuralCaptureInstallPromise: Promise<void> | null = null;

function retryableCrashRuntimeLoad(): Promise<CrashRuntimeModule> {
  if (crashRuntimeLoadPromise) return crashRuntimeLoadPromise;
  const promise = crashRuntimeLoader();
  crashRuntimeLoadPromise = promise;
  void promise.catch(() => {
    if (crashRuntimeLoadPromise === promise) crashRuntimeLoadPromise = null;
  });
  return promise;
}

function retryablePrivacyRuntimeLoad(): Promise<PrivacyRuntimeModule> {
  if (privacyRuntimeLoadPromise) return privacyRuntimeLoadPromise;
  const promise = privacyRuntimeLoader();
  privacyRuntimeLoadPromise = promise;
  void promise.catch(() => {
    if (privacyRuntimeLoadPromise === promise) privacyRuntimeLoadPromise = null;
  });
  return promise;
}

function resetCrashCaptureLoading(
  loaders?: {
    crash?: CrashRuntimeLoader;
    privacy?: PrivacyRuntimeLoader;
  },
): void {
  crashRuntimeLoader = loaders?.crash ?? loadCrashRuntime;
  privacyRuntimeLoader = loaders?.privacy ?? loadPrivacyRuntime;
  crashRuntimeLoadPromise = null;
  privacyRuntimeLoadPromise = null;
  crashCaptureInstallPromise = null;
  crashStructuralCaptureInstallPromise = null;
}

/** Test-only failure injection for the degrade-and-retry observability seam. */
export function _setCrashCaptureRuntimeLoadersForTests(
  loaders?: {
    crash?: CrashRuntimeLoader;
    privacy?: PrivacyRuntimeLoader;
  },
): void {
  resetCrashCaptureLoading(loaders);
}

function ensureCrashCaptureAfterFirstCommit(): void {
  if (!crashCaptureInstallPromise) {
    const attempt = retryableCrashRuntimeLoad().then(
      ({ ensureProductionCrashCapture }) => {
        ensureProductionCrashCapture();
      },
    );
    crashCaptureInstallPromise = attempt;
    void attempt.catch(() => {
      if (crashCaptureInstallPromise === attempt) crashCaptureInstallPromise = null;
    });
  }

  if (crashStructuralCaptureInstallPromise) return;
  const attempt = Promise.all([
    retryableCrashRuntimeLoad(),
    retryablePrivacyRuntimeLoad(),
  ]).then(
    ([{ installCrashStructuralCaptureProvider }, { CaptureTreeBuilder, encodeCaptureTree }]) => {
      installCrashStructuralCaptureProvider(() => {
        const tree = new CaptureTreeBuilder('screen');
        let nodeCount = 1;
        const appendElement = (parent: object, node: ElementNode, depth: number): void => {
          if (nodeCount >= 1024 || depth >= 64) return;
          const tag = /^[a-z][a-z0-9-]{0,31}$/.test(node.tagType) ? node.tagType : 'node';
          const semanticId = typeof node.props.testId === 'string'
            && /^[A-Za-z0-9._:-]{1,128}$/.test(node.props.testId)
            ? node.props.testId
            : undefined;
          const secure = node.tagType === 'input' && node.props.secureTextEntry === true;
          const captureNode = tree.append(parent, tag, semanticId, secure);
          nodeCount += 1;
          if (secure) return;
          for (const child of node.children) {
            if (child.kind === NodeKind.Element) appendElement(captureNode, child, depth + 1);
          }
        };
        for (const root of [...liveRoots.values()].sort((left, right) => left.rootId - right.rootId).slice(0, 8)) {
          if (nodeCount >= 1024) break;
          const captureRoot = tree.append(tree.root, 'root', `root:${root.rootId}`);
          nodeCount += 1;
          for (const child of root.children) appendElement(captureRoot, child, 2);
        }
        return encodeCaptureTree(tree.root, { deploymentContentCapture: false }, {
          maxNodes: 1024,
          maxDepth: 64,
          maxContentUtf16: 0,
        });
      });
    },
  );
  crashStructuralCaptureInstallPromise = attempt;
  void attempt.catch(() => {
    // Capture is degrade-don't-fail: rendering must not depend on an
    // observability chunk being available in an incomplete dev bundle. Clear
    // only the failed installation so a later commit can retry it.
    if (crashStructuralCaptureInstallPromise === attempt) {
      crashStructuralCaptureInstallPromise = null;
    }
  });
}
