function parseRequestedDirection(value: unknown): Direction | undefined {
  return value === 'ltr' || value === 'rtl' || value === 'auto'
    ? value
    : undefined;
}

function parseRequestedWritingMode(value: unknown): WritingMode | undefined {
  return value === 'horizontal-tb' || value === 'vertical-rl' || value === 'vertical-lr'
    ? value
    : undefined;
}

function getRootInheritedState(rootId: number = 0): InheritedElementState {
  const locale = getExactLocaleSnapshot();
  return {
    rootId,
    direction: locale.direction,
    writingMode: 'horizontal-tb',
    lang: locale.tag,
    safeArea: createRootSafeAreaPropagation(rootId),
    imageListContext: false,
  };
}

function isSemanticRecyclerProps(originalTag: string, props: Props): boolean {
  return originalTag === 'List' && (
    props.virtualized === true ||
    props.__exactComponentName === 'NativeHostList'
  );
}

function isSemanticRecycler(node: Pick<ElementNode, 'originalTag' | 'originalProps'>): boolean {
  return isSemanticRecyclerProps(node.originalTag, node.originalProps);
}

function isImagePolicyPortalBoundary(props: Props): boolean {
  return props.portalTarget !== undefined || props.__exactPortalLevel !== undefined;
}

function imageListContextForElement(props: Props, inherited: InheritedElementState): boolean {
  return isImagePolicyPortalBoundary(props) ? false : inherited.imageListContext;
}

function getInheritedState(
  parent: ElementNode | RootNode | null | undefined,
): InheritedElementState {
  if (parent?.kind === NodeKind.Element) {
    return {
      rootId: parent.propagatedSafeArea?.rootId ?? getRootIdForNode(parent),
      direction: parent.resolvedDirection,
      writingMode: parent.resolvedWritingMode,
      lang: parent.resolvedLang,
      safeArea: parent.propagatedSafeArea ?? createRootSafeAreaPropagation(getRootIdForNode(parent)),
      imageListContext: isSemanticRecycler(parent) ? true : parent.resolvedImageListContext,
    };
  }

  return getRootInheritedState(parent?.kind === NodeKind.Root ? parent.rootId : 0);
}

function readInlineStyleValue(props: Props, key: string): unknown {
  const style = props.style;
  if (!style || typeof style !== 'object') {
    return undefined;
  }

  return (style as Record<string, unknown>)[key];
}

function getRequestedDirection(
  props: Props,
  classNameStyle: CanonicalStyle,
): Direction | undefined {
  return parseRequestedDirection(readInlineStyleValue(props, 'direction')) ?? classNameStyle.direction;
}

function getRequestedWritingMode(
  props: Props,
  classNameStyle: CanonicalStyle,
): WritingMode | undefined {
  return parseRequestedWritingMode(readInlineStyleValue(props, 'writingMode')) ?? classNameStyle.writingMode;
}

function getAutoDirectionText(props: CanonicalProps): string | undefined {
  return props.textContent ?? props.value;
}

function hasStableTextLayoutHint(props: Props): boolean {
  return props.__exactTextLayoutStable === true;
}

function hasFixedPointTextLayout(style: CanonicalStyle): boolean {
  return (
    style.width?.type === 'points' &&
    isFinite(style.width.value) &&
    style.height?.type === 'points' &&
    isFinite(style.height.value)
  );
}

function canPatchElementTextWithoutLayout(instance: ElementNode, props: Props): boolean {
  return (
    instance.tagType === 'text' &&
    hasStableTextLayoutHint(props) &&
    hasFixedPointTextLayout(instance.style)
  );
}

/**
 * Style fields the kernel reads when measuring a raw text leaf (the
 * TextMeasureCallback in kernel ffi.rs). A raw text leaf is a separate
 * kernel node from its styled parent <Text> element and the kernel does not
 * inherit styles across nodes, so this subset must be encoded onto the leaf
 * explicitly or the leaf measures with the default font while the host
 * renders the parent's — adapters that mount text as child leaves (Contract,
 * Solid) get boxes sized for the wrong font.
 */
const TEXT_LEAF_MEASURE_STYLE_KEYS = [
  'fontSize',
  'fontWeight',
  'fontStyle',
  'fontFamily',
  'lineHeight',
  'letterSpacing',
  'fontVariantNumeric',
  'direction',
  'numberOfLines',
] as const satisfies readonly (keyof CanonicalStyle)[];

function textMeasureStyleSubset(style: CanonicalStyle): CanonicalStyle | null {
  let subset: Record<string, unknown> | null = null;
  for (const key of TEXT_LEAF_MEASURE_STYLE_KEYS) {
    const value = style[key];
    if (value !== undefined) {
      (subset ??= {})[key] = value;
    }
  }
  return subset as CanonicalStyle | null;
}

function mergeTextMeasureStyles(
  inheritedStyle: CanonicalStyle | null,
  ownStyle: CanonicalStyle | null,
): CanonicalStyle | null {
  if (!inheritedStyle) {
    return ownStyle;
  }
  if (!ownStyle) {
    return inheritedStyle;
  }
  return {
    ...inheritedStyle,
    ...ownStyle,
  };
}

function inheritedTextMeasureStyleForNode(node: ElementNode): CanonicalStyle | null {
  const ancestors: ElementNode[] = [];
  let cursor: ElementNode | RootNode | TextNode | null = node.parent as
    | ElementNode
    | RootNode
    | TextNode
    | null;
  while (cursor?.kind === NodeKind.Element) {
    const ancestor = cursor as ElementNode;
    ancestors.unshift(ancestor);
    cursor = ancestor.parent as ElementNode | RootNode | TextNode | null;
  }

  let inheritedStyle: CanonicalStyle | null = null;
  let inInlineTextContext = false;
  for (const ancestor of ancestors) {
    if (ancestor.tagType === 'text') {
      inheritedStyle = mergeTextMeasureStyles(
        inheritedStyle,
        textMeasureStyleSubset(ancestor.style),
      );
      inInlineTextContext = true;
    } else if (inInlineTextContext && ancestor.tagType === 'pressable') {
      continue;
    } else {
      inheritedStyle = null;
      inInlineTextContext = false;
    }
  }

  return inheritedStyle;
}

function effectiveTextMeasureStyleForNode(
  node: ElementNode,
  inheritedStyle: CanonicalStyle | null,
): CanonicalStyle | null {
  return mergeTextMeasureStyles(inheritedStyle, textMeasureStyleSubset(node.style));
}

function inheritedTextMeasureStyleForChild(
  child: ElementNode | TextNode,
  inheritedStyle: CanonicalStyle | null,
): CanonicalStyle | null {
  if (child.kind !== NodeKind.Element) {
    return inheritedStyle;
  }

  if (child.tagType === 'text') {
    return effectiveTextMeasureStyleForNode(child, inheritedStyle);
  }

  return inheritedStyle && child.tagType === 'pressable' ? inheritedStyle : null;
}

function inheritedTextMeasureStyleForInsertedChildren(
  parent: ElementNode | RootNode,
): CanonicalStyle | null {
  if (parent.kind !== NodeKind.Element) {
    return null;
  }

  const inheritedStyle = inheritedTextMeasureStyleForNode(parent);
  if (parent.tagType === 'text') {
    return effectiveTextMeasureStyleForNode(parent, inheritedStyle);
  }

  return inheritedStyle && parent.tagType === 'pressable' ? inheritedStyle : null;
}

function styleKeysAffectTextLeafMeasure(
  changedKeys: readonly (keyof CanonicalStyle)[],
): boolean {
  return changedKeys.some((key) =>
    (TEXT_LEAF_MEASURE_STYLE_KEYS as readonly string[]).includes(key),
  );
}

/**
 * A text ELEMENT's wire style: its own full canonical style layered over the
 * inherited measure-style fill.
 *
 * Protocol `SetStyle` REPLACES the kernel node's whole style (kernel
 * `set_style` assigns `node.styles`, and the mask-based decode starts from
 * defaults), so re-encoding only the measure subset onto an already-styled
 * text element silently wipes every non-measure style it carries — most
 * visibly an inline run's explicit `color`, whose TEXT_COLOR set-ness bit is
 * what stops the native presenters from inheriting the parent color over it
 * (ENG-22737: the blog wordmark's orange "Wholly Un" went parent-colored on
 * the first theme flip after the async Inter registration changed the
 * resolved fontFamily id). The node's own keys win over inherited measure
 * values exactly as they already did inside the measure subset merge.
 */
function textElementStyleWithInheritedMeasure(
  node: ElementNode,
  measureStyle: CanonicalStyle,
): CanonicalStyle {
  return { ...measureStyle, ...node.style };
}

/**
 * Keys set (non-undefined) on the canonical style but absent — or undefined,
 * which the protocol encoder skips — from the outgoing wire style. Returns
 * null when the wire style fully covers the canonical style.
 */
function canonicalStyleKeysMissingFromWire(
  canonicalStyle: CanonicalStyle,
  wireStyle: CanonicalStyle,
): Array<keyof CanonicalStyle> | null {
  if (canonicalStyle === wireStyle) {
    return null;
  }

  let missing: Array<keyof CanonicalStyle> | null = null;
  for (const key of Object.keys(canonicalStyle) as Array<keyof CanonicalStyle>) {
    if (canonicalStyle[key] !== undefined && wireStyle[key] === undefined) {
      (missing ??= []).push(key);
    }
  }
  return missing;
}

/**
 * The single emission path for an element-targeted SetStyle (ENG-22791).
 *
 * Protocol `SetStyle` REPLACES the kernel node's whole style: kernel
 * `set_style` assigns `node.styles` and the mask-based decode starts from
 * defaults, so every field missing from the op is reset kernel-side and loses
 * its set-ness mask bit. The invariant enforced here is that an element's
 * wire style must cover every set key of its canonical `node.style` — a
 * narrower SetStyle is exactly the ENG-22737 bug class (the text
 * measure-style re-encode sent only the measure subset onto an inline run,
 * wiping its explicit color and TEXT_COLOR set-ness bit, so native
 * presenters painted it in the parent's theme color after the next rebuild).
 *
 * A violating call site is healed by layering the canonical style over the
 * outgoing style (own keys win, so set-ness can never be silently wiped) and
 * flagged loudly in dev so the call site gets fixed. Intentional un-sets
 * remain possible: removing a style prop shrinks `node.style` first, so the
 * shrunken canonical style is its own cover.
 *
 * Raw text leaves and root containers carry no canonical element style, so
 * they bypass this helper and use `encodeSetStyleOp` directly.
 */
function emitElementSetStyle(
  encoder: ProtocolEncoder,
  node: ElementNode,
  wireStyle: CanonicalStyle,
): void {
  // SetStyle REPLACE semantics would otherwise un-hide a Suspense-hidden
  // node whose canonical style is re-emitted while hidden (ENG-23192).
  wireStyle = suspenseHiddenWireStyle(node, wireStyle);
  const missingKeys = canonicalStyleKeysMissingFromWire(node.style, wireStyle);
  if (missingKeys === null) {
    encodeSetStyleOp(encoder, node.id, wireStyle);
    return;
  }

  if (__DEV__) {
    console.error(
      `[HostOps] SetStyle for <${node.originalTag}> (id=${node.id}) is narrower than the node's canonical style ` +
        `(missing: ${missingKeys.join(', ')}). Protocol SetStyle has replace semantics, so a partial SetStyle wipes ` +
        `every unsent field and its kernel set-ness mask bit (ENG-22737 / ENG-22791). The canonical style was ` +
        `layered over the outgoing style to preserve set-ness; fix the call site to encode the full style.`,
    );
  }

  encodeSetStyleOp(encoder, node.id, { ...wireStyle, ...node.style });
}

/** @internal For testing only (ENG-22791 SetStyle narrowing guard). */
export { emitElementSetStyle as _emitElementSetStyle };

/** Re-encode the measure-style subset onto already-created text leaf children. */
function encodeTextLeafMeasureStyles(encoder: ProtocolEncoder, parent: ElementNode): void {
  const inheritedStyle = inheritedTextMeasureStyleForNode(parent);
  const parentMeasureStyle = effectiveTextMeasureStyleForNode(parent, inheritedStyle);
  if (!parentMeasureStyle) {
    return;
  }

  if (inheritedStyle) {
    emitElementSetStyle(
      encoder,
      parent,
      textElementStyleWithInheritedMeasure(parent, parentMeasureStyle),
    );
  }

  for (const child of parent.children) {
    encodeInheritedTextMeasureStyles(encoder, child, parentMeasureStyle);
  }
}

function encodeInheritedTextMeasureStyles(
  encoder: ProtocolEncoder,
  node: ElementNode | TextNode,
  inheritedStyle: CanonicalStyle | null,
): void {
  if (!inheritedStyle || hasDirtyFlag(node, DirtyFlags.Created)) {
    return;
  }

  if (node.kind === NodeKind.Text) {
    // Raw text leaf: it has no canonical element style to lose, so the plain
    // inherited measure subset is its full wire style.
    encodeSetStyleOp(encoder, node.id, inheritedStyle);
    return;
  }

  const nodeMeasureStyle = inheritedTextMeasureStyleForChild(node, inheritedStyle);
  if (!nodeMeasureStyle) {
    return;
  }

  if (node.tagType === 'text') {
    emitElementSetStyle(
      encoder,
      node,
      textElementStyleWithInheritedMeasure(node, nodeMeasureStyle),
    );
  }

  for (const child of node.children) {
    encodeInheritedTextMeasureStyles(encoder, child, nodeMeasureStyle);
  }
}

/**
 * Re-layer the insertion context's text-measure subset onto a reparented
 * (RFC 0043 detach → insert) subtree (ENG-23202).
 *
 * The kernel has no style inheritance: raw text leaves and text elements
 * carry the measure subset of their ANCESTOR text context baked into their
 * wire style at create time. A subtree moved to a new parent kept the old
 * context's fonts, so its leaves measured with the wrong font until an
 * unrelated style change happened to re-encode them. Mirrors
 * encodeInheritedTextMeasureStyles, and also heals the moved-out-of-text
 * case: SetStyle has REPLACE semantics, so emitting the (possibly empty) new
 * context resets stale inherited fields on raw leaves, and a text element's
 * own canonical style is always layered on top (set-ness safe, ENG-22791).
 */
function syncReparentedTextMeasureStyles(
  encoder: ProtocolEncoder,
  node: ElementNode | TextNode,
  inheritedStyle: CanonicalStyle | null,
): void {
  if (hasDirtyFlag(node, DirtyFlags.Created)) {
    return;
  }

  if (node.kind === NodeKind.Text) {
    // Raw leaf: no canonical style of its own — the inherited subset (or the
    // create-time empty default) IS its full wire style.
    encodeSetStyleOp(encoder, node.id, inheritedStyle ?? {});
    markViewChanged(node);
    return;
  }

  const nodeMeasureStyle = inheritedTextMeasureStyleForChild(node, inheritedStyle);
  if (node.tagType === 'text') {
    emitElementSetStyle(
      encoder,
      node,
      nodeMeasureStyle
        ? textElementStyleWithInheritedMeasure(node, nodeMeasureStyle)
        : node.style,
    );
    markViewChanged(node);
  }

  for (const child of node.children) {
    syncReparentedTextMeasureStyles(encoder, child, nodeMeasureStyle);
  }
}

function canPatchTextNodeWithoutLayout(instance: TextNode): boolean {
  const parent = instance.parent;
  if (parent?.kind !== NodeKind.Element) {
    return false;
  }
  const elementParent = parent as ElementNode;

  return (
    elementParent.tagType === 'text' &&
    hasStableTextLayoutHint(elementParent.originalProps) &&
    hasFixedPointTextLayout(elementParent.style)
  );
}

function serializeNativeViewProps(
  config: TagConfig,
  props: Props,
): string {
  const metadata = config.nativeView;
  if (!metadata) {
    return '{}';
  }

  const payload: Record<string, unknown> = {};
  for (const key of metadata.propKeys) {
    if (props[key] !== undefined) {
      payload[key] = props[key];
    }
  }

  try {
    return JSON.stringify(payload);
  } catch (error) {
    if (__DEV__) {
      console.warn(
        `[HostOps] Failed to serialize native-view props for ${metadata.moduleName}:`,
        error,
      );
    }
    return '{}';
  }
}

function augmentCanonicalPropsForNativeView(
  config: TagConfig,
  props: Props,
  canonicalProps: CanonicalProps,
): CanonicalProps {
  const metadata = config.nativeView;
  if (!metadata) {
    return canonicalProps;
  }

  // Toggle is transported as an exact.toggle NativeView, but its checked
  // value is still a canonical protocol/semantics prop. Preserve the same
  // toggle normalization that a direct canonical `toggle` tag receives;
  // nativeViewProps remains the module-specific payload for the presenter.
  const nativeCanonicalProps = metadata.moduleName === 'exact.toggle'
    ? { ...canonicalProps, ...normalizeProps('toggle', props, config.isRNStyle) }
    : canonicalProps;

  return {
    ...nativeCanonicalProps,
    nativeViewModuleName: metadata.moduleName,
    nativeViewProps: serializeNativeViewProps(config, props),
    nativeViewSelectionTier: metadata.selection?.tier,
    nativeViewGesturePolicy: metadata.selection?.gesturePolicy,
  };
}

function resolveDirectionForElement(
  originalTag: string,
  tagType: CanonicalTagType,
  requestedDirection: Direction | undefined,
  props: CanonicalProps,
  inherited: InheritedElementState,
): ResolvedDirection {
  if (requestedDirection === 'ltr' || requestedDirection === 'rtl') {
    return requestedDirection;
  }

  if (requestedDirection !== 'auto') {
    return inherited.direction;
  }

  const text = getAutoDirectionText(props);
  if (text !== undefined) {
    return detectTextDirection(text, inherited.direction);
  }

  if (__DEV__ && !warnedAutoDirectionTags.has(originalTag)) {
    warnedAutoDirectionTags.add(originalTag);
    console.warn(
      `[HostOps] direction="auto" requires text content; falling back to inherited direction for <${originalTag}> (${tagType}).`,
    );
  }

  return inherited.direction;
}

let resolveElementStateCallCount = 0;

/**
 * Number of resolveElementState invocations since the last reset.
 * @internal For testing only (verifies the updateInstanceProps fast path).
 */
export function _getResolveElementStateCallCount(): number {
  return resolveElementStateCallCount;
}

/** @internal For testing only. */
export function _resetResolveElementStateCallCount(): void {
  resolveElementStateCallCount = 0;
}

function resolveElementState(
  instance: ElementNode,
  config: TagConfig,
  originalTag: string,
  props: Props,
  inherited: InheritedElementState,
): ResolvedElementState {
  resolveElementStateCallCount += 1;
  // Lower text props to a paragraph spec exactly once per resolution and hand
  // the result to normalizeProps, instead of letting normalizeProps lower the
  // same props again internally. lowerTextPropsToParagraphSpec recursively
  // walks children and JSON.stringifies span styles/the whole spec, so a
  // second lowering here was pure duplicated work (ENG-23199).
  const paragraph = config.canonicalType === 'text'
    ? lowerTextPropsToParagraphSpec(props)
    : null;
  const canonicalProps = augmentCanonicalPropsForNativeView(
    config,
    props,
    normalizeProps(config.canonicalType, props, config.isRNStyle, paragraph),
  );
  const resolvedImageListContext = imageListContextForElement(props, inherited);
  if (
    config.canonicalType === 'image' &&
    canonicalProps.imageDynamicRange === undefined &&
    resolvedImageListContext
  ) {
    canonicalProps.imageDynamicRange = 'constrained';
  }
  const classNameStyle = resolveClassNameStyle(props.className, { props });
  const resolvedDirection = resolveDirectionForElement(
    originalTag,
    config.canonicalType,
    getRequestedDirection(props, classNameStyle),
    canonicalProps,
    inherited,
  );
  const resolvedWritingMode =
    getRequestedWritingMode(props, classNameStyle) ?? inherited.writingMode;
  const resolvedLang = canonicalProps.lang ?? inherited.lang;
  const contentContainerStyle = isScrollShapedCanonicalType(config.canonicalType)
    ? normalizeStyle(props.contentContainerStyle as FullStyle | undefined, 'row', {
        resolvedDirection,
        resolvedWritingMode,
        includeInheritedValues: true,
      })
    : {};
  const inlineStyle = normalizeStyle(props.style as FullStyle | undefined, 'row', {
    resolvedDirection,
    resolvedWritingMode,
    includeInheritedValues: true,
  });
  const style = applyTextLayoutPropStyleOverrides(
    config.canonicalType,
      applyPropDrivenStyleOverrides(
        config.canonicalType,
        {
          ...buildDefaultCanonicalStyle(config.defaultFlexDirection, config.isRNStyle),
        ...classNameStyle,
        ...contentContainerStyle,
        ...inlineStyle,
          direction: resolvedDirection,
          writingMode: resolvedWritingMode,
        },
        canonicalProps,
        props,
      ),
    props,
  );
  const accessibilityAwareStyle = applyRootScrollViewportDefaults(
    instance,
    applyAccessibilityDrivenStyleOverrides(style, canonicalProps),
  );

  const safeAreaResolution = resolveSafeAreaForElement(
    instance,
    instance.parent as ElementNode | RootNode | null,
    accessibilityAwareStyle,
    inherited.safeArea,
  );

  if (isScrollShapedCanonicalType(config.canonicalType) && accessibilityAwareStyle.overflow === undefined) {
    safeAreaResolution.style.overflow = 'scroll';
  }

  return {
    props: canonicalProps,
    paragraphSpec: paragraph?.spec ?? null,
    paragraphKey: paragraph?.key ?? null,
    style: safeAreaResolution.style,
    transitions: normalizeTransition((props.style as FullStyle | undefined)?.transition),
    resolvedDirection,
    resolvedWritingMode,
    resolvedLang,
    resolvedImageListContext,
    safeAreaState: safeAreaResolution.safeAreaState,
    propagatedSafeArea: safeAreaResolution.propagatedSafeArea,
  };
}

function applyResolvedElementState(
  instance: ElementNode,
  state: ResolvedElementState,
): void {
  // Island-authoritative style properties (LLP 0313/0417): while a layout
  // island binding is registered for a node, the commit edge is the single
  // writer for the bound property — it writes instance.style directly, and
  // the authored value in originalProps is only the pre-registration seed
  // (often stale: the sink strips the live expression from the authored
  // layer). Any re-resolution — prop updates, inherited-state refresh
  // walks — must carry the committed value forward, or the next SetStyle
  // reverts the kernel to the stale seed (the reinstall-reset bug class).
  const islandBindings = hostMotionLayoutIslandBindingsByNode.get(instance);
  if (islandBindings) {
    const committedStyle = instance.style as Record<string, unknown>;
    const nextStyle = state.style as Record<string, unknown>;
    for (const registration of islandBindings.values()) {
      const committed = committedStyle[registration.property];
      if (committed !== undefined) {
        nextStyle[registration.property] = committed;
      }
    }
  }
  instance.props = state.props;
  instance.paragraphSpec = state.paragraphSpec;
  instance.paragraphKey = state.paragraphKey;
  instance.style = state.style;
  instance.transitions = state.transitions;
  instance.resolvedDirection = state.resolvedDirection;
  instance.resolvedWritingMode = state.resolvedWritingMode;
  instance.resolvedLang = state.resolvedLang;
  instance.resolvedImageListContext = state.resolvedImageListContext;
  instance.safeAreaState = state.safeAreaState;
  instance.propagatedSafeArea = state.propagatedSafeArea;
}

function canRefreshCreatedMountEnvironment(
  instance: ElementNode,
  inherited: InheritedElementState,
): boolean {
  if (instance.safeAreaState !== null) {
    return false;
  }

  const expectedLang = instance.props.lang ?? inherited.lang;
  const expectedImageListContext = imageListContextForElement(instance.originalProps, inherited);
  return (
    instance.tagType !== 'text' &&
    instance.resolvedDirection === inherited.direction &&
    instance.resolvedWritingMode === inherited.writingMode &&
    instance.resolvedLang === expectedLang
    && instance.resolvedImageListContext === expectedImageListContext
  );
}

function refreshCreatedMountEnvironment(
  instance: ElementNode,
  inherited: InheritedElementState,
): void {
  instance.resolvedLang = instance.props.lang ?? inherited.lang;

  const safeAreaResolution = resolveSafeAreaForElement(
    instance,
    instance.parent as ElementNode | RootNode | null,
    applyRootScrollViewportDefaults(instance, instance.style),
    inherited.safeArea,
  );
  instance.style = safeAreaResolution.style;
  instance.safeAreaState = safeAreaResolution.safeAreaState;
  instance.propagatedSafeArea = safeAreaResolution.propagatedSafeArea;
}

interface NormalizedTextChangePayload {
  nativeEvent: {
    text: string;
    selection?: {
      start: number;
      end: number;
    };
    isComposing?: boolean;
    compositionRange?: {
      start: number;
      end: number;
    };
    textRevision?: number;
    classification?: string;
    textChanged?: boolean;
  };
}

type NormalizedImageEventType = 'loadStart' | 'load' | 'error' | 'display';

interface NormalizedImageEventPayload {
  event: NormalizedImageEventType;
  source: ImageLoadEvent['source'];
  cacheType: 'none' | 'disk' | 'memory';
  generation?: number;
  provenance?: ImageLoadEvent['provenance'];
  error: {
    code: ImageErrorCode;
    message: string;
    sourceId?: string;
    retryable: boolean;
    generation?: number;
  };
}

function normalizeTextChangePayload(payload: unknown): NormalizedTextChangePayload {
  const normalizedSelection = normalizeTextSelectionPayload(payload);
  const normalizedCompositionRange = normalizeTextRangePayload(
    payload,
    'compositionRange',
    'compositionStart',
    'compositionEnd',
  );
  const isComposing = readTextComposingPayload(payload);
  const textRevision = readTextRevisionPayload(payload);
  const classification = readTextClassificationPayload(payload);
  if (
    typeof payload === 'object' &&
    payload !== null &&
    'nativeEvent' in payload &&
    typeof (payload as { nativeEvent?: { text?: unknown } }).nativeEvent?.text === 'string'
  ) {
    return {
      nativeEvent: {
        ...(payload as NormalizedTextChangePayload).nativeEvent,
        ...(normalizedSelection ? { selection: normalizedSelection } : {}),
        ...(isComposing !== undefined ? { isComposing } : {}),
        ...(normalizedCompositionRange ? { compositionRange: normalizedCompositionRange } : {}),
        ...(textRevision !== undefined ? { textRevision } : {}),
        ...(classification !== undefined ? { classification } : {}),
        textChanged: readTextChangedPayload(payload),
      },
    };
  }

  const textCandidate =
    typeof payload === 'object' && payload !== null
      ? (
          payload as {
            text?: unknown;
            value?: unknown;
          }
        ).text ??
        (
          payload as {
            text?: unknown;
            value?: unknown;
          }
        ).value
      : payload;

  return {
    nativeEvent: {
      text: typeof textCandidate === 'string' ? textCandidate : '',
      ...(normalizedSelection ? { selection: normalizedSelection } : {}),
      ...(isComposing !== undefined ? { isComposing } : {}),
      ...(normalizedCompositionRange ? { compositionRange: normalizedCompositionRange } : {}),
      ...(textRevision !== undefined ? { textRevision } : {}),
      ...(classification !== undefined ? { classification } : {}),
      textChanged: readTextChangedPayload(payload),
    },
  };
}

function readTextComposingPayload(payload: unknown): boolean | undefined {
  const record = payloadRecord(payload);
  const nativeEvent = payloadRecord(record.nativeEvent);
  const value = nativeEvent.isComposing ?? nativeEvent.composing ?? record.isComposing ?? record.composing;
  return typeof value === 'boolean' ? value : undefined;
}

function readTextChangedPayload(payload: unknown): boolean {
  const record = payloadRecord(payload);
  const nativeEvent = payloadRecord(record.nativeEvent);
  const value = nativeEvent.textChanged ?? record.textChanged;
  return typeof value === 'boolean' ? value : true;
}

function readTextRevisionPayload(payload: unknown): number | undefined {
  const record = payloadRecord(payload);
  const nativeEvent = payloadRecord(record.nativeEvent);
  const value = nativeEvent.textRevision ?? nativeEvent.revision ?? record.textRevision ?? record.revision;
  if (typeof value === 'number' && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === 'string') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return undefined;
}

function readTextClassificationPayload(payload: unknown): string | undefined {
  const record = payloadRecord(payload);
  const nativeEvent = payloadRecord(record.nativeEvent);
  const value =
    nativeEvent.classification ??
    nativeEvent.textClassification ??
    record.classification ??
    record.textClassification;
  return typeof value === 'string' ? value : undefined;
}

function normalizeTextSelectionPayload(payload: unknown): { start: number; end: number } | undefined {
  return normalizeTextRangePayload(payload, 'selection', 'selectionStart', 'selectionEnd');
}

function normalizeTextRangePayload(
  payload: unknown,
  rangeKey: string,
  startKey: string,
  endKey: string,
): { start: number; end: number } | undefined {
  const record = payloadRecord(payload);
  const nativeEvent = payloadRecord(record.nativeEvent);
  const range = payloadRecord(nativeEvent[rangeKey] ?? record[rangeKey]);
  const startCandidate = range.start ?? nativeEvent[startKey] ?? record[startKey];
  const endCandidate = range.end ?? nativeEvent[endKey] ?? record[endKey];

  if (
    typeof startCandidate !== 'number' ||
    typeof endCandidate !== 'number' ||
    !Number.isFinite(startCandidate) ||
    !Number.isFinite(endCandidate)
  ) {
    return undefined;
  }

  return {
    start: startCandidate,
    end: endCandidate,
  };
}

function payloadRecord(payload: unknown): Record<string, unknown> {
  return typeof payload === 'object' && payload !== null
    ? payload as Record<string, unknown>
    : {};
}

function readEventField(payload: unknown, field: string): unknown {
  const record = payloadRecord(payload);
  const nativeEvent = payloadRecord(record.nativeEvent);
  return nativeEvent[field] ?? record[field];
}

function normalizeImageEventName(value: unknown): NormalizedImageEventType | null {
  if (typeof value !== 'string') {
    return null;
  }

  switch (value.toLowerCase()) {
    case 'loadstart':
    case 'load-start':
    case 'load_start':
      return 'loadStart';
    case 'load':
      return 'load';
    case 'error':
      return 'error';
    case 'display':
      return 'display';
    default:
      return null;
  }
}

function finiteNumber(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : 0;
}

function optionalFiniteNumber(value: unknown): number | undefined {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string') {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return undefined;
}

function normalizeImageCacheType(value: unknown): 'none' | 'disk' | 'memory' {
  return value === 'disk' || value === 'memory' || value === 'none' ? value : 'none';
}

function normalizeImageErrorCode(value: unknown): ImageErrorCode {
  switch (value) {
    case 'invalid-source':
    case 'policy-rejected':
    case 'transport':
    case 'http-status':
    case 'content-type':
    case 'invalid-signature':
    case 'encoded-size-limit':
    case 'dimension-limit':
    case 'decode':
    case 'cancelled':
    case 'unsupported-format':
      return value;
    default:
      return 'transport';
  }
}

function normalizeImageEventPayload(payload: unknown): NormalizedImageEventPayload | null {
  const event = normalizeImageEventName(
    readEventField(payload, 'event') ?? readEventField(payload, 'type'),
  );
  if (!event) {
    return null;
  }

  const sourceIdCandidate = readEventField(payload, 'sourceId') ?? readEventField(payload, 'id');
  const uriCandidate =
    readEventField(payload, 'uri') ??
    readEventField(payload, 'src') ??
    readEventField(payload, 'currentSrc');
  const errorCandidate =
    readEventField(payload, 'error') ??
    readEventField(payload, 'message') ??
    'Image failed to load.';

  const encodedSource = readEventField(payload, 'encodedSource');
  const validation = readEventField(payload, 'validation');
  const decodedHit = readEventField(payload, 'decodedHit');
  const generation = optionalFiniteNumber(readEventField(payload, 'generation'));
  const provenance: ImageLoadEvent['provenance'] =
    (
      encodedSource === 'memory' ||
      encodedSource === 'disk' ||
      encodedSource === 'network' ||
      encodedSource === 'bundle' ||
      encodedSource === 'local' ||
      encodedSource === 'data' ||
      encodedSource === 'browser' ||
      encodedSource === 'unknown'
    ) &&
    (validation === 'fresh' || validation === '304' || validation === 'swr' || validation === 'none') &&
    typeof decodedHit === 'boolean'
      ? { encodedSource, validation, decodedHit }
      : undefined;
  const sourceId = typeof sourceIdCandidate === 'string'
    ? redactedImageSourceId(sourceIdCandidate)
    : redactedImageSourceId(typeof uriCandidate === 'string' ? uriCandidate : undefined);

  return {
    event,
    source: {
      id: sourceId,
      width: finiteNumber(
        readEventField(payload, 'width') ?? readEventField(payload, 'naturalWidth'),
      ),
      height: finiteNumber(
        readEventField(payload, 'height') ?? readEventField(payload, 'naturalHeight'),
      ),
    },
    cacheType: normalizeImageCacheType(readEventField(payload, 'cacheType')),
    ...(generation !== undefined ? { generation } : {}),
    ...(provenance ? { provenance } : {}),
    error: {
      code: normalizeImageErrorCode(readEventField(payload, 'code')),
      message: typeof errorCandidate === 'string' ? errorCandidate : 'Image failed to load.',
      sourceId,
      retryable: readEventField(payload, 'retryable') !== false,
      ...(generation !== undefined ? { generation } : {}),
    },
  };
}

/** LLP 0394: fan the flat native lottie lifecycle payload out to the tag's
 * event handlers (event discriminator: load | error | complete | looped). */
function dispatchLottieEventPayload(props: Props, payload: unknown): void {
  if (typeof payload !== 'object' || payload === null) {
    return;
  }
  const record = payload as Record<string, unknown>;
  switch (record.event) {
    case 'load':
      if (typeof props.onLoad === 'function') {
        props.onLoad({
          width: typeof record.width === 'number' ? record.width : 0,
          height: typeof record.height === 'number' ? record.height : 0,
          duration: typeof record.duration === 'number' ? record.duration : 0,
          totalFrames: typeof record.totalFrames === 'number' ? record.totalFrames : 0,
        });
      }
      return;
    case 'error':
      if (typeof props.onError === 'function') {
        props.onError({
          message: typeof record.message === 'string' ? record.message : 'lottie load failed',
        });
      }
      return;
    case 'complete':
      if (typeof props.onComplete === 'function') {
        props.onComplete({});
      }
      return;
    case 'looped':
      if (typeof props.onLooped === 'function') {
        props.onLooped({});
      }
      return;
    default:
      return;
  }
}

/** Match the web mirror's riveevent payload: properties are filtered to
 * primitives so the app-level event has one shape across hosts. */
function primitiveRiveEventProperties(
  value: unknown,
): Record<string, boolean | number | string> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return {};
  const result: Record<string, boolean | number | string> = {};
  for (const [key, candidate] of Object.entries(value as Record<string, unknown>)) {
    if (
      typeof candidate === 'boolean' ||
      typeof candidate === 'string' ||
      (typeof candidate === 'number' && Number.isFinite(candidate))
    ) {
      result[key] = candidate;
    }
  }
  return result;
}

/** LLP 0395: fan the native Rive event envelope out to tag-specific
 * handlers. Rive lifecycle shares EventType.Change with image and Lottie. */
function dispatchRiveEventPayload(props: Props, payload: unknown): void {
  if (typeof payload !== 'object' || payload === null) return;
  const record = payload as Record<string, unknown>;
  switch (record.event) {
    case 'load':
      if (typeof props.onLoad === 'function') {
        props.onLoad({
          artboard: typeof record.artboard === 'string' ? record.artboard : '',
          animations: Array.isArray(record.animations)
            ? record.animations.filter((value): value is string => typeof value === 'string')
            : [],
          stateMachines: Array.isArray(record.stateMachines)
            ? record.stateMachines.filter((value): value is string => typeof value === 'string')
            : [],
          width: typeof record.width === 'number' && Number.isFinite(record.width)
            ? record.width
            : 0,
          height: typeof record.height === 'number' && Number.isFinite(record.height)
            ? record.height
            : 0,
        });
      }
      return;
    case 'error':
      if (typeof props.onError === 'function') {
        props.onError({
          message: typeof record.message === 'string' ? record.message : 'Rive load failed',
        });
      }
      return;
    case 'statechange':
      if (typeof props.onStateChange === 'function') {
        props.onStateChange({
          states: Array.isArray(record.states)
            ? record.states.filter((value): value is string => typeof value === 'string')
            : [],
        });
      }
      return;
    case 'datachange':
      if (typeof props.onDataChange === 'function' && typeof record.name === 'string') {
        const value = record.value;
        if (
          typeof value === 'boolean' ||
          typeof value === 'string' ||
          (typeof value === 'number' && Number.isFinite(value))
        ) {
          props.onDataChange({ name: record.name, value });
        }
      }
      return;
    case 'riveevent':
      if (typeof props.onRiveEvent === 'function') {
        props.onRiveEvent({
          name: typeof record.name === 'string' ? record.name : '',
          type:
            typeof record.type === 'string' || typeof record.type === 'number'
              ? record.type
              : '',
          properties: primitiveRiveEventProperties(record.properties),
          delay: typeof record.delay === 'number' && Number.isFinite(record.delay)
            ? record.delay
            : 0,
        });
      }
      return;
    default:
      return;
  }
}

function dispatchImageEventPayload(props: Props, payload: unknown): void {
  const event = normalizeImageEventPayload(payload);
  if (!event) {
    return;
  }

  switch (event.event) {
    case 'loadStart':
      if (typeof props.onLoadStart === 'function') {
        props.onLoadStart();
      }
      return;
    case 'load':
      if (typeof props.onLoad === 'function') {
        props.onLoad({
          source: event.source,
          cacheType: event.cacheType,
          ...(event.generation !== undefined ? { generation: event.generation } : {}),
          ...(event.provenance ? { provenance: event.provenance } : {}),
        });
      }
      return;
    case 'error':
      if (typeof props.onError === 'function') {
        props.onError(event.error);
      }
      return;
    case 'display':
      if (typeof props.onDisplay === 'function') {
        props.onDisplay();
      }
      return;
  }
}

function normalizeEventTimestamp(value: unknown): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    return Date.now();
  }
  // DOMHighResTimeStamp values are relative to the page's time origin, while
  // native hosts already send Unix-epoch milliseconds. Canonical handlers see
  // one clock regardless of which presentation path delivered the event.
  if (value < 1_000_000_000_000) {
    const timeOrigin = globalThis.performance?.timeOrigin;
    if (typeof timeOrigin === 'number' && Number.isFinite(timeOrigin)) {
      return timeOrigin + value;
    }
    return Date.now();
  }
  return value;
}

function normalizeFocusChangePayload(payload: unknown): {
  nativeEvent: {
    timestamp: number;
    target?: number | null;
    relatedTarget?: number | null;
  };
} {
  const source = payload as {
    nativeEvent?: { timestamp?: unknown; target?: unknown; relatedTarget?: unknown };
    timestamp?: unknown;
    target?: unknown;
    relatedTarget?: unknown;
  } | null;
  const timestamp = source?.nativeEvent?.timestamp ?? source?.timestamp;
  const target = source?.nativeEvent && 'target' in source.nativeEvent
    ? source.nativeEvent.target
    : source?.target;
  const relatedTarget = source?.nativeEvent && 'relatedTarget' in source.nativeEvent
    ? source.nativeEvent.relatedTarget
    : source?.relatedTarget;

  return {
    nativeEvent: {
      timestamp: normalizeEventTimestamp(timestamp),
      target: typeof target === 'number' ? target : null,
      relatedTarget: typeof relatedTarget === 'number' ? relatedTarget : null,
    },
  };
}

function normalizeKeyPayload(payload: unknown): {
  nativeEvent: {
    key: string;
    code: string | null;
    altKey: boolean;
    ctrlKey: boolean;
    metaKey: boolean;
    shiftKey: boolean;
    repeat: boolean;
    timestamp: number;
  };
  preventDefault?: () => void;
  defaultPrevented?: boolean;
} {
  const nativeEvent =
    (payload as {
      nativeEvent?: {
        key?: unknown;
        code?: unknown;
        altKey?: unknown;
        ctrlKey?: unknown;
        metaKey?: unknown;
        shiftKey?: unknown;
        repeat?: unknown;
        timestamp?: unknown;
      };
    } | null)?.nativeEvent;

  return {
    nativeEvent: {
      key: typeof nativeEvent?.key === 'string' ? nativeEvent.key : '',
      code:
        typeof nativeEvent?.code === 'string' && nativeEvent.code.length > 0
          ? nativeEvent.code
          : null,
      altKey: nativeEvent?.altKey === true,
      ctrlKey: nativeEvent?.ctrlKey === true,
      metaKey: nativeEvent?.metaKey === true,
      shiftKey: nativeEvent?.shiftKey === true,
      repeat: nativeEvent?.repeat === true,
      timestamp: normalizeEventTimestamp(nativeEvent?.timestamp),
    },
    preventDefault:
      typeof (payload as { preventDefault?: unknown } | null)?.preventDefault === 'function'
        ? (payload as { preventDefault: () => void }).preventDefault
        : undefined,
    defaultPrevented:
      (payload as { defaultPrevented?: unknown } | null)?.defaultPrevented === true,
  };
}

function normalizeAccessibilityActionPayload(payload: unknown): {
  nativeEvent: {
    actionName: string;
  };
} {
  const actionNameCandidate =
    (payload as { nativeEvent?: { actionName?: unknown }; actionName?: unknown } | null)
      ?.nativeEvent?.actionName ??
    (payload as { nativeEvent?: { actionName?: unknown }; actionName?: unknown } | null)
      ?.actionName;

  return {
    nativeEvent: {
      actionName:
        typeof actionNameCandidate === 'string' && actionNameCandidate.length > 0
          ? actionNameCandidate
          : '',
    },
  };
}

function normalizePagerCommitPayload(payload: unknown): {
  nativeEvent: {
    direction: 'prev' | 'next';
    turnToken: number;
    bindingGeneration: number;
    timestamp: number;
  };
} {
  const nativeEvent = (payload as {
    nativeEvent?: {
      direction?: unknown;
      turnToken?: unknown;
      bindingGeneration?: unknown;
      timestamp?: unknown;
    };
  } | null)?.nativeEvent;
  return {
    nativeEvent: {
      direction: nativeEvent?.direction === 'prev' ? 'prev' : 'next',
      turnToken: typeof nativeEvent?.turnToken === 'number' ? nativeEvent.turnToken : 0,
      bindingGeneration: typeof nativeEvent?.bindingGeneration === 'number'
        ? nativeEvent.bindingGeneration
        : 0,
      timestamp: typeof nativeEvent?.timestamp === 'number'
        ? nativeEvent.timestamp
        : Date.now(),
    },
  };
}

function readFiniteNumber(value: unknown, fallback = 0): number {
  if (typeof value === 'number' && isFinite(value)) {
    return value;
  }
  if (typeof value === 'string') {
    const parsed = Number(value);
    return isFinite(parsed) ? parsed : fallback;
  }
  return fallback;
}

function normalizeNativeListGeometryFeedback(
  value: unknown,
): NativeListGeometryFeedback | undefined {
  const candidate = value as {
    producerGeneration?: unknown;
    modelRevision?: unknown;
    geometryRevision?: unknown;
    constraintsEpoch?: unknown;
    measurements?: unknown;
  } | null;
  const isPositiveUint32 = (input: unknown): input is number =>
    typeof input === 'number' &&
    Number.isInteger(input) &&
    input > 0 &&
    input <= 0xffff_ffff;
  if (
    !isPositiveUint32(candidate?.producerGeneration) ||
    !isPositiveUint32(candidate?.modelRevision) ||
    !isPositiveUint32(candidate?.geometryRevision) ||
    typeof candidate?.constraintsEpoch !== 'number' ||
    !Number.isSafeInteger(candidate.constraintsEpoch) ||
    candidate.constraintsEpoch <= 0 ||
    !Array.isArray(candidate.measurements) ||
    candidate.measurements.length > 512
  ) {
    return undefined;
  }
  const seen = new Set<number>();
  const measurements: Array<{ readonly index: number; readonly size: number }> = [];
  for (const raw of candidate.measurements) {
    const measurement = raw as { index?: unknown; size?: unknown } | null;
    if (
      typeof measurement?.index !== 'number' ||
      !Number.isInteger(measurement.index) ||
      measurement.index < 0 ||
      measurement.index > 0xffff_ffff ||
      !seen.add(measurement.index) ||
      typeof measurement.size !== 'number' ||
      !Number.isFinite(measurement.size) ||
      measurement.size < 0
    ) {
      return undefined;
    }
    measurements.push({ index: measurement.index, size: measurement.size });
  }
  return {
    producerGeneration: candidate.producerGeneration,
    modelRevision: candidate.modelRevision,
    geometryRevision: candidate.geometryRevision,
    constraintsEpoch: candidate.constraintsEpoch,
    measurements,
  };
}

function normalizeScrollPayload(payload: unknown): {
  nativeEvent: {
    contentOffset: {
      x: number;
      y: number;
    };
    contentSize: {
      width: number;
      height: number;
    };
    layoutMeasurement: {
      width: number;
      height: number;
    };
    timestamp: number;
    source: 'user' | 'command' | 'restore';
    geometrySeq?: number;
    velocity?: number;
    interactionEpoch?: number;
    commandSeq?: number;
    nativeListGeometry?: NativeListGeometryFeedback;
  };
} {
  const nativeEvent =
    (payload as {
      nativeEvent?: {
        contentOffset?: {
          x?: unknown;
          y?: unknown;
        };
        timestamp?: unknown;
        contentSize?: { width?: unknown; height?: unknown };
        layoutMeasurement?: { width?: unknown; height?: unknown };
        source?: unknown;
        geometrySeq?: unknown;
        velocity?: unknown;
        interactionEpoch?: unknown;
        commandSeq?: unknown;
        nativeListGeometry?: unknown;
      };
    } | null)?.nativeEvent;
  const contentOffset =
    nativeEvent?.contentOffset ??
    (payload as {
      contentOffset?: {
        x?: unknown;
        y?: unknown;
      };
    } | null)?.contentOffset;
  const interactionEpoch = nativeEvent?.interactionEpoch
    ?? (payload as { interactionEpoch?: unknown } | null)?.interactionEpoch;
  const commandSeq = nativeEvent?.commandSeq
    ?? (payload as { commandSeq?: unknown } | null)?.commandSeq;
  const nativeListGeometry = normalizeNativeListGeometryFeedback(
    nativeEvent?.nativeListGeometry,
  );

  return {
    nativeEvent: {
      contentOffset: {
        x: readFiniteNumber(contentOffset?.x ?? (payload as { x?: unknown } | null)?.x),
        y: readFiniteNumber(contentOffset?.y ?? (payload as { y?: unknown } | null)?.y),
      },
      contentSize: {
        width: readFiniteNumber(
          nativeEvent?.contentSize?.width ??
            (payload as { contentSize?: { width?: unknown } } | null)?.contentSize?.width,
        ),
        height: readFiniteNumber(
          nativeEvent?.contentSize?.height ??
            (payload as { contentSize?: { height?: unknown } } | null)?.contentSize?.height,
        ),
      },
      layoutMeasurement: {
        width: readFiniteNumber(
          nativeEvent?.layoutMeasurement?.width ??
            (payload as { layoutMeasurement?: { width?: unknown } } | null)?.layoutMeasurement?.width,
        ),
        height: readFiniteNumber(
          nativeEvent?.layoutMeasurement?.height ??
            (payload as { layoutMeasurement?: { height?: unknown } } | null)?.layoutMeasurement?.height,
        ),
      },
      timestamp: readFiniteNumber(nativeEvent?.timestamp, Date.now()),
      source: nativeEvent?.source === 'command' || nativeEvent?.source === 'restore'
        ? nativeEvent.source
        : 'user',
      geometrySeq: typeof nativeEvent?.geometrySeq === 'number'
        ? nativeEvent.geometrySeq
        : undefined,
      velocity: typeof nativeEvent?.velocity === 'number' ? nativeEvent.velocity : undefined,
      interactionEpoch: interactionEpoch == null
        ? undefined
        : readFiniteNumber(interactionEpoch),
      ...(commandSeq == null
        ? {}
        : { commandSeq: readFiniteNumber(commandSeq) }),
      ...(nativeListGeometry == null ? {} : { nativeListGeometry }),
    },
  };
}

function normalizeRefreshPayload(payload: unknown): {
  nativeEvent: {
    contentOffset: { x: number; y: number };
    pullDistance: number;
    timestamp: number;
  };
} {
  const scroll = normalizeScrollPayload(payload);
  const nativeEvent = (payload as {
    nativeEvent?: { pullDistance?: unknown; timestamp?: unknown };
    pullDistance?: unknown;
  } | null)?.nativeEvent;
  return {
    nativeEvent: {
      contentOffset: scroll.nativeEvent.contentOffset,
      pullDistance: readFiniteNumber(
        nativeEvent?.pullDistance ??
          (payload as { pullDistance?: unknown } | null)?.pullDistance,
      ),
      timestamp: readFiniteNumber(nativeEvent?.timestamp, scroll.nativeEvent.timestamp),
    },
  };
}

function resolveScrollEventThrottle(props: Props): number {
  const value = props.scrollEventThrottle;
  const throttle = typeof value === 'number' && isFinite(value) ? value : 0;
  return throttle > 0 ? throttle : 0;
}

/**
 * Per-instance scroll throttle state. Kept outside the onScroll wrapper so an
 * unrelated event-prop change (which rebuilds the wrapper) does not reset the
 * throttle window mid-scroll.
 */
interface ScrollDispatchState {
  lastDispatchAt: number | null;
}

const scrollThrottleState = new WeakMap<ElementNode, ScrollDispatchState>();

function getScrollThrottleState(instance: ElementNode): ScrollDispatchState {
  let state = scrollThrottleState.get(instance);
  if (!state) {
    state = {
      lastDispatchAt: null,
    };
    scrollThrottleState.set(instance, state);
  }
  return state;
}

function getElementTestId(instance: ElementNode): string | undefined {
  const candidate =
    instance.originalProps.testId ??
    instance.originalProps.testID ??
    instance.originalProps['data-testid'] ??
    instance.originalProps['data-test-id'] ??
    instance.originalProps.id;
  return typeof candidate === 'string' && candidate.length > 0
    ? candidate
    : undefined;
}

function getElementLabel(instance: ElementNode): string | undefined {
  if (typeof instance.props.accessibilityLabel === 'string' && instance.props.accessibilityLabel.length > 0) {
    return instance.props.accessibilityLabel;
  }

  if (instance.tagType === 'input') {
    return instance.props.value ?? instance.props.placeholder;
  }

  return instance.props.textContent;
}

function syncInputFocusTracking(instance: ElementNode, focused: boolean): void {
  const rootId = getRootIdForNode(instance);

  if (!focused) {
    clearFocusedInput(rootId, instance.id);
    clearFocusedTarget();
    return;
  }

  noteFocusedInput(rootId, instance.id);
  setFocusedTarget({
    viewId: instance.id,
    type: instance.originalTag,
    label: getElementLabel(instance),
    testId: getElementTestId(instance),
  });
}

function upsertEventHandler(
  instance: ElementNode,
  eventType: EventType,
  handler: Function,
): void {
  const existing = instance.events.get(eventType);
  if (existing) {
    updateHandler(existing.handlerId, handler);
    existing.handler = handler;
    productionEventMetadata.set(existing.handlerId, {
      category: productionCategoryForHostEvent(eventType),
      secureInput: isSecureChangeEvent(instance, eventType),
    });
    return;
  }

  const handlerId = registerHandler(handler);
  productionEventMetadata.set(handlerId, {
    category: productionCategoryForHostEvent(eventType),
    secureInput: isSecureChangeEvent(instance, eventType),
  });
  instance.events.set(eventType, { handlerId, handler });
}

function productionCategoryForHostEvent(eventType: EventType): ProductionActionCategory {
  switch (eventType) {
    case EventType.Press:
    case EventType.PressIn:
    case EventType.PressOut:
    case EventType.LongPress:
    case EventType.KeyDown:
    case EventType.KeyUp:
    case EventType.AccessibilityAction:
    case EventType.MotionGestureStart:
    case EventType.MotionGestureEnd:
      return 'press';
    case EventType.Change:
      return 'change';
    case EventType.Focus:
    case EventType.FocusIn:
      return 'focus';
    case EventType.Blur:
    case EventType.FocusOut:
      return 'blur';
    case EventType.Scroll:
    case EventType.ScrollEnd:
    case EventType.Refresh:
      return 'scroll';
    case EventType.PagerCommit:
      return 'navigation';
    default:
      return 'unknown';
  }
}

function isSecureChangeEvent(instance: ElementNode, eventType: EventType): boolean {
  if (eventType !== EventType.Change) return false;
  return instance.originalProps.secureTextEntry === true
    || instance.originalProps.type === 'password'
    || instance.props.secureTextEntry === true;
}

function removeEventHandler(
  instance: ElementNode,
  eventType: EventType,
): void {
  const existing = instance.events.get(eventType);
  if (!existing) {
    return;
  }
  unregisterHandler(existing.handlerId, instance.id, eventType, getRootIdForNode(instance));
  instance.events.delete(eventType);
}

function bindFunctionPropEvent(
  instance: ElementNode,
  props: Props,
  activeEvents: Set<EventType>,
  binding: (typeof PRESS_EVENT_BINDINGS)[number],
): void {
  const handler = props[binding.propName];
  if (typeof handler === 'function') {
    activeEvents.add(binding.eventType);
    upsertEventHandler(instance, binding.eventType, (payload: unknown) => {
      if (binding.eventType === EventType.Press) {
        beginContractPerfInput(
          getRootIdForNode(instance),
          getElementTestId(instance),
          'update',
        );
      }
      handler(payload);
    });
  } else {
    removeEventHandler(instance, binding.eventType);
  }
}

function eventPropsChanged(previousProps: Props, nextProps: Props): boolean {
  for (const propName of EVENT_PROP_NAMES) {
    if (previousProps[propName] !== nextProps[propName]) {
      return true;
    }
  }
  return false;
}

const MOTION_GESTURE_IDENTITY_HISTORY_CAPACITY = 256;
const motionGestureIdentityHistory = new WeakMap<ElementNode, Map<string, string>>();

function rememberMotionGestureIdentities(instance: ElementNode, descriptor: unknown): void {
  if (!descriptor || typeof descriptor !== 'object' || Array.isArray(descriptor)) return;
  const identities = motionGestureIdentityHistory.get(instance) ?? new Map<string, string>();
  const rootId = getRootIdForNode(instance);
  const seen = new Set<object>();
  const collect = (candidate: unknown): void => {
    if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate) || seen.has(candidate)) {
      return;
    }
    seen.add(candidate);
    const record = candidate as Record<string, unknown>;
    if (typeof record.id === 'string' && record.id.length > 0) {
      const nativeId = motionGestureDescriptorNativeId(rootId, instance.id, record.id).toString(10);
      // Refresh insertion order for active identities without ever relabeling
      // an old native id as the descriptor currently installed on the node.
      identities.delete(nativeId);
      identities.set(nativeId, record.id);
    }
    if (Array.isArray(record.gestures)) record.gestures.forEach(collect);
  };
  collect(descriptor);
  while (identities.size > MOTION_GESTURE_IDENTITY_HISTORY_CAPACITY) {
    const oldest = identities.keys().next().value;
    if (oldest === undefined) break;
    identities.delete(oldest);
  }
  motionGestureIdentityHistory.set(instance, identities);
}

function normalizeMotionGesturePayload(
  instance: ElementNode,
  payload: unknown,
): unknown {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return payload;
  const event = { ...(payload as Record<string, unknown>) };
  rememberMotionGestureIdentities(instance, instance.originalProps.__exactMotionGesture);
  const identities = motionGestureIdentityHistory.get(instance);
  if (!identities) return event;

  const nativeRootId = event.gestureId;
  if (typeof nativeRootId === 'string') {
    event.gestureId = identities.get(nativeRootId) ?? nativeRootId;
  }
  if (event.sample && typeof event.sample === 'object' && !Array.isArray(event.sample)) {
    const sample = { ...(event.sample as Record<string, unknown>) };
    if (typeof sample.gestureId === 'string') {
      sample.gestureId = identities.get(sample.gestureId) ?? sample.gestureId;
    }
    event.sample = sample;
  }
  const resolvedCommand = event.command && typeof event.command === 'object' &&
      !Array.isArray(event.command)
    ? resolveNativeMotionCommandIdentity(
      event.command as Parameters<typeof resolveNativeMotionCommandIdentity>[0],
    )
    : undefined;
  if (event.command !== null && event.command !== undefined) {
    // Unknown/pruned digests fail closed. In particular, never relabel a
    // delayed terminal with the command on the node's current descriptor.
    event.command = resolvedCommand ?? null;
  }
  if (
    event.dispatchReceipt &&
    typeof event.dispatchReceipt === 'object' && !Array.isArray(event.dispatchReceipt)
  ) {
    const receipt = event.dispatchReceipt as Record<string, unknown>;
    const receiptCommand = receipt.command && typeof receipt.command === 'object' &&
        !Array.isArray(receipt.command)
      ? resolveNativeMotionCommandIdentity(
        receipt.command as Parameters<typeof resolveNativeMotionCommandIdentity>[0],
      )
      : undefined;
    event.dispatchReceipt = receiptCommand ? {
      ...receipt,
      command: receiptCommand,
      gestureId: event.gestureId,
    } : null;
  }
  return event;
}

interface MotionGestureObservationInvocations {
  nextGeneration: number;
  byStream: Map<string, number>;
}

const motionGestureObservationInvocations = new WeakMap<
  ElementNode,
  MotionGestureObservationInvocations
>();

function motionGestureObservationGeneration(
  instance: ElementNode,
  event: Record<string, unknown>,
  terminal: boolean,
): number {
  let invocations = motionGestureObservationInvocations.get(instance);
  if (!invocations) {
    invocations = { nextGeneration: 1, byStream: new Map() };
    motionGestureObservationInvocations.set(instance, invocations);
  }
  const stream = event.compositionInstanceId;
  const key = `${typeof stream}:${String(stream ?? 'unknown')}`;
  let generation = invocations.byStream.get(key);
  if (generation === undefined) {
    generation = invocations.nextGeneration++;
    invocations.byStream.set(key, generation);
  }
  if (terminal) invocations.byStream.delete(key);
  return generation;
}

function motionGestureTypeForObservation(
  descriptor: unknown,
  gestureId: string,
): string {
  if (!descriptor || typeof descriptor !== 'object' || Array.isArray(descriptor)) return 'gesture';
  const record = descriptor as Record<string, unknown>;
  if (record.id === gestureId && typeof record.kind === 'string') return record.kind;
  if (Array.isArray(record.gestures)) {
    for (const child of record.gestures) {
      const type = motionGestureTypeForObservation(child, gestureId);
      if (type !== 'gesture') return type;
    }
  }
  return 'gesture';
}

function finiteMotionObservation(value: unknown): number | undefined {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

function motionObservationStreamId(value: unknown): number | string | undefined {
  if (typeof value === 'number' && Number.isSafeInteger(value) && value > 0) return value;
  if (typeof value !== 'string' || !/^[1-9][0-9]*$/.test(value)) return undefined;
  try {
    return BigInt(value) <= 0xffff_ffff_ffff_ffffn ? value : undefined;
  } catch {
    return undefined;
  }
}

function motionObservationInvocationId(event: Record<string, unknown>): string | undefined {
  const normalized = motionObservationStreamId(event.compositionInstanceId);
  return normalized === undefined ? undefined : String(normalized);
}

function publishNativeMotionGestureObservation(
  instance: ElementNode,
  payload: unknown,
  terminal: boolean,
): void {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return;
  const event = payload as Record<string, unknown>;
  const gestureId = typeof event.gestureId === 'string' && event.gestureId.length > 0
    ? event.gestureId
    : null;
  if (!gestureId) return;
  const sample = event.sample && typeof event.sample === 'object' && !Array.isArray(event.sample)
    ? event.sample as Record<string, unknown>
    : event;
  const phase = terminal && (
    event.phase === 'ended' || event.phase === 'cancelled' || event.phase === 'failed'
  ) ? event.phase : 'began';
  const translationX = finiteMotionObservation(sample.translationX);
  const translationY = finiteMotionObservation(sample.translationY);
  const velocityX = finiteMotionObservation(sample.velocityX);
  const velocityY = finiteMotionObservation(sample.velocityY);
  const streamId = motionObservationStreamId(event.streamId);
  const invocationId = motionObservationInvocationId(event);
  // Native activation and terminal payloads are one compound lifecycle. An
  // old producer without that identity must fail closed instead of publishing
  // an unfinishable `began` entry keyed by a physical member stream.
  if (invocationId === undefined) return;
  try {
    publishMotionGestureState({
      rootId: getRootIdForNode(instance),
      viewId: instance.id,
      gestureId,
      invocationId,
      type: typeof sample.gestureKind === 'string'
        ? sample.gestureKind
        : motionGestureTypeForObservation(instance.originalProps.__exactMotionGesture, gestureId),
      state: phase,
      generation: motionGestureObservationGeneration(instance, event, terminal),
      ...(streamId === undefined ? {} : { streamId }),
      ...(translationX !== undefined && translationY !== undefined
        ? { translation: { x: translationX, y: translationY } }
        : {}),
      ...(velocityX !== undefined && velocityY !== undefined
        ? { velocity: { x: velocityX, y: velocityY } }
        : {}),
      ...(finiteMotionObservation(sample.scale) === undefined
        ? {}
        : { scale: finiteMotionObservation(sample.scale)! }),
      ...(finiteMotionObservation(sample.rotation) === undefined
        ? {}
        : { rotation: finiteMotionObservation(sample.rotation)! }),
      ...(finiteMotionObservation(sample.pointerCount) === undefined
        ? {}
        : { pointerCount: Math.max(0, Math.trunc(finiteMotionObservation(sample.pointerCount)!)) }),
      ...(typeof event.reason === 'string' ? { reason: event.reason } : {}),
      ...(terminal
        ? {
            terminalOutcome: phase === 'failed'
              ? 'failed' as const
              : event.committed === true ? 'commit' as const : 'cancel' as const,
          }
        : {}),
      updatedAt: finiteMotionObservation(sample.timestampMs) ?? Date.now(),
    });
  } catch {
    // Native outcome delivery is correctness-bearing; diagnostics are not.
  }
}

/**
 * Shallow strict-equality check over original (framework-level) props.
 *
 * Used as the updateInstanceProps fast path: when every prop value (including
 * the `style` and `children` references) is identical, re-running
 * resolveElementState cannot produce a different result, so the whole
 * resolution + diff + encode pipeline can be skipped.
 */
function originalPropsShallowEqual(previousProps: Props, nextProps: Props): boolean {
  const previousKeys = Object.keys(previousProps);
  if (previousKeys.length !== Object.keys(nextProps).length) {
    return false;
  }
  for (const key of previousKeys) {
    if (previousProps[key] !== nextProps[key]) {
      return false;
    }
  }
  return true;
}

function emitNativeListModelChunks(
  encoder: ProtocolEncoder,
  instance: ElementNode,
  props: Props,
): void {
  if (instance.tagType !== 'list') return;
  const chunks = props.__exactNativeListModelChunks;
  if (!Array.isArray(chunks)) return;
  for (const chunk of chunks) {
    if (chunk instanceof Uint8Array) {
      setListModelChunk(encoder, instance.id, chunk);
    }
  }
}

// ENG-23550: observed-revision acks for native-owned text editing (LLP 0297
// A3 "async revert"). Under the runtime-thread flip the change handler is an
// async observer; when the app REJECTS a keystroke its controlled value does
// not change, so no text op flows back and the host cannot distinguish "app
// JS is still catching up" from "app JS observed the keystroke and said no".
// After the app framework has had its flush turn, ack the highest observed
// `textRevision` per field — plus whether the field is controlled at ack
// time — through the async host-call transport; the host reconciles a
// still-divergent controlled value back into the native field. Hosts without
// the op (plain web, older hosts) degrade to a silent no-op.
const pendingTextInputObservedRevisionAcks = new Map<
  number,
  { instance: ElementNode; revision: number }
>();
let textInputObservedRevisionAckFlushScheduled = false;

function scheduleTextInputObservedRevisionAck(instance: ElementNode, revision: number): void {
  const prior = pendingTextInputObservedRevisionAcks.get(instance.id);
  if (!prior || prior.revision < revision) {
    pendingTextInputObservedRevisionAcks.set(instance.id, { instance, revision });
  }
  if (textInputObservedRevisionAckFlushScheduled) {
    return;
  }
  textInputObservedRevisionAckFlushScheduled = true;
  // A macrotask, not a microtask: the app framework schedules its state
  // flush while the change handler runs (so its timer/microtask sits ahead
  // of this one in the FIFO). By the time this fires, the app's decision for
  // the acked revision has committed and the ack is ordered after the
  // resulting ops. The host side self-heals if an interleaving still slips
  // through (the watermark only ever ratchets forward).
  setTimeout(flushTextInputObservedRevisionAcks, 0);
}

function flushTextInputObservedRevisionAcks(): void {
  textInputObservedRevisionAckFlushScheduled = false;
  const acks = Array.from(pendingTextInputObservedRevisionAcks.values());
  pendingTextInputObservedRevisionAcks.clear();
  for (const { instance, revision } of acks) {
    // Live reads at ack time — the app may have changed the props in
    // response to this very change (ENG-23202 staleness rule).
    const rawValue = instance.originalProps.value;
    const controlled = rawValue != null;
    // The host compares the ack's own authoritative value against its
    // session text (its JS-text mirror is echo-synced with native text and
    // cannot serve as the comparison source). Secure fields never send
    // content — digest-only by design (LLP 0297 A3 row 4), so a controlled
    // secure field does not support the value-unchanged revert.
    const secure = instance.originalProps.secureTextEntry === true;
    hostCallOptionalAsync(
      'textInput.ackObservedRevision',
      JSON.stringify({
        nodeId: instance.id,
        revision,
        controlled,
        ...(controlled && !secure
          ? { value: typeof rawValue === 'string' ? rawValue : String(rawValue) }
          : {}),
      }),
      { silent: true },
    );
  }
}

export function _resetTextInputObservedRevisionAcksForTests(): void {
  pendingTextInputObservedRevisionAcks.clear();
  textInputObservedRevisionAckFlushScheduled = false;
}

// ENG-23560 (LLP 0297 §4.3): the TextInput `filter` prop — same-keystroke
// Layer-2 worklet filters. The prop takes a `'worklet'`-directive function
// (its source extracted at build time onto `__workletSource` by
// createWorkletSourcePlugin — HBC retains no source, so runtime toString()
// cannot work) or a raw source string. Install rides the async host-call
// transport per node; the resident UI worklet runtime serves accept /
// reject / replace verdicts inside the native preflight, so a rejected
// character never renders. Hosts without the ops (plain web) and filters
// without extractable source degrade to the async-revert contract.
const installedTextInputFilterSources = new Map<number, string>();
const warnedUnextractableFilters = new WeakSet<object>();

function resolveTextInputFilterWorkletSource(filter: unknown): string | null {
  if (typeof filter === 'string' && filter.length > 0) {
    return filter;
  }
  if (typeof filter === 'function') {
    const source = (filter as { __workletSource?: unknown }).__workletSource;
    if (typeof source === 'string' && source.length > 0) {
      return source;
    }
  }
  return null;
}

// The user filter is called as `filter(text, tx)` and may return a boolean
// (accept/reject), a string (replacement), or a raw verdict object — the
// wrapper normalizes all three to the worklet-runtime verdict shape.
function composeTextInputFilterInstallSource(userSource: string): string {
  return (
    '(function(){ var __exactFilter = (' +
    userSource +
    ');\n' +
    'return function(tx){\n' +
    '  var verdict = __exactFilter(tx.text, tx);\n' +
    "  if (verdict === true || verdict === undefined || verdict === null) { return { action: 'accept' }; }\n" +
    "  if (verdict === false) { return { action: 'reject' }; }\n" +
    "  if (typeof verdict === 'string') {\n" +
    "    return verdict === tx.text ? { action: 'accept' } : { action: 'replace', text: verdict };\n" +
    '  }\n' +
    "  if (typeof verdict === 'object' && typeof verdict.action === 'string') { return verdict; }\n" +
    "  return { action: 'accept' };\n" +
    '}; })()'
  );
}

function syncTextInputFilterProp(instance: ElementNode, props: Props): void {
  // Live read from originalProps first (ENG-23202 staleness rule): the
  // Contract runtime registers events with a handlers-only props object,
  // and the dynamic-prop update that actually delivers `filter` skips
  // processEventProps when no EVENT prop changed — originalProps is the
  // one source that always carries the committed value.
  const filter =
    (instance.originalProps as { filter?: unknown } | undefined)?.filter
      ?? (props as { filter?: unknown }).filter;
  const prior = installedTextInputFilterSources.get(instance.id);

  // `false` counts as absent so Contract props can default the attr off.
  if (filter == null || filter === false) {
    if (prior !== undefined) {
      removeTextInputFilter(instance.id);
    }
    return;
  }

  const source = resolveTextInputFilterWorkletSource(filter);
  if (source == null) {
    if (
      typeof filter === 'object' || typeof filter === 'function'
        ? !warnedUnextractableFilters.has(filter as object)
        : true
    ) {
      if (typeof filter === 'function' || typeof filter === 'object') {
        warnedUnextractableFilters.add(filter as object);
      }
      if (process.env.NODE_ENV !== 'production') {
        // eslint-disable-next-line no-console
        console.warn(
          '[ExactRenderer] TextInput filter has no compiled worklet source — '
            + "declare it as a top-level function whose body starts with the 'worklet' "
            + 'directive (or pass a source string). Falling back to the async '
            + 'controlled contract for this field.',
        );
      }
    }
    if (prior !== undefined) {
      removeTextInputFilter(instance.id);
    }
    return;
  }

  if (prior === source) {
    return;
  }
  installedTextInputFilterSources.set(instance.id, source);
  queueTextInputFilterOp(instance.id, composeTextInputFilterInstallSource(source));
}

function removeTextInputFilter(nodeId: number): void {
  installedTextInputFilterSources.delete(nodeId);
  queueTextInputFilterOp(nodeId, null);
}

// Mount runs during bundle evaluation, BEFORE the host installs
// the async host ingress (installGlobals lands after eval), and the sync bridge
// is refused off-main under the runtime-thread flip — so filter ops are a
// desired-state queue pumped until the async bridge appears (bounded).
// `null` source = remove.
const pendingTextInputFilterOps = new Map<number, string | null>();
let textInputFilterPumpScheduled = false;
let textInputFilterPumpAttempts = 0;
const TEXT_INPUT_FILTER_PUMP_MAX_ATTEMPTS = 80;
const TEXT_INPUT_FILTER_PUMP_RETRY_MS = 250;

function queueTextInputFilterOp(nodeId: number, composedSource: string | null): void {
  pendingTextInputFilterOps.set(nodeId, composedSource);
  textInputFilterPumpAttempts = 0;
  scheduleTextInputFilterPump(0);
}

function scheduleTextInputFilterPump(delayMs: number): void {
  if (textInputFilterPumpScheduled) {
    return;
  }
  textInputFilterPumpScheduled = true;
  setTimeout(pumpTextInputFilterOps, delayMs);
}

function pumpTextInputFilterOps(): void {
  textInputFilterPumpScheduled = false;
  if (pendingTextInputFilterOps.size === 0) {
    return;
  }
  const bridge = hostCallAsyncBridge();
  if (!bridge) {
    textInputFilterPumpAttempts += 1;
    if (textInputFilterPumpAttempts >= TEXT_INPUT_FILTER_PUMP_MAX_ATTEMPTS) {
      if (process.env.NODE_ENV !== 'production') {
        // eslint-disable-next-line no-console
        console.warn(
          '[ExactRenderer] giving up installing text-input filters — the '
            + 'async host-call bridge never appeared (plain web host?). '
            + 'Affected fields keep the async controlled contract.',
        );
      }
      pendingTextInputFilterOps.clear();
      return;
    }
    scheduleTextInputFilterPump(TEXT_INPUT_FILTER_PUMP_RETRY_MS);
    return;
  }

  for (const [nodeId, composedSource] of Array.from(pendingTextInputFilterOps)) {
    pendingTextInputFilterOps.delete(nodeId);
    const operation = composedSource == null
      ? 'worklet.removeTextInputFilter'
      : 'worklet.installTextInputFilter';
    const args = composedSource == null
      ? JSON.stringify({ nodeId })
      : JSON.stringify({ nodeId, source: composedSource });
    bridge(operation, args).then((result) => {
      if (process.env.NODE_ENV !== 'production') {
        // eslint-disable-next-line no-console
        console.log(`[ExactRenderer] ${operation} ok for node ${nodeId}: ${String(result).slice(0, 80)}`);
      }
      return result;
    }).catch((error: unknown) => {
      if (process.env.NODE_ENV !== 'production') {
        // eslint-disable-next-line no-console
        console.warn(
          `[ExactRenderer] ${operation} failed for node ${nodeId}: `
            + `${error instanceof Error ? error.message : String(error)}. `
            + 'The field keeps the async controlled contract.',
        );
      }
    });
  }
}

export function _resetTextInputFiltersForTests(): void {
  installedTextInputFilterSources.clear();
  pendingTextInputFilterOps.clear();
  textInputFilterPumpScheduled = false;
  textInputFilterPumpAttempts = 0;
}

/**
 * Process event props for an element and update the handler registry.
 * This is framework-agnostic - each framework calls this with its props.
 *
 * IMPORTANT: This function updates handlers in place to maintain stable handler IDs.
 * The native side caches handler IDs from BindEvent opcodes, so we must not change
 * IDs unnecessarily.
 */
export function processEventProps(
  instance: ElementNode,
  props: Props,
  config: TagConfig
): void {
  const supportsPressEvents =
    config.supportsPressEvents || instance.pressOverride === true;
  const supportsChangeEvents = config.supportsChangeEvents === true;
  const supportsTransitionEvents = config.supportsTransitionEvents !== false;
  const supportsScrollEvents = isScrollShapedCanonicalType(config.canonicalType);
  rememberMotionGestureIdentities(instance, props.__exactMotionGesture);

  // If this element doesn't support any events, clear all handlers
  if (!supportsPressEvents && !supportsChangeEvents && !supportsTransitionEvents && !supportsScrollEvents) {
    for (const [eventType, binding] of instance.events) {
      unregisterHandler(binding.handlerId, instance.id, eventType, getRootIdForNode(instance));
    }
    instance.events.clear();
    return;
  }

  // Track which events are present in props
  const activeEvents = new Set<EventType>();

  if (supportsPressEvents) {
    for (const binding of PRESS_EVENT_BINDINGS) {
      bindFunctionPropEvent(instance, props, activeEvents, binding);
    }
  }

  // Process change events (for toggles, inputs)
  if (supportsChangeEvents) {
    if (instance.tagType === 'image') {
      const hasImageEventHandler =
        typeof props.onLoadStart === 'function' ||
        typeof props.onLoad === 'function' ||
        typeof props.onError === 'function' ||
        typeof props.onDisplay === 'function';

      if (hasImageEventHandler) {
        activeEvents.add(EventType.Change);
        upsertEventHandler(instance, EventType.Change, (payload: unknown) => {
          dispatchImageEventPayload(props, payload);
        });
      } else {
        removeEventHandler(instance, EventType.Change);
      }
    } else if (instance.tagType === 'lottie') {
      // LLP 0394: lottie lifecycle rides EventType.Change like image; the
      // flat payload carries an `event` discriminator plus load metadata.
      const hasLottieEventHandler =
        typeof props.onLoad === 'function' ||
        typeof props.onError === 'function' ||
        typeof props.onComplete === 'function' ||
        typeof props.onLooped === 'function';

      if (hasLottieEventHandler) {
        activeEvents.add(EventType.Change);
        upsertEventHandler(instance, EventType.Change, (payload: unknown) => {
          dispatchLottieEventPayload(props, payload);
        });
      } else {
        removeEventHandler(instance, EventType.Change);
      }
    } else if (instance.tagType === 'rive') {
      const hasRiveEventHandler =
        typeof props.onLoad === 'function' ||
        typeof props.onError === 'function' ||
        typeof props.onStateChange === 'function' ||
        typeof props.onDataChange === 'function' ||
        typeof props.onRiveEvent === 'function';

      if (hasRiveEventHandler) {
        activeEvents.add(EventType.Change);
        upsertEventHandler(instance, EventType.Change, (payload: unknown) => {
          dispatchRiveEventPayload(props, payload);
        });
      } else {
        removeEventHandler(instance, EventType.Change);
      }
    } else if (instance.tagType === 'nativeView') {
      const moduleName = instance.props.nativeViewModuleName;
      const isToggleNativeView = moduleName === 'exact.toggle';
      const hasNativeViewChangeHandler =
        typeof props.onChange === 'function' ||
        (isToggleNativeView && typeof props.onValueChange === 'function');
      // LLP 0420 §8: a module-backed view whose events are neither a control
      // "change" nor a protocol event — the graphics surface publishes its
      // epoch grant, its own box, and its pointer stream on one named module
      // channel. `onNativeViewEvent` is the raw seam for that: it receives the
      // event NAME alongside the decoded payload, which the Change envelope
      // structurally cannot carry.
      const nativeViewEventHandler =
        typeof props.onNativeViewEvent === 'function'
          ? (props.onNativeViewEvent as (eventName: string, payload: unknown) => void)
          : null;

      if (hasNativeViewChangeHandler || nativeViewEventHandler) {
        if (hasNativeViewChangeHandler) activeEvents.add(EventType.Change);

        // Native-view controls report already-structured payloads from the host
        // (for example `{ value: 0.42 }` for sliders). Unlike text inputs, this
        // payload should not be coerced into a text event shape.
        if (hasNativeViewChangeHandler) {
          const changeHandler = (payload: unknown) => {
            if (isToggleNativeView && typeof props.onValueChange === 'function') {
              const value =
                (payload as { nativeEvent?: { value?: unknown }; value?: unknown } | null)?.nativeEvent?.value ??
                (payload as { nativeEvent?: { value?: unknown }; value?: unknown } | null)?.value ??
                payload;
              props.onValueChange(value as boolean);
            }

            const onChange = props.onChange as ((event: unknown) => void) | undefined;
            onChange?.(payload);
          };

          upsertEventHandler(instance, EventType.Change, changeHandler);
        } else {
          removeEventHandler(instance, EventType.Change);
        }

        if (typeof instance.props.nativeViewModuleName === 'string') {
          registerNativeViewEventHandler(
            instance.id,
            instance.props.nativeViewModuleName,
            (eventName, payload) => {
              if (eventName !== 'change') {
                if (!nativeViewEventHandler) {
                  return false;
                }
                nativeViewEventHandler(eventName, payload);
                return true;
              }
              if (hasNativeViewChangeHandler) {
                return dispatchSyntheticEvent(instance, EventType.Change, payload);
              }
              nativeViewEventHandler?.(eventName, payload);
              return nativeViewEventHandler !== null;
            },
          );
        }
      } else {
        unregisterNativeViewEventHandler(instance.id);
        removeEventHandler(instance, EventType.Change);
      }
    } else {
      const hasToggleChangeHandler = typeof props.onValueChange === 'function';
      const hasTextChangeHandler =
        typeof props.onChangeText === 'function' ||
        typeof props.onChange === 'function' ||
        typeof props.onSelectionChange === 'function';

      if (hasToggleChangeHandler || hasTextChangeHandler) {
        activeEvents.add(EventType.Change);

        const changeHandler = (payload: unknown) => {
          if (typeof props.onValueChange === 'function') {
            const value =
              (payload as { nativeEvent?: { value?: unknown }; value?: unknown } | null)?.nativeEvent?.value ??
              (payload as { nativeEvent?: { value?: unknown }; value?: unknown } | null)?.value ??
              payload;
            props.onValueChange(value as boolean);
          }

          if (typeof props.onChangeText === 'function' || typeof props.onChange === 'function') {
            const event = normalizeTextChangePayload(payload);
            if (event.nativeEvent.classification === 'native-preflight') {
              // The host is holding a keystroke on this sync dispatch
              // (LLP 0297 A3 deprecation window) — record the field so
              // preflight-dependent inputs stay discoverable.
              recordTextInputPreflightDispatch({
                viewId: instance.id,
                testId: getElementTestId(instance),
                nativeId:
                  typeof instance.originalProps.nativeID === 'string'
                    ? instance.originalProps.nativeID
                    : undefined,
                handlerId: instance.events.get(EventType.Change)?.handlerId ?? 0,
                // Live read — `value` is not in EVENT_PROP_NAMES, so the
                // captured `props` can be stale here too (ENG-23202).
                controlled: instance.originalProps.value != null,
              });
            }
            const shouldDispatchCommittedText =
              event.nativeEvent.textChanged !== false &&
              event.nativeEvent.isComposing !== true;
            if (shouldDispatchCommittedText && typeof props.onChangeText === 'function') {
              props.onChangeText(event.nativeEvent.text);
            }
            if (shouldDispatchCommittedText && typeof props.onChange === 'function') {
              props.onChange(event);
            }
          }

          if (typeof props.onSelectionChange === 'function') {
            const event = normalizeTextChangePayload(payload);
            if (event.nativeEvent.selection) {
              props.onSelectionChange({
                nativeEvent: {
                  selection: event.nativeEvent.selection,
                  text: event.nativeEvent.text,
                  ...(event.nativeEvent.isComposing !== undefined
                    ? { isComposing: event.nativeEvent.isComposing }
                    : {}),
                  ...(event.nativeEvent.compositionRange
                    ? { compositionRange: event.nativeEvent.compositionRange }
                    : {}),
                  ...(event.nativeEvent.textRevision !== undefined
                    ? { textRevision: event.nativeEvent.textRevision }
                    : {}),
                  ...(event.nativeEvent.classification !== undefined
                    ? { classification: event.nativeEvent.classification }
                    : {}),
                },
              });
            }
          }

          // ENG-23550: a final/non-composing change that carries a native
          // textRevision gets an observed-revision ack after the app's flush
          // turn. Composing previews do not invoke the committed-value
          // callbacks, so acknowledging one could let it stand in for the
          // app's later decision on the final candidate.
          const observedTextRevision = readTextRevisionPayload(payload);
          const isComposing = normalizeTextChangePayload(payload).nativeEvent.isComposing === true;
          if (observedTextRevision !== undefined && !isComposing) {
            scheduleTextInputObservedRevisionAck(instance, observedTextRevision);
          }
        };

        upsertEventHandler(instance, EventType.Change, changeHandler);
      } else {
        // Remove change handler if no longer in props
        removeEventHandler(instance, EventType.Change);
      }
    }
  }

  if (config.nodeType === NodeType.TextInput) {
    syncTextInputFilterProp(instance, props);
  }

  if (supportsTransitionEvents) {
    if (typeof props.onTransitionEnd === 'function') {
      activeEvents.add(EventType.TransitionEnd);
      upsertEventHandler(instance, EventType.TransitionEnd, props.onTransitionEnd);
    } else {
      removeEventHandler(instance, EventType.TransitionEnd);
    }
  }

  // Native lease grants and terminals share one acknowledged outcome log.
  // Start is a distinct handler so React can establish a claim only after the
  // arena really activates; terminal then releases that exact stream claim.
  if (typeof props.__exactMotionGestureStart === 'function') {
    activeEvents.add(EventType.MotionGestureStart);
    upsertEventHandler(
      instance,
      EventType.MotionGestureStart,
      (payload: unknown) => {
        const handler = instance.originalProps.__exactMotionGestureStart;
        const normalized = normalizeMotionGesturePayload(instance, payload);
        publishNativeMotionGestureObservation(instance, normalized, false);
        if (typeof handler === 'function') {
          handler(normalized);
        }
      },
    );
  } else {
    removeEventHandler(instance, EventType.MotionGestureStart);
  }

  if (typeof props.__exactMotionGestureEnd === 'function') {
    activeEvents.add(EventType.MotionGestureEnd);
    upsertEventHandler(
      instance,
      EventType.MotionGestureEnd,
      (payload: unknown) => {
        const handler = instance.originalProps.__exactMotionGestureEnd;
        const normalized = normalizeMotionGesturePayload(instance, payload);
        publishNativeMotionGestureObservation(instance, normalized, true);
        if (typeof handler === 'function') {
          handler(normalized);
        }
      },
    );
  } else {
    removeEventHandler(instance, EventType.MotionGestureEnd);
  }

  if (supportsScrollEvents) {
    const hasScroll = typeof props.onScroll === 'function';
    const hasScrollEnd = typeof props.onScrollEnd === 'function';
    const hasRefresh = typeof props.onRefresh === 'function';
    if (hasScroll) {
      activeEvents.add(EventType.Scroll);
      const onScroll = props.onScroll as (
        event: ReturnType<typeof normalizeScrollPayload>
      ) => void;
      const scrollEventThrottle = resolveScrollEventThrottle(props);
      const throttleState = getScrollThrottleState(instance);
      upsertEventHandler(instance, EventType.Scroll, (payload: unknown) => {
        const event = normalizeScrollPayload(payload);
        if (event.nativeEvent.nativeListGeometry == null) {
          publishHostMotionScrollOffset(
            instance,
            event.nativeEvent.contentOffset.x,
            event.nativeEvent.contentOffset.y,
          );
        }
        const timestamp = event.nativeEvent.timestamp;
        if (
          event.nativeEvent.nativeListGeometry == null &&
          scrollEventThrottle > 0 &&
          throttleState.lastDispatchAt !== null &&
          timestamp >= throttleState.lastDispatchAt &&
          timestamp - throttleState.lastDispatchAt < scrollEventThrottle
        ) {
          return;
        }
        throttleState.lastDispatchAt = timestamp;
        beginContractPerfInput(
          getRootIdForNode(instance),
          getElementTestId(instance),
          'scroll',
        );
        onScroll(event);
      });
    } else {
      removeEventHandler(instance, EventType.Scroll);
      scrollThrottleState.delete(instance);
    }
    if (hasScrollEnd) {
      activeEvents.add(EventType.ScrollEnd);
      upsertEventHandler(
        instance,
        EventType.ScrollEnd,
        (payload: unknown) => {
          const event = normalizeScrollPayload(payload);
          publishHostMotionScrollOffset(
            instance,
            event.nativeEvent.contentOffset.x,
            event.nativeEvent.contentOffset.y,
          );
          (props.onScrollEnd as (
            event: ReturnType<typeof normalizeScrollPayload>
          ) => void)(event);
        },
      );
    } else {
      removeEventHandler(instance, EventType.ScrollEnd);
    }
    if (hasRefresh) {
      activeEvents.add(EventType.Refresh);
      upsertEventHandler(
        instance,
        EventType.Refresh,
        (payload: unknown) => {
          const event = normalizeRefreshPayload(payload);
          publishHostMotionScrollOffset(
            instance,
            event.nativeEvent.contentOffset.x,
            event.nativeEvent.contentOffset.y,
          );
          (props.onRefresh as (
            event: ReturnType<typeof normalizeRefreshPayload>
          ) => void)(event);
        },
      );
    } else {
      removeEventHandler(instance, EventType.Refresh);
    }
  }

  for (const binding of FOCUS_AND_KEYBOARD_BINDINGS) {
    const handler = props[binding.propName];
    const submitEditingHandler =
      instance.tagType === 'input' && binding.eventType === EventType.KeyDown
        ? props.onSubmitEditing
        : undefined;
    const needsInternalInputTracking =
      instance.tagType === 'input' &&
      (binding.eventType === EventType.Focus || binding.eventType === EventType.Blur);

    if (
      typeof handler === 'function' ||
      typeof submitEditingHandler === 'function' ||
      needsInternalInputTracking
    ) {
      activeEvents.add(binding.eventType);
      upsertEventHandler(instance, binding.eventType, (payload: unknown) => {
        const normalizedPayload = binding.normalize(payload);
        if (binding.eventType === EventType.Focus) {
          syncInputFocusTracking(instance, true);
        } else if (binding.eventType === EventType.Blur) {
          syncInputFocusTracking(instance, false);
        }
        if (typeof handler === 'function') {
          handler(normalizedPayload);
        }
        if (
          typeof submitEditingHandler === 'function' &&
          binding.eventType === EventType.KeyDown &&
          (normalizedPayload as { nativeEvent: { key?: string } }).nativeEvent.key === 'Enter' &&
          // Read multiline at dispatch time: this closure is only rebuilt
          // when an EVENT_PROP_NAMES prop changes, so the registration-time
          // `props` capture goes stale when multiline flips with
          // identity-stable handlers (ENG-23202). originalProps is updated
          // on every updateInstanceProps.
          instance.originalProps.multiline !== true
        ) {
          submitEditingHandler();
        }
      });
    } else {
      removeEventHandler(instance, binding.eventType);
    }
  }

  // Remove handlers for events no longer in props
  for (const [eventType, binding] of instance.events) {
    if (!activeEvents.has(eventType)) {
      unregisterHandler(binding.handlerId, instance.id, eventType, getRootIdForNode(instance));
      instance.events.delete(eventType);
    }
  }
}

/**
 * Recursively clean up event handlers for a node and all its children.
 * This ensures native event listeners are properly released.
 */
export function cleanupNodeHandlers(
  node: ElementNode | TextNode,
  rootId: number = getRootIdForNode(node),
): void {
  if (node.kind === NodeKind.Element) {
    const element = node as ElementNode;

    if (element.tagType === 'nativeView') {
      unregisterNativeViewEventHandler(element.id);
    }

    // Unregister all event handlers for this node
    for (const [eventType, binding] of element.events) {
      unregisterHandler(binding.handlerId, element.id, eventType, rootId);
    }
    element.events.clear();

    // ENG-23560: unbind the node's worklet text-input filter, if any.
    if (installedTextInputFilterSources.has(element.id)) {
      removeTextInputFilter(element.id);
    }

    // Recursively clean up children
    for (const child of element.children) {
      cleanupNodeHandlers(child, rootId);
    }
  }
}

// =============================================================================
// High-Level Host Operations
// =============================================================================

/**
 * Create an element instance.
 * Used by framework adapters during React's render phase, so this must remain side-effect free.
 */
export function createInstance(
  type: string,
  props: Props,
): ElementNode {
  const config = getTagConfig(type) ?? defaultTagConfig;

  // Create the element node
  const instance = createElementNode(
    config.canonicalType,
    type,
    config.isRNStyle,
    props
  );

  applyResolvedElementState(
    instance,
    resolveElementState(instance, config, type, props, getRootInheritedState(0)),
  );

  // Event handlers are intentionally NOT registered here: React can abort a
  // render and drop the instance, which would leak entries in the global
  // handler registry. Registration happens at commit, in encodeCreatedSubtree.
  return instance;
}

/**
 * Create a text instance.
 * Used by framework adapters during React's render phase, so this must remain side-effect free.
 */
export function createTextInstance(text: string): TextNode {
  return createTextNode(text);
}

function encodeCreatedSubtree(
  encoder: ProtocolEncoder,
  node: ElementNode | TextNode,
  inheritedState: InheritedElementState = getRootInheritedState(),
  inheritedTextMeasureStyle: CanonicalStyle | null = null,
): void {
  if (!hasDirtyFlag(node, DirtyFlags.Created)) {
    return;
  }

  if (node.kind === NodeKind.Text) {
    encodeCreateText(encoder, node);
    if (inheritedTextMeasureStyle) {
      // Raw text leaf: no canonical element style to lose (see
      // emitElementSetStyle).
      encodeSetStyleOp(encoder, node.id, inheritedTextMeasureStyle);
    }
    markViewChanged(node);
    clearDirtyFlags(node);
    return;
  }

  const nodeTextMeasureStyle = inheritedTextMeasureStyleForChild(
    node,
    inheritedTextMeasureStyle,
  );

  const config = getTagConfig(node.originalTag) ?? defaultTagConfig;
  // Commit-time event registration (createInstance is render-phase pure).
  // processEventProps is idempotent, so adapters that already registered
  // handlers imperatively (DOM shim, Solid, Vue) keep their stable handler IDs.
  processEventProps(node, node.originalProps, config);
  if (canRefreshCreatedMountEnvironment(node, inheritedState)) {
    refreshCreatedMountEnvironment(node, inheritedState);
  } else {
    applyResolvedElementState(
      node,
      resolveElementState(node, config, node.originalTag, node.originalProps, inheritedState),
    );
  }
  encodeCreateElement(encoder, node);
  emitNativeListModelChunks(encoder, node, node.originalProps);
  if (inheritedTextMeasureStyle && node.tagType === 'text' && nodeTextMeasureStyle) {
    // Layer the node's own full style on top: this SetStyle replaces the one
    // encodeCreateElement just sent, so a measure-only subset would strip the
    // node's explicit non-measure styles (e.g. an inline run color).
    emitElementSetStyle(
      encoder,
      node,
      textElementStyleWithInheritedMeasure(node, nodeTextMeasureStyle),
    );
  }
  markViewChanged(node);
  const childInheritedState: InheritedElementState = {
    rootId: node.propagatedSafeArea?.rootId ?? inheritedState.rootId,
    direction: node.resolvedDirection,
    writingMode: node.resolvedWritingMode,
    lang: node.resolvedLang,
    safeArea: node.propagatedSafeArea ?? inheritedState.safeArea,
    imageListContext: isSemanticRecycler(node) ? true : node.resolvedImageListContext,
  };
  for (const child of node.children) {
    encodeCreatedSubtree(encoder, child, childInheritedState, nodeTextMeasureStyle);
  }
  if (node.children.length > 0) {
    encodeChildren(encoder, node);
  }
  clearDirtyFlags(node);
}

function syncInheritedStateInSubtree(
  encoder: ProtocolEncoder,
  node: ElementNode | TextNode,
  forceDescend = false,
): void {
  if (node.kind === NodeKind.Text) {
    return;
  }

  const config = getTagConfig(node.originalTag) ?? defaultTagConfig;
  const previousStyle = node.style;
  const previousProps = node.props;
  const previousTransitions = node.transitions;
  const previousDirection = node.resolvedDirection;
  const previousWritingMode = node.resolvedWritingMode;
  const previousLang = node.resolvedLang;
  const previousImageListContext = node.resolvedImageListContext;
  const previousSafeArea = node.propagatedSafeArea;
  const nextState = resolveElementState(
    node,
    config,
    node.originalTag,
    node.originalProps,
    getInheritedState(node.parent as ElementNode | RootNode | null),
  );
  const changedStyleKeys = collectChangedStyleKeys(previousStyle, nextState.style);
  const styleChanged = changedStyleKeys.length > 0;
  const propsChanged = !propsEqual(previousProps, nextState.props);
  const transitionsChanged = !transitionsEqual(previousTransitions, nextState.transitions);
  const inheritedStateChanged =
    previousDirection !== nextState.resolvedDirection ||
    previousWritingMode !== nextState.resolvedWritingMode ||
    previousLang !== nextState.resolvedLang ||
    previousImageListContext !== nextState.resolvedImageListContext ||
    !safeAreaPropagationEqual(previousSafeArea, nextState.propagatedSafeArea);

  applyResolvedElementState(node, nextState);

  if (!hasDirtyFlag(node, DirtyFlags.Created)) {
    if (styleChanged) {
      markViewChanged(node);
      if (styleKeysAffectLayout(changedStyleKeys)) {
        markLayoutDirtyForNode(node);
      }
      encodeStyleUpdate(encoder, node, changedStyleKeys);
      if (node.tagType === 'text' && styleKeysAffectTextLeafMeasure(changedStyleKeys)) {
        encodeTextLeafMeasureStyles(encoder, node);
      }
    }

    if (transitionsChanged) {
      markViewChanged(node);
      setTransition(encoder, node.id, node.transitions);
    }

    if (propsChanged) {
      markViewChanged(node);
      getPendingCommitState(getRootIdForNode(node)).warningAnalysisDirty = true;
      encodeRemovedProps(encoder, node.id, previousProps, nextState.props);
      encodeProps(encoder, node);
    } else if (
      previousLang !== node.resolvedLang &&
      typeof node.props.lang === 'string' &&
      node.props.lang.length > 0
    ) {
      markViewChanged(node);
      setLang(encoder, node.id, node.resolvedLang);
    }
  }

  // Inherited state (direction/writingMode/lang/safeArea) only reaches
  // children when it changed, but callers whose trigger is invisible to that
  // check — a font-registry change re-resolving baked fontFamily IDs anywhere
  // in the tree (ENG-22788) — force the full descent.
  if (!inheritedStateChanged && !forceDescend) {
    return;
  }

  for (const child of node.children) {
    syncInheritedStateInSubtree(encoder, child, forceDescend);
  }
}

function syncSelectablePropsInSubtree(
  encoder: ProtocolEncoder,
  node: ElementNode | TextNode,
): void {
  if (node.kind === NodeKind.Text) {
    return;
  }

  if (
    !hasDirtyFlag(node, DirtyFlags.Created) &&
    (node.tagType === 'text' || node.props.selectable !== undefined)
  ) {
    // Only the resolved selectable state can change on a reparent or an
    // ancestor selectable toggle. Re-running full encodeProps here re-sent
    // textContent for every text descendant of every keyed list move, and
    // kernel set_prop("text") remeasures — a layout storm on pure reorders
    // (ENG-23161).
    encodeResolvedSelectable(encoder, node);
  }

  for (const child of node.children) {
    syncSelectablePropsInSubtree(encoder, child);
  }
}

function hasCommittedViewportSizeChanged(rootId: number): boolean {
  const currentViewport = getScreenDimensions(rootId);
  const previousViewport = committedRootViewportSizes.get(rootId);
  return (
    previousViewport === undefined ||
    previousViewport.width !== currentViewport.width ||
    previousViewport.height !== currentViewport.height
  );
}

function syncRootInheritedState(root: RootNode): void {
  const enc = getEncoderForRoot(root.rootId);
  const opCountBefore = enc.getOpCount();

  for (const child of root.children) {
    syncInheritedStateInSubtree(enc, child);
  }

  if (enc.getOpCount() > opCountBefore) {
    commitBatch(root);
  }
}

function syncLiveRootInheritedState(): void {
  for (const root of liveRoots.values()) {
    syncRootInheritedState(root);
  }
}

/**
 * Re-resolve every live node's style after a font-registry change and
 * re-encode the nodes whose canonical style actually changed (ENG-22788).
 *
 * Font family IDs are baked into canonical styles at encode time:
 * `resolveFontFamilyId` skips a custom family until its record is `loaded`,
 * so a node encoded before `loadFont` resolved keeps the fallback family ID
 * until something else happens to re-encode its style. ENG-22728 made font
 * registration remeasure text (kernel measure caches + relayout) but never
 * refreshed the baked IDs — the blog's first paint stayed on the system font
 * until navigation re-rendered the route.
 *
 * The walk reuses syncInheritedStateInSubtree with a forced descent: it
 * re-runs resolveElementState per element, diffs against the retained
 * canonical style, and re-emits only changed nodes. A changed fontFamily is
 * never patchable, so changed nodes get their full canonical style via
 * SetStyle (REPLACE semantics — see textElementStyleWithInheritedMeasure /
 * ENG-22737), and text-leaf measure styles are re-encoded because fontFamily
 * is a TEXT_LEAF_MEASURE_STYLE_KEY.
 */
export function refreshFontResolutionForLiveRoots(): void {
  refreshResolvedStateForLiveRoots();
}

/**
 * Forced-descent re-resolution of every live element (shared by the
 * font-registry refresh above and the ENG-23202 color-scheme refresh):
 * re-runs resolveElementState per element, diffs against retained canonical
 * state, and re-encodes only actually-changed nodes.
 */
function refreshResolvedStateForLiveRoots(): void {
  for (const root of liveRoots.values()) {
    const enc = getEncoderForRoot(root.rootId);
    const opCountBefore = enc.getOpCount();

    for (const child of root.children) {
      syncInheritedStateInSubtree(enc, child, true);
    }

    if (enc.getOpCount() > opCountBefore) {
      commitBatch(root);
    }
  }
}

/**
 * Re-resolve inherited layout state for an already-mounted root after the host
 * environment changes.
 *
 * Window state changes (viewport size, safe area insets, keyboard metrics)
 * affect style resolution even when JSX/template props stay byte-for-byte
 * identical. Adapters call this helper from their root window subscriptions so
 * host-ops can recompute the affected styles without relying on framework prop
 * diffs.
 */
export function syncRootWindowState(root: RootNode): void {
  const enc = getEncoderForRoot(root.rootId);

  for (const child of root.children) {
    syncInheritedStateInSubtree(enc, child);
  }

  commitBatch(root);
}

export function syncRootInheritedWindowState(root: RootNode): void {
  const enc = getEncoderForRoot(root.rootId);
  const opCountBefore = enc.getOpCount();
  const viewportChanged = hasCommittedViewportSizeChanged(root.rootId);

  for (const child of root.children) {
    syncInheritedStateInSubtree(enc, child);
  }

  // A viewport-size change must reach commitBatch even when no inherited
  // style ops were generated: commitBatch is what re-encodes the root
  // node's width/height and recomputes kernel layout. Recording the new
  // size here without committing (the pre-ENG-22691 behavior) silently
  // pinned the kernel root at its boot dimensions for fixed-style trees —
  // the macOS window resized while the app surface stayed frozen.
  if (enc.getOpCount() > opCountBefore || viewportChanged) {
    commitBatch(root);
  }
}

/**
 * Nodes detached via the RFC 0043 detachChild path and not yet re-inserted.
 *
 * React's keyed reorders call insertBefore on mounted nodes WITHOUT a prior
 * detach and never change ancestor context, so they must not pay a subtree
 * re-resolution (ENG-23161). Only a genuine detach → insert reparent (the DOM
 * shim's insertNodeIntoParent, available to all adapters) changes the
 * inherited context and needs it (ENG-23202).
 */
const pendingReparentedNodes = new WeakSet<ElementNode | TextNode>();

function syncReparentedSubtree(
  enc: ProtocolEncoder,
  parent: ElementNode | RootNode,
  child: ElementNode | TextNode,
): void {
  if (hasDirtyFlag(child, DirtyFlags.Created)) {
    return;
  }
  // Re-resolve inherited element state (direction/lang/safe-area) against the
  // new ancestor chain, then re-layer the new context's text measure subset —
  // the kernel has no style inheritance, so leaves keep the OLD parent's font
  // subset until re-encoded (ENG-23202).
  if (child.kind === NodeKind.Element) {
    syncInheritedStateInSubtree(enc, child);
  }
  syncReparentedTextMeasureStyles(
    enc,
    child,
    inheritedTextMeasureStyleForInsertedChildren(parent),
  );
}

/**
 * Append a child to a parent and encode the operation.
 */
export function appendChild(parent: ElementNode | RootNode, child: ElementNode | TextNode): void {
  const wasDetached = pendingReparentedNodes.delete(child);
  const moved = nodeAppendChild(parent, child as ElementNode);
  // ENG-23198: already attached in place — nothing structural changed, so
  // skip the selectable re-sync subtree walk, the (no-op) created-subtree
  // encode, and the children-dirty mark. Keyed reorder passes call this for
  // every row on every list change; without the guard a pure append to an
  // n-row list re-emitted props for all n rows' text descendants.
  if (!moved && !wasDetached && !hasDirtyFlag(child, DirtyFlags.Created)) {
    return;
  }
  const enc = getEncoderForNode(parent);
  // Selectable re-sync must run while Created flags are still intact: its
  // !Created gate skips nodes that encodeCreatedSubtree is about to encode in
  // full, so only pre-existing (reparented) nodes get their props re-emitted.
  syncSelectablePropsInSubtree(enc, child);
  encodeCreatedSubtree(
    enc,
    child,
    getInheritedState(parent),
    inheritedTextMeasureStyleForInsertedChildren(parent),
  );
  if (wasDetached) {
    syncReparentedSubtree(enc, parent, child);
  }
  markChildrenDirty(parent);
}

/**
 * Insert a child before another child and encode the operation.
 */
export function insertBefore(
  parent: ElementNode | RootNode,
  child: ElementNode | TextNode,
  beforeChild: ElementNode | TextNode
): void {
  const wasDetached = pendingReparentedNodes.delete(child);
  const moved = nodeInsertBefore(parent, child as ElementNode, beforeChild as ElementNode);
  // ENG-23198: see appendChild — already immediately before `beforeChild`,
  // nothing structural changed.
  if (!moved && !wasDetached && !hasDirtyFlag(child, DirtyFlags.Created)) {
    return;
  }
  const enc = getEncoderForNode(parent);
  // See appendChild: run before encoding so the !Created gate is meaningful.
  syncSelectablePropsInSubtree(enc, child);
  encodeCreatedSubtree(
    enc,
    child,
    getInheritedState(parent),
    inheritedTextMeasureStyleForInsertedChildren(parent),
  );
  if (wasDetached) {
    syncReparentedSubtree(enc, parent, child);
  }
  markChildrenDirty(parent);
}

/**
 * Detach a child from its parent without destroying the subtree.
 *
 * This is the DOM-spec-style "remove from this parent, but keep the node alive"
 * primitive required for RFC 0043 reparenting. Event handlers stay registered
 * and descendants keep their identity so the subtree can be inserted again.
 */
export function detachChild(parent: ElementNode | RootNode, child: ElementNode | TextNode): void {
  nodeRemoveChild(parent, child as ElementNode);
  pendingReparentedNodes.add(child);
  markChildrenDirty(parent);
}

/**
 * Remove a child from a parent and destroy the detached subtree.
 *
 * The destructive behavior here is deliberate: existing React/Solid/Vue host
 * configs use removeChild for final removal. RFC 0043 adds detachChild for the
 * non-destructive DOM-shim path.
 */
export function removeChild(parent: ElementNode | RootNode, child: ElementNode | TextNode): void {
  const enc = getEncoderForNode(parent);
  const rootId = getRootIdForNode(parent);
  // Clean up event handlers
  cleanupNodeHandlers(child, rootId);
  nodeRemoveChild(parent, child as ElementNode);
  if (!hasDirtyFlag(child, DirtyFlags.Created)) {
    // Pass rootId explicitly: the child is already severed from the tree, so
    // walking up from it would misattribute the destroyed views to root 0.
    destroySubtree(child, enc, rootId);
  }
  markChildrenDirty(parent);
}

function dropDynamicRangeSidecarSubtree(node: ElementNode | TextNode): void {
  getDynamicRangeResolutionRuntimeState().sidecar.destroy(node.id);
}

/**
 * Clear all children from a container and encode the operation.
 */
export function clearContainer(container: RootNode): void {
  const enc = getEncoderForNode(container);
  const rootId = container.rootId;
  // Clean up all event handlers and destroy children
  for (const child of container.children.slice()) {
    cleanupNodeHandlers(child, rootId);
    if (!hasDirtyFlag(child, DirtyFlags.Created)) {
      destroySubtree(child, enc, rootId);
    }
  }

  nodeClearChildren(container);
  markChildrenDirty(container);
}

/**
 * Destroy a root and flush the teardown batch before releasing its encoder.
 *
 * This is intentionally per-root instead of global reset logic so DOM handles,
 * multi-root adapters, and HMR teardown can remove one root without affecting
 * any others.
 */
export function destroyRoot(rootId: number): void {
  const root = liveRoots.get(rootId);
  const enc = encoders.get(rootId);
  const dispatchFailed = protocolDispatchFailedRoots.has(rootId);

  try {
    if (!root) {
      if (enc) {
        if (dispatchFailed) enc.reset();
        else flushRootProtocol(rootId, enc);
      }
      return;
    }

    clearContainer(root);
    const encoder = getEncoderForRoot(rootId);
    if (dispatchFailed) {
      // No further protocol frame for this root has a trustworthy predecessor.
      // Local teardown still releases callbacks and authorities, but the root
      // ID stays quarantined because the native side may own the failed frame.
      encoder.reset();
    } else {
      flushDirtyChildren(encoder, pendingCommitStateByRoot.get(rootId));
      encodePendingMotionCommands(rootId, encoder);
      const commitMotionTeardown = encodeMotionDescriptorSnapshot(encoder, root, []);
      encodePendingMotionCommands(rootId, encoder);
      flushRootProtocol(rootId, encoder);
      commitMotionTeardown();
    }
  } finally {
    // Native teardown can apply its frame and then throw. Local ownership and
    // resources must still be released exactly once; flushRootProtocol has
    // already quarantined the ambiguous root ID in that case.
    releaseMotionSourceMembershipsForRoot(rootId);
    encoders.delete(rootId);
    pendingCommitStateByRoot.delete(rootId);
    committedPagerBindingsByRoot.delete(rootId);
    committedMotionDescriptorsByRoot.delete(rootId);
    committedMotionWorkletArtifactsByRoot.delete(rootId);
    committedMotionDescriptorTransactionsByRoot.delete(rootId);
    motionTransactionsByRoot.delete(rootId);
    unregisterInspectorRoot(rootId);
    rootOwners.delete(rootId);
    protocolSuppressedRoots.delete(rootId);
    (globalThis as typeof globalThis & {
      __exactDomMirror?: { remove(rootId: number): void };
    }).__exactDomMirror?.remove(rootId);
  }
}

/**
 * Recursively destroy a node and all of its descendants.
 *
 * Important: we must encode destroys bottom-up so parents don't temporarily
 * reference children that no longer exist during intermediate batches.
 */
function destroySubtree(
  node: ElementNode | TextNode,
  enc?: ProtocolEncoder,
  rootId: number = getRootIdForNode(node),
): void {
  dropDynamicRangeSidecarSubtree(node);
  const encoder = enc ?? getEncoderForRoot(rootId);
  if (node.kind === NodeKind.Element) {
    // Copy because children array is still used by node ops.
    const children = (node as ElementNode).children.slice();
    for (const child of children) {
      destroySubtree(child, encoder, rootId);
    }
  }

  // The owning rootId is threaded through (like cleanupNodeHandlers) because
  // the subtree may already be detached, which would resolve to root 0.
  getPendingCommitState(rootId).changedViews.add(node.id);
  encodeDestroy(encoder, node);
}

let dynamicRangeRenderRevision = 0;

function isImageNode(node: ElementNode): boolean {
  const tag = typeof node.originalTag === 'string'
    ? node.originalTag.toLowerCase()
    : '';
  return tag === 'image' || tag === 'img';
}

function isInsideListContext(node: ElementNode): boolean {
  let parent = node.parent;
  while (parent && parent.kind !== NodeKind.Root) {
    const originalTag = (parent as ElementNode).originalTag;
    const tag = typeof originalTag === 'string' ? originalTag.toLowerCase() : '';
    if (tag === 'list' || tag === 'virtuallist' || tag === 'flatlist') return true;
    parent = parent.parent;
  }
  return false;
}

function declaredDynamicRangeObservations(
  props: Record<string, unknown>,
): DynamicRangeDeclaredObservation[] {
  const observations: DynamicRangeDeclaredObservation[] = [];
  const source =
    typeof props.source === 'object' && props.source !== null
      ? (props.source as Record<string, unknown>)
      : undefined;
  const add = (
    by: DynamicRangeDeclaredObservation['by'],
    rangeClass: unknown,
    encoding: unknown,
  ) => {
    if (
      (rangeClass === 'sdr' || rangeClass === 'hdr' || rangeClass === 'unknown') &&
      (encoding === 'sdr' ||
        encoding === 'gain-map' ||
        encoding === 'pq' ||
        encoding === 'hlg' ||
        encoding === 'unknown')
    ) {
      observations.push({ by, rangeClass, source: encoding });
    }
  };
  add(
    'manifest',
    props.rangeClass ?? source?.rangeClass,
    props.dynamicRangeSource ?? source?.dynamicRangeSource,
  );
  add(
    'container-parser',
    props.parsedRangeClass ?? source?.parsedRangeClass,
    props.parsedDynamicRangeSource ?? source?.parsedDynamicRangeSource,
  );
  return observations;
}

function stampDynamicRangePolicies(root: RootNode): void {
  const sidecar = getDynamicRangeResolutionRuntimeState().sidecar;
  const images: ElementNode[] = [];
  const collect = (node: ElementNode): void => {
    if (isImageNode(node)) images.push(node);
    for (const child of node.children ?? []) {
      if (child.kind === NodeKind.Element) collect(child);
    }
  };
  for (const child of root.children) {
    if (child.kind === NodeKind.Element) collect(child);
  }
  // Non-image commits must not invalidate the inspector's serialization
  // cache merely to advance an unrelated HDR sidecar fence.
  if (images.length === 0) return;
  // The sidecar is realm-global (one per JS realm) while this counter is
  // module-scoped; a dev-SSR server that re-instantiates the renderer module
  // graph per request (fresh counter) against the persistent realm sidecar
  // would otherwise trip the must-increase fence. Syncing forward preserves
  // the strictly-increasing invariant in both worlds (ENG-25030).
  dynamicRangeRenderRevision =
    Math.max(dynamicRangeRenderRevision, sidecar.renderRevision) + 1;
  sidecar.beginRenderRevision(dynamicRangeRenderRevision);
  for (const node of images) {
    const props = node.originalProps;
    const propPresent = Object.prototype.hasOwnProperty.call(props, 'dynamicRange');
    const policy = resolveDynamicRangePolicy({
      ...(propPresent ? { prop: props.dynamicRange } : {}),
      ...(typeof props.hdr === 'boolean' ? { alias: props.hdr } : {}),
      ...(typeof (globalThis as { __exactDynamicRangeDefault?: unknown })
        .__exactDynamicRangeDefault === 'string'
        ? {
            appDefault: (globalThis as {
              __exactDynamicRangeDefault?: 'auto' | 'standard' | 'constrained' | 'no-limit';
            }).__exactDynamicRangeDefault,
          }
        : {}),
      listContext: isInsideListContext(node),
    });
    sidecar.stamp(node.id, {
      policy,
      declaredObservations: declaredDynamicRangeObservations(props),
      ...(policy.invalidInput && typeof props.dynamicRange === 'string'
        ? { rawInvalidValue: props.dynamicRange }
        : {}),
    });
  }
}

/**
 * Update an element's props and encode changes.
 */
export function updateInstanceProps(
  instance: ElementNode,
  oldProps: Props,
  newProps: Props
): void {
  const config = getTagConfig(instance.originalTag) ?? defaultTagConfig;
  let updateEconomy: UpdateEconomyBridge | undefined;
  if (
    ('env' in import.meta &&
      (import.meta as UpdateEconomyImportMeta).env.DEV === true) ||
    process.env.NODE_ENV === 'test'
  ) {
    updateEconomy = (globalThis as typeof globalThis & {
      __exactUpdateEconomy?: { bridge?: UpdateEconomyBridge };
    }).__exactUpdateEconomy?.bridge;
  }

  // Update style if changed
  // NOTE: React 19 may pass the same props object for both oldProps and newProps,
  // so we compare against the stored instance.style instead of oldProps.style
  const previousProps = instance.originalProps ?? oldProps;
  if (previousProps.__exactMotionGesture !== newProps.__exactMotionGesture) {
    rememberMotionGestureIdentities(instance, newProps.__exactMotionGesture);
  }

  // Fast path: React 19 commits a host update whenever the props object
  // identity changes, even if every prop value is unchanged (a parent
  // re-render recreates the element). Shallow-equal props (style and children
  // compared by identity) cannot change the resolved state, so skip the full
  // resolveElementState pipeline. The same-reference case must NOT take this
  // path: the DOM shim mutates its live props object in place and relies on
  // full re-resolution to discover changes.
  if (previousProps !== newProps && originalPropsShallowEqual(previousProps, newProps)) {
    instance.originalProps = newProps;
    updateEconomy?.recordHostElement(getRootIdForNode(instance), true, true);
    return;
  }

  const oldCanonicalProps = instance.props;
  const oldStyle = instance.style;
  const oldResolvedDirection = instance.resolvedDirection;
  const oldResolvedWritingMode = instance.resolvedWritingMode;
  const oldResolvedLang = instance.resolvedLang;
  const oldResolvedImageListContext = instance.resolvedImageListContext;
  const oldPropagatedSafeArea = instance.propagatedSafeArea;
  const oldTransitions = instance.transitions;
  const oldParagraphKey = instance.paragraphKey;
  const nextState = resolveElementState(
    instance,
    config,
    instance.originalTag,
    newProps,
    getInheritedState(instance.parent as ElementNode | RootNode | null),
  );
  const newCanonicalProps = nextState.props;
  const newStyle = nextState.style;
  const newTransitions = nextState.transitions;
  // Island-authoritative style carry-over happens inside
  // applyResolvedElementState (single choke point for every re-resolution
  // path — prop updates AND inherited-state refresh walks).
  const changedStyleKeys = collectChangedStyleKeys(oldStyle, newStyle);
  const styleChanged = changedStyleKeys.length > 0;
  const transitionsChanged = !transitionsEqual(oldTransitions, newTransitions);
  const propsChanged = !propsEqual(oldCanonicalProps, newCanonicalProps);
  const textContentChanged =
    oldCanonicalProps.textContent !== newCanonicalProps.textContent ||
    oldCanonicalProps.value !== newCanonicalProps.value;
  const textMeasureChanged =
    instance.tagType === 'text' && oldParagraphKey !== nextState.paragraphKey;
  const inheritedStateChanged =
    oldResolvedDirection !== nextState.resolvedDirection ||
    oldResolvedWritingMode !== nextState.resolvedWritingMode ||
    oldResolvedLang !== nextState.resolvedLang ||
    oldResolvedImageListContext !== nextState.resolvedImageListContext ||
    isSemanticRecyclerProps(instance.originalTag, previousProps) !==
      isSemanticRecyclerProps(instance.originalTag, newProps) ||
    !safeAreaPropagationEqual(oldPropagatedSafeArea, nextState.propagatedSafeArea);

  applyResolvedElementState(instance, nextState);

  // Update events if changed
  const eventsChanged = eventPropsChanged(previousProps, newProps);
  const nativeListModelChanged =
    previousProps.__exactNativeListModelChunks !== newProps.__exactNativeListModelChunks;
  updateEconomy?.recordHostElement(
    getRootIdForNode(instance),
    !(
      styleChanged ||
      transitionsChanged ||
      propsChanged ||
      inheritedStateChanged ||
      eventsChanged ||
      nativeListModelChanged
    ),
    false,
  );

  if (eventsChanged) {
    processEventProps(instance, newProps, config);
  }

  // Store the new original props for future diffing
  instance.originalProps = newProps;

  // ENG-23560: the worklet filter rides a NON-event prop, so the
  // eventsChanged fast path above misses it — the Contract runtime
  // delivers `filter` through a dynamic-prop update whose event handlers
  // are identity-stable. Runs after the originalProps commit so the sync
  // reads the fresh value.
  if (config.nodeType === NodeType.TextInput) {
    syncTextInputFilterProp(instance, newProps);
  }

  // Safe-area sibling-expansion resolution (safe-area.ts) caches a per-parent
  // sum of children's declared `safeAreaInset` props keyed by a generation
  // counter (ENG-23195). Structural child-set changes bump that counter on
  // their own; a prop-only change to an existing child's `safeAreaInset` value
  // does not go through appendChild/removeChild, so it must bump explicitly.
  if (previousProps.safeAreaInset !== newProps.safeAreaInset) {
    invalidateSiblingSafeAreaInsetCache(instance.parent);
  }

  if (hasDirtyFlag(instance, DirtyFlags.Created)) {
    return;
  }

  const enc = getEncoderForNode(instance);

  if (nativeListModelChanged) {
    markViewChanged(instance);
    emitNativeListModelChunks(enc, instance, newProps);
  }

  if (styleChanged) {
    markViewChanged(instance);
    if (styleKeysAffectLayout(changedStyleKeys)) {
      markLayoutDirtyForNode(instance);
    }
    encodeStyleUpdate(enc, instance, changedStyleKeys);
    if (instance.tagType === 'text' && styleKeysAffectTextLeafMeasure(changedStyleKeys)) {
      encodeTextLeafMeasureStyles(enc, instance);
    }
  }

  if (transitionsChanged) {
    markViewChanged(instance);
    setTransition(enc, instance.id, instance.transitions);
  }

  if (propsChanged) {
    markViewChanged(instance);
    getPendingCommitState(getRootIdForNode(instance)).warningAnalysisDirty = true;
    // Vanished canonical keys must be cleared explicitly: kernel set_prop is
    // insert-only, so without a ClearProp the old disabled/label/testId value
    // stayed live on native forever (ENG-23153).
    encodeRemovedProps(enc, instance.id, oldCanonicalProps, newCanonicalProps);
    const textRemoved =
      (oldCanonicalProps.textContent !== undefined &&
        newCanonicalProps.textContent === undefined) ||
      (oldCanonicalProps.value !== undefined && newCanonicalProps.value === undefined);
    if (textRemoved) {
      clearTextContent(enc, instance.id);
    }
    const canPatchStableTextContent =
      textContentChanged &&
      !styleChanged &&
      canPatchElementTextWithoutLayout(instance, newProps);
    if (
      (textMeasureChanged || textContentChanged) &&
      !canPatchStableTextContent
    ) {
      markLayoutDirtyForNode(instance);
    }
    if (canPatchStableTextContent && typeof newCanonicalProps.textContent === 'string') {
      setTextContent(enc, instance.id, newCanonicalProps.textContent);
    } else {
      // An unrelated prop change (accessibilityLabel, disabled, ...) must not
      // re-send identical text: the kernel remeasures on every text set
      // (ENG-23161).
      encodeProps(enc, instance, { skipTextContent: !textContentChanged });
    }
  } else if (
    oldResolvedLang !== instance.resolvedLang &&
    typeof instance.props.lang === 'string' &&
    instance.props.lang.length > 0
  ) {
    markViewChanged(instance);
    setLang(enc, instance.id, instance.resolvedLang);
  }

  if (oldCanonicalProps.selectable !== newCanonicalProps.selectable) {
    for (const child of instance.children) {
      syncSelectablePropsInSubtree(enc, child);
    }
  }

  if (inheritedStateChanged) {
    for (const child of instance.children) {
      syncInheritedStateInSubtree(enc, child);
    }
  }

  if (eventsChanged) {
    markViewChanged(instance);
    getPendingCommitState(getRootIdForNode(instance)).warningAnalysisDirty = true;
    encodeEvents(enc, instance);
  }
}

/**
 * Suspense/Offscreen visibility toggles (ENG-23192).
 *
 * react-reconciler calls hide/unhide per host node when a mounted <Suspense>
 * boundary re-suspends (mutation mode, ConcurrentRoot). These were missing
 * from the hostConfig, so the first post-mount suspension called `undefined`
 * and unmounted the root. Semantics mirror react-dom: hide = display:'none'
 * (emitted as a wire-only override; the canonical `instance.style` stays the
 * visible truth so later prop diffs are unaffected), unhide = re-emit the
 * canonical style (protocol SetStyle REPLACE semantics clear the override).
 * Raw text leaves hide as empty text and restore from the reconciler-supplied
 * text.
 */
// Nodes currently hidden by a Suspense/Offscreen boundary. React can commit
// updates INSIDE a hidden subtree (a store update re-rendering suspended
// content); every element SetStyle funnels through emitElementSetStyle, which
// re-applies the display:'none' override for members so a canonical style
// re-emission cannot silently un-hide them, and updateTextContent skips
// emission for hidden leaves (unhideTextInstance restores the live text).
const suspenseHiddenElements = new WeakSet<ElementNode>();
const suspenseHiddenTextLeaves = new WeakSet<TextNode>();
const suspenseHiddenTextUpdates = new WeakSet<TextNode>();

/** @internal Wire-style override hook for Suspense-hidden elements. */
function suspenseHiddenWireStyle(
  node: ElementNode,
  wireStyle: CanonicalStyle,
): CanonicalStyle {
  if (!suspenseHiddenElements.has(node) || wireStyle.display === 'none') {
    return wireStyle;
  }
  return { ...wireStyle, display: 'none' };
}

export function hideInstance(instance: ElementNode): void {
  suspenseHiddenElements.add(instance);
  if (hasDirtyFlag(instance, DirtyFlags.Created)) {
    return;
  }
  const enc = getEncoderForNode(instance);
  markViewChanged(instance);
  markLayoutDirtyForNode(instance);
  emitElementSetStyle(enc, instance, { ...instance.style, display: 'none' });
}

export function unhideInstance(instance: ElementNode): void {
  suspenseHiddenElements.delete(instance);
  if (hasDirtyFlag(instance, DirtyFlags.Created)) {
    return;
  }
  const enc = getEncoderForNode(instance);
  markViewChanged(instance);
  markLayoutDirtyForNode(instance);
  emitElementSetStyle(enc, instance, instance.style);
}

export function hideTextInstance(instance: TextNode): void {
  suspenseHiddenTextLeaves.add(instance);
  suspenseHiddenTextUpdates.delete(instance);
  if (hasDirtyFlag(instance, DirtyFlags.Created)) {
    return;
  }
  markViewChanged(instance);
  markLayoutDirtyForNode(instance);
  setTextContent(getEncoderForNode(instance), instance.id, '');
}

export function unhideTextInstance(instance: TextNode, text: string): void {
  suspenseHiddenTextLeaves.delete(instance);
  // updateTextContent remains the retained truth after a hidden update. When
  // no update ran, preserve React's unhide contract and accept its supplied
  // text instead (ENG-24193).
  const liveText = suspenseHiddenTextUpdates.has(instance) ? instance.text : text;
  suspenseHiddenTextUpdates.delete(instance);
  instance.text = liveText;
  if (hasDirtyFlag(instance, DirtyFlags.Created)) {
    return;
  }
  markViewChanged(instance);
  markLayoutDirtyForNode(instance);
  setTextContent(getEncoderForNode(instance), instance.id, liveText);
}

/**
 * Update a text node's content and encode the change.
 */
export function updateTextContent(instance: TextNode, newText: string): void {
  // Vite's dev gate folds away in production bundles: the
  // equality optimization keeps its separately required rollback lookup, but
  // the profiling bridge incurs no global lookup or call when absent.
  let updateEconomy: UpdateEconomyBridge | undefined;
  if (
    ('env' in import.meta &&
      (import.meta as UpdateEconomyImportMeta).env.DEV === true) ||
    process.env.NODE_ENV === 'test'
  ) {
    updateEconomy = (globalThis as typeof globalThis & {
      __exactUpdateEconomy?: { bridge?: UpdateEconomyBridge };
    }).__exactUpdateEconomy?.bridge;
  }
  const sameText = Object.is(instance.text, newText);
  const skipEqualText = sameText && rawTextEqualitySkipEnabled(
    updateEconomy?.isPathEnabled('rawTextEqualitySkip'),
  );
  updateEconomy?.recordHostText(getRootIdForNode(instance), sameText, skipEqualText);
  if (skipEqualText) {
    return;
  }
  instance.text = newText;
  // Text committed inside a Suspense-hidden subtree must not repaint the
  // hidden leaf; unhideTextInstance re-emits the live text (ENG-23192).
  if (suspenseHiddenTextLeaves.has(instance)) {
    suspenseHiddenTextUpdates.add(instance);
    return;
  }
  if (hasDirtyFlag(instance, DirtyFlags.Created)) {
    return;
  }
  markViewChanged(instance);
  if (!canPatchTextNodeWithoutLayout(instance)) {
    markLayoutDirtyForNode(instance);
  }
  setTextContent(getEncoderForNode(instance), instance.id, newText);
}

/**
 * React calls the host config's resetTextContent when a host component
 * transitions from string children (shouldSetTextContent true) to element
 * children (fiber ContentReset): the old text must be cleared before the new
 * child instances are placed. The prop diff cannot express this — a vanished
 * textContent key is never encoded (the protocol has no prop-removal op) —
 * so without an explicit clear the kernel keeps the stale string (ENG-23160).
 */
export function resetInstanceTextContent(instance: ElementNode): void {
  delete instance.props.textContent;
  instance.paragraphSpec = null;
  instance.paragraphKey = null;
  if (hasDirtyFlag(instance, DirtyFlags.Created)) {
    return;
  }
  markViewChanged(instance);
  markLayoutDirtyForNode(instance);
  setTextContent(getEncoderForNode(instance), instance.id, '');
}

/**
 * Finalize initial children after tree building.
 * Kept as a no-op because protocol encoding happens only once React commits placement.
 */
export function finalizeInstance(instance: ElementNode): void {
  void instance;
}

/**
 * Compositor-only presentation properties one whole-root Motion binding may
 * drive. `borderRadius`/`shadowOpacity`/`shadowRadius` are the LLP 0417 §4
 * `presentationPaint` class: CALayer scalars (`cornerRadius`,
 * `shadowOpacity`, `shadowRadius`) with no Taffy, measurement, semantics, or
 * hit-test participation. `shadowOffset` is object-valued and stays out.
 */
export type HostMotionBindingProperty =
  | 'translateX'
  | 'translateY'
  | 'scale'
  | 'scaleX'
  | 'scaleY'
  | 'rotation'
  | 'opacity'
  | 'borderRadius'
  | 'shadowOpacity'
  | 'shadowRadius';

export type HostMotionLayoutIslandProperty =
  | 'width'
  | 'height'
  | 'minWidth'
  | 'minHeight'
  | 'maxWidth'
  | 'maxHeight'
  | 'flexGrow'
  | 'flexShrink'
  | 'flexBasis'
  | 'rowGap'
  | 'columnGap'
  | 'aspectRatio';

export type HostMotionLayoutIslandClosureClass = 'fixedEnvelope' | 'closedAncestor';

export interface HostMotionSharedValue {
  readonly id: string;
  readonly generation: number;
  current(): number;
  /** Runtime-local authored intents; driver samples never reach this channel. */
  subscribeUserIntent?(
    listener: (intent: HostMotionSharedValueUserIntent) => void,
  ): () => void;
  /** Native protocol hosts lease per-frame driver authority from the web store. */
  acquireNativeDriverAuthority?(): () => void;
  /**
   * Intent-free adoption of a native terminal sample (FX2-d): the store takes
   * the slab's value without emitting a user intent or driver lifecycle churn,
   * so subsequent `.value` reads observe what the gesture's worklets wrote.
   */
  adoptNativeSample?(value: number): void;
  /** JS-side publish edges (authored writes, adopted terminal samples). */
  subscribe?(listener: (value: number) => void): () => void;
  /** Web fallback driver lifecycle; emits edges, never per-frame samples. */
  subscribeDriverLifecycle?(
    listener: (event: HostMotionDriverLifecycleEvent) => void,
  ): () => void;
  driverLifecycleSnapshot?(): HostMotionDriverLifecycleEvent | null;
}

export interface HostMotionDriverLifecycleEvent {
  readonly generation: number;
  readonly state: 'running' | 'settled' | 'cancelled' | 'stale';
  readonly driver: MotionCommandDriver;
  readonly reason?: string;
  readonly updatedAt: number;
}

export interface HostMotionRuntimeWorkletArtifact {
  readonly schemaVersion: unknown;
  readonly installFormat: unknown;
  readonly compilerId: unknown;
  readonly source: unknown;
  readonly captureNames: unknown;
  readonly captureKinds: unknown;
  readonly captures: unknown;
  readonly inputSlots: unknown;
  readonly outputSlots: unknown;
  readonly callbacks?: unknown;
}

export interface HostMotionDerivedNodeMetadata {
  /** Component/hook lifetime plus authored derive/sink site. */
  readonly identity: string;
  readonly generation: number;
  readonly role: 'derive' | 'sink';
  readonly artifact: HostMotionRuntimeWorkletArtifact;
}

const hostMotionDerivedNodeMetadata = new WeakMap<object, HostMotionDerivedNodeMetadata>();

/** Attach compiler/bundler metadata without changing the web value surface. */
export function attachHostMotionDerivedNodeMetadata(
  target: object,
  metadata: HostMotionDerivedNodeMetadata,
): void {
  if (typeof metadata.identity !== 'string' || metadata.identity.length === 0) {
    throw new TypeError('[motion] derived graph identity must be non-empty');
  }
  if (!Number.isInteger(metadata.generation) || metadata.generation <= 0) {
    throw new RangeError('[motion] derived graph generation must be positive');
  }
  hostMotionDerivedNodeMetadata.set(target, Object.freeze({ ...metadata }));
}

/** Create a Contract-owned graph node backed by its ordinary web evaluator. */
export function createHostMotionDerivedNode(
  metadata: HostMotionDerivedNodeMetadata,
  current: () => number,
): HostMotionSharedValue {
  const node = Object.freeze({
    id: metadata.identity,
    generation: metadata.generation,
    current,
  });
  attachHostMotionDerivedNodeMetadata(node, metadata);
  return node;
}

export interface HostMotionDerivedBindingRegistration {
  readonly property: HostMotionBindingProperty;
  readonly source: HostMotionSharedValue;
}

const hostMotionDerivedBindingsByNode = new WeakMap<
  ElementNode,
  Map<string, HostMotionDerivedBindingRegistration>
>();

/** Register the final graph node feeding one native presentation property. */
export function registerHostMotionDerivedBinding(
  node: ElementNode,
  property: HostMotionBindingProperty,
  source: HostMotionSharedValue,
): () => void {
  if (!hostMotionDerivedNodeMetadata.has(source as object)) {
    throw new TypeError('[motion] derived binding source has no typed graph metadata');
  }
  let registrations = hostMotionDerivedBindingsByNode.get(node);
  if (!registrations) {
    registrations = new Map();
    hostMotionDerivedBindingsByNode.set(node, registrations);
  }
  const key = `${source.id}:${property}`;
  registrations.set(key, { property, source });
  return () => {
    const current = hostMotionDerivedBindingsByNode.get(node);
    current?.delete(key);
    if (current?.size === 0) hostMotionDerivedBindingsByNode.delete(node);
  };
}

const hostMotionStyleBindings = new WeakMap<object, readonly HostMotionDerivedBindingRegistration[]>();

/**
 * React carrier: ordinary enumerable style fields remain unchanged while the
 * original style object carries native graph edges out-of-band.
 */
export function createHostMotionStyleCarrier(
  style: Readonly<Record<string, unknown>>,
  bindings: readonly HostMotionDerivedBindingRegistration[],
): Readonly<Record<string, unknown>> {
  const carrier = { ...style };
  hostMotionStyleBindings.set(carrier, Object.freeze([...bindings]));
  return carrier;
}

/**
 * Native protocol presence plus explicit host consumption is the opt-in for
 * app-JS-free frame evaluation. A protocol transport alone is insufficient:
 * reduced hosts such as TUI may accept ordinary ops without consuming Motion
 * descriptors. LLP 0368 D6 keeps descriptor/command emission itself behind
 * the emitted-frame screen until the Phase 1 per-root authority lands.
 */
export function hasNativeMotionProtocolEnvironment(): boolean {
  const exactHost = (globalThis as typeof globalThis & {
    exact?: {
      dispatch?: unknown;
      dispatchWithDebugContext?: unknown;
      consumesMotionProtocol?: unknown;
    };
  }).exact;
  const hasProtocolTransport = typeof exactHost?.dispatch === 'function' ||
    typeof exactHost?.dispatchWithDebugContext === 'function';
  return hasProtocolTransport && exactHost?.consumesMotionProtocol === true;
}

export type HostMotionSharedValueUserIntent =
  | Readonly<{ kind: 'writeValue'; value: number }>
  | Readonly<{ kind: 'startDriver'; driver: MotionCommandDriver }>
  | Readonly<{ kind: 'cancelDriver' }>;

interface HostMotionBindingRegistration {
  property: HostMotionBindingProperty;
  source: HostMotionSharedValue;
  multiplier: number;
  offset: number;
}

const hostMotionBindingsByNode = new WeakMap<
  ElementNode,
  Map<string, HostMotionBindingRegistration>
>();

export interface HostMotionLayoutIslandBindingRegistration {
  readonly islandRoot: ElementNode;
  readonly closureClass: HostMotionLayoutIslandClosureClass;
  readonly property: HostMotionLayoutIslandProperty;
  readonly source: HostMotionSharedValue;
}

const hostMotionLayoutIslandBindingsByNode = new WeakMap<
  ElementNode,
  Map<string, HostMotionLayoutIslandBindingRegistration>
>();

function isElementDescendantOrSelf(node: ElementNode, ancestor: ElementNode): boolean {
  let cursor: BaseNode | null = node;
  while (cursor) {
    if (cursor === ancestor) return true;
    cursor = cursor.parent;
  }
  return false;
}

/**
 * Register one compiler-proven SharedValue -> layout property edge inside a
 * bounded LLP 0313 island. The general Motion descriptor table is the only
 * native production transport; callers do not issue island host operations.
 */
export function registerHostMotionLayoutIslandBinding(
  node: ElementNode,
  islandRoot: ElementNode,
  property: HostMotionLayoutIslandProperty,
  source: HostMotionSharedValue,
  closureClass: HostMotionLayoutIslandClosureClass = 'fixedEnvelope',
): () => void {
  if (closureClass !== 'fixedEnvelope' && closureClass !== 'closedAncestor') {
    throw new TypeError('[motion] layout-island closure class is invalid');
  }
  if (!Object.hasOwn(MOTION_LAYOUT_ISLAND_PROPERTY_CODE, property)) {
    throw new TypeError('[motion] layout-island property is invalid');
  }
  if (!isElementDescendantOrSelf(node, islandRoot)) {
    throw new TypeError('[motion] layout-island target must be inside its island root');
  }
  let registrations = hostMotionLayoutIslandBindingsByNode.get(node);
  if (!registrations) {
    registrations = new Map();
    hostMotionLayoutIslandBindingsByNode.set(node, registrations);
  }
  const key = `${islandRoot.id}:${property}`;
  const registration = { islandRoot, closureClass, property, source } as const;
  registrations.set(key, registration);
  scheduleMotionRegistryCommit(node);
  // The authoritative kernel tree must carry the value too: the island arena
  // refines BETWEEN commits, and when it is not running — lift rejected,
  // demoted, or a host whose motion lane is not live — a grow/basis track
  // would otherwise have no value at all and collapse. Deferred past the
  // mounting pass because a style op encoded mid-mount lands inside the
  // mount's own transaction.
  let disposed = false;
  const commitAuthoritativeValue = (value: number): void => {
    if (disposed || !Number.isFinite(value)) return;
    if ((node.style as Record<string, unknown>)[property] === value) return;
    (node.style as Record<string, unknown>)[property] = value;
    // Full-style wire op: protocol SetStyle has replace semantics, so a
    // narrow `{ [property]: value }` op would wipe the track's other set
    // fields kernel-side (flexBasis 0 reverting to auto turns a
    // proportional grow row into content-basis layout — ENG-22791 class).
    emitElementSetStyle(getEncoderForNode(node), node, { ...node.style });
    markLayoutDirtyForNode(node);
  };
  queueMicrotask(() => {
    commitAuthoritativeValue(registration.source.current());
  });
  // JS-side publishes (seed/action writes, terminal write-back adoption) are
  // commit edges: the arena refines BETWEEN commits, but the authoritative
  // kernel style must carry the committed value or the model layout snaps
  // back to the registration-time value on the next ordinary commit (a
  // dragged divider would visually revert the moment its command action
  // re-rendered). Per-frame worklet writes never reach the JS store, so this
  // subscription fires only at bounded edges.
  const unsubscribeCommitEdge = registration.source.subscribe?.((value: number) => {
    commitAuthoritativeValue(value);
  });
  return () => {
    disposed = true;
    unsubscribeCommitEdge?.();
    const current = hostMotionLayoutIslandBindingsByNode.get(node);
    if (current?.get(key) !== registration) return;
    current?.delete(key);
    if (current?.size === 0) hostMotionLayoutIslandBindingsByNode.delete(node);
    scheduleMotionRegistryCommit(node);
  };
}

/**
 * The prop an authoring tier sets on a container to mark it as a layout-island
 * root (Contract's `layoutIsland=true`; LLP 0417 §5). Sidecar-only: hosts
 * without an island arena ignore it.
 *
 * The constant and the resolution rule live in `motion-layout-island-shared.ts`
 * so this host and the lightweight web host share one implementation.
 */
export {
  HOST_MOTION_LAYOUT_ISLAND_ROOT_PROP,
} from './motion-layout-island-shared.js';

/**
 * Resolve the marked island root that owns a sink target.
 *
 * Authoring tiers know the island root as a view-tree ancestor, not as a
 * mounted node they hold a handle on, so registration resolves it from the
 * committed tree instead of threading a second element through every sink
 * call site.
 *
 * Resolution mirrors the compiler's static rule: strictly enclosing for an
 * extent property, enclosing-or-SELF for an interior one. Omitting `property`
 * keeps the strict reading, which is the safe default.
 */
export function resolveHostMotionLayoutIslandRoot(
  node: ElementNode,
  property?: HostMotionLayoutIslandProperty,
): ElementNode | null {
  return resolveMotionLayoutIslandRootNode(node, property);
}

/** Commit-collector/test projection of one target's island edges. */
export function getHostMotionLayoutIslandBindings(
  node: ElementNode,
): readonly HostMotionLayoutIslandBindingRegistration[] {
  return [...(hostMotionLayoutIslandBindingsByNode.get(node)?.values() ?? [])];
}

/**
 * The distinct SharedValue roots feeding one node's presentation-sink
 * bindings (direct and derived; derived nodes are walked through their
 * artifact captures — scalar captures are constants and carry no drivers).
 * The RFC 0368 drag projection uses this to hold its overlay through the
 * release springs: restore happens when none of these report a running
 * driver after the lease resolves.
 */
export function getHostMotionNodeDriverSources(
  node: ElementNode,
): readonly HostMotionSharedValue[] {
  const out = new Map<string, HostMotionSharedValue>();
  const visit = (source: HostMotionSharedValue, depth: number): void => {
    if (depth > 32) return;
    const metadata = hostMotionDerivedNodeMetadata.get(source as object);
    if (!metadata) {
      out.set(source.id, source);
      return;
    }
    const captures = Array.isArray(metadata.artifact.captures)
      ? metadata.artifact.captures
      : [];
    for (const capture of captures) {
      if (capture && typeof capture === 'object') {
        visit(capture as HostMotionSharedValue, depth + 1);
      }
    }
  };
  for (const binding of hostMotionBindingsByNode.get(node)?.values() ?? []) {
    visit(binding.source, 0);
  }
  for (const binding of hostMotionDerivedBindingsByNode.get(node)?.values() ?? []) {
    visit(binding.source, 0);
  }
  return [...out.values()];
}

/**
 * Register one compiler-proven direct SharedValue -> compositor property
 * edge. This remains the allocation-free primitive and the compatibility
 * path for pre-M6 artifacts; richer expressions use DerivedValue nodes.
 */
export function registerHostMotionBinding(
  node: ElementNode,
  property: HostMotionBindingProperty,
  source: HostMotionSharedValue,
  multiplier = 1,
  offset = 0,
): () => void {
  if (!Number.isFinite(multiplier) || !Number.isFinite(offset)) {
    throw new TypeError('[motion] native binding scale/offset must be finite');
  }
  let registrations = hostMotionBindingsByNode.get(node);
  if (!registrations) {
    registrations = new Map();
    hostMotionBindingsByNode.set(node, registrations);
  }
  const key = `${source.id}:${property}`;
  registrations.set(key, { property, source, multiplier, offset });
  return () => {
    const current = hostMotionBindingsByNode.get(node);
    current?.delete(key);
    if (current?.size === 0) hostMotionBindingsByNode.delete(node);
  };
}

export type HostMotionScrollAxis = 'x' | 'y';

export interface HostMotionWritableSharedValue extends HostMotionSharedValue {
  /** Synchronous UI/DOM-owned publication; Motion validates finite writes. */
  value: number;
}

export interface HostMotionScrollBindingRegistration {
  readonly axis: HostMotionScrollAxis;
  readonly source: HostMotionWritableSharedValue;
}

const hostMotionScrollBindingsByNode = new WeakMap<
  ElementNode,
  Map<string, HostMotionScrollBindingRegistration>
>();
const pendingMotionRegistryCommitRoots = new Set<RootNode>();

function scheduleMotionRegistryCommit(node: ElementNode): void {
  let parent = node.parent;
  while (parent && parent.kind !== NodeKind.Root) parent = parent.parent;
  if (!parent || parent.kind !== NodeKind.Root) return;
  const root = parent as RootNode;
  if (pendingMotionRegistryCommitRoots.has(root)) return;
  pendingMotionRegistryCommitRoots.add(root);
  queueMicrotask(() => {
    pendingMotionRegistryCommitRoots.delete(root);
    // A React layout effect registers after the host commit that attached the
    // ref. Emit the new sidecar in a descriptor-only follow-up commit. If the
    // root was destroyed/unregistered in the meantime, its node is detached.
    if (liveRoots.get(root.rootId) === root && node.parent !== null) commitBatch(root);
  });
}

/**
 * Imperative scroller access for the sortable drag session (auto-scroll and
 * cross-list hit testing). The active web host registers an adapter per
 * scroller-capable node; `rect()` is in viewport coordinates — the same basis
 * as `motion.measure` and gesture `absoluteX/Y` samples, while
 * `contentStart()` accounts for the host's border, padding, and scroll offset.
 * Native presenters do not register adapters in v1: the sortable session
 * degrades to the translation-only slot math there.
 */
export interface HostMotionSortableScrollHost {
  rect(): { x: number; y: number; width: number; height: number } | null;
  /** Item-content origin along the axis in viewport coordinates. */
  contentStart(axis: HostMotionScrollAxis): number | null;
  offset(axis: HostMotionScrollAxis): number;
  /** Clamped write; returns the delta actually applied. */
  scrollBy(axis: HostMotionScrollAxis, delta: number): number;
}

const hostMotionSortableScrollHostsByNode = new WeakMap<
  ElementNode,
  HostMotionSortableScrollHost
>();

export function registerHostMotionSortableScrollHost(
  node: ElementNode,
  host: HostMotionSortableScrollHost,
): () => void {
  hostMotionSortableScrollHostsByNode.set(node, host);
  return () => {
    if (hostMotionSortableScrollHostsByNode.get(node) === host) {
      hostMotionSortableScrollHostsByNode.delete(node);
    }
  };
}

export function resolveHostMotionSortableScrollHost(
  node: ElementNode,
): HostMotionSortableScrollHost | null {
  return hostMotionSortableScrollHostsByNode.get(node) ?? null;
}

/**
 * Associate a host-owned scroller with the SharedValue it publishes. Native
 * commit collection lowers this registration to ScrollBinding; the DOM host
 * writes it synchronously from the browser's scroll dispatch.
 */
export function registerHostMotionScrollBinding(
  node: ElementNode,
  source: HostMotionWritableSharedValue,
  axis: HostMotionScrollAxis = 'y',
): () => void {
  if (axis !== 'x' && axis !== 'y') {
    throw new TypeError('[motion] scroll binding axis must be x or y');
  }
  let registrations = hostMotionScrollBindingsByNode.get(node);
  if (!registrations) {
    registrations = new Map();
    hostMotionScrollBindingsByNode.set(node, registrations);
  }
  const key = `${source.id}:${axis}`;
  registrations.set(key, { axis, source });
  scheduleMotionRegistryCommit(node);
  return () => {
    const current = hostMotionScrollBindingsByNode.get(node);
    current?.delete(key);
    if (current?.size === 0) hostMotionScrollBindingsByNode.delete(node);
    scheduleMotionRegistryCommit(node);
  };
}

/** Commit-collector/test view of a node's typed scroll descriptor sources. */
export function getHostMotionScrollBindings(
  node: ElementNode,
): readonly HostMotionScrollBindingRegistration[] {
  return [...(hostMotionScrollBindingsByNode.get(node)?.values() ?? [])];
}

/**
 * Web/JS fallback publication. This intentionally happens before ordinary
 * `onScroll` delivery so dependent direct style sinks update in the same
 * browser event task. Native M7 performs the equivalent write in presenter
 * space on the display-link tick.
 */
export function publishHostMotionScrollOffset(
  node: ElementNode,
  x: number,
  y: number,
): boolean {
  if (!Number.isFinite(x) || !Number.isFinite(y)) {
    throw new TypeError('[motion] scroll offsets must be finite');
  }
  // Native presenters publish ScrollBinding values directly on their frame
  // tick. Replaying the same host event through the JS SharedValue setter
  // would enqueue a delayed SetMotionCommand back to that presenter.
  if (hasNativeMotionProtocolHost(getRootIdForNode(node))) return false;
  const registrations = hostMotionScrollBindingsByNode.get(node);
  if (!registrations || registrations.size === 0) return false;
  for (const { axis, source } of registrations.values()) {
    source.value = axis === 'x' ? x : y;
  }
  return true;
}

interface ContractPagerNativeDescriptor {
  bindingGeneration: number;
  centerRevision: number;
  turnToken: number;
  prevEnabled: boolean;
  nextEnabled: boolean;
  /** 0 never, 1 external, 2 always (LLP 0336 §4.1.1 animateCenter=). */
  centerAnimation?: number;
  /** 0 none, 1 prev, 2 next — direction that reached `centerRevision`. */
  centerDirection?: number;
}

const PAGER_ANIMATE_CENTER_BY_CODE = ['never', 'external', 'always'] as const;
const PAGER_CENTER_DIRECTION_BY_CODE = ['none', 'prev', 'next'] as const;

function contractPagerNativeDescriptor(id: string): ContractPagerNativeDescriptor | null {
  return (globalThis as typeof globalThis & {
    __exactGetContractPagerNativeDescriptor?: (pagerId: string) => ContractPagerNativeDescriptor | null;
  }).__exactGetContractPagerNativeDescriptor?.(id) ?? null;
}

function pagerClaimViewId(node: ElementNode, claim: string): number | null {
  if (claim.length === 0) return node.id;
  const matches: number[] = [];
  for (let current = node.parent; current && current.kind !== NodeKind.Root; current = current.parent) {
    const element = current as ElementNode;
    const props = element.originalProps ?? {};
    const testId = props.testId ?? props.testID ?? props['data-testid'];
    if (testId === claim) matches.push(element.id);
  }
  if (matches.length > 1) return null;
  return matches[0] ?? node.id;
}

function collectPagerBindingDescriptors(root: RootNode): PagerBindingDescriptor[] {
  const descriptors: PagerBindingDescriptor[] = [];
  const hasCell = (node: ElementNode, side: 'prev' | 'next'): boolean => {
    const visit = (candidate: ElementNode): boolean => {
      if (candidate.originalProps?.__exactPagerCell === side) return true;
      return candidate.children.some((child) => child.kind === NodeKind.Element && visit(child));
    };
    return visit(node);
  };
  const visit = (node: ElementNode): void => {
    const props = node.originalProps ?? {};
    const id = props.__exactPagerId;
    if (typeof id === 'string' && id.length > 0) {
      const runtime = contractPagerNativeDescriptor(id);
      const claim = typeof props.__exactPagerClaim === 'string'
        ? props.__exactPagerClaim
        : '';
      const claimViewId = pagerClaimViewId(node, claim);
      if (runtime && claimViewId !== null) {
        descriptors.push({
          pagerViewId: node.id,
          claimViewId,
          bindingGeneration: runtime.bindingGeneration >>> 0,
          centerRevision: runtime.centerRevision >>> 0,
          turnToken: runtime.turnToken >>> 0,
          axis: props.__exactPagerAxis === 'vertical' ? 'vertical' : 'horizontal',
          hasPrev: runtime.prevEnabled && hasCell(node, 'prev'),
          hasNext: runtime.nextEnabled && hasCell(node, 'next'),
          animateCenter: PAGER_ANIMATE_CENTER_BY_CODE[runtime.centerAnimation ?? 0] ?? 'never',
          centerDirection: PAGER_CENTER_DIRECTION_BY_CODE[runtime.centerDirection ?? 0] ?? 'none',
        });
      }
    }
    for (const child of node.children) {
      if (child.kind === NodeKind.Element) visit(child);
    }
  };
  for (const child of root.children) {
    if (child.kind === NodeKind.Element) visit(child);
  }
  return descriptors;
}

function encodePagerBindingSnapshot(
  encoder: ProtocolEncoder,
  root: RootNode,
  descriptors = collectPagerBindingDescriptors(root),
): void {
  const previous = committedPagerBindingsByRoot.get(root.rootId);
  const equal = previous !== undefined &&
    previous.length === descriptors.length &&
    previous.every((binding, index) => {
      const next = descriptors[index];
      return next !== undefined &&
        binding.pagerViewId === next.pagerViewId &&
        binding.claimViewId === next.claimViewId &&
        binding.bindingGeneration === next.bindingGeneration &&
        binding.centerRevision === next.centerRevision &&
        binding.turnToken === next.turnToken &&
        binding.axis === next.axis &&
        binding.hasPrev === next.hasPrev &&
        binding.hasNext === next.hasNext &&
        binding.animateCenter === next.animateCenter &&
        binding.centerDirection === next.centerDirection;
    });
  if (equal || (descriptors.length === 0 && previous === undefined)) return;
  encoder.setPagerBindings(root.id, descriptors);
  if (descriptors.length === 0) {
    committedPagerBindingsByRoot.delete(root.rootId);
  } else {
    committedPagerBindingsByRoot.set(
      root.rootId,
      descriptors.map((binding) => ({ ...binding })),
    );
  }
}

function motionDescriptorId(identity: string): bigint {
  return motionDescriptorIdFromStableIdentity(identity);
}

// Codes 0-6 are the LLP 0099 M2 layout; 7-9 append the LLP 0417 §4
// presentationPaint class. Appending keeps the descriptor byte layout
// (parameters are still [propertyCode, multiplier, offset]), but the enum
// append is `property-binding` layoutVersion 2 in
// tests/motion/record-classes.json: a host that only accepts codes 0-6
// must fail the schema-digest handshake up front instead of rejecting
// each snapshot with InvalidDescriptorShape.
const MOTION_BINDING_PROPERTY_CODE: Record<HostMotionBindingProperty, number> = {
  translateX: 0,
  translateY: 1,
  scale: 2,
  rotation: 3,
  opacity: 4,
  scaleX: 5,
  scaleY: 6,
  borderRadius: 7,
  shadowOpacity: 8,
  shadowRadius: 9,
};

const MOTION_LAYOUT_ISLAND_PROPERTY_CODE: Record<HostMotionLayoutIslandProperty, number> = {
  width: 0,
  height: 1,
  minWidth: 2,
  minHeight: 3,
  maxWidth: 4,
  maxHeight: 5,
  flexGrow: 6,
  flexShrink: 7,
  flexBasis: 8,
  rowGap: 9,
  columnGap: 10,
  aspectRatio: 11,
};

function isMotionCommandProducer(source: HostMotionSharedValue): boolean {
  const hasIntentSubscription = typeof source.subscribeUserIntent === 'function';
  const hasNativeAuthority = typeof source.acquireNativeDriverAuthority === 'function';
  if (hasIntentSubscription !== hasNativeAuthority) {
    throw new TypeError(
      `[motion] SharedValue ${source.id} must implement both command intent and native authority hooks`,
    );
  }
  return hasIntentSubscription;
}

interface CollectedMotionDescriptorRecords {
  readonly descriptors: MotionDescriptorRecord[];
  readonly sources: ReadonlyMap<string, HostMotionSharedValue>;
  readonly observabilityBindings: readonly HostMotionObservabilityBinding[];
  readonly workletArtifacts: MotionWorkletInstallArtifact[];
  readonly callbackRegistrations: MotionWorkletCallbackRegistration[];
}

interface HostMotionObservabilityBinding {
  readonly source: HostMotionSharedValue;
  readonly viewId: number;
  readonly property: string;
}

interface MotionDismissLayerClaim {
  readonly node: ElementNode;
  readonly rootId: string;
  readonly layerId: string;
  readonly parentId?: string;
  readonly modal: boolean;
  readonly portalOrder: number;
  readonly visualOrder: number;
  readonly mountSequence: number;
}

/**
 * Native hosts cannot invoke React closures to ask whether a dismiss layer is
 * topmost. Resolve the serializable ordering projection once, while building
 * the transaction-scoped Motion snapshot, and admit only one layer per stack.
 * A topmost layer without a swipe gesture intentionally blocks lower layers.
 */
function collectTopmostMotionDismissLayers(root: RootNode): ReadonlySet<ElementNode> {
  const claims: MotionDismissLayerClaim[] = [];
  // The reconciler root is the native stack authority. Framework adapters
  // may serialize different public root spellings (React DOM's `document`
  // fallback versus Contract's numeric root id), but nodes in this traversal
  // already belong to one exact RootNode. Grouping by an author/framework
  // hint would split one native dismiss stack and admit multiple winners.
  const canonicalRootId = String(root.rootId);
  const visit = (node: ElementNode): void => {
    const raw = node.originalProps.__exactMotionDismissLayerClaim;
    if (raw !== undefined && raw !== null) {
      if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
        throw new TypeError('[motion] dismiss layer claim must be an object');
      }
      const candidate = raw as Record<string, unknown>;
      const rootId = candidate.rootId;
      const layerId = candidate.layerId;
      const parentId = candidate.parentId;
      const portalOrder = candidate.portalOrder;
      const visualOrder = candidate.visualOrder;
      const mountSequence = candidate.mountSequence;
      if (
        candidate.schemaVersion !== 1 ||
        typeof rootId !== 'string' || rootId.length === 0 || rootId.length > 256 ||
        typeof layerId !== 'string' || layerId.length === 0 || layerId.length > 256 ||
        (parentId !== null && parentId !== undefined &&
          (typeof parentId !== 'string' || parentId.length === 0 || parentId.length > 256)) ||
        typeof candidate.modal !== 'boolean' ||
        typeof portalOrder !== 'number' || !Number.isFinite(portalOrder) ||
        typeof visualOrder !== 'number' || !Number.isFinite(visualOrder) ||
        typeof mountSequence !== 'number' || !Number.isSafeInteger(mountSequence) ||
        mountSequence <= 0
      ) {
        throw new TypeError('[motion] dismiss layer claim has invalid ordering metadata');
      }
      claims.push({
        node,
        rootId: canonicalRootId,
        layerId,
        ...(typeof parentId === 'string' ? { parentId } : {}),
        modal: candidate.modal,
        portalOrder,
        visualOrder,
        mountSequence,
      });
    }
    for (const child of node.children) {
      if (child.kind === NodeKind.Element) visit(child);
    }
  };
  for (const child of root.children) {
    if (child.kind === NodeKind.Element) visit(child);
  }

  const byIdentity = new Map<string, MotionDismissLayerClaim>();
  for (const claim of claims) {
    const identity = `${claim.rootId}\0${claim.layerId}`;
    if (byIdentity.has(identity)) {
      throw new TypeError(`[motion] duplicate dismiss layer identity ${claim.layerId}`);
    }
    byIdentity.set(identity, claim);
  }
  const mountIdentities = new Set<string>();
  for (const claim of claims) {
    const identity = `${claim.rootId}\0${claim.mountSequence}`;
    if (mountIdentities.has(identity)) {
      throw new TypeError(`[motion] duplicate dismiss layer mount sequence ${claim.mountSequence}`);
    }
    mountIdentities.add(identity);
  }
  for (const claim of claims) {
    const visited = new Set([claim.layerId]);
    let parentId = claim.parentId;
    while (parentId) {
      if (visited.has(parentId)) {
        throw new TypeError(`[motion] cyclic dismiss layer ancestry at ${claim.layerId}`);
      }
      visited.add(parentId);
      parentId = byIdentity.get(`${claim.rootId}\0${parentId}`)?.parentId;
    }
  }
  const isDescendant = (
    candidate: MotionDismissLayerClaim,
    ancestor: MotionDismissLayerClaim,
  ): boolean => {
    const visited = new Set<string>();
    let parentId = candidate.parentId;
    while (parentId) {
      if (parentId === ancestor.layerId) return true;
      if (visited.has(parentId)) {
        throw new TypeError(`[motion] cyclic dismiss layer ancestry at ${candidate.layerId}`);
      }
      visited.add(parentId);
      parentId = byIdentity.get(`${candidate.rootId}\0${parentId}`)?.parentId;
    }
    return false;
  };
  const compare = (left: MotionDismissLayerClaim, right: MotionDismissLayerClaim): number => {
    if (isDescendant(left, right)) return 1;
    if (isDescendant(right, left)) return -1;
    if (left.modal !== right.modal) return left.modal ? 1 : -1;
    if (left.portalOrder !== right.portalOrder) return left.portalOrder - right.portalOrder;
    if (left.visualOrder !== right.visualOrder) return left.visualOrder - right.visualOrder;
    return left.mountSequence - right.mountSequence;
  };
  const topmost = new Set<ElementNode>();
  const rootIds = new Set(claims.map((claim) => claim.rootId));
  for (const rootId of rootIds) {
    const ordered = claims.filter((claim) => claim.rootId === rootId).sort(compare);
    const winner = ordered.at(-1);
    if (winner) topmost.add(winner.node);
  }
  return topmost;
}

function collectMotionDescriptorRecords(
  root: RootNode,
  pagerBindings: readonly PagerBindingDescriptor[],
): CollectedMotionDescriptorRecords {
  const descriptors = new Map<bigint, MotionDescriptorRecord>();
  const sources = new Map<string, HostMotionSharedValue>();
  const observabilityBindings: HostMotionObservabilityBinding[] = [];
  const workletArtifacts: MotionWorkletInstallArtifact[] = [];
  const callbackRegistrations: MotionWorkletCallbackRegistration[] = [];
  const topmostDismissLayers = collectTopmostMotionDismissLayers(root);
  const derivedIdsByObject = new WeakMap<object, Map<string, bigint>>();
  const sharedSourcesByDerivedObject = new WeakMap<object, Set<HostMotionSharedValue>>();
  const loweringDerived = new Set<object>();
  const insert = (descriptor: MotionDescriptorRecord): void => {
    const existing = descriptors.get(descriptor.id);
    if (existing) {
      const equal = existing.generation === descriptor.generation &&
        existing.nodeId === descriptor.nodeId && existing.kind === descriptor.kind &&
        existing.dependencies.length === descriptor.dependencies.length &&
        existing.dependencies.every((value, index) => value === descriptor.dependencies[index]) &&
        existing.parameters.length === descriptor.parameters.length &&
        existing.parameters.every((value, index) => Object.is(value, descriptor.parameters[index]));
      if (!equal) throw new Error(`[motion] descriptor identity collision at ${descriptor.id}`);
      return;
    }
    descriptors.set(descriptor.id, descriptor);
  };
  const pushWorkletArtifact = (artifact: MotionWorkletInstallArtifact): void => {
    const existing = workletArtifacts.find((candidate) =>
      candidate.descriptorId === artifact.descriptorId && candidate.phase === artifact.phase);
    if (existing) {
      if (JSON.stringify(existing) !== JSON.stringify(artifact)) {
        throw new Error(
          `[motion] worklet artifact collision at ${artifact.descriptorId}/${artifact.phase}`,
        );
      }
      return;
    }
    workletArtifacts.push(artifact);
  };
  const ensureSharedValue = (source: HostMotionSharedValue): bigint => {
    const existingSource = sources.get(source.id);
    if (existingSource && existingSource !== source) {
      throw new Error(`[motion] SharedValue identity collision at ${source.id}`);
    }
    sources.set(source.id, source);
    const commandProducer = isMotionCommandProducer(source);
    const current = source.current();
    if (!Number.isFinite(current)) {
      throw new TypeError(`[motion] SharedValue ${source.id} produced a non-finite value`);
    }
    if (
      !Number.isInteger(source.generation) || source.generation <= 0 ||
      source.generation > 0xffff_ffff
    ) {
      throw new RangeError(`[motion] SharedValue ${source.id} has an invalid generation`);
    }
    const sourceId = motionDescriptorId(`shared:${source.id}`);
    if (!descriptors.has(sourceId)) {
      const committed = commandProducer
        ? committedMotionDescriptorsByRoot.get(root.rootId)?.find((descriptor) =>
            descriptor.id === sourceId &&
            descriptor.kind === MotionDescriptorKind.SharedValue &&
            descriptor.generation === source.generation,
          )
        : undefined;
      insert({
        id: sourceId,
        generation: source.generation,
        nodeId: 0,
        kind: MotionDescriptorKind.SharedValue,
        dependencies: [],
        // Once command ingress is attached, authored scalar changes ride
        // WriteValue and must not masquerade as structural graph snapshots.
        // Legacy/fake sources without the producer hooks keep the shipped
        // snapshot-update behavior for compatibility.
        parameters: [committed?.parameters[0] ?? current],
      });
    }
    return sourceId;
  };
  const ensureDerivedValue = (
    source: HostMotionSharedValue,
    sinkNodeId = 0,
    sinkProperty?: HostMotionBindingProperty,
  ): bigint => {
    const object = source as object;
    const metadata = hostMotionDerivedNodeMetadata.get(object);
    if (!metadata) throw new TypeError(`[motion] ${source.id} has no derived graph metadata`);
    const scope = metadata.role === 'sink'
      ? `${root.rootId}:${sinkNodeId}:${sinkProperty ?? 'unknown'}`
      : `${root.rootId}:component`;
    const cached = derivedIdsByObject.get(object)?.get(scope);
    if (cached !== undefined) return cached;
    if (loweringDerived.has(object)) {
      throw new TypeError(`[motion] derived graph ${metadata.identity} is cyclic`);
    }
    loweringDerived.add(object);
    try {
      const artifact = metadata.artifact;
      if (artifact.schemaVersion !== 1 || artifact.installFormat !== 'source-utf8') {
        throw new TypeError(`[motion] ${metadata.identity} has an unsupported worklet artifact schema`);
      }
      if (
        !Array.isArray(artifact.captureNames) || !Array.isArray(artifact.captureKinds) ||
        !Array.isArray(artifact.captures) ||
        artifact.captureNames.length !== artifact.captureKinds.length ||
        artifact.captureNames.length !== artifact.captures.length
      ) {
        throw new TypeError(`[motion] ${metadata.identity} has inconsistent capture descriptors`);
      }
      if (
        !Array.isArray(artifact.inputSlots) || artifact.inputSlots.length !== 0 ||
        !Array.isArray(artifact.outputSlots) || artifact.outputSlots.length !== 1 ||
        artifact.outputSlots[0] !== 'return.value'
      ) {
        throw new TypeError(
          `[motion] ${metadata.identity} derive artifact must have no inputs and output return.value`,
        );
      }
      const names = artifact.captureNames as unknown[];
      if (
        names.some((name) => typeof name !== 'string' || name.length === 0) ||
        new Set(names).size !== names.length
      ) {
        throw new TypeError(`[motion] ${metadata.identity} has invalid capture names`);
      }
      const dependencies: bigint[] = [];
      const sharedSources = new Set<HostMotionSharedValue>();
      const captureIdentity: string[] = [];
      const captures = (artifact.captures as unknown[]).map((capture, index) => {
        const name = names[index] as string;
        const kind = (artifact.captureKinds as unknown[])[index];
        if (kind === 'scalar') {
          if (typeof capture !== 'boolean' &&
              (typeof capture !== 'number' || !Number.isFinite(capture))) {
            throw new TypeError(`[motion] ${metadata.identity} scalar capture ${name} is invalid`);
          }
          captureIdentity.push(
            `scalar:${name}:${typeof capture === 'boolean' ? (capture ? 1 : 0) : capture}`,
          );
          return capture;
        }
        if (kind !== 'sharedValue' || !capture || typeof capture !== 'object') {
          throw new TypeError(`[motion] ${metadata.identity} capture ${name} is not graph-readable`);
        }
        const candidate = capture as HostMotionSharedValue;
        if (
          typeof candidate.id !== 'string' || candidate.id.length === 0 ||
          !Number.isInteger(candidate.generation) || candidate.generation <= 0 ||
          typeof candidate.current !== 'function'
        ) {
          throw new TypeError(`[motion] ${metadata.identity} capture ${name} has an invalid value handle`);
        }
        const dependencyId = hostMotionDerivedNodeMetadata.has(capture)
          ? ensureDerivedValue(candidate)
          : ensureSharedValue(candidate);
        if (hostMotionDerivedNodeMetadata.has(capture)) {
          for (const dependency of sharedSourcesByDerivedObject.get(capture) ?? []) {
            sharedSources.add(dependency);
          }
        } else {
          sharedSources.add(candidate);
        }
        dependencies.push(dependencyId);
        captureIdentity.push(`descriptor:${name}:${dependencyId}:${candidate.generation}`);
        if (!hostMotionDerivedNodeMetadata.has(capture)) return capture;
        return Object.freeze({
          id: candidate.id,
          generation: candidate.generation,
          current: () => candidate.current(),
          __exactMotionDescriptorId: dependencyId.toString(),
        });
      });
      const compilerId = typeof artifact.compilerId === 'string' ? artifact.compilerId : '';
      const descriptorId = motionDescriptorId(
        `derived:${scope}:${metadata.identity}:${compilerId}:${captureIdentity.join('|')}`,
      );
      let byScope = derivedIdsByObject.get(object);
      if (!byScope) {
        byScope = new Map();
        derivedIdsByObject.set(object, byScope);
      }
      byScope.set(scope, descriptorId);
      sharedSourcesByDerivedObject.set(object, sharedSources);
      insert({
        id: descriptorId,
        generation: metadata.generation,
        nodeId: metadata.role === 'sink' ? sinkNodeId : 0,
        kind: MotionDescriptorKind.DerivedValue,
        dependencies,
        parameters: [],
      });
      const lowered = lowerMotionDerivedWorkletArtifact({
        authoredId: metadata.identity,
        descriptorId,
        nodeId: metadata.role === 'sink' ? sinkNodeId : 0,
        generation: metadata.generation,
        artifact: Object.freeze({ ...artifact, captures: Object.freeze(captures) }),
      });
      for (const [sourceId, capturedSource] of lowered.sharedValueCaptures) {
        const nativeSourceId = ensureSharedValue(capturedSource as HostMotionSharedValue);
        if (nativeSourceId !== motionDescriptorId(`shared:${sourceId}`)) {
          throw new Error(`[motion] derive capture ${sourceId} resolved to the wrong descriptor`);
        }
      }
      pushWorkletArtifact(lowered.artifact);
      callbackRegistrations.push(...lowered.callbackRegistrations);
      return descriptorId;
    } finally {
      loweringDerived.delete(object);
    }
  };
  const styleBindings = (style: unknown): HostMotionDerivedBindingRegistration[] => {
    if (Array.isArray(style)) return style.flatMap(styleBindings);
    if (!style || typeof style !== 'object') return [];
    return [...(hostMotionStyleBindings.get(style) ?? [])];
  };
  const visit = (node: ElementNode): void => {
    const gesture = node.originalProps.__exactMotionGesture;
    const dismissLayerClaim = node.originalProps.__exactMotionDismissLayerClaim;
    if (
      gesture !== undefined && gesture !== null &&
      (dismissLayerClaim === undefined || dismissLayerClaim === null ||
        topmostDismissLayers.has(node))
    ) {
      const ownerTestId = typeof node.originalProps.testID === 'string'
        ? node.originalProps.testID
        : typeof node.originalProps.testId === 'string'
          ? node.originalProps.testId
          : undefined;
      const lowered = lowerMotionGestureSidecarRecords(
        root.rootId,
        node.id,
        gesture,
        ownerTestId,
      );
      for (const [sourceId, source] of lowered.sharedValueCaptures) {
        const nativeSourceId = ensureSharedValue(source as HostMotionSharedValue);
        const expectedSourceId = motionDescriptorId(`shared:${sourceId}`);
        if (nativeSourceId !== expectedSourceId) {
          throw new Error(`[motion] worklet capture ${sourceId} resolved to the wrong descriptor`);
        }
      }
      lowered.artifacts.forEach(pushWorkletArtifact);
      callbackRegistrations.push(...lowered.callbackRegistrations);
      for (const descriptor of lowered.descriptors) {
        insert(descriptor);
      }
    }
    const dragPresentation = node.originalProps.__exactMotionDragPresentation as
      | { claim?: unknown; placeholder?: unknown }
      | undefined;
    if (dragPresentation && typeof dragPresentation === 'object') {
      // RFC 0368: presentation-layer claim rides the descriptor sidecar as
      // kind 15 — parameters = [placeholder] (0 hidden, 1 ghost, 2 none).
      const placeholderCode = dragPresentation.placeholder === 'ghost'
        ? 1
        : dragPresentation.placeholder === 'none'
          ? 2
          : 0;
      insert({
        id: motionDescriptorId(`drag-presentation:${root.rootId}:${node.id}`),
        generation: 1,
        nodeId: node.id,
        kind: MotionDescriptorKind.DragPresentation,
        dependencies: [],
        parameters: [placeholderCode],
      });
    }
    for (const binding of hostMotionBindingsByNode.get(node)?.values() ?? []) {
      const sourceId = ensureSharedValue(binding.source);
      observabilityBindings.push({
        source: binding.source,
        viewId: node.id,
        property: binding.property,
      });
      insert({
        id: motionDescriptorId(
          `binding:${root.rootId}:${node.id}:${binding.source.id}:${binding.property}`,
        ),
        generation: binding.source.generation,
        nodeId: node.id,
        kind: MotionDescriptorKind.PropertyBinding,
        dependencies: [sourceId],
        parameters: [
          MOTION_BINDING_PROPERTY_CODE[binding.property],
          binding.multiplier,
          binding.offset,
        ],
      });
    }
    for (const binding of hostMotionLayoutIslandBindingsByNode.get(node)?.values() ?? []) {
      if (!isElementDescendantOrSelf(node, binding.islandRoot)) {
        throw new TypeError(
          `[motion] layout-island target ${node.id} left island ${binding.islandRoot.id}`,
        );
      }
      const sourceId = ensureSharedValue(binding.source);
      observabilityBindings.push({
        source: binding.source,
        viewId: node.id,
        property: `layout.${binding.property}`,
      });
      insert({
        id: motionDescriptorId(
          `layout-island:${root.rootId}:${binding.islandRoot.id}:${node.id}:` +
          `${binding.source.id}:${binding.property}`,
        ),
        generation: binding.source.generation,
        nodeId: node.id,
        kind: MotionDescriptorKind.LayoutIslandBinding,
        dependencies: [sourceId],
        parameters: [
          binding.islandRoot.id,
          binding.closureClass === 'closedAncestor' ? 1 : 0,
          MOTION_LAYOUT_ISLAND_PROPERTY_CODE[binding.property],
        ],
      });
    }
    const derivedBindings = [
      ...(hostMotionDerivedBindingsByNode.get(node)?.values() ?? []),
      ...styleBindings(node.originalProps.style),
    ];
    for (const binding of derivedBindings) {
      const sourceId = ensureDerivedValue(binding.source, node.id, binding.property);
      for (const source of sharedSourcesByDerivedObject.get(binding.source as object) ?? []) {
        observabilityBindings.push({
          source,
          viewId: node.id,
          property: binding.property,
        });
      }
      insert({
        id: motionDescriptorId(
          `binding:${root.rootId}:${node.id}:${sourceId}:${binding.property}`,
        ),
        generation: binding.source.generation,
        nodeId: node.id,
        kind: MotionDescriptorKind.PropertyBinding,
        dependencies: [sourceId],
        parameters: [MOTION_BINDING_PROPERTY_CODE[binding.property], 1, 0],
      });
    }
    for (const binding of hostMotionScrollBindingsByNode.get(node)?.values() ?? []) {
      const sourceId = ensureSharedValue(binding.source);
      insert({
        id: motionDescriptorId(
          `scroll:${root.rootId}:${node.id}:${binding.source.id}:${binding.axis}`,
        ),
        generation: binding.source.generation,
        nodeId: node.id,
        kind: MotionDescriptorKind.ScrollBinding,
        dependencies: [sourceId],
        parameters: [binding.axis === 'y' ? 1 : 0],
      });
    }
    for (const child of node.children) {
      if (child.kind === NodeKind.Element) visit(child);
    }
  };
  for (const child of root.children) {
    if (child.kind === NodeKind.Element) visit(child);
  }

  // LLP 0099 M2 absorbs the shipped 0336 descriptor into the general graph.
  // The legacy opcode remains in the same frame as a compatibility projection
  // until every host consumes this record directly.
  for (const pager of pagerBindings) {
    insert({
      id: motionDescriptorId(`pager:${root.rootId}:${pager.pagerViewId}`),
      generation: Math.max(1, pager.bindingGeneration >>> 0),
      nodeId: pager.pagerViewId,
      kind: MotionDescriptorKind.Pager,
      dependencies: [],
      parameters: [
        pager.claimViewId,
        pager.centerRevision,
        pager.turnToken,
        pager.axis === 'vertical' ? 1 : 0,
        pager.hasPrev ? 1 : 0,
        pager.hasNext ? 1 : 0,
        PAGER_ANIMATE_CENTER_BY_CODE.indexOf(pager.animateCenter ?? 'never'),
        PAGER_CENTER_DIRECTION_BY_CODE.indexOf(pager.centerDirection ?? 'none'),
      ],
    });
  }
  return {
    descriptors: [...descriptors.values()].sort((left, right) =>
      left.id < right.id ? -1 : left.id > right.id ? 1 : 0,
    ),
    sources,
    observabilityBindings,
    workletArtifacts: workletArtifacts.sort((left, right) => {
      const leftDescriptor = BigInt(left.descriptorId);
      const rightDescriptor = BigInt(right.descriptorId);
      if (leftDescriptor !== rightDescriptor) return leftDescriptor < rightDescriptor ? -1 : 1;
      return left.phase.localeCompare(right.phase);
    }),
    callbackRegistrations,
  };
}

function motionDescriptorsEqual(
  left: readonly MotionDescriptorRecord[],
  right: readonly MotionDescriptorRecord[],
): boolean {
  return left.length === right.length && left.every((descriptor, index) => {
    const next = right[index];
    return next !== undefined &&
      descriptor.id === next.id &&
      descriptor.generation === next.generation &&
      descriptor.nodeId === next.nodeId &&
      descriptor.kind === next.kind &&
      descriptor.dependencies.length === next.dependencies.length &&
      descriptor.dependencies.every((dependency, dependencyIndex) =>
        dependency === next.dependencies[dependencyIndex],
      ) &&
      descriptor.parameters.length === next.parameters.length &&
      descriptor.parameters.every((parameter, parameterIndex) =>
        Object.is(parameter, next.parameters[parameterIndex]),
      );
  });
}

function motionWorkletArtifactsEqual(
  left: readonly MotionWorkletInstallArtifact[],
  right: readonly MotionWorkletInstallArtifact[],
): boolean {
  // Artifact records are compiler-canonical, JSON-safe, and already sorted.
  // Comparing their wire representation also guards every future schema field
  // from accidentally being omitted from the commit-change decision.
  return left.length === right.length && JSON.stringify(left) === JSON.stringify(right);
}

type ExactRunOnJSDispatcher = (
  callbackIdentity: number,
  metadata: unknown,
  ...arguments_: number[]
) => unknown;

let installedMotionRunOnJSDispatcher: ExactRunOnJSDispatcher | null = null;
let priorMotionRunOnJSDispatcher: ExactRunOnJSDispatcher | undefined;

const MOTION_RUN_ON_JS_U64_MAX = (1n << 64n) - 1n;

function canonicalMotionRunOnJSU64(value: unknown): bigint | null {
  if (typeof value !== 'string' || !/^[1-9][0-9]{0,19}$/.test(value)) return null;
  const parsed = BigInt(value);
  return parsed <= MOTION_RUN_ON_JS_U64_MAX ? parsed : null;
}

function motionRunOnJSSourceKey(
  rootId: number,
  registration: MotionWorkletCallbackRegistration,
): string {
  return `${rootId}\0${registration.sourceIdentity}\0${registration.generation}`;
}

function ensureMotionRunOnJSDispatcher(): void {
  if (installedMotionRunOnJSDispatcher) return;
  const globals = globalThis as typeof globalThis & {
    __exactRunOnJS?: ExactRunOnJSDispatcher;
  };
  priorMotionRunOnJSDispatcher = typeof globals.__exactRunOnJS === 'function'
    ? globals.__exactRunOnJS
    : undefined;
  const dispatcher: ExactRunOnJSDispatcher = (identity, metadata, ...arguments_) => {
    const installed = motionWorkletCallbackRegistrations.get(identity);
    if (!installed) {
      try {
        return priorMotionRunOnJSDispatcher?.(identity, metadata, ...arguments_);
      } catch (error) {
        // The native drain invokes one global dispatcher for an immutable batch.
        // Never let one compatibility callback abort delivery of later records.
        // eslint-disable-next-line no-console
        console.error(`[ExactRenderer] runOnJS callback ${identity} threw:`, error);
        return undefined;
      }
    }
    const { rootId, registration } = installed;
    if (!metadata || typeof metadata !== 'object' || Array.isArray(metadata)) return undefined;
    const record = metadata as Record<string, unknown>;
    const sourceIdentity = canonicalMotionRunOnJSU64(record.sourceIdentity);
    const sourceSequence = canonicalMotionRunOnJSU64(record.sourceSequence);
    const generation = canonicalMotionRunOnJSU64(record.generation);
    if (
      sourceIdentity === null || sourceSequence === null || generation === null ||
      record.sourceIdentity !== registration.sourceIdentity ||
      generation !== BigInt(registration.generation)
    ) {
      return undefined;
    }
    if (arguments_.length !== registration.payloadKeys.length) {
      return undefined;
    }
    const payload: Record<string, number> = {};
    for (let index = 0; index < registration.payloadKeys.length; index += 1) {
      const value = arguments_[index];
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        return undefined;
      }
      payload[registration.payloadKeys[index]!] = value;
    }
    const sourceKey = motionRunOnJSSourceKey(rootId, registration);
    const previousSequence = motionRunOnJSLastSourceSequence.get(sourceKey);
    if (previousSequence !== undefined && sourceSequence <= previousSequence) {
      // ENG-25119: a replayed/stale source record is a dropped best-effort
      // dispatch — make it agent-observable instead of a silent undefined.
      try {
        recordGestureTraceEvent({
          rootId,
          phase: 'terminal-scheduling',
          status: 'dropped',
          reason: 'stale-source-sequence',
          detail: {
            bridge: 'run-on-js-native',
            bestEffort: true,
            sourceIdentity: registration.sourceIdentity,
          },
          generations: {
            sourceSequence: sourceSequence.toString(),
            lastAcceptedSequence: previousSequence.toString(),
          },
        });
      } catch {
        // Trace facts are never allowed to break the bridge.
      }
      return undefined;
    }
    // Consume the record before invoking user code. A callback throw must not
    // make the same source record replayable on a later native drain.
    motionRunOnJSLastSourceSequence.set(sourceKey, sourceSequence);
    try {
      recordGestureTraceEvent({
        rootId,
        phase: 'terminal-scheduling',
        status: 'ok',
        reason: 'invoked',
        detail: {
          bridge: 'run-on-js-native',
          bestEffort: true,
          sourceIdentity: registration.sourceIdentity,
        },
        generations: { sourceSequence: sourceSequence.toString() },
      });
    } catch {
      // Trace facts are never allowed to break the bridge.
    }
    try {
      return registration.callback(payload);
    } catch (error) {
      // ex_hermes_dispatch_worklet_calls stops a batch when its dispatcher
      // throws, so callback isolation belongs at this app-runtime boundary.
      // eslint-disable-next-line no-console
      console.error(`[ExactRenderer] Motion runOnJS callback ${identity} threw:`, error);
      return undefined;
    }
  };
  installedMotionRunOnJSDispatcher = dispatcher;
  globals.__exactRunOnJS = dispatcher;
}

function maybeRemoveMotionRunOnJSDispatcher(): void {
  if (!installedMotionRunOnJSDispatcher || motionWorkletCallbackRegistrations.size > 0) return;
  const globals = globalThis as typeof globalThis & {
    __exactRunOnJS?: ExactRunOnJSDispatcher;
  };
  if (globals.__exactRunOnJS === installedMotionRunOnJSDispatcher) {
    if (priorMotionRunOnJSDispatcher) {
      globals.__exactRunOnJS = priorMotionRunOnJSDispatcher;
    } else {
      delete globals.__exactRunOnJS;
    }
  }
  installedMotionRunOnJSDispatcher = null;
  priorMotionRunOnJSDispatcher = undefined;
}

function prepareMotionWorkletCallbackRegistrationReconciliation(
  rootId: number,
  registrations: readonly MotionWorkletCallbackRegistration[],
): () => void {
  const desired = new Map<number, MotionWorkletCallbackRegistration>();
  for (const registration of registrations) {
    const duplicate = desired.get(registration.identity);
    if (duplicate && (
      duplicate.callback !== registration.callback ||
      duplicate.action !== registration.action ||
      duplicate.payloadKeys.join('\0') !== registration.payloadKeys.join('\0') ||
      duplicate.sourceIdentity !== registration.sourceIdentity ||
      duplicate.generation !== registration.generation
    )) {
      throw new Error(
        `[motion] runOnJS callback identity ${registration.identity} collides within root ${rootId}`,
      );
    }
    desired.set(registration.identity, registration);
    const claimed = motionWorkletCallbackRegistrations.get(registration.identity);
    if (claimed && claimed.rootId !== rootId) {
      throw new Error(
        `[motion] runOnJS callback identity ${registration.identity} is already live in root ` +
        `${claimed.rootId}`,
      );
    }
  }

  const previous = motionWorkletCallbackRegistrationsByRoot.get(rootId);
  const previousSourceKeys = new Set(
    [...(previous?.values() ?? [])].map((registration) =>
      motionRunOnJSSourceKey(rootId, registration)),
  );
  const desiredSourceKeys = new Set(
    [...desired.values()].map((registration) =>
      motionRunOnJSSourceKey(rootId, registration)),
  );
  return () => {
    if (previous) {
      for (const identity of previous.keys()) {
        const claimed = motionWorkletCallbackRegistrations.get(identity);
        if (claimed?.rootId === rootId) motionWorkletCallbackRegistrations.delete(identity);
      }
    }
    for (const sourceKey of previousSourceKeys) {
      if (!desiredSourceKeys.has(sourceKey)) motionRunOnJSLastSourceSequence.delete(sourceKey);
    }
    if (desired.size === 0) {
      motionWorkletCallbackRegistrationsByRoot.delete(rootId);
    } else {
      motionWorkletCallbackRegistrationsByRoot.set(rootId, desired);
      for (const [identity, registration] of desired) {
        motionWorkletCallbackRegistrations.set(identity, { rootId, registration });
      }
      ensureMotionRunOnJSDispatcher();
    }
    maybeRemoveMotionRunOnJSDispatcher();
  };
}

function prepareMotionWorkletInstallPlaneDispatch(
  plane: MotionWorkletInstallPlane,
): (() => void) | undefined {
  // Empty planes need no second transport leg: native reconcile tears down a
  // predecessor registry transaction synchronously. Any non-empty compiler
  // plane is required capability, so absence is a commit-time failure rather
  // than a deferred retry that can eventually disappear.
  if (
    plane.schemaVersion !== MOTION_WORKLET_INSTALL_PLANE_SCHEMA_VERSION ||
    plane.schemaDigest !== MOTION_WORKLET_INSTALL_PLANE_SCHEMA_DIGEST
  ) {
    throw new Error('[motion] refusing a mixed-version worklet install plane');
  }
  if (plane.artifacts.length > MOTION_WORKLET_INSTALL_PLANE_BOUNDS.maximumArtifactsPerPlane) {
    throw new RangeError('[motion] worklet install plane exceeds the generated artifact bound');
  }
  const callbackIdentities = new Set<string>();
  for (const artifact of plane.artifacts) {
    if (!callbackIdentities.add(artifact.callbackIdentity)) {
      throw new Error(`[motion] duplicate worklet callback identity ${artifact.callbackIdentity}`);
    }
  }
  if (plane.artifacts.length === 0) return undefined;
  // Diagnostic Apple runtimes intentionally install the generic async bridge.
  // Some Phase-0 Release hosts also retain a provisional typed capability
  // object, but it is not the transport that owns this runtime's Motion join.
  // Armed runtimes expose no generic bridge, so they continue through the
  // typed CapSec ingress below.
  const bridge = diagnosticHostCallAsyncBridge() ?? hostCallAsyncBridge();
  if (!bridge) {
    throw new Error(
      `[motion] root ${plane.rootId} cannot commit worklet descriptors before `
      + 'the async artifact-install transport is available',
    );
  }
  const encodedPlane = JSON.stringify(plane);
  if (
    new TextEncoder().encode(encodedPlane).byteLength >
      MOTION_WORKLET_INSTALL_PLANE_BOUNDS.maximumPlaneUtf8Bytes
  ) {
    throw new RangeError('[motion] worklet install plane exceeds the generated UTF-8 byte bound');
  }
  // All validation and capability admission above stay synchronous so a bad
  // artifact plane can reject the commit before any binary bytes are staged.
  // The returned closure is invoked only after that exact commit's protocol
  // flush succeeds; merely preparing a transaction cannot leak an install.
  return () => {
    const install = Promise.resolve().then(
      () => bridge('worklet.syncMotionArtifacts', encodedPlane),
    );
    let bridgeSettled = false;
    let deadlineExpired = false;
    const invalidateIfCurrent = (
      error: unknown,
      confirmedBridgeRejection: boolean,
    ): void => {
      const committed = committedMotionDescriptorTransactionsByRoot.get(plane.rootId);
      if (
        committed?.epoch !== plane.transaction.epoch ||
        committed.motionSeq.toString(10) !== plane.transaction.motionSeq ||
        committed.rootInstance !== plane.transaction.rootInstance
      ) {
        // A newer descriptor transaction owns this root. A late rejection from
        // the predecessor must not delete its fingerprints, callbacks, or
        // SharedValue authority.
        return;
      }
      if (confirmedBridgeRejection) {
        // A rejected bridge promise is native's terminal acknowledgement that
        // this exact graph was discarded. Fence app callbacks before releasing
        // source subscriptions/authority so neither plane can target the absent
        // graph. The exact-transaction check above protects a successor root
        // transaction from a predecessor's late rejection.
        prepareMotionWorkletCallbackRegistrationReconciliation(plane.rootId, [])();
        releaseMotionSourceMembershipsForRoot(plane.rootId);
        committedMotionDescriptorTransactionsByRoot.delete(plane.rootId);
      }
      // Forget content fingerprints so a later authored commit emits a fresh
      // transaction. An app-side deadline is only an uncertain liveness signal:
      // retain its exact transaction marker and ownership quarantine so a late
      // native rejection can still retire A, while a committed B fences it.
      committedMotionDescriptorsByRoot.delete(plane.rootId);
      committedMotionWorkletArtifactsByRoot.delete(plane.rootId);
      // eslint-disable-next-line no-console
      console.error(
        `[ExactRenderer] Motion worklet transaction rejected for root ${plane.rootId}:`,
        error,
      );
    };
    const deadlineMs = motionWorkletInstallDeadlineMs;
    const deadline = setTimeout(() => {
      pendingMotionWorkletInstallDeadlineTimers.delete(deadline);
      if (bridgeSettled || deadlineExpired) return;
      deadlineExpired = true;
      invalidateIfCurrent(new Error(
        `artifact install did not settle before the ${deadlineMs}ms deadline`,
      ), false);
    }, deadlineMs);
    pendingMotionWorkletInstallDeadlineTimers.add(deadline);
    void install.then(
      (status: unknown) => {
        if (bridgeSettled) return;
        bridgeSettled = true;
        try {
          if (!status || typeof status !== 'object' || Array.isArray(status)) {
            throw new TypeError('artifact install returned a non-object terminal status');
          }
          const terminal = status as {
            state?: unknown;
            rootId?: unknown;
            artifactCount?: unknown;
            pendingSharedCaptures?: unknown;
          };
          if (terminal.state !== 'installed' && terminal.state !== 'torn-down') {
            throw new Error(
              `artifact install returned non-terminal state ${String(terminal.state)}`,
            );
          }
          if (terminal.rootId !== plane.rootId) {
            throw new Error(
              `artifact install terminal named root ${String(terminal.rootId)}, expected ${plane.rootId}`,
            );
          }
          if (terminal.pendingSharedCaptures !== 0) {
            throw new Error('artifact install terminal retained unresolved SharedValue captures');
          }
          const expectedArtifactCount = terminal.state === 'installed' ? plane.artifacts.length : 0;
          if (
            terminal.artifactCount !== expectedArtifactCount ||
            (terminal.state === 'torn-down' && plane.artifacts.length !== 0)
          ) {
            throw new Error(
              `artifact install terminal reported ${String(terminal.artifactCount)} artifacts, ` +
              `expected ${expectedArtifactCount}`,
            );
          }
          // Arming observability (issues/20260728-native-motion-arming-boot-race):
          // silence used to be indistinguishable from armed — the rejection
          // path logs, so the accepted terminal must too.
          // eslint-disable-next-line no-console
          console.info(
            `[ExactRenderer] Motion worklet plane ${String(terminal.state)} for root ${plane.rootId}: ` +
            `${plane.artifacts.length} artifact(s), epoch ${plane.transaction.epoch}, seq ${plane.transaction.motionSeq}`,
          );
        } catch (error) {
          clearTimeout(deadline);
          pendingMotionWorkletInstallDeadlineTimers.delete(deadline);
          // A fulfilled but malformed/non-terminal response is a transport
          // contract violation, not native confirmation that the graph was
          // discarded. Invalidate for retry but keep ownership quarantined.
          invalidateIfCurrent(error, false);
          return;
        }
        clearTimeout(deadline);
        pendingMotionWorkletInstallDeadlineTimers.delete(deadline);
      },
      (error: unknown) => {
        if (bridgeSettled) return;
        bridgeSettled = true;
        clearTimeout(deadline);
        pendingMotionWorkletInstallDeadlineTimers.delete(deadline);
        invalidateIfCurrent(error, true);
      },
    );
  };
}

/** Test-only deadline override; resetHostOpsState restores the production value. */
export function _setMotionWorkletInstallDeadlineForTests(milliseconds: number): void {
  if (!Number.isSafeInteger(milliseconds) || milliseconds <= 0) {
    throw new RangeError('[motion] install deadline must be a positive integer');
  }
  motionWorkletInstallDeadlineMs = milliseconds;
}

function hasNativeMotionProtocolHost(rootId: number): boolean {
  if (protocolSuppressedRoots.has(rootId)) return false;
  const exactHost = (globalThis as typeof globalThis & {
    exact?: {
      dispatch?: unknown;
      dispatchWithDebugContext?: unknown;
    };
  }).exact;
  return typeof exactHost?.dispatch === 'function' ||
    typeof exactHost?.dispatchWithDebugContext === 'function';
}

function motionDriverTarget(driver: MotionCommandDriver): number | undefined {
  switch (driver.kind) {
    case 'spring':
    case 'timing':
      return driver.target;
    case 'decay':
      return undefined;
    case 'sequence':
      return driver.drivers.length === 0
        ? undefined
        : motionDriverTarget(driver.drivers[driver.drivers.length - 1]!);
    case 'repeat':
      return motionDriverTarget(driver.driver);
  }
}

function publishMotionDriverObservation(
  membership: HostMotionObservabilityMembership,
  target: HostMotionObservabilityTarget,
  event: HostMotionDriverLifecycleEvent,
  state: HostMotionDriverLifecycleEvent['state'] = event.state,
  reason: string | undefined = event.reason,
): void {
  try {
    publishMotionAnimationState({
      rootId: membership.rootId,
      viewId: target.viewId,
      animationId: target.animationId,
      property: target.property,
      driver: event.driver.kind,
      state,
      generation: event.generation,
      ...(motionDriverTarget(event.driver) === undefined
        ? {}
        : { target: motionDriverTarget(event.driver)! }),
      ...(reason ? { reason } : {}),
      updatedAt: event.updatedAt,
    });
  } catch {
    // Driver execution is authoritative; the agent mirror is best-effort.
  }
}

function releaseMotionObservabilityMembership(
  membership: HostMotionObservabilityMembership,
  reason: string,
): void {
  if (membership.active) {
    const stale = { ...membership.active, updatedAt: Date.now() };
    for (const target of membership.targets.values()) {
      publishMotionDriverObservation(membership, target, stale, 'stale', reason);
    }
  }
  try {
    membership.unsubscribe();
  } catch (error) {
    // External lifecycle hooks cannot make an already-authoritative root
    // commit appear to have failed.
    // eslint-disable-next-line no-console
    console.error(
      `[ExactRenderer] Motion observability cleanup failed for root ${membership.rootId}:`,
      error,
    );
  }
}

function reconcileMotionObservabilityMemberships(
  rootId: number,
  bindings: readonly HostMotionObservabilityBinding[],
): void {
  const grouped = new Map<
    string,
    { source: HostMotionSharedValue; bindings: HostMotionObservabilityBinding[] }
  >();
  if (!hasNativeMotionProtocolHost(rootId)) {
    for (const binding of bindings) {
      const subscribe = binding.source.subscribeDriverLifecycle;
      const snapshot = binding.source.driverLifecycleSnapshot;
      if ((subscribe === undefined) !== (snapshot === undefined)) {
        throw new TypeError(
          `[motion] SharedValue ${binding.source.id} must implement both driver lifecycle hooks`,
        );
      }
      if (!subscribe || !snapshot) continue;
      const current = grouped.get(binding.source.id);
      if (current && current.source !== binding.source) {
        throw new Error(`[motion] SharedValue identity collision at ${binding.source.id}`);
      }
      (current ?? (() => {
        const created = { source: binding.source, bindings: [] };
        grouped.set(binding.source.id, created);
        return created;
      })()).bindings.push(binding);
    }
  }

  let memberships = motionObservabilityMembershipsByRoot.get(rootId);
  if (!memberships) {
    memberships = new Map();
    motionObservabilityMembershipsByRoot.set(rootId, memberships);
  }
  for (const [sourceId, membership] of [...memberships]) {
    const desired = grouped.get(sourceId);
    if (!desired || desired.source !== membership.source) {
      releaseMotionObservabilityMembership(membership, 'source-detached');
      memberships.delete(sourceId);
    }
  }

  for (const [sourceId, desired] of grouped) {
    let membership = memberships.get(sourceId);
    if (!membership) {
      const created: HostMotionObservabilityMembership = {
        rootId,
        source: desired.source,
        targets: new Map(),
        active: null,
        unsubscribe: () => {},
      };
      created.unsubscribe = desired.source.subscribeDriverLifecycle!((event) => {
        created.active = event.state === 'running' ? event : null;
        for (const target of created.targets.values()) {
          publishMotionDriverObservation(created, target, event);
        }
      });
      membership = created;
      memberships.set(sourceId, membership);
    }

    const desiredTargets = new Map<string, HostMotionObservabilityBinding>();
    for (const binding of desired.bindings) {
      desiredTargets.set(`${binding.viewId}\0${binding.property}`, binding);
    }
    const nextTargets = new Map<string, HostMotionObservabilityTarget>();
    for (const [key, binding] of desiredTargets) {
      const existing = membership.targets.get(key);
      nextTargets.set(key, existing ?? {
        viewId: binding.viewId,
        property: binding.property,
        animationId: `motion:${sourceId}:${nextMotionObservabilityBinding++}`,
      });
    }
    if (membership.active) {
      for (const [key, target] of membership.targets) {
        if (!nextTargets.has(key)) {
          publishMotionDriverObservation(
            membership,
            target,
            { ...membership.active, updatedAt: Date.now() },
            'stale',
            'binding-detached',
          );
        }
      }
    }
    const priorTargets = membership.targets;
    membership.targets = nextTargets;
    if (!membership.active) {
      const snapshot = membership.source.driverLifecycleSnapshot?.() ?? null;
      membership.active = snapshot?.state === 'running' ? snapshot : null;
    }
    if (membership.active) {
      for (const [key, target] of membership.targets) {
        if (!priorTargets.has(key)) {
          publishMotionDriverObservation(membership, target, membership.active);
        }
      }
    }
  }
  if (memberships.size === 0) motionObservabilityMembershipsByRoot.delete(rootId);
}

function releaseMotionObservabilityMembershipsForRoot(rootId: number): void {
  const memberships = motionObservabilityMembershipsByRoot.get(rootId);
  if (!memberships) return;
  for (const membership of memberships.values()) {
    releaseMotionObservabilityMembership(membership, 'root-destroyed');
  }
  motionObservabilityMembershipsByRoot.delete(rootId);
}

function nextMotionTransaction(rootId: number): {
  epoch: number;
  motionSeq: bigint;
  rootInstance: number;
} {
  let current = motionTransactionsByRoot.get(rootId);
  if (!current) {
    if (nextMotionRootInstance > 0xffff_ffff) {
      throw new RangeError('[motion] root-instance identity space exhausted');
    }
    current = {
      epoch: motionEpoch,
      motionSeq: 0n,
      rootInstance: nextMotionRootInstance++,
    };
  }
  if (current.epoch !== motionEpoch) {
    throw new Error(`[motion] root ${rootId} retained a stale transaction epoch`);
  }
  if (current.motionSeq >= 0xffff_ffff_ffff_ffffn) {
    throw new RangeError(`[motion] sequence exhausted for root ${rootId}`);
  }
  const next = {
    epoch: current.epoch,
    motionSeq: current.motionSeq + 1n,
    rootInstance: current.rootInstance,
  };
  motionTransactionsByRoot.set(rootId, next);
  return { ...next };
}

function driverIsDecorativeAutonomous(driver: MotionCommandDriver): boolean {
  switch (driver.kind) {
    case 'decay':
    case 'repeat':
      return true;
    case 'sequence':
      return driver.drivers.some(driverIsDecorativeAutonomous);
    case 'spring':
    case 'timing':
      return false;
  }
}

function reducedMotionRewriteForDriver(
  driver: MotionCommandDriver,
): MotionCommandReducedMotionRewrite {
  const interactionClass: MotionInteractionClass = driverIsDecorativeAutonomous(driver)
    ? 'decorativeAutonomous'
    : 'localSettle';
  const resolution = resolveMotionReducedMotion(interactionClass, {
    reducedMotion: getExactAccessibilitySnapshot().prefersReducedMotion,
  });
  return {
    profileVersion: MOTION_VALUE_COMMAND_SCHEMA.reducedMotion.profileVersion,
    interactionClass,
    applied: resolution.applied,
    action: resolution.action,
    durationMs: resolution.durationMs,
  };
}

function getPendingMotionCommandQueue(rootId: number): MotionCommandPendingQueue {
  let queue = pendingMotionCommandsByRoot.get(rootId);
  if (!queue) {
    queue = new MotionCommandPendingQueue();
    pendingMotionCommandsByRoot.set(rootId, queue);
  }
  return queue;
}

function encodePendingMotionCommands(
  rootId: number,
  encoder: ProtocolEncoder,
): number {
  const queue = pendingMotionCommandsByRoot.get(rootId);
  if (!queue || queue.length === 0) return 0;
  const commands = queue.drain();
  if (queue.length === 0) pendingMotionCommandsByRoot.delete(rootId);
  for (const command of commands) {
    encoder.setMotionCommand(rootId, encodeMotionValueCommand(command));
  }
  return commands.length;
}

function flushPendingMotionCommands(rootId: number, encoder?: ProtocolEncoder): number {
  if (encoder) return encodePendingMotionCommands(rootId, encoder);
  if (!liveRoots.has(rootId) || !hasNativeMotionProtocolHost(rootId)) {
    const dropped = pendingMotionCommandsByRoot.get(rootId)?.length ?? 0;
    if (dropped > 0) {
      // Arming observability (issues/20260728-native-motion-arming-boot-race):
      // this clear used to be silent, and it discards authored driver
      // intents — including the one-shot native-authority replay — with no
      // trace.
      // eslint-disable-next-line no-console
      console.error(
        `[ExactRenderer] Motion command flush DROPPED ${dropped} pending command(s) for root ${rootId}: ` +
        `liveRoot=${liveRoots.has(rootId)} nativeHost=${hasNativeMotionProtocolHost(rootId)}`,
      );
    }
    pendingMotionCommandsByRoot.get(rootId)?.clear();
    pendingMotionCommandsByRoot.delete(rootId);
    return 0;
  }
  // Standalone command flushes use an isolated frame so they cannot publish
  // UI mutations accumulated on the root's commit encoder ahead of commit.
  const commandEncoder = createProtocolEncoder(64 * 1024, rootId);
  const count = encodePendingMotionCommands(rootId, commandEncoder);
  if (count > 0) flushRootProtocol(rootId, commandEncoder);
  return count;
}

function schedulePendingMotionCommandFlush(rootId: number): void {
  if (pendingMotionCommandFlushRoots.has(rootId)) return;
  pendingMotionCommandFlushRoots.add(rootId);
  queueMicrotask(() => {
    pendingMotionCommandFlushRoots.delete(rootId);
    flushPendingMotionCommands(rootId);
  });
}

function enqueueMotionUserIntent(
  membership: HostMotionSourceMembership,
  intent: HostMotionSharedValueUserIntent,
): void {
  if (motionSourceMembershipsByIdentity.get(membership.source.id) !== membership) {
    return;
  }
  const transaction = nextMotionTransaction(membership.rootId);
  if (transaction.epoch !== membership.epoch) return;
  const base = {
    transaction,
    commandId: transaction.motionSeq,
    target: {
      descriptorId: membership.descriptorId,
      generation: membership.generation,
      epoch: membership.epoch,
    },
  } as const;
  let command: MotionValueCommand;
  switch (intent.kind) {
    case 'writeValue':
      command = {
        ...base,
        kind: 'writeValue',
        value: intent.value,
        reducedMotion: MOTION_NO_REDUCED_MOTION,
      };
      break;
    case 'startDriver':
      command = {
        ...base,
        kind: 'startDriver',
        driver: intent.driver,
        reducedMotion: reducedMotionRewriteForDriver(intent.driver),
      };
      break;
    case 'cancelDriver':
      command = {
        ...base,
        kind: 'cancelDriver',
        reducedMotion: MOTION_NO_REDUCED_MOTION,
      };
      break;
  }
  // Validation and bounded admission are synchronous with the authored
  // setter. A full queue throws before the SharedValue mutates its shadow.
  getPendingMotionCommandQueue(membership.rootId).enqueue(command);
  schedulePendingMotionCommandFlush(membership.rootId);
}

function releaseMotionSourceMembership(membership: HostMotionSourceMembership): void {
  const rootMemberships = motionSourceMembershipsByRoot.get(membership.rootId);
  if (rootMemberships?.get(membership.source.id) === membership) {
    rootMemberships.delete(membership.source.id);
    if (rootMemberships.size === 0) {
      motionSourceMembershipsByRoot.delete(membership.rootId);
    }
  }
  if (motionSourceMembershipsByIdentity.get(membership.source.id) === membership) {
    motionSourceMembershipsByIdentity.delete(membership.source.id);
  }
  const descriptorKey = membership.descriptorId.toString();
  if (motionSourceMembershipsByDescriptorId.get(descriptorKey) === membership) {
    motionSourceMembershipsByDescriptorId.delete(descriptorKey);
  }
  // Fence callbacks before releasing authority; no post-detach intent may
  // enter the root queue even if a future authority implementation wakes.
  try {
    membership.unsubscribeIntent();
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error(
      `[ExactRenderer] Motion intent cleanup failed for SharedValue ${membership.source.id}:`,
      error,
    );
  }
  try {
    membership.releaseNativeAuthority();
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error(
      `[ExactRenderer] Motion authority cleanup failed for SharedValue ${membership.source.id}:`,
      error,
    );
  }
}

function releaseMotionSourceMembershipsForRoot(rootId: number): void {
  releaseMotionObservabilityMembershipsForRoot(rootId);
  const memberships = motionSourceMembershipsByRoot.get(rootId);
  if (memberships) {
    for (const membership of [...memberships.values()]) {
      releaseMotionSourceMembership(membership);
    }
  }
  pendingMotionCommandsByRoot.get(rootId)?.clear();
  pendingMotionCommandsByRoot.delete(rootId);
  pendingMotionCommandFlushRoots.delete(rootId);
}

function reconcileMotionSourceMemberships(
  rootId: number,
  sources: ReadonlyMap<string, HostMotionSharedValue>,
): void {
  const nativeHost = hasNativeMotionProtocolHost(rootId);
  const desired = new Map(
    [...sources].filter(([, source]) => nativeHost && isMotionCommandProducer(source)),
  );
  const current = motionSourceMembershipsByRoot.get(rootId);
  if (current) {
    for (const membership of [...current.values()]) {
      const source = desired.get(membership.source.id);
      if (
        source !== membership.source ||
        source.generation !== membership.generation ||
        membership.epoch !== motionEpoch
      ) {
        releaseMotionSourceMembership(membership);
      }
    }
  }
  if (desired.size === 0) return;
  const transaction = motionTransactionsByRoot.get(rootId);
  if (!transaction || transaction.epoch !== motionEpoch) {
    throw new Error(`[motion] root ${rootId} cannot attach a command source before its snapshot`);
  }
  let memberships = motionSourceMembershipsByRoot.get(rootId);
  if (!memberships) {
    memberships = new Map();
    motionSourceMembershipsByRoot.set(rootId, memberships);
  }
  // Hermes lowers `for … of` bindings function-wide. The intent listener
  // escapes this loop, so a later reconciliation could observe another
  // iteration's `attached`/`bufferedIntents` cells (or an uninitialised
  // buffer) when a newly mounted card seeded its SharedValues. forEach gives
  // every source a real callback scope and stable listener captures.
  desired.forEach((source, sourceId) => {
    if (memberships.has(sourceId)) return;
    const claimed = motionSourceMembershipsByIdentity.get(sourceId);
    if (claimed) {
      const cause = claimed.source === source
        ? `is already bound to root ${claimed.rootId}`
        : 'collides with another live SharedValue object';
      throw new Error(`[motion] SharedValue ${sourceId} ${cause}; v1 values are single-root`);
    }
    const subscribeUserIntent = source.subscribeUserIntent!;
    const acquireNativeDriverAuthority = source.acquireNativeDriverAuthority!;
    const bufferedIntents: HostMotionSharedValueUserIntent[] = [];
    let attached = false;
    const membership: HostMotionSourceMembership = {
      rootId,
      source,
      descriptorId: motionDescriptorId(`shared:${source.id}`),
      generation: source.generation,
      epoch: transaction.epoch,
      unsubscribeIntent: () => {},
      releaseNativeAuthority: () => {},
    };
    try {
      const unsubscribeIntent = subscribeUserIntent.call(source, (intent) => {
        if (!attached) {
          // Authority acquisition may synchronously replay the one authored
          // intent. Buffer it until acquisition succeeds so a throwing hook
          // cannot leak a command for an unattached source.
          bufferedIntents.push(intent);
          return;
        }
        enqueueMotionUserIntent(membership, intent);
      });
      if (typeof unsubscribeIntent !== 'function') {
        throw new TypeError(
          `[motion] SharedValue ${sourceId} intent subscription did not return cleanup`,
        );
      }
      membership.unsubscribeIntent = unsubscribeIntent;
      const releaseNativeAuthority = acquireNativeDriverAuthority.call(source);
      if (typeof releaseNativeAuthority !== 'function') {
        throw new TypeError(
          `[motion] SharedValue ${sourceId} authority acquisition did not return cleanup`,
        );
      }
      membership.releaseNativeAuthority = releaseNativeAuthority;
      memberships.set(sourceId, membership);
      motionSourceMembershipsByIdentity.set(sourceId, membership);
      motionSourceMembershipsByDescriptorId.set(
        membership.descriptorId.toString(),
        membership,
      );
      attached = true;
      for (const intent of bufferedIntents) enqueueMotionUserIntent(membership, intent);
    } catch (error) {
      releaseMotionSourceMembership(membership);
      // Binary snapshot flush, fingerprints, callback registration, and the
      // artifact plane are already authoritative here. Keep that commit
      // successful, leave no partial membership, and retry on the next commit.
      // eslint-disable-next-line no-console
      console.error(
        `[ExactRenderer] Motion source attachment failed for SharedValue ${sourceId} ` +
          `on committed root ${rootId}:`,
        error,
      );
    }
  });
}

function validateMotionSourceMembershipClaims(
  rootId: number,
  sources: ReadonlyMap<string, HostMotionSharedValue>,
): void {
  if (!hasNativeMotionProtocolHost(rootId)) return;
  for (const [sourceId, source] of sources) {
    if (!isMotionCommandProducer(source)) continue;
    const claimed = motionSourceMembershipsByIdentity.get(sourceId);
    // A same-root replacement is a valid generation/lifetime transition.
    // The collector already rejects two different live objects with the same
    // id in one descriptor set, and reconcile releases the old membership
    // only after staging the replacement snapshot.
    if (!claimed || claimed.rootId === rootId) continue;
    const cause = claimed.source === source
      ? `is already bound to root ${claimed.rootId}`
      : 'collides with another live SharedValue object';
    throw new Error(`[motion] SharedValue ${sourceId} ${cause}; v1 values are single-root`);
  }
}

function encodeMotionDescriptorSnapshot(
  encoder: ProtocolEncoder,
  root: RootNode,
  pagerBindings: readonly PagerBindingDescriptor[],
): () => void {
  const {
    descriptors,
    sources,
    observabilityBindings,
    workletArtifacts,
    callbackRegistrations,
  } = collectMotionDescriptorRecords(root, pagerBindings);
  validateMotionSourceMembershipClaims(root.rootId, sources);
  const commitCallbackRegistrations =
    prepareMotionWorkletCallbackRegistrationReconciliation(
      root.rootId,
      callbackRegistrations,
    );
  const previous = committedMotionDescriptorsByRoot.get(root.rootId);
  const descriptorsChanged = !(
    (previous === undefined && descriptors.length === 0) ||
    (previous !== undefined && motionDescriptorsEqual(previous, descriptors))
  );
  const previousArtifacts = committedMotionWorkletArtifactsByRoot.get(root.rootId);
  const artifactsChanged = !(
    (previousArtifacts === undefined && workletArtifacts.length === 0) ||
    (previousArtifacts !== undefined &&
      motionWorkletArtifactsEqual(previousArtifacts, workletArtifacts))
  );
  const changed = descriptorsChanged || artifactsChanged;
  let commitChangedDescriptors: (() => void) | undefined;
  let dispatchInstallPlane: (() => void) | undefined;
  if (changed) {
    // The committed-seed reuse above exists ONLY to keep an unchanged graph
    // byte-stable (so live scalar writes never masquerade as structural
    // changes). Once the snapshot IS changing, a stale seed is pure harm:
    // the native install re-seeds the slab from it and the activation
    // replay adopts the stale value back into the JS store, reverting every
    // committed write (the reinstall reset). Refresh command-producer seeds
    // to the store's current values before encoding.
    for (const source of sources.values()) {
      if (!isMotionCommandProducer(source)) continue;
      const current = source.current();
      if (!Number.isFinite(current)) continue;
      const sourceId = motionDescriptorId(`shared:${source.id}`);
      const descriptor = descriptors.find(
        (candidate) =>
          candidate.id === sourceId && candidate.kind === MotionDescriptorKind.SharedValue,
      );
      if (descriptor && descriptor.parameters[0] !== current) {
        (descriptor.parameters as number[])[0] = current;
      }
    }
    const transaction = nextMotionTransaction(root.rootId);
    // Validate required async transport before staging binary operations. The
    // returned dispatcher is held until this transaction's synchronous binary
    // flush succeeds, preserving the binary-first native join.
    if (hasNativeMotionProtocolHost(root.rootId)) {
      dispatchInstallPlane = prepareMotionWorkletInstallPlaneDispatch(Object.freeze({
        schemaVersion: MOTION_WORKLET_INSTALL_PLANE_SCHEMA_VERSION,
        schemaDigest: MOTION_WORKLET_INSTALL_PLANE_SCHEMA_DIGEST,
        rootId: root.rootId,
        transaction: Object.freeze({
          epoch: transaction.epoch,
          motionSeq: transaction.motionSeq.toString(10),
          rootInstance: transaction.rootInstance,
        }),
        artifacts: Object.freeze([...workletArtifacts]),
      }));
    }
    // The record is a whole-root replacement. Every previously committed
    // descriptor detaches in phase one, even when its identity survives, so
    // presenter work in the middle observes only authored/base presentation.
    // The complete replacement set reattaches in phase two. This is LLP 0099
    // M2's generalized pager ordering rule and prevents live presenter updates
    // from wiping or being composed against a stale Motion override.
    const detachIds = (previous ?? []).map((descriptor) => descriptor.id);
    const chunks = chunkMotionSnapshot(
      transaction.motionSeq,
      {
        transaction,
        detachIds,
        descriptors,
      },
    );
    for (const chunk of chunks) {
      // Motion ops are root-scoped; using the protocol root id (rather than the
      // internal root view id) lets native reject cross-root chunk splicing.
      encoder.setMotionSnapshotChunk(root.rootId, encodeMotionSnapshotChunk(chunk));
    }
    const committedDescriptors = descriptors.map((descriptor) => ({
      ...descriptor,
      dependencies: [...descriptor.dependencies],
      parameters: [...descriptor.parameters],
    }));
    commitChangedDescriptors = () => {
      if (committedDescriptors.length === 0) {
        committedMotionDescriptorsByRoot.delete(root.rootId);
      } else {
        committedMotionDescriptorsByRoot.set(root.rootId, committedDescriptors);
      }
      if (workletArtifacts.length === 0) {
        committedMotionWorkletArtifactsByRoot.delete(root.rootId);
      } else {
        committedMotionWorkletArtifactsByRoot.set(root.rootId, workletArtifacts);
      }
      committedMotionDescriptorTransactionsByRoot.set(root.rootId, transaction);
    };
  }
  return () => {
    commitChangedDescriptors?.();
    commitCallbackRegistrations();
    dispatchInstallPlane?.();
    // Membership changes are part of the successful root commit, not binary
    // staging. In particular, acquiring native authority can deactivate a
    // local driver and replay one authored intent; doing that before
    // flushRootProtocol meant a throwing host dispatch left JS believing the
    // failed snapshot owned the source. Attach only after the binary snapshot
    // is accepted. Any replay is queued on the next root-clock command frame,
    // after the descriptor transaction it targets.
    try {
      reconcileMotionObservabilityMemberships(root.rootId, observabilityBindings);
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error(
        `[ExactRenderer] Motion observability reconciliation failed for committed root ` +
          `${root.rootId}:`,
        error,
      );
    }
    try {
      reconcileMotionSourceMemberships(root.rootId, sources);
    } catch (error) {
      // Every app-provided hook has its own rollback above. This final fence
      // protects the commit boundary from an unexpected reconciliation fault.
      // eslint-disable-next-line no-console
      console.error(
        `[ExactRenderer] Motion source reconciliation failed for committed root ` +
          `${root.rootId}:`,
        error,
      );
    }
    // A changed snapshot rebuilds the native value slab from descriptor seed
    // parameters, and those seeds were refreshed to the store's live values
    // at encode time. What that refresh cannot cover is store movement
    // between encode and this post-flush commit — intent-free writes that
    // forwarding never re-emits: a synchronous protocol host applies the
    // snapshot inline during the binary flush and its terminal command
    // dispatch lands through adoptNativeSample, and the source-provided
    // reconciliation hooks above run before this loop. Re-issue one
    // WriteValue per diverged command producer so the new slab converges on
    // the store (the store is the authority).
    if (changed && hasNativeMotionProtocolHost(root.rootId)) {
      for (const source of sources.values()) {
        if (!isMotionCommandProducer(source)) continue;
        const membership = motionSourceMembershipsByIdentity.get(source.id);
        if (!membership) continue;
        const sourceId = motionDescriptorId(`shared:${source.id}`);
        const descriptor = descriptors.find(
          (candidate) =>
            candidate.id === sourceId && candidate.kind === MotionDescriptorKind.SharedValue,
        );
        if (!descriptor) continue;
        const current = source.current();
        if (!Number.isFinite(current) || descriptor.parameters[0] === current) continue;
        enqueueMotionUserIntent(membership, { kind: 'writeValue', value: current });
      }
    }
  };
}

/**
 * Commit the batch - set root styles, compute layout, and dispatch to native.
 */
export function commitBatch(container: RootNode): void {
  if (protocolDispatchFailedRoots.has(container.rootId)) {
    throw new Error(
      `[ExactRenderer] Root ${container.rootId} cannot retry after a protocol dispatch failure; ` +
        'destroy it locally and use a new root ID until the renderer and host reset together',
    );
  }
  ensureCrashCaptureAfterFirstCommit();
  let updateEconomy: UpdateEconomyBridge | undefined;
  if (
    ('env' in import.meta &&
      (import.meta as UpdateEconomyImportMeta).env.DEV === true) ||
    process.env.NODE_ENV === 'test'
  ) {
    updateEconomy = (globalThis as typeof globalThis & {
      __exactUpdateEconomy?: { bridge?: UpdateEconomyBridge };
    }).__exactUpdateEconomy?.bridge;
  }
  const updateEconomyStartedAt = updateEconomy?.now() ?? 0;
  const enc = getEncoderForRoot(container.rootId);
  const state = getPendingCommitState(container.rootId);
  const rootChildrenDirty =
    hasDirtyFlag(container, DirtyFlags.Created) ||
    hasDirtyFlag(container, DirtyFlags.Children);
  if (rootChildrenDirty) {
    state.dirtyChildren.add(container);
    state.layoutDirty = true;
  }

  flushDirtyChildren(enc, state);
  // LLP 0336 P2: the descriptor set is a complete, generation-fenced
  // snapshot. A final zero-count op is the detach-before-destroy signal.
  const pagerBindings = collectPagerBindingDescriptors(container);
  encodePagerBindingSnapshot(enc, container, pagerBindings);
  // Commands issued before this commit precede its structural snapshot under
  // the shared root clock. A driver replay caused by a new attachment is
  // captured by the second drain and follows that snapshot in the same frame.
  encodePendingMotionCommands(container.rootId, enc);
  const commitMotionDescriptorSnapshot = encodeMotionDescriptorSnapshot(
    enc,
    container,
    pagerBindings,
  );
  encodePendingMotionCommands(container.rootId, enc);

  const { width, height } = getScreenDimensions(container.rootId);
  const previousViewport = committedRootViewportSizes.get(container.rootId);
  const viewportChanged =
    previousViewport === undefined ||
    previousViewport.width !== width ||
    previousViewport.height !== height;

  if (viewportChanged) {
    committedRootViewportSizes.set(container.rootId, { width, height });
    state.layoutDirty = true;
    state.changedViews.add(container.id);

    // Root container: a RootNode carries no canonical element style, and this
    // viewport set IS the root's full style (see emitElementSetStyle).
    encodeSetStyleOp(enc, container.id, {
      width: { type: 'points', value: width },
      height: { type: 'points', value: height },
      flexDirection: 'column',
      alignItems: 'stretch',
      justifyContent: 'flex-start',
    });
  }

  if (state.layoutDirty) {
    updateEconomy?.recordLayout(container.rootId);
    enc.computeLayout(container.id, width, height);
  }

  const protocolOps = enc.getOpCount();
  const protocolBytes = protocolOps > 0
    ? flushRootProtocol(container.rootId, enc)
    : 0;
  updateEconomy?.recordProtocol(container.rootId, protocolOps, protocolBytes);
  commitMotionDescriptorSnapshot();
  const changedViews = Array.from(state.changedViews);
  finishContractPerfCommit(container.rootId, {
    protocolOps,
    protocolBytes,
    changedViews: changedViews.length,
  });
  const analyzeWarnings = state.warningAnalysisDirty;
  state.layoutDirty = false;
  state.warningAnalysisDirty = false;
  state.changedViews.clear();
  clearDirtyFlags(container);
  stampDynamicRangePolicies(container);
  notifyCommit(container, {
    changedViews,
    analyzeWarnings,
  });
  syncKeyboardAvoidanceAfterCommit(container.rootId);
  // Plain-web pixels for host-ops adapters: when the DOM mirror is installed
  // (no protocol host on the page), it re-renders this root's node tree into
  // real DOM after every commit. Undefined everywhere else.
  (globalThis as typeof globalThis & {
    __exactDomMirror?: { sync(root: RootNode): void };
  }).__exactDomMirror?.sync(container);
  if (updateEconomy) {
    updateEconomy.finishCommit(
      container.rootId,
      updateEconomy.now() - updateEconomyStartedAt,
    );
  }
}

/**
 * Render a minimal fallback message when framework rendering fails.
 * This keeps the native tree in a coherent state instead of leaving the app blank.
 */
export function renderErrorFallback(container: RootNode, message: string): void {
  const enc = getEncoderForRoot(container.rootId);
  const fallbackProps: Props = {
    style: {
      color: '#ff3b30',
      padding: 16,
      fontSize: 14,
    },
  };

  clearContainer(container);

  const fallback = createInstance('Text', fallbackProps);
  encodeCreateElement(enc, fallback);

  const text = createTextNode(message);
  encodeCreateText(enc, text);
  clearDirtyFlags(text);

  nodeAppendChild(fallback, text);
  nodeAppendChild(container, fallback);
  encodeChildren(enc, fallback);
  clearDirtyFlags(fallback);
  encodeChildren(enc, container);
  commitBatch(container);
}

/**
 * motion.measure geometry source under a native protocol host (LLP 0099
 * §Worklets). The web presenters register a DOM provider; on native the
 * kernel is the layout authority and runs on the SAME thread as the app
 * runtime (LLP 0297), so `exact.getAbsoluteLayout(viewId)` is a legal
 * synchronous read. Resolution walks the live renderer trees for the
 * `testId` prop — measure calls are bounded-edge only (mount, gesture
 * terminal), never per-frame, so a tree walk is fine.
 *
 * Scoping: a caller-supplied rootId restricts resolution to that root.
 * Without one, roots are walked in ascending rootId order so cross-root
 * duplicate testIds resolve deterministically (lowest rootId wins) — the
 * rule documented at the motion-measure provider seam.
 */
function findNodeByTestId(
  testId: string,
  rootId?: number,
): { node: ElementNode; rootId: number } | null {
  const walk = (node: ElementNode): ElementNode | null => {
    if ((node.props as { testId?: unknown }).testId === testId) return node;
    for (const child of node.children) {
      if (child.kind !== NodeKind.Element) continue;
      const match = walk(child);
      if (match) return match;
    }
    return null;
  };
  let roots: RootNode[];
  if (rootId !== undefined) {
    const scoped = liveRoots.get(rootId);
    roots = scoped ? [scoped] : [];
  } else {
    roots = [...liveRoots.values()].sort((left, right) => left.rootId - right.rootId);
  }
  for (const root of roots) {
    for (const child of root.children) {
      if (child.kind !== NodeKind.Element) continue;
      const match = walk(child);
      if (match) return { node: match, rootId: root.rootId };
    }
  }
  return null;
}

function ensureNativeMotionMeasureProvider(): void {
  if (getMotionMeasureProvider()) return;
  const native = (
    globalThis as {
      exact?: { getAbsoluteLayout?: (viewId: number) => { x: number; y: number; width: number; height: number } | null };
    }
  ).exact;
  if (typeof native?.getAbsoluteLayout !== 'function') return;
  const getAbsoluteLayout = native.getAbsoluteLayout.bind(native);
  setMotionMeasureProvider((testId, rootId) => {
    const found = findNodeByTestId(testId, rootId);
    if (!found) return null;
    // Returns null until the kernel's first layout pass covers the node —
    // callers already treat measure() as nullable and retry/fall back.
    const frame = getAbsoluteLayout(found.node.id);
    if (!frame) return null;
    // Kernel absolute layouts are root-local. Compose the root's window
    // placement so native measure() shares the window basis of gesture
    // absoluteX/Y and the web getBoundingClientRect provider.
    const offset = getMotionMeasureRootWindowOffset(found.rootId);
    return {
      x: frame.x + offset.x,
      y: frame.y + offset.y,
      width: frame.width,
      height: frame.height,
    };
  });
}

/**
 * Create the root container and register it with native.
 *
 * @param rootId - Root ID for multi-root support (default 0 = single root)
 * @param owner - Optional public adapter owner name. When supplied, the root
 *   ID is claimed so another adapter/DOM handle cannot silently reuse it.
 */
export function createRoot(rootId: number = 0, owner?: string): RootNode {
  if (protocolDispatchFailedRoots.has(rootId)) {
    throw new Error(
      `[ExactRenderer] Root ${rootId} is quarantined after a protocol dispatch failure; ` +
        'use a new root ID until the renderer and host reset together.',
    );
  }
  if (liveRoots.has(rootId)) {
    throw new Error(`Root ${rootId} is already initialized.`);
  }

  if (owner) {
    claimRoot(rootId, owner);
  }

  const root = createRootNode(rootId);
  const enc = getEncoderForRoot(rootId);
  enc.createView(root.id, NodeType.View);
  liveRoots.set(root.rootId, root);
  ensureNativeMotionMeasureProvider();
  ensureLocaleRootSync();
  ensureAccessibilityRootSync();
  ensureFontRegistryRootSync();
  ensureThemeSchemeRootSync();
  registerRoot(root);

  const ensureAgentServer = (
    globalThis as {
      __exactEnsureAgentServer?: (() => void) | undefined;
    }
  ).__exactEnsureAgentServer;
  const shouldBootAgentServer =
    (globalThis as {
      __exactAgentBootstrap?: {
        boot?: boolean;
      };
    }).__exactAgentBootstrap?.boot === true ||
    (typeof process === 'object' &&
      process !== null &&
      typeof process.env?.EXACT_AGENT_BOOT === 'string' &&
      process.env.EXACT_AGENT_BOOT === '1');

  if (shouldBootAgentServer && typeof ensureAgentServer === 'function') {
    ensureAgentServer();
  }

  return root;
}

export function unregisterInspectorRoot(rootId: number): void {
  releaseMotionSourceMembershipsForRoot(rootId);
  releaseMotionObservabilityMembershipsForRoot(rootId);
  clearMotionRootObservability(rootId);
  prepareMotionWorkletCallbackRegistrationReconciliation(rootId, [])();
  liveRoots.delete(rootId);
  committedRootViewportSizes.delete(rootId);
  committedPagerBindingsByRoot.delete(rootId);
  committedMotionDescriptorsByRoot.delete(rootId);
  committedMotionWorkletArtifactsByRoot.delete(rootId);
  committedMotionDescriptorTransactionsByRoot.delete(rootId);
  motionTransactionsByRoot.delete(rootId);
  pendingCommitStateByRoot.delete(rootId);
  maybeDisposeLocaleRootSync();
  maybeDisposeAccessibilityRootSync();
  maybeDisposeFontRegistryRootSync();
  maybeDisposeThemeSchemeRootSync();
  unregisterRoot(rootId);
}

export function _resetHostOpsState(): void {
  resetCrashCaptureLoading();
  for (const timer of pendingMotionWorkletInstallDeadlineTimers) clearTimeout(timer);
  pendingMotionWorkletInstallDeadlineTimers.clear();
  motionWorkletInstallDeadlineMs = DEFAULT_MOTION_WORKLET_INSTALL_DEADLINE_MS;
  for (const rootId of [...motionSourceMembershipsByRoot.keys()]) {
    releaseMotionSourceMembershipsForRoot(rootId);
  }
  const motionObservabilityRootIds = new Set([
    ...liveRoots.keys(),
    ...motionObservabilityMembershipsByRoot.keys(),
  ]);
  for (const rootId of motionObservabilityRootIds) {
    releaseMotionObservabilityMembershipsForRoot(rootId);
    clearMotionRootObservability(rootId);
  }
  nextMotionObservabilityBinding = 1;
  liveRoots.clear();
  rootOwners.clear();
  committedRootViewportSizes.clear();
  committedPagerBindingsByRoot.clear();
  committedMotionDescriptorsByRoot.clear();
  committedMotionWorkletArtifactsByRoot.clear();
  committedMotionDescriptorTransactionsByRoot.clear();
  motionWorkletCallbackRegistrationsByRoot.clear();
  motionWorkletCallbackRegistrations.clear();
  motionRunOnJSLastSourceSequence.clear();
  maybeRemoveMotionRunOnJSDispatcher();
  motionTransactionsByRoot.clear();
  motionSourceMembershipsByIdentity.clear();
  motionSourceMembershipsByDescriptorId.clear();
  pendingMotionCommandsByRoot.clear();
  pendingMotionCommandFlushRoots.clear();
  pendingMotionRegistryCommitRoots.clear();
  if (motionEpoch >= 0xffff_ffff) {
    throw new RangeError('[motion] epoch identity space exhausted');
  }
  motionEpoch += 1;
  pendingCommitStateByRoot.clear();
  maybeDisposeLocaleRootSync();
  maybeDisposeAccessibilityRootSync();
  maybeDisposeFontRegistryRootSync();
  maybeDisposeThemeSchemeRootSync();
  encoders.clear();
  protocolSuppressedRoots.clear();
  // Test/process-wide reset is the only in-process operation that releases a
  // failed-root quarantine. Production callers must reset the host in lockstep.
  protocolDispatchFailedRoots.clear();
  warnedAutoDirectionTags.clear();
  resetProtocolTapForTests();
  resetKeyboardAvoidanceState();
  clearFocusedTarget();
  _resetTextInputObservedRevisionAcksForTests();
  _resetTextInputFiltersForTests();
  dynamicRangeRenderRevision = 0;
  resetDynamicRangeResolutionRuntimeState();
}

// ---------------------------------------------------------------------------
// LLP 0281 stage 0 — the host channel-application seam
// ---------------------------------------------------------------------------
//
// A value-channel style sink (a `transform`/`opacity` attr driven by a
// frame-coalesced channel value) must reach pixels as compositor-only work,
// bypassing the reactive flush and the host-ops prop diff entirely. Hosts
// that can do that register an applier here (the web dom-mirror writes the
// style straight onto the DOM node); the Contract runtime calls
// `applyHostChannelStyle` per coalesced frame and falls back to an ordinary
// coalesced prop update when no applier is installed (correct semantics,
// slower path — the native fast path arrives with LLP 0099's substrate).

export type HostChannelStyleApplier = (
  /** The host-ops element node the sink is bound to. */
  node: unknown,
  /** Lowered style prop name (`transform`, `opacity`). */
  styleProp: string,
  /** Evaluated sink value (string transform, numeric opacity, ...). */
  value: unknown,
) => boolean;

let hostChannelStyleApplier: HostChannelStyleApplier | null = null;

/** Install (or clear, with null) the host's channel style applier. */
export function setHostChannelStyleApplier(next: HostChannelStyleApplier | null): void {
  hostChannelStyleApplier = next;
}

export function getHostChannelStyleApplier(): HostChannelStyleApplier | null {
  return hostChannelStyleApplier;
}

/**
 * Apply a channel-driven style value through the host fast path. Returns
 * false when no host applier is installed or the applier declined the node
 * — callers then fall back to the coalesced host-ops update.
 */
export function applyHostChannelStyle(node: unknown, styleProp: string, value: unknown): boolean {
  if (!hostChannelStyleApplier) {
    return false;
  }
  try {
    return hostChannelStyleApplier(node, styleProp, value);
  } catch (error) {
    console.warn('[exact] host channel style applier failed', error);
    return false;
  }
}
