// @system @ref LLP 0099#agent-api
// @system @ref LLP 0336#61-arbitration-arena-normative-v1-contract
import type {
  MotionAnimationAgentState,
  MotionArbitrationReceipt,
  MotionDismissLayerAgentReceipt,
  MotionDismissLayerAgentState,
  MotionGestureAgentLifecycleState,
  MotionGestureAgentState,
  MotionObservabilityData,
  MotionRetentionAgentState,
} from "./types.js";

/** Public, conformance-pinned bounds. Overflow evicts history, never truth. */
export const MOTION_OBSERVABILITY_LIMITS = Object.freeze({
  gestureStatesPerRoot: 1_024,
  animationStatesPerRoot: 1_024,
  retentionsPerRoot: 256,
  arbitrationReceiptsPerRoot: 100,
});

const TERMINAL_GESTURE_STATES = new Set<MotionGestureAgentLifecycleState>([
  "ended",
  "cancelled",
  "failed",
  "stale",
]);
const GESTURE_STATES = new Set<MotionGestureAgentLifecycleState>([
  "idle",
  "began",
  "active",
  ...TERMINAL_GESTURE_STATES,
]);
const ANIMATION_STATES = new Set<MotionAnimationAgentState["state"]>([
  "scheduled",
  "running",
  "settling",
  "settled",
  "cancelled",
  "stale",
]);
const TERMINAL_ANIMATION_STATES = new Set<MotionAnimationAgentState["state"]>([
  "settled",
  "cancelled",
  "stale",
]);
const ACTIVE_ANIMATION_STATES = new Set<MotionAnimationAgentState["state"]>([
  "scheduled",
  "running",
  "settling",
]);
const RETENTION_STATES = new Set<MotionRetentionAgentState["state"]>([
  "retaining",
  "released",
  "cancelled",
  "stale",
]);
const TERMINAL_RETENTION_STATES = new Set<MotionRetentionAgentState["state"]>([
  "released",
  "cancelled",
  "stale",
]);

interface RootMotionState {
  gestures: Map<string, MotionGestureAgentState>;
  animations: Map<string, MotionAnimationAgentState>;
  retentions: Map<string, MotionRetentionAgentState>;
  dismissLayers: Map<string, MotionDismissLayerAgentState>;
  dismissReceipts: MotionDismissLayerAgentReceipt[];
  receipts: MotionArbitrationReceipt[];
  lastSourceReceiptSequence: bigint;
  nextReceiptSequence: number;
  lastActivityAt: number;
  gestureStateEvictions: number;
  animationStateEvictions: number;
  retentionStateEvictions: number;
  arbitrationReceiptEvictions: number;
  staleStateDrops: number;
  staleReceiptDrops: number;
}

export interface MotionObservabilityChange {
  generation: number;
  rootId: number;
  viewIds: number[];
  kind: "gesture" | "animation" | "retention" | "dismiss" | "receipt" | "clear";
}

type MotionObservabilityListener = (change: MotionObservabilityChange) => void;

interface MotionObservabilityStore {
  generation: number;
  roots: Map<number, RootMotionState>;
  listeners: Set<MotionObservabilityListener>;
}

type MotionObservabilityGlobal = typeof globalThis & {
  __exactMotionObservability?: MotionObservabilityStore;
};

function store(): MotionObservabilityStore {
  const scope = globalThis as MotionObservabilityGlobal;
  return (scope.__exactMotionObservability ??= {
    generation: 0,
    roots: new Map(),
    listeners: new Set(),
  });
}

function newRootState(): RootMotionState {
  return {
    gestures: new Map(),
    animations: new Map(),
    retentions: new Map(),
    dismissLayers: new Map(),
    dismissReceipts: [],
    receipts: [],
    lastSourceReceiptSequence: 0n,
    nextReceiptSequence: 0,
    lastActivityAt: 0,
    gestureStateEvictions: 0,
    animationStateEvictions: 0,
    retentionStateEvictions: 0,
    arbitrationReceiptEvictions: 0,
    staleStateDrops: 0,
    staleReceiptDrops: 0,
  };
}

function rootState(rootId: number): RootMotionState {
  const current = store();
  let root = current.roots.get(rootId);
  if (!root) {
    root = newRootState();
    current.roots.set(rootId, root);
  }
  return root;
}

function finite(value: number, label: string): number {
  if (!Number.isFinite(value)) {
    throw new TypeError(`[motion-observability] ${label} must be finite`);
  }
  return value;
}

function nonnegativeInteger(value: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new TypeError(
      `[motion-observability] ${label} must be a non-negative safe integer`,
    );
  }
  return value;
}

function positiveInteger(value: number, label: string): number {
  if (!Number.isSafeInteger(value) || value < 1) {
    throw new TypeError(
      `[motion-observability] ${label} must be a positive safe integer`,
    );
  }
  return value;
}

function positiveU64Identity(
  value: number | string,
  label: string,
): { value: number | string; comparable: bigint } {
  if (typeof value === "number") {
    positiveInteger(value, label);
    return { value, comparable: BigInt(value) };
  }
  if (!/^[1-9][0-9]*$/.test(value)) {
    throw new TypeError(
      `[motion-observability] ${label} must be a positive integer or canonical decimal u64`,
    );
  }
  const comparable = BigInt(value);
  if (comparable > 0xffff_ffff_ffff_ffffn) {
    throw new TypeError(`[motion-observability] ${label} must fit u64`);
  }
  return { value, comparable };
}

function identity(value: string, label: string): string {
  if (typeof value !== "string" || value.length === 0) {
    throw new TypeError(`[motion-observability] ${label} must be non-empty`);
  }
  return value;
}

function enumValue<T extends string>(
  value: T,
  allowed: ReadonlySet<T>,
  label: string,
): T {
  if (!allowed.has(value)) {
    throw new TypeError(`[motion-observability] invalid ${label} ${value}`);
  }
  return value;
}

function timestamp(value: number | undefined): number {
  return finite(value ?? Date.now(), "timestamp");
}

function emit(
  rootId: number,
  viewIds: Iterable<number>,
  kind: MotionObservabilityChange["kind"],
): void {
  const current = store();
  current.generation += 1;
  const change: MotionObservabilityChange = {
    generation: current.generation,
    rootId,
    viewIds: Array.from(new Set(viewIds)).sort((left, right) => left - right),
    kind,
  };
  for (const listener of current.listeners) {
    try {
      listener(change);
    } catch {
      // Observability listeners are never allowed to break Motion.
    }
  }
}

function gestureKey(
  value: Pick<MotionGestureAgentState, "viewId" | "gestureId" | "invocationId">,
): string {
  // A gesture descriptor can have more than one live composition instance.
  // Keep the legacy singleton key for publishers without an invocation id,
  // but never collapse two explicitly identified instances into one state.
  return `${value.viewId}\0${value.gestureId}\0${value.invocationId ?? ""}`;
}

function animationKey(
  value: Pick<MotionAnimationAgentState, "viewId" | "animationId">,
): string {
  return `${value.viewId}:${value.animationId}`;
}

function cloneGesture(value: MotionGestureAgentState): MotionGestureAgentState {
  return {
    ...value,
    ...(value.translation ? { translation: { ...value.translation } } : {}),
    ...(value.velocity ? { velocity: { ...value.velocity } } : {}),
  };
}

function cloneAnimation(value: MotionAnimationAgentState): MotionAnimationAgentState {
  return { ...value };
}

function cloneRetention(value: MotionRetentionAgentState): MotionRetentionAgentState {
  return { ...value, viewIds: [...value.viewIds] };
}

function cloneDismissLayer(value: MotionDismissLayerAgentState): MotionDismissLayerAgentState {
  return {
    ...value,
    ...(value.triggers ? { triggers: [...value.triggers] } : {}),
    ...(value.command ? { command: { ...value.command } } : {}),
  };
}

function cloneDismissReceipt(
  value: MotionDismissLayerAgentReceipt,
): MotionDismissLayerAgentReceipt {
  return {
    ...value,
    ...(value.command ? { command: { ...value.command } } : {}),
  };
}

function cloneReceipt(value: MotionArbitrationReceipt): MotionArbitrationReceipt {
  return {
    ...value,
    hitPath: [...value.hitPath],
    contenders: value.contenders.map((contender) => ({ ...contender })),
    ...(value.winner ? { winner: { ...value.winner } } : {}),
  };
}

function isStaleState(
  existing: { generation: number; updatedAt: number; state: string } | undefined,
  next: { generation: number; updatedAt: number },
  terminalStates: ReadonlySet<string>,
): boolean {
  if (!existing) return false;
  if (next.generation < existing.generation) return true;
  if (next.generation > existing.generation) return false;
  return terminalStates.has(existing.state) || next.updatedAt < existing.updatedAt;
}

function trimStateMap<T extends { viewId?: number; state: string }>(
  values: Map<string, T>,
  limit: number,
  terminalStates: ReadonlySet<string>,
): { evictions: number; viewIds: number[] } {
  let evictions = 0;
  const viewIds: number[] = [];
  while (values.size > limit) {
    const terminal = Array.from(values.entries()).find(([, value]) =>
      terminalStates.has(value.state),
    );
    const oldest = terminal ?? values.entries().next().value;
    if (!oldest) break;
    values.delete(oldest[0]);
    if (typeof oldest[1].viewId === "number") viewIds.push(oldest[1].viewId);
    evictions += 1;
  }
  return { evictions, viewIds };
}

export function subscribeMotionObservability(
  listener: MotionObservabilityListener,
): () => void {
  const listeners = store().listeners;
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export type MotionGestureStatePublish = Omit<MotionGestureAgentState, "updatedAt"> & {
  updatedAt?: number;
};

/** Publish one recognizer state. Stale generations and terminal resurrection are ignored. */
export function publishMotionGestureState(
  input: MotionGestureStatePublish,
): boolean {
  const rootId = nonnegativeInteger(input.rootId, "rootId");
  const viewId = nonnegativeInteger(input.viewId, "viewId");
  const generation = positiveInteger(input.generation, "generation");
  const updatedAt = timestamp(input.updatedAt);
  identity(input.gestureId, "gestureId");
  if (input.invocationId !== undefined) identity(input.invocationId, "invocationId");
  identity(input.type, "gesture type");
  enumValue(input.state, GESTURE_STATES, "gesture state");
  if (typeof input.streamId === "number") {
    nonnegativeInteger(input.streamId, "streamId");
  } else if (typeof input.streamId === "string") {
    if (!/^(0|[1-9][0-9]*)$/.test(input.streamId)) {
      throw new TypeError("[motion-observability] streamId must be canonical decimal u64");
    }
    const streamId = BigInt(input.streamId);
    if (streamId > 0xffff_ffff_ffff_ffffn) {
      throw new TypeError("[motion-observability] streamId must fit u64");
    }
  } else if (input.streamId !== undefined) {
    throw new TypeError("[motion-observability] streamId must be a number or decimal string");
  }
  if (input.translation) {
    finite(input.translation.x, "translation.x");
    finite(input.translation.y, "translation.y");
  }
  if (input.velocity) {
    finite(input.velocity.x, "velocity.x");
    finite(input.velocity.y, "velocity.y");
  }
  if (input.scale !== undefined) finite(input.scale, "scale");
  if (input.rotation !== undefined) finite(input.rotation, "rotation");
  if (input.pointerCount !== undefined) {
    nonnegativeInteger(input.pointerCount, "pointerCount");
  }

  const root = rootState(rootId);
  const value = cloneGesture({ ...input, rootId, viewId, generation, updatedAt });
  const key = gestureKey(value);
  if (isStaleState(root.gestures.get(key), value, TERMINAL_GESTURE_STATES)) {
    root.staleStateDrops += 1;
    return false;
  }
  root.gestures.delete(key);
  root.gestures.set(key, value);
  root.lastActivityAt = Math.max(root.lastActivityAt, updatedAt);
  const trimmed = trimStateMap(
    root.gestures,
    MOTION_OBSERVABILITY_LIMITS.gestureStatesPerRoot,
    TERMINAL_GESTURE_STATES,
  );
  root.gestureStateEvictions += trimmed.evictions;
  emit(rootId, [viewId, ...trimmed.viewIds], "gesture");
  return true;
}

export type MotionAnimationStatePublish = Omit<
  MotionAnimationAgentState,
  "updatedAt" | "settled"
> & { updatedAt?: number; settled?: boolean };

export function publishMotionAnimationState(
  input: MotionAnimationStatePublish,
): boolean {
  const rootId = nonnegativeInteger(input.rootId, "rootId");
  const viewId = nonnegativeInteger(input.viewId, "viewId");
  const generation = positiveInteger(input.generation, "generation");
  const updatedAt = timestamp(input.updatedAt);
  identity(input.animationId, "animationId");
  identity(input.property, "property");
  identity(input.driver, "driver");
  enumValue(input.state, ANIMATION_STATES, "animation state");
  if (input.progress !== undefined) finite(input.progress, "progress");
  if (input.target !== undefined) finite(input.target, "target");
  const settled = TERMINAL_ANIMATION_STATES.has(input.state);
  if (input.settled !== undefined && input.settled !== settled) {
    throw new TypeError(
      "[motion-observability] settled must agree with animation state",
    );
  }
  const value = cloneAnimation({
    ...input,
    rootId,
    viewId,
    generation,
    updatedAt,
    settled,
  });
  const root = rootState(rootId);
  const key = animationKey(value);
  if (
    isStaleState(
      root.animations.get(key),
      value,
      TERMINAL_ANIMATION_STATES,
    )
  ) {
    root.staleStateDrops += 1;
    return false;
  }
  root.animations.delete(key);
  root.animations.set(key, value);
  root.lastActivityAt = Math.max(root.lastActivityAt, updatedAt);
  const trimmed = trimStateMap(
    root.animations,
    MOTION_OBSERVABILITY_LIMITS.animationStatesPerRoot,
    TERMINAL_ANIMATION_STATES,
  );
  root.animationStateEvictions += trimmed.evictions;
  emit(rootId, [viewId, ...trimmed.viewIds], "animation");
  return true;
}

export type MotionRetentionStatePublish = Omit<
  MotionRetentionAgentState,
  "updatedAt"
> & { updatedAt?: number };

export function publishMotionRetentionState(
  input: MotionRetentionStatePublish,
): boolean {
  const rootId = nonnegativeInteger(input.rootId, "rootId");
  const generation = positiveInteger(input.generation, "generation");
  const updatedAt = timestamp(input.updatedAt);
  identity(input.retentionId, "retentionId");
  identity(input.kind, "retention kind");
  enumValue(input.state, RETENTION_STATES, "retention state");
  const viewIds = Array.from(
    new Set(input.viewIds.map((viewId) => nonnegativeInteger(viewId, "viewId"))),
  ).sort((left, right) => left - right);
  const value = cloneRetention({
    ...input,
    rootId,
    generation,
    updatedAt,
    viewIds,
  });
  const root = rootState(rootId);
  if (
    isStaleState(
      root.retentions.get(value.retentionId),
      value,
      TERMINAL_RETENTION_STATES,
    )
  ) {
    root.staleStateDrops += 1;
    return false;
  }
  root.retentions.delete(value.retentionId);
  root.retentions.set(value.retentionId, value);
  root.lastActivityAt = Math.max(root.lastActivityAt, updatedAt);
  const trimmed = trimStateMap(
    root.retentions,
    MOTION_OBSERVABILITY_LIMITS.retentionsPerRoot,
    TERMINAL_RETENTION_STATES,
  );
  root.retentionStateEvictions += trimmed.evictions;
  emit(rootId, viewIds, "retention");
  return true;
}

function validateDismissCommand(
  command: MotionDismissLayerAgentState["command"],
): MotionDismissLayerAgentState["command"] {
  if (!command) return undefined;
  return {
    commandInstanceId: identity(command.commandInstanceId, "dismiss command instance"),
    action: identity(command.action, "dismiss command action"),
    ownerInstance: identity(command.ownerInstance, "dismiss command owner"),
    bindingGeneration: positiveInteger(
      command.bindingGeneration,
      "dismiss command generation",
    ),
  };
}

/**
 * Replace the agent mirror from the renderer-owned dismiss-stack authority.
 * This is a projection boundary: callers cannot incrementally invent layers.
 */
export function replaceMotionDismissLayerProjection(input: {
  rootId: number;
  layers: readonly MotionDismissLayerAgentState[];
  receipts: readonly MotionDismissLayerAgentReceipt[];
  updatedAt?: number;
}): void {
  const rootId = nonnegativeInteger(input.rootId, "rootId");
  const updatedAt = timestamp(input.updatedAt);
  const nextLayers = new Map<string, MotionDismissLayerAgentState>();
  for (const layer of input.layers) {
    if (nonnegativeInteger(layer.rootId, "dismiss layer rootId") !== rootId) {
      throw new TypeError("[motion-observability] dismiss layer root mismatch");
    }
    const layerId = identity(layer.layerId, "dismiss layerId");
    if (nextLayers.has(layerId)) {
      throw new TypeError(`[motion-observability] duplicate dismiss layer ${layerId}`);
    }
    const portalOrder = finite(layer.portalOrder, "dismiss portalOrder");
    const visualOrder = finite(layer.visualOrder, "dismiss visualOrder");
    if (typeof layer.modal !== "boolean" || typeof layer.topmost !== "boolean") {
      throw new TypeError("[motion-observability] dismiss layer flags must be boolean");
    }
    nextLayers.set(layerId, {
      rootId,
      layerId,
      ...(layer.parentId === undefined
        ? {}
        : { parentId: identity(layer.parentId, "dismiss parentId") }),
      ...(layer.viewId === undefined
        ? {}
        : { viewId: nonnegativeInteger(layer.viewId, "dismiss viewId") }),
      generation: positiveInteger(layer.generation, "dismiss layer generation"),
      modal: layer.modal,
      portalOrder,
      visualOrder,
      mountSequence: positiveInteger(layer.mountSequence, "dismiss mountSequence"),
      topmost: layer.topmost,
      ...(layer.triggers === undefined
        ? {}
        : {
            triggers: layer.triggers.map((trigger) => {
              if (trigger !== "escape" && trigger !== "outside-press" && trigger !== "swipe-down") {
                throw new TypeError(`[motion-observability] invalid dismiss trigger ${trigger}`);
              }
              return trigger;
            }),
          }),
      ...(layer.activeClaimGestureId === undefined
        ? {}
        : {
            activeClaimGestureId: identity(
              layer.activeClaimGestureId,
              "dismiss active claim",
            ),
          }),
      ...(layer.command ? { command: validateDismissCommand(layer.command)! } : {}),
    });
  }
  const nextReceipts = input.receipts.map((entry) => {
    if (nonnegativeInteger(entry.rootId, "dismiss receipt rootId") !== rootId) {
      throw new TypeError("[motion-observability] dismiss receipt root mismatch");
    }
    if (
      entry.kind !== "topmost-claim" &&
      entry.kind !== "structural-cancel" &&
      entry.kind !== "dismiss"
    ) {
      throw new TypeError("[motion-observability] invalid dismiss receipt kind");
    }
    return {
      rootId,
      sequence: positiveInteger(entry.sequence, "dismiss receipt sequence"),
      layerId: identity(entry.layerId, "dismiss receipt layerId"),
      generation: positiveInteger(entry.generation, "dismiss receipt generation"),
      kind: entry.kind,
      decision: identity(entry.decision, "dismiss receipt decision"),
      ...(entry.gestureId === undefined
        ? {}
        : { gestureId: identity(entry.gestureId, "dismiss receipt gestureId") }),
      ...(entry.command ? { command: validateDismissCommand(entry.command)! } : {}),
      timestampMs: timestamp(entry.timestampMs),
    } satisfies MotionDismissLayerAgentReceipt;
  });

  const root = rootState(rootId);
  const affectedViewIds = new Set<number>();
  root.dismissLayers.forEach((layer) => {
    if (layer.viewId !== undefined) affectedViewIds.add(layer.viewId);
  });
  nextLayers.forEach((layer) => {
    if (layer.viewId !== undefined) affectedViewIds.add(layer.viewId);
  });
  root.dismissLayers = nextLayers;
  root.dismissReceipts = nextReceipts.map(cloneDismissReceipt);
  root.lastActivityAt = Math.max(root.lastActivityAt, updatedAt);
  emit(rootId, affectedViewIds, "dismiss");
}

export type MotionArbitrationReceiptPublish = Omit<
  MotionArbitrationReceipt,
  "sequence" | "sourceSequence" | "timestampMs"
> & { sequence?: number | string; timestampMs?: number };

/** Append one arena outcome. A supplied source sequence is monotonic per root. */
export function recordMotionArbitrationReceipt(
  input: MotionArbitrationReceiptPublish,
): boolean {
  const rootId = nonnegativeInteger(input.rootId, "rootId");
  const root = rootState(rootId);
  const sourceSequence = input.sequence === undefined
    ? undefined
    : positiveU64Identity(input.sequence, "receipt sequence");
  if (sourceSequence !== undefined) {
    if (sourceSequence.comparable <= root.lastSourceReceiptSequence) {
      root.staleReceiptDrops += 1;
      return false;
    }
  }
  const timestampMs = timestamp(input.timestampMs);
  const receipt: MotionArbitrationReceipt = cloneReceipt({
    ...input,
    rootId,
    sequence: root.nextReceiptSequence + 1,
    ...(sourceSequence !== undefined ? { sourceSequence: sourceSequence.value } : {}),
    timestampMs,
    streamId: positiveU64Identity(input.streamId, "streamId").value,
    profileGeneration: nonnegativeInteger(
      input.profileGeneration,
      "profileGeneration",
    ),
    claimSetGeneration: nonnegativeInteger(
      input.claimSetGeneration,
      "claimSetGeneration",
    ),
    gestureId: identity(input.gestureId, "gestureId"),
    inputKind: identity(input.inputKind, "inputKind"),
    ruleCode: identity(input.ruleCode, "ruleCode"),
    ...(input.viewId !== undefined
      ? { viewId: nonnegativeInteger(input.viewId, "viewId") }
      : {}),
    hitPath: input.hitPath.map((viewId) => nonnegativeInteger(viewId, "hitPath")),
    contenders: input.contenders.map((contender) => ({
      ...contender,
      claimId: identity(contender.claimId, "contender.claimId"),
      eligible:
        typeof contender.eligible === "boolean"
          ? contender.eligible
          : (() => {
              throw new TypeError(
                "[motion-observability] contender.eligible must be boolean",
              );
            })(),
    })),
    ...(input.winner
      ? {
          winner: {
            ...input.winner,
            claimId: identity(input.winner.claimId, "winner.claimId"),
          },
        }
      : {}),
  });
  if (sourceSequence !== undefined) {
    root.lastSourceReceiptSequence = sourceSequence.comparable;
  }
  root.nextReceiptSequence = receipt.sequence;
  root.receipts.push(receipt);
  root.lastActivityAt = Math.max(root.lastActivityAt, timestampMs);
  while (
    root.receipts.length >
    MOTION_OBSERVABILITY_LIMITS.arbitrationReceiptsPerRoot
  ) {
    root.receipts.shift();
    root.arbitrationReceiptEvictions += 1;
  }
  emit(rootId, receipt.viewId === undefined ? [] : [receipt.viewId], "receipt");
  return true;
}

export function getMotionNodeObservability(
  viewId: number,
  rootId?: number,
): {
  gestures: MotionGestureAgentState[];
  animations: MotionAnimationAgentState[];
  dismissLayers: MotionDismissLayerAgentState[];
} {
  const roots =
    rootId === undefined
      ? store().roots.values()
      : [store().roots.get(rootId)].filter(
          (root): root is RootMotionState => root !== undefined,
        );
  const gestures: MotionGestureAgentState[] = [];
  const animations: MotionAnimationAgentState[] = [];
  const dismissLayers: MotionDismissLayerAgentState[] = [];
  for (const root of roots) {
    for (const value of root.gestures.values()) {
      if (value.viewId === viewId) gestures.push(cloneGesture(value));
    }
    for (const value of root.animations.values()) {
      if (value.viewId === viewId) animations.push(cloneAnimation(value));
    }
    for (const value of root.dismissLayers.values()) {
      if (value.viewId === viewId) dismissLayers.push(cloneDismissLayer(value));
    }
  }
  gestures.sort((left, right) =>
    left.gestureId.localeCompare(right.gestureId) ||
    (left.invocationId ?? "").localeCompare(right.invocationId ?? ""),
  );
  animations.sort((left, right) =>
    left.animationId.localeCompare(right.animationId),
  );
  dismissLayers.sort((left, right) => left.mountSequence - right.mountSequence);
  return { gestures, animations, dismissLayers };
}

export function findMotionGestureStates(options: {
  rootId: number;
  viewId?: number;
  gestureId?: string;
}): MotionGestureAgentState[] {
  const root = store().roots.get(options.rootId);
  if (!root) return [];
  return Array.from(root.gestures.values())
    .filter(
      (value) =>
        (options.viewId === undefined || value.viewId === options.viewId) &&
        (options.gestureId === undefined || value.gestureId === options.gestureId),
    )
    .map(cloneGesture)
    .sort((left, right) =>
      left.gestureId.localeCompare(right.gestureId) ||
      (left.invocationId ?? "").localeCompare(right.invocationId ?? ""),
    );
}

export function getMotionObservabilitySnapshot(
  rootId: number,
): MotionObservabilityData {
  const root = store().roots.get(rootId) ?? newRootState();
  const gestures = Array.from(root.gestures.values())
    .map(cloneGesture)
    .sort(
      (left, right) =>
        left.viewId - right.viewId ||
        left.gestureId.localeCompare(right.gestureId) ||
        (left.invocationId ?? "").localeCompare(right.invocationId ?? ""),
    );
  const animations = Array.from(root.animations.values())
    .map(cloneAnimation)
    .sort(
      (left, right) =>
        left.viewId - right.viewId ||
        left.animationId.localeCompare(right.animationId),
    );
  const retentions = Array.from(root.retentions.values())
    .map(cloneRetention)
    .sort((left, right) => left.retentionId.localeCompare(right.retentionId));
  const dismissLayers = Array.from(root.dismissLayers.values())
    .map(cloneDismissLayer)
    .sort((left, right) => left.mountSequence - right.mountSequence);
  return {
    schemaVersion: 1,
    generation: store().generation,
    rootId,
    gestures,
    animations,
    retentions,
    dismissLayers,
    dismissReceipts: root.dismissReceipts.map(cloneDismissReceipt),
    arbitrationReceipts: root.receipts.map(cloneReceipt),
    activeDriverCount: animations.filter((value) =>
      ACTIVE_ANIMATION_STATES.has(value.state),
    ).length,
    activeRetentionCount: retentions.filter(
      (value) => value.state === "retaining",
    ).length,
    lastActivityAt: root.lastActivityAt,
    bounds: {
      gestureStateCapacity: MOTION_OBSERVABILITY_LIMITS.gestureStatesPerRoot,
      animationStateCapacity:
        MOTION_OBSERVABILITY_LIMITS.animationStatesPerRoot,
      retentionStateCapacity: MOTION_OBSERVABILITY_LIMITS.retentionsPerRoot,
      arbitrationReceiptCapacity:
        MOTION_OBSERVABILITY_LIMITS.arbitrationReceiptsPerRoot,
      gestureStateEvictions: root.gestureStateEvictions,
      animationStateEvictions: root.animationStateEvictions,
      retentionStateEvictions: root.retentionStateEvictions,
      arbitrationReceiptEvictions: root.arbitrationReceiptEvictions,
      staleStateDrops: root.staleStateDrops,
      staleReceiptDrops: root.staleReceiptDrops,
    },
  };
}

export function getMotionSettlingState(rootId: number): {
  activeDriverCount: number;
  activeRetentionCount: number;
  activeCount: number;
  lastActivityAt: number;
} {
  const root = store().roots.get(rootId);
  if (!root) {
    return {
      activeDriverCount: 0,
      activeRetentionCount: 0,
      activeCount: 0,
      lastActivityAt: 0,
    };
  }
  const animations = Array.from(root.animations.values());
  const retentions = Array.from(root.retentions.values());
  const activeDriverCount = animations.filter((value) =>
    ACTIVE_ANIMATION_STATES.has(value.state),
  ).length;
  const activeRetentionCount = retentions.filter(
    (value) => value.state === "retaining",
  ).length;
  const lastActivityAt = [...animations, ...retentions].reduce(
    (latest, value) => Math.max(latest, value.updatedAt),
    0,
  );
  return {
    activeDriverCount,
    activeRetentionCount,
    activeCount: activeDriverCount + activeRetentionCount,
    lastActivityAt,
  };
}

export function clearMotionNodeObservability(rootId: number, viewId: number): void {
  const root = store().roots.get(rootId);
  if (!root) return;
  for (const [key, value] of root.gestures) {
    if (value.viewId === viewId) root.gestures.delete(key);
  }
  for (const [key, value] of root.animations) {
    if (value.viewId === viewId) root.animations.delete(key);
  }
  for (const [key, value] of root.retentions) {
    if (!value.viewIds.includes(viewId)) continue;
    const remainingViewIds = value.viewIds.filter((candidate) => candidate !== viewId);
    if (remainingViewIds.length === 0) {
      root.retentions.delete(key);
    } else {
      root.retentions.set(key, { ...value, viewIds: remainingViewIds });
    }
  }
  for (const [key, value] of root.dismissLayers) {
    if (value.viewId === viewId) root.dismissLayers.delete(key);
  }
  emit(rootId, [viewId], "clear");
}

export function clearMotionRootObservability(rootId: number): void {
  if (store().roots.delete(rootId)) emit(rootId, [], "clear");
}

/** Test/runtime reset. Listener identity survives so renderer subscriptions remain valid. */
export function resetMotionObservabilityState(): void {
  const current = store();
  const rootIds = Array.from(current.roots.keys());
  current.roots.clear();
  current.generation += 1;
  for (const rootId of rootIds) emit(rootId, [], "clear");
}
