// Stable package surface; the inventory-derived identity lives in the
// generated neighbor and is freshness-gated by motion-conformance.
export * from './motion-schema.generated.js';

import {
  MOTION_SCHEMA_DISPATCH_PAYLOAD_LENGTH_OFFSET,
  MOTION_SCHEMA_DISPATCH_PREFIX,
} from './motion-schema.generated.js';

/** Wrap one app protocol frame in the inventory-derived Motion identity.
 * Native hosts validate and strip every envelope before kernel ingress. */
export function wrapMotionSchemaDispatchEnvelope(payload: Uint8Array): Uint8Array {
  const wrapped = new Uint8Array(MOTION_SCHEMA_DISPATCH_PREFIX.length + payload.length);
  wrapped.set(MOTION_SCHEMA_DISPATCH_PREFIX);
  new DataView(wrapped.buffer).setUint32(
    MOTION_SCHEMA_DISPATCH_PAYLOAD_LENGTH_OFFSET,
    payload.length,
    true,
  );
  wrapped.set(payload, MOTION_SCHEMA_DISPATCH_PREFIX.length);
  return wrapped;
}
