import type { CanonicalProps } from '../types.js';

export type ImageCanonicalTagType = 'image' | 'svg';

export interface ImagePropsRuntime {
  normalize(
    tagType: ImageCanonicalTagType,
    props: Record<string, unknown>,
    isRNStyle: boolean,
    canonical: CanonicalProps,
  ): void;
}

let installedRuntime: ImagePropsRuntime | undefined;

export function installImagePropsRuntime(runtime: ImagePropsRuntime): void {
  installedRuntime = runtime;
}

export function normalizeImageProps(
  tagType: ImageCanonicalTagType,
  props: Record<string, unknown>,
  isRNStyle: boolean,
  canonical: CanonicalProps,
): void {
  if (!installedRuntime) {
    throw new Error(
      `[exact-renderer] ${tagType} prop normalization requires the image runtime; ` +
      'import @exact/renderer/image-props-production before mounting this surface.',
    );
  }
  installedRuntime.normalize(tagType, props, isRNStyle, canonical);
}

export function _resetImagePropsRuntimeForTests(): void {
  installedRuntime = undefined;
}
