// @system @ref LLP 0420 §3/§4/§6/§8 — the native leg of a Contract `graphics`
// surface: the module-backed `nativeView` mount, the epoch handshake, the
// publication writer, and the pointer/size republication.
//
// WHY A `nativeView` LEAF AND NOT A STYLED HOST ELEMENT.
// A Contract behavior cannot measure its own element — there is no `onLayout`,
// `motion.measure` is DOM-only, and `bounds()` is null on native (LLP 0353 SG1
// D). The painter view therefore has to report its own box, and a module-backed
// leaf is the only mount shape that owns a real platform view able to do that.
// The same view is where the platform's pointer input arrives, so one leaf
// carries both §8 channels.
//
// WHAT DOES *NOT* TRAVEL AS A PROP. The scene does not. `nativeViewProps`
// carries only mount-frozen surface policy — `surfaceId` (a diagnostics label),
// `backendId`, `viewBox`, `gestureClaim`. The scene rides opcodes 40/41, keyed
// by the mounted node's PROTOCOL VIEW ID, which is the envelope's
// `surfaceViewId`. There is no string surface key on the wire.
//
// THIS MODULE IS THE DEFERRED HALF (LLP 0128). The backend gate, the tag, and
// the identity constants live in `../graphics-native-gate.js` because a
// Contract mount has to answer "native leaf or LLP 0352 placeholder?"
// synchronously; everything below only runs once a surface has actually
// mounted, so it reaches the runtime through `../graphics-lazy.js`. Re-exported
// here so `@exact/renderer/graphics-native-surface` still carries the whole §3
// surface for the loaded path and for tests.

import type {
  GraphicsPointerEvent,
  GraphicsSurfaceSize,
} from '@exact/graphics/contract';

import {
  GRAPHICS_SCENE_EVENT_NAME,
  _resetGraphicsSceneNativeViewTagForTests,
} from '../graphics-native-gate.js';
import { getRootContainerForNode } from '../host-ops.js';
import { createProtocolEncoder, dispatchProtocol } from '../protocol/encoder.js';
import type { ElementNode } from '../nodes/node.js';
import {
  createScenePublisher,
  type GraphicsWireRecord,
  type PublishableScene,
  type ScenePublisher,
  type ScenePublisherDiagnostic,
} from './scene-protocol.js';

export {
  GRAPHICS_APPLE_BACKEND_ID,
  GRAPHICS_SCENE_EVENT_NAME,
  GRAPHICS_SCENE_MODULE_NAME,
  graphicsSceneNativeViewTag,
  hasGraphicsProtocolHost,
} from '../graphics-native-gate.js';

// ---------------------------------------------------------------------------
// Wire writing
// ---------------------------------------------------------------------------

/**
 * One dedicated encoder per root, NOT the root's commit encoder.
 *
 * Publications are produced on the scene's own flush cadence (a microtask
 * behind an rAF driver), which is not the reconciler's commit cadence. Writing
 * into the shared commit encoder would mean either holding chunks until the
 * next unrelated commit — a scene that stops committing would freeze on the
 * host — or flushing a batch some other caller was still staging. A dedicated
 * encoder is still the ordinary command buffer: same `exact.dispatch`, same
 * batch decode, same commit executor on the host side.
 *
 * Refcounted rather than kept forever. `BufferWriter.ensureCapacity` doubles,
 * and a publication body is bounded at 8 MiB (§4), so one large publication
 * grows the buffer to ~16 MB — which a module-level cache then pins for the
 * process lifetime, long after the root it belonged to was torn down. The
 * count is per ROOT, not per surface, so two surfaces on one root still share
 * the one encoder and the entry only drops when the last of them disposes.
 */
interface RootEncoder {
  readonly encoder: ReturnType<typeof createProtocolEncoder>;
  /** Surfaces currently bound to this root; the entry drops at zero. */
  surfaces: number;
}

const encodersByRoot = new Map<number, RootEncoder>();

function retainEncoderForRoot(rootId: number): void {
  const entry = encodersByRoot.get(rootId);
  if (entry) {
    entry.surfaces += 1;
    return;
  }
  encodersByRoot.set(rootId, { encoder: createProtocolEncoder(64 * 1024, rootId), surfaces: 1 });
}

function releaseEncoderForRoot(rootId: number): void {
  const entry = encodersByRoot.get(rootId);
  if (!entry) return;
  entry.surfaces -= 1;
  if (entry.surfaces <= 0) encodersByRoot.delete(rootId);
}

function encoderForRoot(rootId: number): ReturnType<typeof createProtocolEncoder> {
  // A write outside a bound surface's lifetime cannot happen — `bind` retains
  // before any publisher exists and `dispose` releases only after `teardown()`
  // has written — but if one ever did, it gets a transient encoder rather than
  // a cached one: re-caching here would re-pin the buffer the release above
  // exists to hand back.
  return encodersByRoot.get(rootId)?.encoder ?? createProtocolEncoder(64 * 1024, rootId);
}

/** @internal test seam — drops the cached per-root encoders. */
export function _resetGraphicsTransportForTests(): void {
  encodersByRoot.clear();
  _resetGraphicsSceneNativeViewTagForTests();
}

/** @internal test seam — the roots currently holding a retained encoder. */
export function _graphicsEncoderRootsForTests(): number[] {
  return [...encodersByRoot.keys()];
}

function writeWireRecord(rootId: number, record: GraphicsWireRecord): void {
  const encoder = encoderForRoot(rootId);
  if (record.kind === 'publication') {
    for (const chunk of record.chunks) {
      encoder.graphicsPublicationChunk(record.surfaceViewId, chunk);
    }
  } else {
    encoder.graphicsSceneTeardown(record.surfaceViewId, record.payload);
  }
  dispatchProtocol(encoder);
}

// ---------------------------------------------------------------------------
// Event payloads
// ---------------------------------------------------------------------------

function readNumber(source: Record<string, unknown>, key: string): number | null {
  const value = source[key];
  return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function pointerPhase(value: unknown): GraphicsPointerEvent['phase'] | null {
  return value === 'down' || value === 'move' || value === 'up' || value === 'cancel'
    ? value
    : null;
}

// ---------------------------------------------------------------------------
// The binding
// ---------------------------------------------------------------------------

export interface NativeGraphicsSurfaceSink {
  emitPointer(event: GraphicsPointerEvent): void;
  emitSize(size: GraphicsSurfaceSize): void;
}

export interface NativeGraphicsSurfaceOptions {
  /** The surface's scene — the publication source. */
  readonly scene: PublishableScene;
  /** Author-visible surface key; diagnostics only, never wire identity. */
  readonly surfaceId: string;
  /** Where §8's two streams are republished. Absent for an anonymous scene. */
  readonly sink?: NativeGraphicsSurfaceSink | undefined;
  /**
   * `'mouse'` on the AppKit arm, `'touch'` on UIKit. The wire does not carry
   * it: the platform arm is a property of the host, not of the sample.
   */
  readonly pointerType?: GraphicsPointerEvent['pointerType'];
  readonly onDiagnostic?: (diagnostic: ScenePublisherDiagnostic) => void;
}

export interface NativeGraphicsSurfaceBinding {
  /** Pass as the element's `onNativeViewEvent` prop AT CREATION. */
  readonly onNativeViewEvent: (eventName: string, payload: unknown) => void;
  /** Call once with the mounted host element; idempotent. */
  bind(element: ElementNode): void;
  /** Emits the opcode-41 teardown and stops publishing. */
  dispose(): void;
  /** @internal introspection for tests. */
  readonly publisher: ScenePublisher | null;
}

/**
 * Wire one native graphics surface: publisher, epoch handshake, and the §8
 * stream republication.
 *
 * THE HANDSHAKE, IN ORDER (§3):
 *   1. this mount creates the `nativeView` leaf; its protocol view id is the
 *      envelope's `surfaceViewId`;
 *   2. the host view attaches to the consumer's committed-scene store, which
 *      MINTS the epoch (or returns the one this surface already holds) and
 *      sends `{kind:"attach", sceneEpoch, consumerToken}` back over the module
 *      channel — the token identifies WHICH consumer granted it, because the
 *      epoch number repeats across consumer stores (§3);
 *   3. `grantEpoch` releases the publisher — nothing at all is written before
 *      this point, because there is no epoch to stamp;
 *   4. every envelope from then on echoes that epoch, and the consumer
 *      discards anything that does not match it by equality.
 */
export function createNativeGraphicsSurface(
  options: NativeGraphicsSurfaceOptions,
): NativeGraphicsSurfaceBinding {
  const pointerType = options.pointerType ?? 'mouse';
  let publisher: ScenePublisher | null = null;
  let disposed = false;
  let boundNodeId: number | null = null;
  /** The root whose encoder this surface retained, so `dispose` releases the
   * same one `bind` took (and releases nothing when `bind` never ran). */
  let retainedRootId: number | null = null;
  /** Payloads that arrive before `bind` (they cannot, but a dropped grant is
   * an unrecoverable blank surface, so the ordering is not assumed). The
   * consumer identity travels WITH the epoch: replaying the number alone would
   * hand the publisher a tokenless grant and defeat §3's same-consumer test. */
  let pendingGrant: { epoch: bigint; consumerToken?: string } | null = null;

  const report = (code: string, message: string): void => {
    options.onDiagnostic?.({
      code: 'graphics_publication_write_failed',
      message: `[${code}] ${message}`,
    });
  };

  const handleAttach = (payload: Record<string, unknown>): void => {
    const raw = payload.sceneEpoch;
    let epoch: bigint;
    try {
      epoch = typeof raw === 'bigint' ? raw : BigInt(String(raw));
    } catch {
      report('graphics_attach_epoch_invalid', `attach carried sceneEpoch ${String(raw)}`);
      return;
    }
    if (epoch <= 0n) {
      report('graphics_attach_epoch_invalid', `attach carried sceneEpoch ${String(raw)}`);
      return;
    }
    // §3's consumer identity. A host that omits it leaves the field undefined
    // rather than sending a placeholder, because the publisher answers "no
    // token" by re-projecting — the safe side — and a placeholder shared by two
    // different consumers would read as one and suppress the grant.
    const consumerToken = typeof payload.consumerToken === 'string' ? payload.consumerToken : undefined;
    if (publisher) publisher.grantEpoch(epoch, consumerToken);
    else pendingGrant = { epoch, ...(consumerToken === undefined ? {} : { consumerToken }) };
  };

  const handleLayout = (payload: Record<string, unknown>): void => {
    const width = readNumber(payload, 'width');
    const height = readNumber(payload, 'height');
    if (width === null || height === null) return;
    options.sink?.emitSize({
      width,
      height,
      scale: readNumber(payload, 'scale') ?? 1,
    });
  };

  const handlePointer = (payload: Record<string, unknown>): void => {
    const phase = pointerPhase(payload.phase);
    const x = readNumber(payload, 'x');
    const y = readNumber(payload, 'y');
    // `t` is CACurrentMediaTime() * 1000 on the host — monotonic by
    // construction. There is deliberately no JS-side fallback clock: a sample
    // stamped here would carry this thread's scheduling delay as if it were
    // input timing, and the velocity tracker cannot tell the difference.
    const timestampMs = readNumber(payload, 't');
    if (phase === null || x === null || y === null || timestampMs === null) return;
    options.sink?.emitPointer({
      phase,
      x,
      y,
      pointerId: readNumber(payload, 'pointerId') ?? 1,
      pointerType,
      timestampMs,
    });
  };

  const onNativeViewEvent = (eventName: string, payload: unknown): void => {
    if (disposed || eventName !== GRAPHICS_SCENE_EVENT_NAME) return;
    if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) return;
    const record = payload as Record<string, unknown>;
    switch (record.kind) {
      case 'attach':
        handleAttach(record);
        break;
      case 'layout':
        handleLayout(record);
        break;
      case 'pointer':
        handlePointer(record);
        break;
      case 'resync':
        // §2's drop-whole path: the consumer kept its last complete scene and
        // is asking for a full. `requestResync` forces the NEXT publication to
        // `full` and, when nothing is pending, projects one from the scene's
        // current snapshot immediately.
        publisher?.requestResync();
        break;
      default:
        break;
    }
  };

  return {
    onNativeViewEvent,
    bind(element: ElementNode) {
      if (disposed || boundNodeId !== null) return;
      const surfaceViewId = element.id;
      if (!Number.isInteger(surfaceViewId) || surfaceViewId <= 0) return;
      boundNodeId = surfaceViewId;
      const rootId = getRootContainerForNode(element)?.rootId ?? 0;
      retainEncoderForRoot(rootId);
      retainedRootId = rootId;
      publisher = createScenePublisher({
        scene: options.scene,
        surfaceViewId,
        write: (record) => {
          writeWireRecord(rootId, record);
          if (record.kind === 'publication') {
            // §6 lag bound, honestly. v1 has NO wire acknowledgment (§2):
            // `appliedGeneration` is consumer-local state. The consumer
            // applies accepted batches in FIFO order in-process, and any
            // publication it cannot apply comes back as a resync request — so
            // acceptance of the dispatch is the producer's only, and
            // sufficient, ack proxy. Without it the outstanding set never
            // drains and EVERY publication past the second converts to `full`,
            // which on a 600-node page is a full JSON scene per frame.
            publisher?.noteApplied(record.commitGeneration);
          }
        },
        ...(options.onDiagnostic ? { onDiagnostic: options.onDiagnostic } : {}),
      });
      // The host view may already have granted before this binding existed
      // (the module event channel is not ordered against the mount return).
      if (pendingGrant !== null) {
        publisher.grantEpoch(pendingGrant.epoch, pendingGrant.consumerToken);
        pendingGrant = null;
      }
    },
    dispose() {
      if (disposed) return;
      disposed = true;
      // Teardown BEFORE unregistering: `teardown()` writes opcode 41 for the
      // granted epoch, which is what retires the consumer's retained scene.
      publisher?.teardown();
      publisher = null;
      pendingGrant = null;
      boundNodeId = null;
      // AFTER the teardown write: releasing first would hand the last surface
      // on this root a transient encoder for its opcode-41 record.
      if (retainedRootId !== null) {
        releaseEncoderForRoot(retainedRootId);
        retainedRootId = null;
      }
      // The module event handler is host-ops' registration (it owns the
      // nativeView bridge slot keyed by node id) and host-ops releases it when
      // the element is destroyed. `disposed` above makes any event that races
      // that release a no-op.
    },
    get publisher() {
      return publisher;
    },
  };
}
