// @system @ref LLP 0420 §2/§3/§4/§6 — the TypeScript producer side of the
// semantic-graphics publication transport.
//
// Three pure layers plus one small stateful publisher:
//
//   encodePublicationBody  — GraphicsOperation[] -> the reassembled body
//                            (magic "GSCN", UTF-8 JSON operations, a
//                            length-prefixed 4-byte-aligned column section).
//   decodePublicationBody  — the exact inverse. It exists so the round trip is
//                            provable without a Swift host, and so the Apple
//                            decoder has a reference implementation to match.
//   chunkPublication       — body -> one 56-byte-headered payload per protocol
//                            op (opcode 40), matching
//                            `kernel/src/graphics_transport.rs` field for field,
//                            plus the one payload digest every chunk carries.
//   createScenePublisher   — the consumer-minted epoch handshake (§3), commit
//                            subscription, squash + lag-bound flow control (§6),
//                            resync, and teardown (opcode 41).
//
// The encoder imports no protocol writer and touches no DOM: the caller owns
// the BufferWriter and hands this module a `write` callback. That keeps every
// byte fixture-testable and is what lets the same bytes be decoded by the Rust
// framing validator (see `tests/graphics/envelope/`).

import type {
  GraphicsCommit,
  GraphicsNodeRecord,
  GraphicsOperation,
  GraphicsSceneSnapshot,
} from '@exact/graphics';

/** Little-endian `"GSCN"`. Repeated in the chunk header and the body (§4). */
export const GRAPHICS_ENVELOPE_MAGIC = 0x4e_43_53_47;
export const GRAPHICS_WIRE_SCHEMA_VERSION = 1;
export const GRAPHICS_CHUNK_HEADER_SIZE = 56;
export const GRAPHICS_TEARDOWN_SIZE = 12;
export const GRAPHICS_MAX_OP_PAYLOAD = 65_535;
export const GRAPHICS_MAX_CHUNK_DATA = GRAPHICS_MAX_OP_PAYLOAD - GRAPHICS_CHUNK_HEADER_SIZE;
export const GRAPHICS_MAX_PUBLICATION_BYTES = 8 * 1024 * 1024;
/** magic(4) + version(2) + reserved(2) + operationsLength(4). */
export const GRAPHICS_BODY_HEADER_SIZE = 12;
/** byteLength(4) + dtype(1) + reserved(3). */
export const GRAPHICS_COLUMN_DESCRIPTOR_SIZE = 8;

const U64_MAX = 0xffff_ffff_ffff_ffffn;

export type GraphicsPublicationMode = 'full' | 'diff';
export type GraphicsColumnDtype = 'f32' | 'u32';
export type GraphicsColumnData = Float32Array | Uint32Array;

const DTYPE_CODE: Readonly<Record<GraphicsColumnDtype, number>> = { f32: 0, u32: 1 };

export interface GraphicsColumn {
  readonly dtype: GraphicsColumnDtype;
  readonly data: GraphicsColumnData;
}

export type GraphicsProtocolErrorCode =
  | 'invalid_magic'
  | 'schema_version_mismatch'
  | 'unexpected_end'
  | 'trailing_bytes'
  | 'non_zero_reserved'
  | 'invalid_operations'
  | 'invalid_json'
  | 'unsupported_column_dtype'
  | 'invalid_column_descriptor'
  | 'misaligned_column'
  | 'column_index_out_of_range'
  | 'publication_too_large'
  | 'chunk_too_large'
  | 'invalid_chunk_index'
  | 'chunk_envelope_mismatch'
  | 'missing_chunk'
  | 'duplicate_chunk'
  | 'chunk_size_mismatch'
  | 'payload_digest_mismatch'
  | 'unknown_publication_mode'
  | 'zero_identity'
  | 'full_publication_has_base_generation'
  | 'non_monotonic_base_generation';

/**
 * Typed transport failure. Every rejection path in this module raises this
 * rather than a raw `Error`, so a consumer can branch on `code` instead of
 * matching message text — §2's drop-whole classes are exactly these codes.
 */
export class GraphicsProtocolError extends Error {
  readonly code: GraphicsProtocolErrorCode;

  constructor(code: GraphicsProtocolErrorCode, message: string) {
    super(`[graphics-protocol] ${message}`);
    this.name = 'GraphicsProtocolError';
    this.code = code;
  }
}

const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder('utf-8', { fatal: true });

function align4(value: number): number {
  return (value + 3) & ~3;
}

function fail(code: GraphicsProtocolErrorCode, message: string): never {
  throw new GraphicsProtocolError(code, message);
}

// ---------------------------------------------------------------------------
// Digest
// ---------------------------------------------------------------------------

let digestCalls = 0;

/**
 * Test-only instrumentation: how many times {@link graphicsPayloadDigest} has
 * run in this process. Nothing in the production path reads it; it is the seam
 * the co-located suite uses to assert that one publication costs exactly one
 * digest pass (a module-internal call cannot be intercepted by a spy on the
 * exported binding, so the counter lives here instead).
 *
 * @internal
 */
export function graphicsDigestCallCount(): number {
  return digestCalls;
}

/**
 * FNV-1a 64 over the reassembled body — byte for byte the algorithm
 * `kernel/src/motion_transport.rs`'s `payload_digest` uses (offset basis
 * `0xcbf29ce484222325`, prime `0x100000001b3`), which is the digest the
 * graphics chunk header's `payload_digest` field carries.
 *
 * The hot loop runs on 32-bit halves with `Math.imul` rather than BigInt: this
 * runs once per published frame inside §7's 2.5 ms commit+encode budget, and a
 * BigInt multiply per byte costs roughly two orders of magnitude more. The
 * co-located test pins it against a naive BigInt implementation.
 *
 * It is also the single most expensive step in the publish path — on the §7
 * reference scene one pass is ~half of the whole encode+chunk cost — so the
 * producer computes it exactly once per publication, in
 * {@link chunkPublication}, and every other producer-side consumer reads that
 * value rather than recomputing it. {@link graphicsDigestCallCount} exists so
 * the co-located suite can hold that invariant.
 */
export function graphicsPayloadDigest(bytes: Uint8Array): bigint {
  digestCalls += 1;
  // 0xcbf29ce484222325
  let hi = 0xcbf2_9ce4;
  let lo = 0x8422_2325;
  for (let index = 0; index < bytes.length; index += 1) {
    lo = (lo ^ bytes[index]!) >>> 0;
    // (hi:lo) * 0x100000001b3, mod 2^64. prime = (0x100 << 32) | 0x1b3.
    const l0 = lo & 0xffff;
    const l1 = lo >>> 16;
    const t0 = l0 * 0x1b3;
    const t1 = l1 * 0x1b3 + (t0 >>> 16);
    const nextLo = (((t1 & 0xffff) << 16) | (t0 & 0xffff)) >>> 0;
    const carry = t1 >>> 16;
    hi = (Math.imul(hi, 0x1b3) + Math.imul(lo, 0x100) + carry) >>> 0;
    lo = nextLo;
  }
  return (BigInt(hi) << 32n) | BigInt(lo);
}

// ---------------------------------------------------------------------------
// Body encoding
// ---------------------------------------------------------------------------

export interface PublicationOperationsSource {
  readonly operations: readonly GraphicsOperation[];
}

export interface EncodePublicationBodyOptions {
  /** Defaults to `GRAPHICS_MAX_PUBLICATION_BYTES`; refused, never truncated. */
  readonly maxPublicationBytes?: number;
}

export interface EncodedPublicationBody {
  readonly bytes: Uint8Array;
  readonly opCount: number;
}

interface StagedColumn {
  readonly dtype: GraphicsColumnDtype;
  readonly bytes: Uint8Array;
}

function stageColumn(view: ArrayBufferView): StagedColumn {
  const raw = new Uint8Array(view.buffer, view.byteOffset, view.byteLength);
  if (view instanceof Float32Array) return { dtype: 'f32', bytes: raw };
  if (view instanceof Uint32Array) return { dtype: 'u32', bytes: raw };
  return fail(
    'unsupported_column_dtype',
    `only Float32Array and Uint32Array columns travel in v1; got ${view.constructor.name}`,
  );
}

function isColumnCandidate(value: unknown): value is ArrayBufferView {
  return ArrayBuffer.isView(value) && !(value instanceof DataView);
}

/**
 * Encode one publication body: the §4 header, the UTF-8 JSON operations
 * section, and the length-prefixed column section holding every externalized
 * typed array.
 *
 * Typed-array-valued props (the batch columns — `positions`, `radii`,
 * `colors`, `glyphs`, `itemIds`, and any sibling) are replaced in the JSON by
 * `{"__col": n}` and appended to the column section with their dtype, so the
 * decoder rebuilds the right view. Strings and plain numbers stay inline.
 */
export function encodePublicationBody(
  commit: PublicationOperationsSource,
  options: EncodePublicationBodyOptions = {},
): EncodedPublicationBody {
  const maxBytes = options.maxPublicationBytes ?? GRAPHICS_MAX_PUBLICATION_BYTES;
  const columns: StagedColumn[] = [];
  const json = JSON.stringify(commit.operations, (_key: string, value: unknown) => {
    if (isColumnCandidate(value)) {
      const index = columns.length;
      columns.push(stageColumn(value));
      return { __col: index };
    }
    return value;
  });
  const operationsBytes = textEncoder.encode(json ?? '[]');

  const columnCountOffset = align4(GRAPHICS_BODY_HEADER_SIZE + operationsBytes.length);
  let cursor = columnCountOffset + 4;
  const dataOffsets: number[] = [];
  for (const column of columns) {
    cursor += GRAPHICS_COLUMN_DESCRIPTOR_SIZE;
    cursor = align4(cursor);
    dataOffsets.push(cursor);
    cursor += column.bytes.length;
    cursor = align4(cursor);
  }
  const totalSize = cursor;
  if (totalSize > maxBytes) {
    fail(
      'publication_too_large',
      `publication body is ${totalSize} bytes; the bound is ${maxBytes}`,
    );
  }

  const bytes = new Uint8Array(totalSize);
  const view = new DataView(bytes.buffer);
  view.setUint32(0, GRAPHICS_ENVELOPE_MAGIC, true);
  view.setUint16(4, GRAPHICS_WIRE_SCHEMA_VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, operationsBytes.length, true);
  bytes.set(operationsBytes, GRAPHICS_BODY_HEADER_SIZE);
  view.setUint32(columnCountOffset, columns.length, true);
  let descriptorOffset = columnCountOffset + 4;
  for (let index = 0; index < columns.length; index += 1) {
    const column = columns[index]!;
    const dataOffset = dataOffsets[index]!;
    view.setUint32(descriptorOffset, column.bytes.length, true);
    view.setUint8(descriptorOffset + 4, DTYPE_CODE[column.dtype]);
    bytes.set(column.bytes, dataOffset);
    descriptorOffset = align4(dataOffset + column.bytes.length);
  }

  return { bytes, opCount: commit.operations.length };
}

// ---------------------------------------------------------------------------
// Body decoding
// ---------------------------------------------------------------------------

export interface DecodedPublicationBody {
  readonly operations: GraphicsOperation[];
  readonly columns: GraphicsColumn[];
}

function readColumns(bytes: Uint8Array, view: DataView, start: number): GraphicsColumn[] {
  if (start + 4 > bytes.length) {
    fail('unexpected_end', 'body ends before its column count');
  }
  const count = view.getUint32(start, true);
  // The count is a u32 off the wire. Nothing here reserves capacity from it, so
  // an absurd value would still be caught — but on the FIRST MISSING DESCRIPTOR
  // below, while the Swift decoder rejects it at the count itself
  // (`ExactGraphicsSceneProtocol.decodeColumns`). Two implementations rejecting
  // the same bytes with different codes at different points is exactly the
  // asymmetry the cross-language fixtures exist to catch, so mirror the Swift
  // bound and its error verbatim.
  if (count > Math.floor((bytes.length - start) / GRAPHICS_COLUMN_DESCRIPTOR_SIZE)) {
    fail(
      'invalid_column_descriptor',
      `body declares ${count} columns but is only ${bytes.length} bytes`,
    );
  }
  const columns: GraphicsColumn[] = [];
  let offset = start + 4;
  for (let index = 0; index < count; index += 1) {
    if (offset + GRAPHICS_COLUMN_DESCRIPTOR_SIZE > bytes.length) {
      fail('unexpected_end', `body ends inside column ${index}'s descriptor`);
    }
    const byteLength = view.getUint32(offset, true);
    const dtypeCode = view.getUint8(offset + 4);
    if (view.getUint8(offset + 5) !== 0 || view.getUint8(offset + 6) !== 0 || view.getUint8(offset + 7) !== 0) {
      fail('non_zero_reserved', `column ${index} has non-zero descriptor reserved bytes`);
    }
    const dtype: GraphicsColumnDtype | null =
      dtypeCode === 0 ? 'f32' : dtypeCode === 1 ? 'u32' : null;
    if (dtype === null) {
      fail('unsupported_column_dtype', `column ${index} declares unknown dtype ${dtypeCode}`);
    }
    if (byteLength % 4 !== 0) {
      fail(
        'invalid_column_descriptor',
        `column ${index} declares ${byteLength} bytes, which is not a whole number of 4-byte elements`,
      );
    }
    const dataOffset = align4(offset + GRAPHICS_COLUMN_DESCRIPTOR_SIZE);
    if (dataOffset % 4 !== 0) {
      fail('misaligned_column', `column ${index} data starts at ${dataOffset}`);
    }
    if (dataOffset + byteLength > bytes.length) {
      fail('unexpected_end', `body ends inside column ${index}'s data`);
    }
    const absolute = bytes.byteOffset + dataOffset;
    const elements = byteLength / 4;
    // Zero-copy when the host buffer happens to place the column on its
    // element boundary (the common case: a body allocated by this module or
    // reassembled into a fresh buffer). Otherwise copy rather than refuse — a
    // consumer must not lose a valid publication to its own buffer placement.
    const data: GraphicsColumnData =
      absolute % 4 === 0
        ? dtype === 'f32'
          ? new Float32Array(bytes.buffer, absolute, elements)
          : new Uint32Array(bytes.buffer, absolute, elements)
        : dtype === 'f32'
          ? new Float32Array(bytes.slice(dataOffset, dataOffset + byteLength).buffer)
          : new Uint32Array(bytes.slice(dataOffset, dataOffset + byteLength).buffer);
    columns.push({ dtype, data });
    offset = align4(dataOffset + byteLength);
  }
  return columns;
}

function isColumnMarker(value: unknown): value is { __col: number } {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  const keys = Object.keys(value);
  if (keys.length !== 1 || keys[0] !== '__col') return false;
  return typeof (value as { __col: unknown }).__col === 'number';
}

/**
 * The exact inverse of {@link encodePublicationBody}. A bad magic, an
 * unsupported schema version, a malformed column section, or an out-of-range
 * `{"__col": n}` marker raises a typed {@link GraphicsProtocolError} — never a
 * raw throw and never a partial result, per §2's drop-whole rule.
 */
export function decodePublicationBody(bytes: Uint8Array): DecodedPublicationBody {
  if (bytes.length < GRAPHICS_BODY_HEADER_SIZE) {
    fail('unexpected_end', `body is ${bytes.length} bytes; the header alone is ${GRAPHICS_BODY_HEADER_SIZE}`);
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  if (view.getUint32(0, true) !== GRAPHICS_ENVELOPE_MAGIC) {
    fail('invalid_magic', 'body does not start with "GSCN"');
  }
  const schemaVersion = view.getUint16(4, true);
  if (schemaVersion !== GRAPHICS_WIRE_SCHEMA_VERSION) {
    fail('schema_version_mismatch', `body declares schema version ${schemaVersion}`);
  }
  if (view.getUint16(6, true) !== 0) {
    fail('non_zero_reserved', 'body reserved u16 is non-zero');
  }
  const operationsLength = view.getUint32(8, true);
  if (GRAPHICS_BODY_HEADER_SIZE + operationsLength > bytes.length) {
    fail('unexpected_end', `body declares ${operationsLength} operation bytes but holds fewer`);
  }
  const columns = readColumns(bytes, view, align4(GRAPHICS_BODY_HEADER_SIZE + operationsLength));

  let json: string;
  try {
    json = textDecoder.decode(
      bytes.subarray(GRAPHICS_BODY_HEADER_SIZE, GRAPHICS_BODY_HEADER_SIZE + operationsLength),
    );
  } catch {
    fail('invalid_json', 'operations section is not valid UTF-8');
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(json, (_key: string, value: unknown) => {
      if (!isColumnMarker(value)) return value;
      const index = value.__col;
      if (!Number.isInteger(index) || index < 0 || index >= columns.length) {
        fail('column_index_out_of_range', `{"__col": ${index}} has no column`);
      }
      return columns[index]!.data;
    });
  } catch (error) {
    if (error instanceof GraphicsProtocolError) throw error;
    return fail('invalid_json', `operations section did not parse: ${String(error)}`);
  }

  if (!Array.isArray(parsed)) {
    fail('invalid_operations', 'operations section is not a JSON array');
  }
  for (const entry of parsed) {
    if (typeof entry !== 'object' || entry === null || typeof (entry as { type?: unknown }).type !== 'string') {
      fail('invalid_operations', 'every operation must be an object with a string `type`');
    }
  }

  return { operations: parsed as GraphicsOperation[], columns };
}

// ---------------------------------------------------------------------------
// Chunking
// ---------------------------------------------------------------------------

export interface ChunkPublicationInput {
  readonly body: Uint8Array;
  readonly surfaceViewId: number;
  readonly sceneEpoch: bigint;
  readonly commitGeneration: bigint;
  readonly mode: GraphicsPublicationMode;
  readonly baseCommitGeneration?: bigint;
  readonly opCount: number;
}

/**
 * What {@link chunkPublication} produces: the protocol payloads, plus the
 * envelope facts it had to compute to write those headers.
 *
 * `payloadDigest` is returned rather than left implicit in the header bytes
 * because it is the expensive part of chunking (§7): a caller that also needs
 * the digest — the publisher's wire record does — must read it from here
 * instead of paying for a second pass over the body.
 */
export interface ChunkedPublication {
  /** One protocol payload per `graphicsPublicationChunk(viewId, payload)`. */
  readonly chunks: Uint8Array[];
  /** The FNV-1a 64 digest carried, identically, by every chunk header. */
  readonly payloadDigest: bigint;
  /** The reassembled body's byte length, as written into each header. */
  readonly totalSize: number;
}

export interface GraphicsChunkHeader {
  readonly schemaVersion: number;
  readonly surfaceViewId: number;
  readonly sceneEpoch: bigint;
  readonly commitGeneration: bigint;
  readonly mode: GraphicsPublicationMode;
  readonly baseCommitGeneration: bigint;
  readonly opCount: number;
  readonly chunkIndex: number;
  readonly chunkCount: number;
  readonly totalSize: number;
  readonly payloadDigest: bigint;
}

function requireU32(value: number, field: string): number {
  if (!Number.isInteger(value) || value < 0 || value > 0xffff_ffff) {
    fail('invalid_operations', `${field} must be a u32; got ${value}`);
  }
  return value;
}

function requireU64(value: bigint, field: string): bigint {
  if (value < 0n || value > U64_MAX) {
    fail('invalid_operations', `${field} must be a u64; got ${value}`);
  }
  return value;
}

/**
 * Split one publication body into protocol payloads, each carrying the §4
 * 56-byte little-endian header. Validation mirrors
 * `GraphicsPublicationChunk::validate` in the kernel exactly, so a payload this
 * function returns can only be rejected there by a transport fault, never by a
 * producer-side framing bug.
 *
 * The body is digested once here; the digest comes back on the result so no
 * caller has to re-derive it (§7's encode budget does not have room to hash the
 * same body twice).
 */
export function chunkPublication(input: ChunkPublicationInput): ChunkedPublication {
  const { body, mode } = input;
  const surfaceViewId = requireU32(input.surfaceViewId, 'surfaceViewId');
  const opCount = requireU32(input.opCount, 'opCount');
  const sceneEpoch = requireU64(input.sceneEpoch, 'sceneEpoch');
  const commitGeneration = requireU64(input.commitGeneration, 'commitGeneration');
  const baseCommitGeneration = requireU64(input.baseCommitGeneration ?? 0n, 'baseCommitGeneration');

  if (surfaceViewId === 0) fail('zero_identity', 'surfaceViewId must be non-zero');
  if (sceneEpoch === 0n) fail('zero_identity', 'sceneEpoch must be non-zero');
  if (commitGeneration === 0n) fail('zero_identity', 'commitGeneration must be non-zero');
  if (mode === 'full' && baseCommitGeneration !== 0n) {
    fail(
      'full_publication_has_base_generation',
      `a full publication must declare base 0; got ${baseCommitGeneration}`,
    );
  }
  if (mode === 'diff' && baseCommitGeneration >= commitGeneration) {
    fail(
      'non_monotonic_base_generation',
      `diff base ${baseCommitGeneration} is not older than generation ${commitGeneration}`,
    );
  }
  const totalSize = body.length;
  if (totalSize === 0 || totalSize > GRAPHICS_MAX_PUBLICATION_BYTES) {
    fail('publication_too_large', `publication body is ${totalSize} bytes`);
  }

  const chunkCount = Math.max(1, Math.ceil(totalSize / GRAPHICS_MAX_CHUNK_DATA));
  if (chunkCount > 0xffff) {
    fail('invalid_chunk_index', `publication needs ${chunkCount} chunks; the u16 bound is 65535`);
  }
  const payloadDigest = graphicsPayloadDigest(body);

  const payloads: Uint8Array[] = [];
  for (let index = 0; index < chunkCount; index += 1) {
    const start = index * GRAPHICS_MAX_CHUNK_DATA;
    const slice = body.subarray(start, Math.min(start + GRAPHICS_MAX_CHUNK_DATA, totalSize));
    const payload = new Uint8Array(GRAPHICS_CHUNK_HEADER_SIZE + slice.length);
    const view = new DataView(payload.buffer);
    view.setUint32(0, GRAPHICS_ENVELOPE_MAGIC, true);
    view.setUint16(4, GRAPHICS_WIRE_SCHEMA_VERSION, true);
    view.setUint32(6, surfaceViewId, true);
    view.setBigUint64(10, sceneEpoch, true);
    view.setBigUint64(18, commitGeneration, true);
    view.setUint8(26, mode === 'full' ? 0 : 1);
    view.setUint8(27, 0);
    view.setBigUint64(28, baseCommitGeneration, true);
    view.setUint32(36, opCount, true);
    view.setUint16(40, index, true);
    view.setUint16(42, chunkCount, true);
    view.setUint32(44, totalSize, true);
    view.setBigUint64(48, payloadDigest, true);
    payload.set(slice, GRAPHICS_CHUNK_HEADER_SIZE);
    payloads.push(payload);
  }
  return { chunks: payloads, payloadDigest, totalSize };
}

export interface DecodedPublicationChunk {
  readonly header: GraphicsChunkHeader;
  readonly data: Uint8Array;
}

/** Reference decoder for one opcode-40 payload; mirrors the Rust decoder. */
export function decodePublicationChunk(payload: Uint8Array): DecodedPublicationChunk {
  if (payload.length < GRAPHICS_CHUNK_HEADER_SIZE) {
    fail('unexpected_end', `chunk payload is ${payload.length} bytes; the header is ${GRAPHICS_CHUNK_HEADER_SIZE}`);
  }
  const view = new DataView(payload.buffer, payload.byteOffset, payload.byteLength);
  if (view.getUint32(0, true) !== GRAPHICS_ENVELOPE_MAGIC) {
    fail('invalid_magic', 'chunk payload does not start with "GSCN"');
  }
  const schemaVersion = view.getUint16(4, true);
  if (schemaVersion !== GRAPHICS_WIRE_SCHEMA_VERSION) {
    fail('schema_version_mismatch', `chunk declares schema version ${schemaVersion}`);
  }
  const modeCode = view.getUint8(26);
  if (modeCode !== 0 && modeCode !== 1) {
    fail('unknown_publication_mode', `chunk declares mode ${modeCode}`);
  }
  if (view.getUint8(27) !== 0) {
    fail('non_zero_reserved', 'chunk reserved byte is non-zero');
  }
  const surfaceViewId = view.getUint32(6, true);
  const sceneEpoch = view.getBigUint64(10, true);
  const commitGeneration = view.getBigUint64(18, true);
  const baseCommitGeneration = view.getBigUint64(28, true);
  // The five envelope rules below are enforced by the kernel validator
  // (`GraphicsPublicationChunk::validate`) and by the Apple decoder
  // (`ExactGraphicsSceneProtocol.validate(header:dataCount:)`), in this order.
  // Leaving them out here made the reference decoder the loosest of the three:
  // take any `chunkPublication` payload, zero bytes 10..17, and this function
  // accepted and reassembled a publication both hosts refuse. That is exactly
  // the cross-language asymmetry the committed `tests/graphics/envelope`
  // fixtures exist to catch, and a decoder that disagrees about which bytes
  // are legal cannot serve as the other two implementations' reference.
  if (surfaceViewId === 0) fail('zero_identity', 'chunk declares surfaceViewId 0');
  if (sceneEpoch === 0n) fail('zero_identity', 'chunk declares sceneEpoch 0');
  if (commitGeneration === 0n) fail('zero_identity', 'chunk declares commitGeneration 0');
  if (modeCode === 0 && baseCommitGeneration !== 0n) {
    fail(
      'full_publication_has_base_generation',
      `a full publication must declare base 0; got ${baseCommitGeneration}`,
    );
  }
  if (modeCode === 1 && baseCommitGeneration >= commitGeneration) {
    fail(
      'non_monotonic_base_generation',
      `diff base ${baseCommitGeneration} is not older than generation ${commitGeneration}`,
    );
  }
  const chunkIndex = view.getUint16(40, true);
  const chunkCount = view.getUint16(42, true);
  if (chunkCount === 0 || chunkIndex >= chunkCount) {
    fail('invalid_chunk_index', `chunk ${chunkIndex} of ${chunkCount}`);
  }
  const totalSize = view.getUint32(44, true);
  if (totalSize === 0 || totalSize > GRAPHICS_MAX_PUBLICATION_BYTES) {
    fail('publication_too_large', `chunk declares a ${totalSize}-byte publication`);
  }
  const data = payload.subarray(GRAPHICS_CHUNK_HEADER_SIZE);
  if (data.length > GRAPHICS_MAX_CHUNK_DATA) {
    fail('chunk_too_large', `chunk carries ${data.length} bytes`);
  }
  if (data.length > totalSize || (chunkCount === 1 && data.length !== totalSize)) {
    fail('chunk_size_mismatch', `chunk carries ${data.length} of a declared ${totalSize} bytes`);
  }
  return {
    header: {
      schemaVersion,
      surfaceViewId,
      sceneEpoch,
      commitGeneration,
      mode: modeCode === 0 ? 'full' : 'diff',
      baseCommitGeneration,
      opCount: view.getUint32(36, true),
      chunkIndex,
      chunkCount,
      totalSize,
      payloadDigest: view.getBigUint64(48, true),
    },
    data,
  };
}

/**
 * Reassemble a complete publication. All-or-nothing per §2: a missing index, a
 * duplicate, an envelope disagreement, a short/long body, or a digest mismatch
 * refuses the whole publication.
 */
export function reassemblePublication(payloads: readonly Uint8Array[]): {
  header: GraphicsChunkHeader;
  body: Uint8Array;
} {
  if (payloads.length === 0) fail('missing_chunk', 'no chunks to reassemble');
  const chunks = payloads.map(decodePublicationChunk);
  const first = chunks[0]!.header;
  const slices = new Map<number, Uint8Array>();
  for (const chunk of chunks) {
    const header = chunk.header;
    if (
      header.surfaceViewId !== first.surfaceViewId ||
      header.sceneEpoch !== first.sceneEpoch ||
      header.commitGeneration !== first.commitGeneration ||
      header.mode !== first.mode ||
      header.baseCommitGeneration !== first.baseCommitGeneration ||
      header.opCount !== first.opCount ||
      header.chunkCount !== first.chunkCount ||
      header.totalSize !== first.totalSize ||
      header.payloadDigest !== first.payloadDigest
    ) {
      fail('chunk_envelope_mismatch', 'chunks disagree about their publication envelope');
    }
    if (slices.has(header.chunkIndex)) {
      fail('duplicate_chunk', `chunk ${header.chunkIndex} arrived twice`);
    }
    slices.set(header.chunkIndex, chunk.data);
  }
  if (slices.size !== first.chunkCount) {
    fail('missing_chunk', `have ${slices.size} of ${first.chunkCount} chunks`);
  }
  const body = new Uint8Array(first.totalSize);
  let offset = 0;
  for (let index = 0; index < first.chunkCount; index += 1) {
    const slice = slices.get(index);
    if (!slice) fail('missing_chunk', `chunk ${index} is missing`);
    if (offset + slice.length > body.length) {
      fail('chunk_size_mismatch', 'chunks exceed the declared publication size');
    }
    body.set(slice, offset);
    offset += slice.length;
  }
  if (offset !== first.totalSize) {
    fail('chunk_size_mismatch', `reassembled ${offset} of a declared ${first.totalSize} bytes`);
  }
  if (graphicsPayloadDigest(body) !== first.payloadDigest) {
    fail('payload_digest_mismatch', 'reassembled body does not match its declared digest');
  }
  return { header: first, body };
}

// ---------------------------------------------------------------------------
// Teardown
// ---------------------------------------------------------------------------

/** The opcode-41 record: `surface_view_id: u32 LE`, `scene_epoch: u64 LE`. */
export function encodeTeardownRecord(surfaceViewId: number, sceneEpoch: bigint): Uint8Array {
  if (requireU32(surfaceViewId, 'surfaceViewId') === 0) {
    fail('zero_identity', 'surfaceViewId must be non-zero');
  }
  if (requireU64(sceneEpoch, 'sceneEpoch') === 0n) {
    fail('zero_identity', 'sceneEpoch must be non-zero');
  }
  const bytes = new Uint8Array(GRAPHICS_TEARDOWN_SIZE);
  const view = new DataView(bytes.buffer);
  view.setUint32(0, surfaceViewId, true);
  view.setBigUint64(4, sceneEpoch, true);
  return bytes;
}

export function decodeTeardownRecord(bytes: Uint8Array): {
  surfaceViewId: number;
  sceneEpoch: bigint;
} {
  if (bytes.length < GRAPHICS_TEARDOWN_SIZE) {
    fail('unexpected_end', `teardown record is ${bytes.length} bytes`);
  }
  if (bytes.length > GRAPHICS_TEARDOWN_SIZE) {
    fail('trailing_bytes', `teardown record has ${bytes.length - GRAPHICS_TEARDOWN_SIZE} trailing bytes`);
  }
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const surfaceViewId = view.getUint32(0, true);
  const sceneEpoch = view.getBigUint64(4, true);
  if (surfaceViewId === 0) fail('zero_identity', 'surfaceViewId must be non-zero');
  if (sceneEpoch === 0n) fail('zero_identity', 'sceneEpoch must be non-zero');
  return { surfaceViewId, sceneEpoch };
}

// ---------------------------------------------------------------------------
// Publisher
// ---------------------------------------------------------------------------

/** The slice of `GraphicsScene` a publisher needs. */
export interface PublishableScene {
  subscribe(listener: (commit: GraphicsCommit) => void): () => void;
  snapshot(): GraphicsSceneSnapshot;
}

export interface GraphicsPublicationRecord {
  readonly kind: 'publication';
  readonly surfaceViewId: number;
  readonly sceneEpoch: bigint;
  readonly commitGeneration: bigint;
  readonly mode: GraphicsPublicationMode;
  readonly baseCommitGeneration: bigint;
  readonly opCount: number;
  readonly totalSize: number;
  readonly payloadDigest: bigint;
  /** One protocol payload per `graphicsPublicationChunk(viewId, payload)`. */
  readonly chunks: Uint8Array[];
}

export interface GraphicsTeardownRecord {
  readonly kind: 'teardown';
  readonly surfaceViewId: number;
  readonly sceneEpoch: bigint;
  /** The payload for `graphicsSceneTeardown(viewId, payload)`. */
  readonly payload: Uint8Array;
}

export type GraphicsWireRecord = GraphicsPublicationRecord | GraphicsTeardownRecord;

export type ScenePublisherDiagnosticCode =
  | 'graphics_publication_encode_failed'
  | 'graphics_publication_write_failed'
  | 'graphics_teardown_without_epoch';

export interface ScenePublisherDiagnostic {
  readonly code: ScenePublisherDiagnosticCode;
  readonly message: string;
  readonly commitGeneration?: string;
}

export interface ScenePublisherOptions {
  readonly scene: PublishableScene;
  readonly surfaceViewId: number;
  readonly write: (record: GraphicsWireRecord) => void;
  readonly onDiagnostic?: (diagnostic: ScenePublisherDiagnostic) => void;
  /** §6's lag bound; the next publication converts to `full` at or past it. */
  readonly maxUnappliedGenerations?: number;
  /** The flush window. Defaults to `queueMicrotask`, matching scene commits. */
  readonly scheduleFlush?: (flush: () => void) => void;
}

export interface ScenePublisher {
  /** The consumer-granted epoch, or `null` while still waiting for the grant. */
  readonly grantedEpoch: bigint | null;
  /**
   * Publications written but not yet acknowledged through `noteApplied`,
   * **saturating one past `maxUnappliedGenerations`**.
   *
   * §6 only ever asks whether the producer is at or past its lag bound, so the
   * publisher retains that many recent generations and no more. A consumer that
   * never acknowledges therefore costs O(bound) memory rather than one BigInt
   * per published frame forever — at 60 fps the unbounded form grew by 216,000
   * entries an hour. Below the bound the number is exact; at or past it the
   * number reads `maxUnappliedGenerations + 1`.
   */
  readonly unappliedGenerations: number;
  /**
   * §3: the consumer mints and grants; nothing publishes before this call.
   *
   * `consumerToken` is §3's opaque per-grant consumer identity: equal across
   * re-deliveries of the SAME grant, different whenever the consumer behind
   * the grant changed. It exists because the epoch number alone cannot answer
   * that question — epochs are minted per consumer store, so a replacement
   * store's first grant repeats the number the previous one handed out. A
   * grant that omits it (a shell older than the field) is treated as a new
   * consumer every time; see `grantEpoch` in the implementation.
   */
  grantEpoch(epoch: bigint | number | string, consumerToken?: string): void;
  /** The consumer's applied-generation acknowledgment; drives the lag bound. */
  noteApplied(commitGeneration: bigint | number | string): void;
  /** §2's resync path: force the next publication to `full`. */
  requestResync(): void;
  /** Encode and write any pending publication now. */
  flush(): void;
  /** Emit the opcode-41 record and stop publishing. */
  teardown(): void;
  /** Stop publishing without emitting a teardown. */
  dispose(): void;
}

function toU64(value: bigint | number | string, field: string): bigint {
  const parsed = typeof value === 'bigint' ? value : BigInt(value);
  return requireU64(parsed, field);
}

/**
 * Project a committed snapshot back into the `GraphicsOperation[]` a `full`
 * publication carries (§2's "the first publication in an epoch is always
 * full", and the resync path's only way to satisfy it).
 *
 * `GraphicsScene` has no "re-emit as full" method — `snapshot()` returns a
 * `GraphicsSceneSnapshot`, not operations — so this projection is the whole
 * mechanism, and its ORDER is the load-bearing part rather than a detail.
 *
 * The consumer rebuilds `roots` by appending each parentless `create` in
 * arrival order, and rebuilds a parent's `children` from the parent record
 * when it lands (the Apple store's `apply`). So:
 *
 *   - roots are emitted in `snapshot.roots` order, NOT in node-map insertion
 *     order. Those two disagree the moment anything reorders a root: the map
 *     keeps creation order while `roots` keeps z-order, and a naive
 *     `nodes.map(...)` therefore hands the consumer a scene painted in the
 *     wrong stacking order — with every node present, so nothing fails.
 *   - each subtree follows its parent depth-first in the parent's own
 *     `children` order, so a consumer that appends children as they arrive
 *     (rather than trusting the parent record) lands on the same order.
 *
 * Any node the roots walk cannot reach — which the scene model does not
 * produce, since a node is a root until it is parented — is appended at the
 * end rather than dropped: losing a node silently is worse than emitting it
 * in a defensible position.
 */
export function graphicsSnapshotOperations(
  snapshot: GraphicsSceneSnapshot,
): GraphicsOperation[] {
  const byId = new Map<string, GraphicsNodeRecord>();
  for (const node of snapshot.nodes) byId.set(node.internalNodeId, node);

  const operations: GraphicsOperation[] = [];
  const emitted = new Set<string>();
  const visit = (nodeId: string): void => {
    if (emitted.has(nodeId)) return;
    const node = byId.get(nodeId);
    if (!node) return;
    emitted.add(nodeId);
    operations.push({ type: 'create', nodeId: node.internalNodeId, node });
    for (const child of node.children) visit(child);
  };
  for (const rootId of snapshot.roots) visit(rootId);
  for (const node of snapshot.nodes) visit(node.internalNodeId);
  return operations;
}

/**
 * The stateful producer: epoch handshake, commit subscription, §6 flow
 * control, and teardown.
 *
 * It never throws into the commit path. An encode or write failure is reported
 * through `onDiagnostic` and drops that publication — a renderer must not take
 * the app down — and the next publication converts to `full`, because a diff
 * whose predecessor was dropped has no valid base.
 */
export function createScenePublisher(options: ScenePublisherOptions): ScenePublisher {
  const { scene, surfaceViewId, write } = options;
  const maxUnapplied = options.maxUnappliedGenerations ?? 2;
  // §6 asks one question of the outstanding set — "are we at or past the lag
  // bound?" — so retaining one generation past the bound answers it with room
  // to spare. Anything older is unconditionally superseded: generations are
  // published in increasing order, so an acknowledgment that retires the oldest
  // retained generation retires every generation that fell out before it, and
  // one that does not leaves the retained window full, which is already "past
  // the bound". Keeping the whole history instead would grow without limit
  // against a consumer that never acknowledges.
  // A non-finite bound would otherwise defeat the trim, which is the one thing
  // this cap exists to guarantee.
  const unappliedCap = Number.isFinite(maxUnapplied) ? Math.max(1, Math.floor(maxUnapplied) + 1) : 1;
  const scheduleFlush = options.scheduleFlush ?? ((run: () => void) => queueMicrotask(run));
  const onDiagnostic = options.onDiagnostic;

  let epoch: bigint | null = null;
  let pending: GraphicsCommit | null = null;
  let scheduled = false;
  let stopped = false;
  let publishedInEpoch = false;
  /** The consumer identity the epoch in force was granted under, or null when
   * the grant carried none (see `grantEpoch`). */
  let grantedConsumer: string | null = null;
  let forceFull = true;
  let lastPublished = 0n;
  let lastApplied = 0n;
  /** Ascending, oldest first, never longer than `unappliedCap`. */
  let unapplied: bigint[] = [];

  const report = (diagnostic: ScenePublisherDiagnostic): void => {
    onDiagnostic?.(diagnostic);
  };

  const schedule = (): void => {
    if (scheduled || stopped || epoch === null || pending === null) return;
    scheduled = true;
    scheduleFlush(() => {
      scheduled = false;
      flush();
    });
  };

  const publish = (commit: GraphicsCommit): void => {
    const granted = epoch;
    if (granted === null) return;
    const generation = toU64(commit.commitGeneration, 'commitGeneration');
    const baseCandidate = lastApplied > 0n ? lastApplied : lastPublished;
    const mustBeFull =
      forceFull ||
      !publishedInEpoch ||
      commit.mode === 'full' ||
      unapplied.length >= maxUnapplied ||
      baseCandidate === 0n ||
      baseCandidate >= generation;
    const mode: GraphicsPublicationMode = mustBeFull ? 'full' : 'diff';
    const operations = mustBeFull
      ? graphicsSnapshotOperations(commit.snapshot ?? scene.snapshot())
      : commit.operations;
    const { bytes, opCount } = encodePublicationBody({ operations });
    // One digest per publication: `chunkPublication` hashes the body to fill
    // the chunk headers and hands the value back for the wire record.
    const { chunks, payloadDigest, totalSize } = chunkPublication({
      body: bytes,
      surfaceViewId,
      sceneEpoch: granted,
      commitGeneration: generation,
      mode,
      baseCommitGeneration: mustBeFull ? 0n : baseCandidate,
      opCount,
    });
    write({
      kind: 'publication',
      surfaceViewId,
      sceneEpoch: granted,
      commitGeneration: generation,
      mode,
      baseCommitGeneration: mustBeFull ? 0n : baseCandidate,
      opCount,
      totalSize,
      payloadDigest,
      chunks,
    });
    publishedInEpoch = true;
    forceFull = false;
    lastPublished = generation;
    unapplied.push(generation);
    if (unapplied.length > unappliedCap) unapplied.shift();
  };

  function flush(): void {
    if (stopped || epoch === null) return;
    const commit = pending;
    pending = null;
    if (commit === null) return;
    try {
      publish(commit);
    } catch (error) {
      // A dropped publication invalidates any base the next diff would name.
      forceFull = true;
      report({
        code:
          error instanceof GraphicsProtocolError
            ? 'graphics_publication_encode_failed'
            : 'graphics_publication_write_failed',
        message: error instanceof Error ? error.message : String(error),
        commitGeneration: commit.commitGeneration,
      });
    }
  }

  /**
   * Force the next publication to `full` and, when nothing is pending, project
   * one from the scene's current committed snapshot.
   *
   * Both entry points need the projection, not just §2's resync path: a scene
   * that committed BEFORE this publisher subscribed leaves `pending` null, so
   * the grant had nothing to flush and — if nothing ever mutated the scene
   * again — the consumer sat on a granted epoch and never received the first
   * `full` it was waiting for. Blank surface, indefinitely.
   *
   * `commitGeneration === '0'` is a scene that has never committed; there is
   * nothing to project, and a publication may not carry generation 0 anyway.
   */
  const resync = (): void => {
    forceFull = true;
    if (stopped || pending !== null) return;
    const snapshot = scene.snapshot();
    if (snapshot.commitGeneration === '0') return;
    pending = {
      kind: 'commit',
      schemaVersion: 1,
      sceneEpoch: snapshot.sceneEpoch,
      commitGeneration: snapshot.commitGeneration,
      mode: 'full',
      operations: graphicsSnapshotOperations(snapshot),
      accepted: true,
      diagnostics: [],
      snapshot,
    };
    schedule();
  };

  const unsubscribe = scene.subscribe((commit: GraphicsCommit) => {
    if (stopped) return;
    // §2: only accepted commits are publishable; a refusal leaves the author's
    // scene canonical and the consumer's last complete scene retained.
    if (!commit.accepted) return;
    // §6 squash: within one flush window the latest state wins outright.
    pending = commit;
    schedule();
  });

  const stop = (): void => {
    stopped = true;
    pending = null;
    unsubscribe();
  };

  return {
    get grantedEpoch() {
      return epoch;
    },
    get unappliedGenerations() {
      return unapplied.length;
    },
    grantEpoch(value, consumerToken) {
      const granted = toU64(value, 'sceneEpoch');
      if (granted === 0n) fail('zero_identity', 'a granted sceneEpoch must be non-zero');
      // A RE-GRANT of the epoch this publisher is already publishing in is a
      // no-op, because there is nothing the consumer can be missing. §3 makes
      // the consumer's `attach` idempotent — it returns the already-granted
      // epoch for every later attach of the same surface — so a presenter-side
      // view recycle replays the same value. Running the projection below for
      // it is guaranteed dead work: the consumer already holds every
      // generation published in this epoch, so §2's duplicate rule
      // (`commitGeneration <= appliedGeneration`) discards the result on
      // arrival — after a second `graphicsSnapshotOperations` walk, a
      // `JSON.stringify` of every node record, an FNV-1a pass over a
      // hundreds-of-KB body, and a multi-chunk dispatch. Resetting the state
      // below would be worse than wasteful: it drops the diff base, so the
      // next ordinary frame converts to `full` as well.
      //
      // The epoch NUMBER cannot decide that on its own, and deciding on it
      // alone blanked the surface: epochs are minted per consumer store, so a
      // replacement store's first grant repeats the number the previous store
      // handed out (the case the surface view goes out of its way to announce
      // on store identity). Suppressing that grant left the new consumer with
      // no retained scene, no applied generation and an `invalidate()` already
      // spent — and on an idle scene, which publishes nothing until input, no
      // later publication ever arrives to expose the miss. The surface stayed
      // blank until the user happened to interact.
      //
      // §3's `consumerToken` is what makes the decision sound: the consumer is
      // the only party that knows whether it is the same consumer, and it says
      // so. A grant WITHOUT one is treated as a new consumer — a shell too old
      // to send the field cannot be distinguished, and one wasted full encode
      // is the cheap side of that trade.
      const sameConsumer = consumerToken !== undefined && consumerToken === grantedConsumer;
      if (granted === epoch && publishedInEpoch && sameConsumer) return;
      epoch = granted;
      grantedConsumer = consumerToken ?? null;
      publishedInEpoch = false;
      forceFull = true;
      lastPublished = 0n;
      lastApplied = 0n;
      unapplied = [];
      // `resync()` covers the commit-before-subscribe case; `schedule()` after
      // it covers the other one, where a commit arrived before the grant and is
      // already pending — its own `schedule()` ran while `epoch` was still null
      // and did nothing, and `resync()` returns early on a non-null `pending`.
      resync();
      schedule();
    },
    noteApplied(value) {
      const generation = toU64(value, 'commitGeneration');
      if (generation > lastApplied) lastApplied = generation;
      unapplied = unapplied.filter((entry) => entry > lastApplied);
    },
    requestResync: resync,
    flush,
    teardown() {
      if (stopped) return;
      const granted = epoch;
      stop();
      if (granted === null) {
        report({
          code: 'graphics_teardown_without_epoch',
          message: 'teardown before an epoch grant retires nothing',
        });
        return;
      }
      try {
        write({
          kind: 'teardown',
          surfaceViewId,
          sceneEpoch: granted,
          payload: encodeTeardownRecord(surfaceViewId, granted),
        });
      } catch (error) {
        report({
          code: 'graphics_publication_write_failed',
          message: error instanceof Error ? error.message : String(error),
        });
      }
    },
    dispose() {
      stop();
    },
  };
}
