import type {
  AgentEvent,
  ElementRef,
  ElementRefInfo,
  Frame,
  Point,
  RootInfo,
  ViewNode,
} from '@exact/core/agent/types';
import {
  recordCommitTimestamp,
  resetAgentInteractionStateTracking,
} from '@exact/core/agent/interaction-state';

import type { ElementNode, HostNode, RootNode } from './nodes/node.js';
import { NodeKind } from './nodes/node.js';
import { getScreenDimensions } from './protocol/index.js';

// ---------------------------------------------------------------------------
// LLP 0321 B1 (ENG-23534) — serialization-visible dirty ledger.
//
// The commit-granular validity authority behind incremental tree
// serialization (the cache itself lives in inspector.ts). Every
// serialization-visible input records here: reconciler/host-ops commits
// (`changedViews` via `notifyCommit` below), interaction overrides
// (text/toggle/value/scroll/host content sizes — writers in inspector.ts),
// root churn, and read-time observations the commit path cannot see (frame
// deltas, safe-area object swaps, floating-position mutations,
// registry/interaction-context fingerprint changes). A cached payload is
// reusable iff it was built at or after the generation that last dirtied its
// view.
//
// The ledger lives in THIS module (not its own file) deliberately: it is
// commit-side shared state, and inspector-runtime is already on the native
// startup graph — a separate module would grow the LLP 0128 startup budget
// for no isolation gain. State rides `globalThis` (the
// `__exactRendererInspectorState` pattern) so writers and readers agree even
// when modules were evaluated more than once. On tracked-map overflow the
// ledger degrades to a whole-tree invalidation rather than guessing — full
// serialization is always a legal fallback.
// ---------------------------------------------------------------------------

interface SerializationLedgerState {
  generation: number;
  dirtyByViewId: Map<number, number>;
  allDirtyGeneration: number;
  reasonCounts: Record<string, number>;
}

type LedgerGlobal = typeof globalThis & {
  __exactSerializationLedger?: SerializationLedgerState;
  __exactSerializationDirtyListeners?: Set<() => void>;
};

/**
 * LLP 0321 B4 (ENG-23536): ledger writes as wake signals. Scroll/value/text
 * overrides (and every other serialization-visible input) record here without
 * emitting a render event, so polling waits rediscover them up to a full poll
 * interval late. Subscribers (the `exact_wait` event loop) are pinged once
 * per ledger write batch; the callback carries no payload — listeners
 * re-evaluate their condition against current state. Same globalThis pattern
 * as the ledger itself so writers and readers agree across double module
 * evaluation.
 */
export function subscribeSerializationDirtySignals(
  listener: () => void,
): () => void {
  const scope = globalThis as LedgerGlobal;
  const listeners = (scope.__exactSerializationDirtyListeners ??= new Set());
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function emitSerializationDirtySignal(): void {
  const listeners = (globalThis as LedgerGlobal)
    .__exactSerializationDirtyListeners;
  if (!listeners || listeners.size === 0) {
    return;
  }
  listeners.forEach((listener) => {
    try {
      listener();
    } catch (error) {
      console.error('[RendererInspector] dirty-signal listener failed:', error);
    }
  });
}

// Bounded so a long-lived session with heavy node churn cannot grow the map
// forever; overflow degrades to all-dirty (correct, just slower once).
const MAX_TRACKED_VIEWS = 65536;

function ledgerState(): SerializationLedgerState {
  const scope = globalThis as LedgerGlobal;
  if (scope.__exactSerializationLedger) {
    return scope.__exactSerializationLedger;
  }
  const state: SerializationLedgerState = {
    generation: 0,
    dirtyByViewId: new Map<number, number>(),
    allDirtyGeneration: 0,
    reasonCounts: {},
  };
  scope.__exactSerializationLedger = state;
  return state;
}

function countLedgerReason(state: SerializationLedgerState, reason: string): void {
  state.reasonCounts[reason] = (state.reasonCounts[reason] ?? 0) + 1;
}

/** Mark a batch of views dirty at a fresh generation. */
export function recordDirtyViews(
  viewIds: Iterable<number>,
  reason: string,
): void {
  const state = ledgerState();
  let bumped = false;
  for (const viewId of viewIds) {
    if (!bumped) {
      state.generation += 1;
      countLedgerReason(state, reason);
      bumped = true;
    }
    state.dirtyByViewId.set(viewId, state.generation);
  }
  if (bumped && state.dirtyByViewId.size > MAX_TRACKED_VIEWS) {
    state.dirtyByViewId.clear();
    state.generation += 1;
    state.allDirtyGeneration = state.generation;
    countLedgerReason(state, 'ledger-overflow');
  }
  if (bumped) {
    emitSerializationDirtySignal();
  }
}

/** Mark everything dirty (root churn, unscoped commits, fingerprint flips). */
export function recordAllDirty(reason: string): void {
  const state = ledgerState();
  state.generation += 1;
  state.allDirtyGeneration = state.generation;
  state.dirtyByViewId.clear();
  countLedgerReason(state, reason);
  emitSerializationDirtySignal();
}

export function ledgerGeneration(): number {
  return ledgerState().generation;
}

/** The generation at which a view was last dirtied (0 = never recorded). */
export function dirtyGenerationFor(viewId: number): number {
  const state = ledgerState();
  return Math.max(
    state.dirtyByViewId.get(viewId) ?? 0,
    state.allDirtyGeneration,
  );
}

export function serializationLedgerStats(): {
  generation: number;
  trackedViews: number;
  allDirtyGeneration: number;
  reasonCounts: Record<string, number>;
} {
  const state = ledgerState();
  return {
    generation: state.generation,
    trackedViews: state.dirtyByViewId.size,
    allDirtyGeneration: state.allDirtyGeneration,
    reasonCounts: { ...state.reasonCounts },
  };
}

/**
 * Full ledger reset — called from `_resetInspectorState` below. Bundle
 * replacement recycles node ids from 1, so a stale ledger (like a stale
 * cache) would corrupt lookups for recycled ids (the ENG-23266 failure
 * class).
 */
export function _resetSerializationLedger(): void {
  const state = ledgerState();
  state.generation = 0;
  state.dirtyByViewId.clear();
  state.allDirtyGeneration = 0;
  state.reasonCounts = {};
}

type InspectorListener = (event: AgentEvent) => void;
type CommitAnalyzer = (root: RootNode) => void;
type ResetHook = () => void;
type RootUnregisterHook = (rootId: number) => void;

interface SnapshotRecord {
  snapshotId: string;
  rootId: number;
  stateVersion: number;
  timestamp: number;
  frameCount: number;
  refs: Record<ElementRef, ElementRefInfo>;
  tree?: ViewNode;
}

interface SharedInspectorState {
  roots: Map<number, RootNode>;
  listeners: Set<InspectorListener>;
  snapshots: Map<string, SnapshotRecord>;
  snapshotOrder: string[];
  textOverrides: Map<number, string>;
  toggleOverrides: Map<number, boolean>;
  valueOverrides: Map<number, unknown>;
  scrollOffsets: Map<number, Point>;
  // LLP 0306 §P5 (ENG-22879): host-reported (native) content sizes — see
  // inspector.ts, which owns the read/write paths. Declared here so both
  // modules agree on the shared global state shape.
  hostScrollContentSizes: Map<number, { width: number; height: number }>;
  snapshotCounter: number;
  stateVersion: number;
  frameCount: number;
  lastCommitAt: number;
  // ENG-23214/23251 (optional: backfilled onto shared states created by an
  // older module evaluation — see inspector.ts, which owns the write paths).
  geometryVersion?: number;
  latestFullSnapshotByRoot?: Map<number, string>;
}

type InspectorGlobal = typeof globalThis & {
  __exactRendererInspectorState?: SharedInspectorState;
  __exactRendererCommitAnalyzers?: Set<CommitAnalyzer>;
  __exactRendererInspectorResetHooks?: Set<ResetHook>;
  __exactRendererRootUnregisterHooks?: Set<RootUnregisterHook>;
};

function inspectorGlobal(): InspectorGlobal {
  return globalThis as InspectorGlobal;
}

function getSharedInspectorState(): SharedInspectorState {
  const scope = inspectorGlobal();
  if (scope.__exactRendererInspectorState) {
    return scope.__exactRendererInspectorState;
  }

  const state: SharedInspectorState = {
    roots: new Map<number, RootNode>(),
    listeners: new Set<InspectorListener>(),
    snapshots: new Map<string, SnapshotRecord>(),
    snapshotOrder: [],
    textOverrides: new Map<number, string>(),
    toggleOverrides: new Map<number, boolean>(),
    valueOverrides: new Map<number, unknown>(),
    scrollOffsets: new Map<number, Point>(),
    hostScrollContentSizes: new Map<number, { width: number; height: number }>(),
    snapshotCounter: 0,
    stateVersion: 0,
    frameCount: 0,
    lastCommitAt: 0,
  };
  scope.__exactRendererInspectorState = state;
  return state;
}

const sharedState = getSharedInspectorState();
const roots = sharedState.roots;
const listeners = sharedState.listeners;
const snapshots = sharedState.snapshots;
const snapshotOrder = sharedState.snapshotOrder;
const textOverrides = sharedState.textOverrides;
const toggleOverrides = sharedState.toggleOverrides;
const valueOverrides = sharedState.valueOverrides;
const scrollOffsets = sharedState.scrollOffsets;
// Backfill for shared states created by an older module evaluation.
sharedState.hostScrollContentSizes ??= new Map();
const hostScrollContentSizes = sharedState.hostScrollContentSizes;

function currentTimestamp(): number {
  return Date.now();
}

function makeRootInfo(root: RootNode): RootInfo {
  const { width, height } = getScreenDimensions(root.rootId);
  return {
    rootId: root.rootId,
    label: root.rootId === 0 ? 'Main' : `Root ${root.rootId}`,
    size: {
      width,
      height,
    },
  };
}

function emit(event: AgentEvent): void {
  for (const listener of listeners) {
    try {
      listener(event);
    } catch (error) {
      console.error('[RendererInspector] listener failed:', error);
    }
  }
}

function collectChangedViews(root: RootNode): number[] {
  const collected: number[] = [];
  const collect = (node: HostNode): void => {
    collected.push(node.id);
    if (node.kind === NodeKind.Element || node.kind === NodeKind.Root) {
      for (const child of node.children) {
        collect(child);
      }
    }
  };

  collect(root);
  return collected;
}

function commitAnalyzers(): Set<CommitAnalyzer> {
  const scope = inspectorGlobal();
  if (!scope.__exactRendererCommitAnalyzers) {
    scope.__exactRendererCommitAnalyzers = new Set<CommitAnalyzer>();
  }
  return scope.__exactRendererCommitAnalyzers;
}

function resetHooks(): Set<ResetHook> {
  const scope = inspectorGlobal();
  if (!scope.__exactRendererInspectorResetHooks) {
    scope.__exactRendererInspectorResetHooks = new Set<ResetHook>();
  }
  return scope.__exactRendererInspectorResetHooks;
}

function rootUnregisterHooks(): Set<RootUnregisterHook> {
  const scope = inspectorGlobal();
  scope.__exactRendererRootUnregisterHooks ??= new Set<RootUnregisterHook>();
  return scope.__exactRendererRootUnregisterHooks;
}

export function registerInspectorCommitAnalyzer(analyzer: CommitAnalyzer): () => void {
  const analyzers = commitAnalyzers();
  analyzers.add(analyzer);
  return () => {
    analyzers.delete(analyzer);
  };
}

export function registerInspectorResetHook(hook: ResetHook): () => void {
  const hooks = resetHooks();
  hooks.add(hook);
  return () => {
    hooks.delete(hook);
  };
}

/** Register owner-local cleanup for state keyed by a root lifecycle. */
export function registerInspectorRootUnregisterHook(
  hook: RootUnregisterHook,
): () => void {
  const hooks = rootUnregisterHooks();
  hooks.add(hook);
  return () => {
    hooks.delete(hook);
  };
}

export function registerRoot(root: RootNode): void {
  roots.set(root.rootId, root);
  sharedState.stateVersion += 1;
  // LLP 0321 B1 (ENG-23534): root churn invalidates every cached
  // serialization — cross-root reuse windows are not worth reasoning about.
  recordAllDirty('root-churn');
  const rootInfo = makeRootInfo(root);
  emit({
    type: 'connect',
    rootId: root.rootId,
    label: rootInfo.label,
    size: rootInfo.size,
  });
}

export function unregisterRoot(rootId: number): void {
  if (!roots.delete(rootId)) {
    return;
  }
  sharedState.stateVersion += 1;
  recordAllDirty('root-churn');
  // ENG-23214: snapshot eviction budgets are per root, so a dead root's
  // records are never displaced by other roots' reads — drop them here so
  // their retained trees don't linger.
  for (let index = snapshotOrder.length - 1; index >= 0; index -= 1) {
    const id = snapshotOrder[index]!;
    if (snapshots.get(id)?.rootId === rootId) {
      snapshots.delete(id);
      snapshotOrder.splice(index, 1);
    }
  }
  sharedState.latestFullSnapshotByRoot?.delete(rootId);
  for (const hook of rootUnregisterHooks()) {
    hook(rootId);
  }
  emit({
    type: 'disconnect',
    reason: `root:${rootId}:unregistered`,
    exitCode: null,
    signal: null,
  });
}

export function notifyCommit(
  root: RootNode,
  options: {
    changedViews?: Iterable<number>;
    analyzeWarnings?: boolean;
  } = {},
): void {
  roots.set(root.rootId, root);
  sharedState.frameCount += 1;
  sharedState.stateVersion += 1;
  sharedState.lastCommitAt = currentTimestamp();
  recordCommitTimestamp(sharedState.lastCommitAt);

  // Materialized once: the ledger write and the render event below both
  // consume it, and the option's type admits one-shot iterators.
  const changedViews =
    options.changedViews !== undefined
      ? Array.from(options.changedViews)
      : undefined;

  // LLP 0321 B1 (ENG-23534): feed the serialization dirty ledger. This must
  // happen regardless of listeners — the ledger is a validity authority, not
  // an event stream. A commit with no changedViews scope conservatively
  // dirties everything (full serialization is always a legal fallback).
  if (changedViews !== undefined) {
    recordDirtyViews(changedViews, 'commit');
  } else {
    recordAllDirty('commit-unscoped');
  }

  if (options.analyzeWarnings !== false) {
    for (const analyzer of commitAnalyzers()) {
      analyzer(root);
    }
  }

  if (listeners.size === 0) {
    return;
  }

  emit({
    type: 'render',
    frameCount: sharedState.frameCount,
    changedViews: changedViews ?? collectChangedViews(root),
  });
}

/**
 * The single complete reset of the shared inspector state. inspector.ts's
 * `_resetInspectorState` delegates here (plus its module-local latches) —
 * ENG-23266 came from this function and inspector.ts's copy drifting apart:
 * this one stopped clearing `hostScrollContentSizes`, so a bundle
 * replacement (which also resets the node-id counter) let recycled viewIds
 * inherit stale native content sizes and corrupt scroll clamp math. New
 * SharedInspectorState fields must be cleared HERE, not in a second copy.
 */
export function _resetInspectorState(): void {
  roots.clear();
  listeners.clear();
  snapshots.clear();
  snapshotOrder.length = 0;
  resetAgentInteractionStateTracking();
  for (const hook of resetHooks()) {
    try {
      hook();
    } catch (error) {
      console.error('[RendererInspector] reset hook failed:', error);
    }
  }
  textOverrides.clear();
  toggleOverrides.clear();
  valueOverrides.clear();
  scrollOffsets.clear();
  hostScrollContentSizes.clear();
  sharedState.latestFullSnapshotByRoot?.clear();
  sharedState.snapshotCounter = 0;
  sharedState.stateVersion = 0;
  sharedState.frameCount = 0;
  sharedState.lastCommitAt = 0;
  sharedState.geometryVersion = 0;
  // LLP 0321 B1 (ENG-23534): bundle replacement recycles node ids, so the
  // ledger resets with the rest of the shared state (the serialization cache
  // clears via a registered reset hook in inspector.ts).
  _resetSerializationLedger();
}
